function evRaison(){ const r=document.getElementById('ev-raison'); return r?r.value:''; }
const EV_REGIMES=[
 [1,'Elle propose, vous décidez',
    'Elle écrit la pièce, la prouve, et attend votre clic. Rien ne change dans le code sans vous.'],
 [2,'Elle applique seule ce qui ne peut pas casser',
    'Cinq familles seulement : de la documentation, du code mort retiré et prouvé mort, du code mort mis en quarantaine, de la mise en forme, et un réglage de valeur borné à 20 %. Tout le reste continue d’attendre votre clic.'],
 [3,'Elle applique seule, sous la garde',
    'Toute famille peut passer, mais rien ne s’écrit sans le test rouge-vert, la relecture, la fenêtre de 24 heures et le retour arrière automatique en cas de perte. Rien ne vous attend : ce que le relecteur refuse est refusé, et appris. C’est le réglage d’une installation neuve.']];
function evChoixRegime(){
    EV.regime = (EV.etat||{}).regime || 3;
    return '<div style="display:grid;gap:8px;margin-bottom:14px" id="ev-regimes">'
      + EV_REGIMES.map(r=>'<button class="ev-opt'+(r[0]===EV.regime?' on':'')+'" data-r="'+r[0]+'" onclick="evChoisirRegime('+r[0]+')">'
        + '<span class="t">'+evH(r[1])+(r[0]===((EV.etat||{}).regime||3)?' <span class="mx-pill">réglage actuel</span>':'')+'</span>'
        + '<span class="d">'+evH(r[2])+'</span></button>').join('')
      + '</div>';
}
function evChoisirRegime(n){
    EV.regime=n;
    document.querySelectorAll('#ev-regimes .ev-opt').forEach(b=>b.classList.toggle('on', +b.dataset.r===n));
}
function evChoixCadence(){
    const c=((EV.etat||{}).cadence)||{heure:5,par_jour:1};
    EV.cadHeure=c.heure; EV.cadJour=c.par_jour;
    const jours=[[0,'jamais toute seule'],[1,'une fois par jour'],[2,'deux fois'],[3,'trois fois'],[4,'quatre fois']];
    let h='<option value="'+0+'"></option>';
    h='';
    for(let i=0;i<24;i++) h+='<option value="'+i+'"'+(i===c.heure?' selected':'')+'>'+(i<10?'0':'')+i+':00</option>';
    return '<div style="margin-bottom:14px"><div class="ev-lbl" style="margin-bottom:6px">Combien de fois par jour</div>'
      + '<div class="ev-chips" id="ev-cadj">'
      + jours.map(j=>'<button class="ev-chip'+(j[0]===c.par_jour?' on':'')+'" data-j="'+j[0]+'" onclick="evChoisirJour('+j[0]+')">'+j[1]+'</button>').join('')
      + '</div><div style="margin-top:10px" id="ev-cadh-bloc"><div class="ev-lbl" style="margin-bottom:6px">À partir de quelle heure</div>'
      + '<select id="ev-cadh" onchange="evChoisirHeure(this.value)" style="padding:6px 10px;border:1px solid var(--line-strong);'
      + 'border-radius:8px;background:var(--surface-solid);color:var(--txt);font-size:13px;font-family:inherit">'+h+'</select></div>'
      + '<div id="ev-cadq" style="margin-top:8px;font-size:12.5px;color:var(--txt-soft)"></div></div>';
}
function evChoisirJour(n){
    EV.cadJour=n;
    document.querySelectorAll('#ev-cadj .ev-chip').forEach(b=>b.classList.toggle('on', +b.dataset.j===n));
    const bl=document.getElementById('ev-cadh-bloc'); if(bl) bl.style.display = n?'':'none';
    evCadencePhrase();
}
function evChoisirHeure(v){ EV.cadHeure=+v; evCadencePhrase(); }
function evCadencePhrase(){
    const q=document.getElementById('ev-cadq'); if(!q) return;
    const n=EV.cadJour, h=EV.cadHeure;
    if(!n){ q.textContent='Elle ne partira jamais d’elle-même : à vous de lancer une passe quand vous le voulez.'; return; }
    const pas=Math.floor(24/n), hs=[];
    for(let i=0;i<n;i++) hs.push((('0'+((h+i*pas)%24)).slice(-2))+':00');
    hs.sort();
    q.textContent = (n===1?'Une passe par jour, à ':'Une passe à ')+hs.join(', ')+'.';
}
function evFeuille(k){
    const f=(evFeuilles())[k]; if(!f) return;
    EV.duree='indefini'; EV._geste=f.geste;
    const duree = f.duree ? '<div style="margin-bottom:14px"><div class="ev-lbl" style="margin-bottom:6px">Combien de temps</div>'
        + '<div class="ev-chips" id="ev-durees">'
        + EV_DUREES.map(d=>'<button class="ev-chip'+(d[0]==='indefini'?' on':'')+'" data-d="'+d[0]+'" onclick="evChoisirDuree(\''+d[0]+'\')">'+d[1]+'</button>').join('')
        + '</div><div id="ev-quand" style="margin-top:8px;font-size:12.5px;color:var(--txt-soft)">Elle durera jusqu’à ce que vous la leviez.</div></div>' : '';
    const choix = (f.choix==='regime') ? evChoixRegime() : '';
    const cadence = f.cadence ? evChoixCadence() : '';
    const raison = f.raison ? '<div style="margin-bottom:14px"><div class="ev-lbl" style="margin-bottom:6px">Pourquoi — gardé avec le geste</div>'
        + '<input id="ev-raison" placeholder="en un mot ou deux…"></div>' : '';
    document.getElementById('ev-fe').innerHTML='<h3>'+evH(f.t)+'</h3>'+choix+cadence+duree+raison
        + '<div class="l3">'+f.l.map(x=>'<div class="k">'+evH(x[0])+'</div><div>'+evH(x[1])+'</div>').join('')+'</div>'
        + (f.relu?('<div class="relu '+(f.ok?'':'ko')+'"><span>'+(f.ok?'✓':'⚠')+'</span><span>'+evH(f.relu)+'</span></div>'):'')
        + '<div class="fin"><button class="mx-btn" onclick="evFermer()">Annuler</button>'
        + '<button class="mx-btn primary" onclick="evExecuter()">'+evH(f.bouton)+'</button></div>';
    document.getElementById('ev-voile').classList.add('on');
}
function evFermer(){ const v=document.getElementById('ev-voile'); if(v) v.classList.remove('on'); }
async function evExecuter(){ const g=EV._geste; evFermer(); if(g) await g(); }
/* Le bouton rendait « demandée : elle part dans la minute », et plus rien ne bougeait : personne
   ne pouvait savoir ce qu’elle avait donné. Il attend la passe et montre sa ligne. */
async function evPasse(){
    let r={};
    try{ r=await apiPost('/api/evolution/run_now',{}); }catch(e){ toast('échec : '+e.message,'error',6000); return; }
    if(r && r.ok===false){ toast(r.error||'refusé','error',6000); return; }
    toast('Passe demandée — elle part dans la minute, sa ligne apparaîtra dans le journal des passes','info',7000);
    const avant=((await evJournalTete())||{}).ts||'';
    let tours=0;
    const minuteur=setInterval(async function(){
        tours++;
        const t=await evJournalTete();
        if((t && t.ts!==avant) || tours>=8){
            clearInterval(minuteur);
            await loadEvolution();
            if(t && t.ts!==avant) toast('Passe terminée : '+(t.quoi||''), t.issue==='proposee'?'success':'info', 8000);
            else toast('La passe n’a pas encore laissé de ligne — le journal se remplira tout seul','warning',6000);
        }
    }, 20000);
    evJournal();
}
async function evJournalTete(){
    try{ const r=await apiGet('/api/evolution/journal'); return (r.passes||[])[0]||null; }catch(e){ return null; }
}
async function evGeste(route, corps){
    try{
        const r=await apiPost(route, corps||{});
        if(r && r.ok===false){ toast(r.error||'refusé','error',6000); }
        else { toast(r && r.message ? r.message : 'fait','success'); }
    }catch(e){ toast('échec : '+e.message,'error',6000); }
    await loadEvolution();
}
document.addEventListener('keydown', function(e){
    if(e.key==='Escape' && document.getElementById('ev-voile') && document.getElementById('ev-voile').classList.contains('on')) evFermer();
});
/* Le bandeau dit l'état : il ne peut pas rester sur une vérité d'il y a une heure. Il se relit
   chaque minute, mais seulement quand l'onglet est devant et qu'aucune feuille n'est ouverte —
   on ne change pas ce qu'on lit sous la main de celui qui décide. */
setInterval(function(){
    const t=document.getElementById('tab-evolution'), v=document.getElementById('ev-voile');
    if(!t || !t.classList.contains('active')) return;
    if(v && v.classList.contains('on')) return;
    evRafraichir();
}, 60000);
// Elle comptait les découvertes ouvertes pendant que la cloche comptait les
// notifications non lues : deux nombres justes, sur deux populations
// différentes, et rien pour le dire. Elle compte désormais ce qui ATTEND —
// c'est-à-dire ce sur quoi vous pouvez agir.
// FAÇADE (lot 8) : gardée pour les autres écrans et leurs bancs — un ancien nom qui renvoie.
function pfSev(s){return s==='critical'?'var(--danger)':(s==='warning'?'var(--warn)':'var(--info)');}
function pfUpdateBadge(n){
    var b=document.getElementById('pf-badge');
    if(!b) return;
    if(n>0){ b.textContent=n; b.style.display=''; b.title=n+' chose(s) en attente de votre avis'; }
    else{ b.style.display='none'; }
}
function pfPollBadge(){
    apiPost('/api/pf/tableau',{}).then(function(d){
        // Ce qui attend un avis, pas le total des anomalies : une découverte
        // sans geste proposé n'appelle aucune décision.
        pfUpdateBadge(((d&&d.attente)||[]).length);
    }).catch(function(){});
}
function _sparkline(vals,color,unit,label){
    if(!vals||!vals.length) return '<div style="font-size:10px;color:var(--txt-faint)">'+label+' : —</div>';
    var w=120,h=28,mn=Math.min.apply(null,vals),mx=Math.max.apply(null,vals);
    var rng=(mx-mn)||1, n=vals.length;
    var pts=vals.map(function(v,i){var x=(i/(n-1||1))*w; var y=h-((v-mn)/rng)*(h-4)-2; return x.toFixed(1)+','+y.toFixed(1);}).join(' ');
    var last=vals[vals.length-1];
    return '<div style="display:flex;flex-direction:column;gap:2px">'+
        '<div style="font-size:10px;color:var(--txt-faint)">'+label+' <b style="color:'+color+'">'+last+unit+'</b></div>'+
        '<svg width="'+w+'" height="'+h+'" style="display:block"><polyline points="'+pts+'" fill="none" stroke="'+color+'" stroke-width="1.5"/></svg></div>';
}
function mailLoadStatus(){
    try{ mailLoadSmtp(); }catch(e){}
    apiPost('/api/mail/status',{}).then(function(d){
        if(!d)return;
        var b=document.getElementById('mail-status-badge');
        if(b){ if(d.configured){b.textContent='configuré';b.style.color='var(--ok)';b.style.background='rgba(39,193,104,.12)';}
               else{b.textContent='non configuré';b.style.color='var(--warn)';b.style.background='rgba(255,165,2,.12)';} }
        var u=document.getElementById('mail-app-url'); if(u&&d.app_url!=null)u.value=d.app_url||'';
        var r=document.getElementById('mail-recap-on'); if(r)r.checked=(d.weekly_recap!==false);
        var dd=document.getElementById('mail-recap-day'); if(dd&&d.recap_day!=null)dd.value=String(d.recap_day);
        var hh=document.getElementById('mail-recap-hour'); if(hh&&d.recap_hour!=null)hh.value=d.recap_hour;
    }).catch(function(){});
}
function mailLoadSmtp(){
    apiPost('/api/mail/smtp',{}).then(function(d){
        if(!d)return;
        function setv(id,v){var e=document.getElementById(id); if(e&&v!=null&&v!=='')e.value=v;}
        setv('mail-smtp-host',d.smtp_host); setv('mail-smtp-port',d.smtp_port);
        setv('mail-smtp-user',d.smtp_user); setv('mail-smtp-from',d.from_addr); setv('mail-smtp-to',d.to_addrs);
        var t=document.getElementById('mail-smtp-tls'); if(t)t.checked=(d.smtp_tls!==false);
        var en=document.getElementById('mail-smtp-enabled'); if(en)en.checked=!!d.enabled;
        var p=document.getElementById('mail-smtp-pass'); if(p)p.placeholder=d.has_password?'•••••• (laisser vide = inchangé)':'mot de passe';
    }).catch(function(){});
}
function mailSaveSmtp(){
    var m=document.getElementById('mail-smtp-msg');
    var payload={save:true,
        enabled:document.getElementById('mail-smtp-enabled').checked,
        smtp_host:(document.getElementById('mail-smtp-host').value||'').trim(),
        smtp_port:parseInt(document.getElementById('mail-smtp-port').value||'587',10),
        smtp_tls:document.getElementById('mail-smtp-tls').checked,
        smtp_user:(document.getElementById('mail-smtp-user').value||'').trim(),
        from_addr:(document.getElementById('mail-smtp-from').value||'').trim(),
        to_addrs:(document.getElementById('mail-smtp-to').value||'').trim()};
    var pw=document.getElementById('mail-smtp-pass').value;
    if(pw)payload.smtp_password=pw;
    if(m){m.textContent='enregistrement…';m.style.color='var(--txt-muted)';}
    apiPost('/api/mail/smtp',payload).then(function(d){
        // Le refus PORTE SA RAISON, et reste affiché : « ✗ erreur » qui
        // s'efface en deux secondes ne laisse rien à corriger.
        if(m){
            m.textContent=(d&&d.ok)?'✓ SMTP enregistré'
                                   :('✗ '+((d&&d.error)||'erreur'));
            m.style.color=(d&&d.ok)?'var(--ok)':'var(--danger-soft)';
            if(d&&d.ok) setTimeout(function(){m.textContent='';},2500);
        }
        var p=document.getElementById('mail-smtp-pass'); if(p)p.value='';
        mailLoadStatus();
    }).catch(function(){if(m){m.textContent='✗ erreur';m.style.color='var(--danger-soft)';}});
}
function mailSaveSettings(){
    var m=document.getElementById('ntm-msg')||document.getElementById('mail-msg');
    var _au=document.getElementById('set-app-url')||document.getElementById('mail-app-url');
    var payload={app_public_url:((_au&&_au.value)||'').trim(),
                 mail_weekly_recap:document.getElementById('mail-recap-on').checked,
                 mail_recap_day:parseInt(document.getElementById('mail-recap-day').value||'0',10),
                 mail_recap_hour:parseInt(document.getElementById('mail-recap-hour').value||'8',10)};
    apiPost('/api/mail/settings',payload).then(function(d){
        if(m){m.textContent=(d&&d.ok)?'✓ enregistré':'✗ erreur';m.style.color=(d&&d.ok)?'var(--accent)':'var(--danger-soft)';setTimeout(function(){m.textContent='';},1800);}
    }).catch(function(){if(m){m.textContent='✗ erreur';m.style.color='var(--danger-soft)';}});
}
function mailTest(){
    var m=document.getElementById('ntm-msg')||document.getElementById('mail-msg'); if(m){m.textContent='envoi…';m.style.color='var(--txt-muted)';}
    apiPost('/api/mail/test',{}).then(function(d){
        // Le succes s'efface, le REFUS reste : quatre secondes ne suffisent pas
        // a lire une erreur SMTP, et c'est elle qui dit quoi corriger.
        if(m){
            m.textContent=(d&&d.ok)?('✓ envoyé à '+(d.to||'toi'))
                                   :('✗ '+((d&&d.error)||'échec'));
            m.style.color=(d&&d.ok)?'var(--ok)':'var(--danger-soft)';
            if(d&&d.ok) setTimeout(function(){m.textContent='';},4000);
        }
    }).catch(function(){if(m){m.textContent='✗ erreur';m.style.color='var(--danger-soft)';}});
}
async function mailRecapNow(){
    if(!await buConfirmer('Envoyer le récap hebdomadaire maintenant (admin + users) ?'))return;
    var m=document.getElementById('ntm-msg')||document.getElementById('mail-msg'); if(m){m.textContent='envoi du récap…';m.style.color='var(--txt-muted)';}
    apiPost('/api/mail/recap_now',{}).then(function(d){
        if(m){m.textContent=(d&&d.ok)?('✓ '+(d.sent||0)+' e-mail(s) envoyé(s)'):('✗ '+((d&&d.reason)||'échec'));m.style.color=(d&&d.ok)?'var(--ok)':'var(--danger-soft)';setTimeout(function(){m.textContent='';},4000);}
    }).catch(function(){if(m){m.textContent='✗ erreur';m.style.color='var(--danger-soft)';}});
}
function sbToggle(head){ const g=head&&head.parentElement; if(g) g.classList.toggle('open'); }
// Le même bouton sert deux gestes selon la largeur : replier la colonne quand
// il y a la place, ouvrir le tiroir quand il n'y en a pas. Deux boutons pour la
// même intention obligeraient à savoir lequel est actif.
function sbEtroit(){ return window.matchMedia('(max-width:900px)').matches; }

function sbCollapse(){
    const sb=document.getElementById('sidebar'); if(!sb) return;
    if(sbEtroit()){
        const ouvert=!sb.classList.contains('drawer-open');
        sb.classList.toggle('drawer-open', ouvert);
        const sc=document.getElementById('sb-scrim'); if(sc) sc.classList.toggle('on', ouvert);
        return;
    }
    sb.classList.toggle('collapsed');
    try{ localStorage.setItem('cass_sidebar', sb.classList.contains('collapsed')?'1':'0'); }catch(e){}
}
function fermerTiroir(){
    const sb=document.getElementById('sidebar'); if(sb) sb.classList.remove('drawer-open');
    const sc=document.getElementById('sb-scrim'); if(sc) sc.classList.remove('on');
}

// ── Menu du compte ───────────────────────────────────────────────────────
function umSegments(){
    const z=document.getElementById('um-seg'); if(!z) return;
    z.innerHTML=TH_ETATS.map(function(x){
        return '<button data-th="'+x[0]+'" aria-pressed="false" title="'+x[1]+'" '+
          'onclick="appliquerTheme(\''+x[0]+'\')">'+x[2]+'<span>'+x[1]+
          '</span></button>'; }).join('');
    appliquerTheme(themeActuel());
}

function basculerCompte(e){
    if(e) e.stopPropagation();
    const m=document.getElementById('usermenu'), b=document.getElementById('av-btn');
    if(!m) return;
    const ouvert=!m.classList.contains('on');
    m.classList.toggle('on', ouvert);
    if(b) b.setAttribute('aria-expanded', ouvert?'true':'false');
    if(ouvert){ remplirCompte(); umSession(); allegeAppliquer(); }
}
function fermerCompte(){
    const m=document.getElementById('usermenu'), b=document.getElementById('av-btn');
    if(m) m.classList.remove('on');
    if(b) b.setAttribute('aria-expanded','false');
}

// Le portrait vient de FastPanel quand il en stocke un ; sinon les initiales
// sur une couleur dérivée du nom — jamais une image générique qui laisserait
// croire à un portrait absent.
ETAT.moi._monPortrait=null; ETAT.moi._monProfil=null;

function _umPortrait(){
    // Le portrait n'était posé qu'à l'OUVERTURE du menu : le bandeau montrait
    // « ·· » en permanence. Il est gardé en mémoire et reposé partout.
    ['av-pic','av-pic-grand','vr-pic','ac-portrait'].forEach(function(id){
        const el=document.getElementById(id); if(!el) return;
        if(ETAT.moi._monPortrait){
            if(!el.querySelector('img'))
                el.innerHTML='<img src="'+escapeAttr(ETAT.moi._monPortrait)+'" alt="" '
                    +'style="width:100%;height:100%;object-fit:cover;border-radius:inherit">';
        } else if(ETAT.moi._mesInitiales && !el.querySelector('img')){
            el.textContent=ETAT.moi._mesInitiales;
        }
    });
}

async function remplirCompte(force){
    const mets=function(id,v){ const el=document.getElementById(id); if(el) el.textContent=v; };
    try{
        const d=(ETAT.moi._monProfil && !force) ? ETAT.moi._monProfil
                                             : await apiPost('/api/me',{});
        ETAT.moi._monProfil=d;
        const mail=String(d.user||'').trim();
        ETAT.moi._monNom = nomLisible(d) || '';
        // LES INITIALES DU NOM, PAS DE L'ADRESSE (24-09) : « administration@… » donnait « AD » dans le bandeau
        // quand Mon Bureau lisait celles du nom affiché. Le même calcul partout ; l'adresse n'est qu'un repli.
        ETAT.moi._mesInitiales=((ETAT.moi._monNom && typeof _cnInitiales==='function') ? _cnInitiales(ETAT.moi._monNom)
                                : (mail.replace(/[^A-Za-z0-9]/g,'').slice(0,2)||'··')).toUpperCase();
        mets('um-nom', ETAT.moi._monNom || '—');
        mets('um-mail', mail || '—');
        mets('vr-nom', ETAT.moi._monNom || mail || '—');
        mets('um-role', String(d.role_label || '').trim()
                       || (d.is_admin ? 'Administrateur' : 'Utilisateur'));
        const n=(d.sites||[]).length, h=(d.sites_herites||[]).length;
        mets('um-sites', h ? (n + ' (dont ' + h + ' via le panneau)') : String(n));
        mets('um-fp', d.fp_account || 'aucun');
        _umPortrait();
        if(d.photo && !ETAT.moi._monPortrait){
            const ph=await apiPost('/api/me/photo',{}).catch(function(){ return {ok:false}; });
            if(ph.ok && ph.photo){ ETAT.moi._monPortrait=ph.photo; _umPortrait(); }
        }
        if(d.fp_account && !ETAT.moi._monPortrait){
            const a=await apiPost('/api/fp/user/avatar',{username:d.fp_account})
                .catch(function(){ return {ok:false}; });
            if(a.ok && a.url){ ETAT.moi._monPortrait=a.url; _umPortrait(); }
        }
    }catch(e){ /* le menu reste utilisable sans ces détails */ }
}

// ── L'état de la session ────────────────────────────────────────────────────
function _umDuree(iso){
    const d=new Date(String(iso||'').replace(' ','T')+'Z');
    if(isNaN(d)) return '—';
    const m=Math.max(0, Math.round((Date.now()-d.getTime())/60000));
    if(m<60) return 'il y a '+m+' min';
    if(m<2880) return 'il y a '+Math.floor(m/60)+' h '+(m%60);
    return 'il y a '+Math.floor(m/1440)+' j';
}
async function umSession(){
    const mets=function(id,v){ const el=document.getElementById(id); if(el) el.textContent=v; };
    try{
        const d=await apiPost('/api/me/sessions',{});
        const l=(d&&d.sessions)||[];
        const moi=l.find(function(x){ return x.current || x.courante; }) || l[0] || {};
        mets('um-depuis', _umDuree(moi.created));
        mets('um-ou', [(moi.ip||'?'), (moi.agent||'')].filter(Boolean).join(' · ') || '—');
        const autres=l.length ? l.length-1 : 0;
        const w=document.getElementById('um-autres');
        if(w){
            w.style.display=autres?'flex':'none';
            mets('um-autres-n', autres+' autre'+(autres>1?'s':'')+' session'+
                                (autres>1?'s':'')+' ouverte'+(autres>1?'s':'')+' ailleurs');
        }
    }catch(e){}
    try{
        const i=await apiGet('/api/server_info');
        const u=i&&(i.cassandra_uptime_secs!=null ? i.cassandra_uptime_secs : null);
        if(u!=null){
            const j=Math.floor(u/86400), h=Math.floor((u%86400)/3600), mn=Math.floor((u%3600)/60);
            mets('um-uptime', 'en ligne depuis '+(j ? (j+' j '+h+' h') : h ? (h+' h '+mn+' min') : (Math.max(1, mn)+' min')));
        } else { mets('um-uptime', '—'); }
    }catch(e){}
}
async function umFermerAutres(){
    if(!await buConfirmer('Fermer toutes les autres sessions ?\n\nLa vôtre est conservée. '+
                'Une session révoquée ne se rend pas.')) return;
    try{
        const d=await apiPost('/api/me/sessions/revoke_others',{});
        if(typeof showToast==='function')
            showToast(((d&&d.revoked)||0)+' session(s) fermée(s)','success',3000);
        umSession();
    }catch(e){}
}
function umRaccourcis(){
    fermerCompte();
    buDire('RACCOURCIS\n\n'+
          'Alt + ←     revenir à l\u2019écran précédent\n'+
          'Alt + →     avancer\n'+
          'Échap       fermer un panneau ou une fenêtre\n\n'+
          'Les deux flèches sont dans le bandeau, à côté du menu.');
}

// ── Verrouiller l'écran ─────────────────────────────────────────────────────
// La session reste OUVERTE : Cassandra continue de surveiller et les tâches
// planifiées continuent. Se déconnecter, lui, ferme tout — ce n'est pas le
// geste qu'on veut en quittant son bureau cinq minutes.
function umVerrouiller(){
    fermerCompte();
    const v=document.getElementById('verrou'); if(!v) return;
    _umPortrait();
    const f=document.getElementById('vr-fb'); if(f) f.textContent='';
    const m=document.getElementById('vr-mdp'); if(m) m.value='';
    v.style.display='flex';
    try{ sessionStorage.setItem('cass_verrou','1'); }catch(e){}
    setTimeout(function(){ if(m) m.focus(); }, 60);
}
async function umDeverrouiller(){
    const m=document.getElementById('vr-mdp'), f=document.getElementById('vr-fb');
    if(!m) return;
    if(f) f.textContent='';
    try{
        const d=await apiPost('/api/me/deverrouiller',{password:m.value});
        if(d&&d.ok){
            document.getElementById('verrou').style.display='none';
            try{ sessionStorage.removeItem('cass_verrou'); }catch(e){}
            m.value='';
            return;
        }
    }catch(e){}
    if(f) f.textContent='Mot de passe incorrect.';
    m.value=''; m.focus();
}

