async function ntSourdinePoser(portee, cible, heures){
    try{
        const d=await apiPost('/api/notif/sourdine',{portee:portee, cible:cible, heures:heures});
        if(typeof showToast==='function')
            showToast(d&&d.ok?(d.fin?('En sourdine jusqu’au '+ntHeure(d.fin)+' le '+String(d.fin).slice(0,10)):'Sourdine levée'):((d&&d.reason)||'échec'),
                      d&&d.ok?'success':'error',4000);
        if(ETAT.notes._nt.vue==='reglages'){ ETAT.notes._nt.reg=null; ntRendre(); }
    }catch(e){}
}

// ── Réglages : machine et personne, dans le panneau ────────────────────────
