async function cronLoad(){
    const list = document.getElementById('cron-list');
    if(!list) return;
    list.innerHTML = '<div class="empty-state">Chargement…</div>';
    try{
        const d = await apiPost('/api/crons/unified', {});
        _cronJobs     = d.jobs || [];
        _cronProjects = d.projects || [];
        cronSummary(d.counts || {});
        cronRender();
        cronBadge();
        crMaintEtat();
        // La fiche ouverte se recharge, sinon on lit un état périmé après une
        // exécution ou un changement de réglage.
        if(ETAT.crons._crSel && _cronJobs.some(function(j){ return j.ref===ETAT.crons._crSel; }))
            crFiche(ETAT.crons._crSel);
        else if(_cronJobs.length) crFiche(_cronJobs[0].ref);
        cronAudit();
    }catch(e){
        list.innerHTML = '<div class="empty-state">Erreur de chargement : ' + escapeHtml(e.message) + '</div>';
    }
}
// L'ancien nom reste appelé par switchTab et par d'anciens raccourcis.
async function loadCrons(){ return cronLoad(); }

function cronSummary(counts){
    const box = document.getElementById('cron-summary');
    if(!box) return;
    box.innerHTML = Object.keys(_CRON_STATE).map(function(k){
        const s = _CRON_STATE[k];
        return '<div class="cr-et" style="--c:'+s.c+'" aria-pressed="false" '+
          'onclick="cronFilterState(\''+k+'\')" title="Cliquer pour filtrer">'+
          '<div class="n">'+(counts[k]||0)+'</div>'+
          '<div class="l">'+s.l+'</div></div>';
    }).join('') +
      '<div class="cr-et" style="--c:var(--txt-muted)" onclick="cronFilterState(\'\')">'+
      '<div class="n">'+(counts.total||0)+'</div><div class="l">au total</div></div>';
    const n = document.getElementById('cr-n');
    if(n) n.textContent = (counts.total||0) + ' tâches';
}

// Deux défauts qui n'apparaissent sur aucune ligne : une collision se voit en
// comparant les tâches entre elles, une sauvegarde absente ne se voit nulle part.
async function cronAudit(){
    const box = document.getElementById('cron-audit');
    if(!box) return;
    try{
        const d = await apiPost('/api/crons/audit', {});
        const cols = d.collisions || [], miss = d.missing_backups || [];
        let chev = [], der = [];
        try{
            const c = await apiPost('/api/crons/chevauchements', {});
            chev = (c && c.chevauchements) || [];
        }catch(e){}
        // Une dérive de durée ne déclenche aucune alerte puisque rien n'échoue :
        // c'est la panne qu'on découvre le jour où la nuit ne suffit plus.
        (_cronJobs||[]).forEach(function(j){
            const x = _crDerive((ETAT.crons._crRuns||{})[j.ref] || []);
            if(x) der.push({ref:j.ref, label:j.description||j.command||j.ref, f:x.facteur,
                            a:x.avant, b:x.apres});
        });
        if(!cols.length && !miss.length && !chev.length && !der.length){
            box.style.display = 'none'; box.innerHTML = ''; return; }
        let h = '';
        chev.forEach(function(c){
            h += '<div class="cr-al" style="--c:var(--danger)"><div class="tx">'+
              '<b>« '+escapeHtml(String(c.label).slice(0,50))+' » se chevauche avec elle-même'+
              '</b><span>'+c.duree_min+' min en moyenne pour un créneau toutes les '+
              c.intervalle_min+' min. Deux copies travaillent en même temps sur les mêmes '+
              'fichiers.'+(c.verrou?' Le verrou est actif : les démarrages en trop sont '+
              'écartés.':' <b>Aucun verrou n\u2019est posé.</b>')+'</span></div>'+
              '<button class="btn-x mini" onclick="crFiche(\''+escapeAttr(c.ref)+
              '\')">Ouvrir</button></div>';
        });
        der.forEach(function(x){
            h += '<div class="cr-al" style="--c:var(--warn)"><div class="tx">'+
              '<b>« '+escapeHtml(String(x.label).slice(0,50))+' » a vu sa durée multipliée '+
              'par '+x.f+'</b><span>'+_crMs(x.a)+' au début de la période, '+_crMs(x.b)+
              ' en fin. Rien n\u2019a échoué — c\u2019est justement pour cela que personne '+
              'ne l\u2019aurait vu.</span></div>'+
              '<button class="btn-x mini" onclick="crFiche(\''+escapeAttr(x.ref)+
              '\')">Ouvrir</button></div>';
        });
        cols.forEach(c => {
            h += `<div class="cr-al" style="--c:var(--warn)"><div class="tx">
              <b>${c.count} tâches lourdes démarrent à ${escapeHtml(c.at)}</b>
              <span>${c.jobs.map(x => escapeHtml(x.label)).join(' · ')}<br>
              Étalement proposé : ${(c.spread||[]).map(p =>
                `${escapeHtml(p.label.slice(0,28))} → <code>${escapeHtml(p.at)}</code>`
              ).join(' · ')}</span></div></div>`;
        });
        miss.forEach(p => {
            h += `<div class="cr-al" style="--c:var(--danger)"><div class="tx">
              <b>Aucune sauvegarde planifiée pour « ${escapeHtml(p.name)} »</b>
              <span>${p.domain ? escapeHtml(p.domain) + ' — ' : ''}le projet n\u2019est
              couvert par rien.</span></div>
              <button class="btn-x mini" onclick="cronNewForProject(${p.id},'${
                escapeHtml(p.name).replace(/'/g,'')}')">En planifier une</button></div>`;
        });
        box.innerHTML = h;
        box.style.display = 'block';
    }catch(e){ box.style.display = 'none'; }
}

