    const v = function(i, x){ const e = document.getElementById(i); if (e) e.value = x; };
    v('sc-pf-id', id); v('sc-pf-nom', r.nom); v('sc-pf-ports', r.ports); v('sc-pf-proto', r.proto || 'TCP'); v('sc-pf-sens', r.sens || 'INPUT');
    v('sc-pf-pol', r.politique || 'DROP'); v('sc-pf-src', (r.sources || '').split(',').filter(Boolean).join(', '));
