        const n = sciEl('text', {x: cx, y: yr + (i < 3 ? 5 : 6), 'text-anchor': 'middle', class: 'val', style: i < 3 ? 'font-size:13px' : 'font-size:16px;fill:var(--surface-solid)'}, s); n.textContent = a.services.length;
