// ══════════════════════════════════════════════════════════
// HISTORIQUE — registre de métriques, marqueurs, corrélation
// ══════════════════════════════════════════════════════════
const MX = {list:[], cur:'cpu', period:'24h', periods:{}, charts:{}, vue:'verdict', seq:0, demande:null, evos:[], evo:null,
            habitude_jours:21};
const _MX_COUL = ['--accent','--violet','--ok','--warn','--info','--danger-soft','--accent-soft','--rose'];
// Un canvas ne résout pas « var(--accent) » : les couleurs se lisent dans les jetons du thème.
// Pour un attribut style, le jeton s'écrit tel quel : la CSS le résout, elle.
const mxT=n=>'var('+n+')';
function mxCoul(nom){ return (getComputedStyle(document.documentElement).getPropertyValue(nom)||'').trim()||'#0a726b'; }
function mxE(t){ if(t==null) return ''; return String(t).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
const _MX_JOURS=['dim.','lun.','mar.','mer.','jeu.','ven.','sam.'];

// L'ouverture : la liste des sources, puis la vue demandée (une courbe si un autre écran l'a
// demandée, le verdict sinon). Un jeton de séquence par chargement : la réponse d'un clic
// précédent, arrivée en retard, n'écrase plus celle du dernier clic.
/* ═══ LE SENSORIUM (08-10) ═══════════════════════════════════════════════════════════════ */
const SN = {etat:null, vue:'maintenant', fam:null};
const SN_FAMILLES = [
  ['system','Système','system.'], ['ressources','Ressources','cpu.|ram.|swap.|load.|disk.|montage.'], ['service','Services','service.|systemd.'],
  ['docker','Conteneurs','docker.|conteneur_ressources.|image.'], ['web','Sites','web.'], ['controle','Contrôles de bout en bout','controle.'],
  ['ssl','Certificats','ssl.'], ['sauvegarde','Sauvegardes','sauvegarde.'], ['prevision','Ce qui va arriver','prevision.'],
  ['flotte','Flotte','fleet.|machine.'], ['config','Config de Cassandra','config.'], ['logiciel','Logiciels','logiciel.'],
  ['reseau','Réseau','interface.|port.'], ['stockage','Stockage','stockage.'], ['securite','Sécurité','security.'],
  ['maj','Mises à jour','maj.'], ['courriel','Courriel','courriel.|domaine_courriel.'], ['acces','Accès et pare-feu','ssh.|cle_ssh.|pare_feu.|fail2ban.|prison.'],
  ['cron','Tâches planifiées','cron.'], ['fastpanel','FastPanel','fastpanel.'], ['erreurs','Erreurs des journaux','erreurs.|journaux.'],
  ['certbot','Renouvellement des certificats','certbot.'], ['box','La box','box.|dns_local'], ['outils','Outils de sécurité','outil_secu.'], ['tailnet','Tailnet','tailnet.'], ['capteur','Capteurs','capteur.'], ['sante','Santé','health.']
];
function _snE(t){ return (typeof flE==='function') ? flE(t) : String(t==null?'':t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function _snFam(wk){ for(const f of SN_FAMILLES){ if(f[2].split('|').some(p=>wk.startsWith(p))) return f[0]; } return 'autre'; }
function _snAge(ts){
  if(!ts) return '?';
  let t = String(ts); if(!/[zZ]$|[+-]\d\d:?\d\d$/.test(t)) t = t.replace(' ','T');   // sans « Z » : heure locale (ancien format)
  const d = new Date(t); if(isNaN(d)) return '?';
  const s = Math.max(0, (Date.now() - d.getTime())/1000);
  return s<60 ? Math.round(s)+' s' : s<3600 ? Math.round(s/60)+' min' : s<86400 ? Math.round(s/3600)+' h' : Math.round(s/86400)+' j';
}
function _snCauses(r){ try{ const d = r.detail ? JSON.parse(r.detail) : null; return (d && d.causes_probables) || []; }catch(e){ return []; } }
function _snNom(wk){ const i = wk.indexOf('.'); return i>=0 ? wk.slice(i+1) : wk; }
// Le libellé d'une clé que le serveur n'a pas étiquetée (corrélations) : celui d'une ligne connue, sinon la clé.
function _snLib(wk){ const r = ((SN.etat&&SN.etat.rows)||[]).find(x=>x.wkey===wk); return (r&&r.libelle) || _snNom(wk); }
// Les détails d'une machine de la flotte, en mots : « disque C: 67 % », « mises à jour il y a 2 j ».
const SN_MACH = {os:'système', antivirus:'antivirus', charge:'charge', mises_a_jour:'mises à jour', services_en_echec:'services en échec', echecs_au_demarrage:'échecs au démarrage'};
function _snMach(cle){ const k = cle.replace(/^disque\./,''); return cle.startsWith('disque.') ? 'disque '+k : (SN_MACH[cle] || cle.replace(/_/g,' ')); }
