function snRail(){
  const el = document.getElementById('sn-list'); if(!el) return;
  const rows = (SN.etat && SN.etat.rows) || [];
  const par = {}; rows.forEach(r=>{ const f=_snFam(String(r.wkey||'')); (par[f]=par[f]||{n:0,w:0}); par[f].n++; if(r.severity==='warning') par[f].w++; });
  let h = '';
  SN_FAMILLES.forEach(([k,lib])=>{ const c = par[k]; if(!c) return;
    h += `<button class="mx-item${SN.fam===k?' on':''}" onclick="SN.fam='${k}';SN.vue='famille';snRail();snRendre()"><span class="mx-dot ${c.w?'warn':'ok'}"></span><span class="nm">${_snE(lib)}</span><span class="mx-st${c.w?' off':''}">${c.w?c.w+' ⚠':c.n}</span></button>`; });
  el.innerHTML = h || '<div class="mx-fam">rien de relevé</div>';
  const nW = rows.filter(r=>r.severity==='warning').length;
  const b = document.getElementById('sn-badge'); if(b){ b.style.display = nW?'':'none'; b.textContent = nW; }
}
function _snLigne(r, avecFam){
  const wk = String(r.wkey||''), w = r.severity==='warning', causes = _snCauses(r), a = r.acquit;
  const gestes = (r.gestes||[]).map(g=>`<button class="mx-btn" onclick='snReparer(${JSON.stringify(wk)}, ${JSON.stringify(g.id)}, ${JSON.stringify(g.libelle)})'>${_snE(g.libelle)}</button>`).join('');
  const acc = w ? `<button class="mx-btn" onclick='snAccepter(${JSON.stringify(wk)})' title="Je sais, c'est normal : se taire jusqu'à l'échéance (revient si ça empire)">Accepter…</button>`
           : (a ? `<button class="mx-btn" onclick='snRetirerAcquit(${JSON.stringify(wk)})'>Ne plus accepter</button>` : '');
  return `<div class="mx-row"><span class="mx-dot ${w?'warn':(a?'':'ok')}"></span>
    <div class="mx-rt"><b style="cursor:pointer" title="${_snE(wk)} — son histoire sur 30 jours" onclick='snHisto(${JSON.stringify(wk)})'>${_snE(r.libelle||_snNom(wk))}${a?` <span class="mx-pill">acceptée</span>`:''}</b><span>${_snE(r.value)}</span>
    ${a?`<span>acceptée : ${_snE(a.raison||'sans raison')}${a.jusqua?' · jusqu\'au '+_snE(String(a.jusqua).slice(0,10)):''}</span>`:''}
    ${causes.length?`<span style="color:var(--warn)">cause probable : ${_snE(causes[0])}${causes.length>1?` <span class="mx-st">(+${causes.length-1})</span>`:''}</span>`:''}</div>
    <div class="mx-gest"><span class="mx-st" title="${_snE(r.observed_at||'')}">il y a ${_snAge(r.observed_at)}</span>${gestes}${acc}</div></div>`;
}
async function snTemoin(){
  const m = prompt("Sur quelle machine Linux de la flotte installer le témoin ?\n\nIl vérifie chaque minute que ce serveur répond, et vous écrit sur Telegram s'il se tait 10 minutes (puis retire le message à son retour). Le jeton du robot Telegram y sera copié, lisible par son seul propriétaire.", "athena");
  if(!m) return;
  const r = await apiPost('/api/sensorium/temoin', {machine:m});
  alert(r && r.ok ? ('Témoin installé sur '+r.machine+'.\nIl surveille '+r.url_lan+' et '+r.url_public+'.') : ('Échec : '+((r&&(r.erreur||r.detail))||'?')));
}
async function snHisto(wk){
  const page = document.getElementById('sn-page'); if(!page) return;
  let r; try{ r = await apiPost('/api/sensorium/historique', {wkey:wk}); }catch(e){ r = {ok:false}; }
  if(!r || !r.ok){ return; }
  const h = r.historique||[], a = r.actuelle||{};
  page.innerHTML = `<section class="mx-sec"><div class="mx-eyebrow"><a style="cursor:pointer" onclick="snRendre()">← retour</a> · ${_snE(_snLib(wk))}</div>
    <div class="mx-verdict"><span class="mx-vmark ${a.severity==='warning'?'':'stable'}"></span><div><p class="mx-vtitle">${_snE(a.value||'—')}</p>
    <p class="mx-vsub">${r.disponibilite_30j!=null?'Disponibilité sur 30 jours : <b>'+_snE(r.disponibilite_30j)+' %</b> · ':''}${h.length} changement${h.length>1?'s':''} en 30 jours</p></div></div></section>
    <section class="mx-sec"><div class="mx-eyebrow">Son histoire</div><div class="mx-rows">${h.map(c=>`<div class="mx-row"><span class="mx-dot ${c.severity==='warning'?'warn':'ok'}"></span><div class="mx-rt"><b>${_snE({added:'apparue',removed:'disparue',modified:'a changé'}[c.change_type]||c.change_type)}</b><span>${_snE(c.new_value||c.old_value||'')}</span>${c.old_value&&c.new_value?`<span class="mx-st">avant : ${_snE(c.old_value)}</span>`:''}</div><span class="mx-st">${_snE(String(c.ts||'').slice(0,16).replace('T',' '))}</span></div>`).join('') || '<div class="mx-vsub">Rien n\'a changé en 30 jours.</div>'}</div></section>`;
}
async function snAccepter(wk){
  const raison = await buSaisir("Pourquoi « "+_snLib(wk)+" » est-elle normale ?\n(elle se taira, et reviendra si son chiffre empire)", "");
  if(raison===null || raison===undefined) return;
  const jours = await buSaisir("Pendant combien de jours ? (0 = sans échéance)", "30");
  if(jours===null || jours===undefined) return;
  const r = await apiPost('/api/sensorium/accepter', {wkey:wk, raison:raison, jours:parseInt(jours||'30',10)||0});
  if(!r || !r.ok){ buDire('Impossible : '+((r&&r.erreur)||'?')); return; }
  snEntrer();
}
async function snRetirerAcquit(wk){ await apiPost('/api/sensorium/retirer', {wkey:wk}); snEntrer(); }
async function snReparer(wk, geste, libelle){
  if(!await buConfirmer(libelle+' ?\n\nLe geste passe par le catalogue sécurisé de Cassandra.')) return;
  const r = await apiPost('/api/sensorium/reparer', {wkey:wk, geste:geste, confirme:true});
  buDire((r&&r.ok?'Fait : ':'Échec : ')+((r&&(r.geste||r.erreur))||'')+(r&&r.resultat&&r.resultat.sortie?'\n\n'+String(r.resultat.sortie).slice(0,600):''));
  setTimeout(snEntrer, 4000);
}
function snRendre(){
  const page = document.getElementById('sn-page'); if(!page) return;
  const E = SN.etat;
  if(!E || !E.ok){ page.innerHTML = `<div class="mx-sec"><div class="mx-verdict"><span class="mx-vmark panne"></span><div><p class="mx-vtitle">Le sensorium ne répond pas</p><p class="mx-vsub">${_snE((E&&E.error)||'')}</p></div></div></div>`; return; }
  const rows = E.rows||[];
  if(SN.vue==='famille' && SN.fam){
    const lib = (SN_FAMILLES.find(f=>f[0]===SN.fam)||[])[1]||SN.fam;
    const sel = rows.filter(r=>_snFam(String(r.wkey||''))===SN.fam).sort((a,b)=>(b.severity==='warning')-(a.severity==='warning') || String(a.wkey).localeCompare(String(b.wkey)));
    page.innerHTML = `<section class="mx-sec"><div class="mx-eyebrow">${_snE(lib)} · ${sel.length} relevé${sel.length>1?'s':''}</div><div class="mx-rows">${sel.map(r=>_snLigne(r,false)).join('')}</div></section>`;
    return;
  }
  if(SN.vue==='changements'){
    const ch = E.changes||[], co = E.correlations||[];
    page.innerHTML = (co.length?`<section class="mx-sec"><div class="mx-eyebrow">Alertes et leur cause probable</div><div class="mx-rows">${co.map(c=>{ let cs=[]; try{cs=JSON.parse(c.causes||'[]');}catch(e){}
        return `<div class="mx-row"><span class="mx-dot warn"></span><div class="mx-rt"><b>${_snE(_snLib(String(c.entite||'')))}</b><span>${_snE(c.alerte)}</span>${cs.map(x=>`<span>↳ ${_snE(x)}</span>`).join('')}</div><span class="mx-st">${_snE(String(c.ts||'').slice(0,16).replace('T',' '))}</span></div>`; }).join('')}</div></section>`:'')
      + `<section class="mx-sec"><div class="mx-eyebrow">Derniers changements</div><div class="mx-rows">${ch.map(c=>`<div class="mx-row"><span class="mx-dot ${c.severity==='warning'?'warn':''}"></span><div class="mx-rt"><b>${_snE(c.entity_name)} <span class="mx-pill">${_snE({added:'apparu',removed:'disparu',modified:'changé'}[c.change_type]||c.change_type)}</span></b><span>${_snE(c.new_value||c.old_value||'')}</span></div><span class="mx-st">${_snE(String(c.ts||'').slice(5,16).replace('T',' '))}</span></div>`).join('') || '<div class="mx-vsub">Aucun changement relevé.</div>'}</div></section>`;
    return;
  }
  if(SN.vue==='capteurs'){
    const cap = rows.filter(r=>String(r.wkey||'').startsWith('capteur.'));
    page.innerHTML = `<section class="mx-sec"><div class="mx-eyebrow">Les capteurs eux-mêmes · ${cap.filter(r=>r.severity==='warning').length} en défaut</div><p class="mx-vsub" style="margin:0">Un capteur en panne ou muet ne mesure plus : ce qu'il avait relevé vieillit sans le dire. On le dit ici.</p><div class="mx-rows">${cap.map(r=>_snLigne(r,false)).join('') || '<div class="mx-vsub">Pas encore de santé des capteurs (premier cycle en cours).</div>'}</div></section>`;
    return;
  }
  // MAINTENANT : le verdict, ce qui demande un geste, ce qui va arriver, les chiffres clés
  const alertes = rows.filter(r=>r.severity==='warning' && !String(r.wkey).startsWith('capteur.'));
  const capKO = rows.filter(r=>r.severity==='warning' && String(r.wkey).startsWith('capteur.'));
  const prev = rows.filter(r=>String(r.wkey).startsWith('prevision.'));
  const get = k => (rows.find(r=>r.wkey===k)||{}).value;
  const titre = alertes.length ? `${alertes.length} point${alertes.length>1?'s':''} demande${alertes.length>1?'nt':''} un regard` : 'Tout ce qui est mesuré va bien';
  const kpi = (lib, v, em) => v ? `<div class="mx-kpi"><span>${_snE(lib)}</span><b>${_snE(v)}</b>${em?`<em>${_snE(em)}</em>`:''}</div>` : '';
  const sante = String(get('health.score')||''), sI = sante.indexOf(' · ');   // le score en grand, le pourquoi en petit
  page.innerHTML =
    `<section class="mx-sec"><div class="mx-verdict"><span class="mx-vmark ${alertes.length?'':'stable'}"></span><div><p class="mx-vtitle">${titre}</p>
      <p class="mx-vsub">${_snE(get('system.hostname')||'')} · ${_snE(get('system.os')||'')} · allumée depuis ${_snE(get('system.uptime')||'?')} · ${rows.length} relevés${E.source!=='collecteur'?' · <b>'+_snE(E.source)+'</b>':''}${capKO.length?` · <a style="color:var(--warn);cursor:pointer" onclick="snVue('capteurs')">${capKO.length} capteur${capKO.length>1?'s':''} en défaut</a>`:''}</p></div></div>
      <div class="mx-kpis">${kpi('Santé', sI>0 ? sante.slice(0, sI) : sante, sI>0 ? sante.slice(sI+3) : '')}${kpi('Disque /', get('disk./.usage'))}${kpi('RAM', get('ram.usage'))}${kpi('Charge', get('load.1m'), get('cpu.load')?'CPU '+get('cpu.load'):'')}${kpi('Température', get('system.temperature'))}${kpi('Mises à jour', (get('maj.paquets')||'').split(',')[0])}</div></section>`
    + (alertes.length?`<section class="mx-sec"><div class="mx-eyebrow">Ce qui demande un regard</div><div class="mx-rows">${alertes.map(r=>_snLigne(r,true)).join('')}</div></section>`:'')
    + (prev.length?`<section class="mx-sec"><div class="mx-eyebrow">Ce qui va arriver</div><div class="mx-rows">${prev.map(r=>_snLigne(r,false)).join('')}</div></section>`:'')
    + `<section class="mx-sec"><div class="mx-eyebrow">La flotte</div><div class="mx-rows">${rows.filter(r=>String(r.wkey).startsWith('fleet.')).map(r=>{
          const m = String(r.wkey).slice(6), det = rows.filter(x=>String(x.wkey).startsWith('machine.'+m+'.') && !String(x.wkey).endsWith('.sonde'));
          const w = r.severity==='warning' || det.some(x=>x.severity==='warning');
          return `<div class="mx-row"><span class="mx-dot ${w?'warn':'ok'}"></span><div class="mx-rt"><b>${_snE(m)}</b><span>${_snE(r.value)}${det.length?' · '+det.slice(0,4).map(x=>{ const c=String(x.wkey).split('.').slice(2).join('.'), v=String(x.value||'');
            return _snE(_snMach(c))+' '+_snE(c==='mises_a_jour' ? v.replace(/^dernière mise à jour\s*/,'') : v); }).join(' · '):''}</span></div><span class="mx-st">il y a ${_snAge(r.observed_at)}</span></div>`; }).join('') || '<div class="mx-vsub">Aucune machine relevée.</div>'}</div></section>`;
}

async function mxEntrer(){
    const box=document.getElementById('mx-list'); if(!box) return;
    if(!MX.list.length) box.innerHTML='<div style="padding:10px;font-size:11px;color:var(--txt-faint)">Chargement…</div>';
    try{
        const d=await apiPost('/api/mesures/sources',{});
        MX.list=d.metrics||[]; MX.periods=d.periods||{}; MX.habitude_jours=d.habitude_jours||21;
    }catch(e){ box.innerHTML='<div style="padding:10px;font-size:11px;color:var(--danger-soft)">Liste des mesures indisponible : '+mxE(e.message||e)+'</div>'; }
    if(MX.demande){ const k=MX.demande; MX.demande=null; mxOpen(k); }
    else mxVue(MX.vue||'verdict');
}
function mxVue(v){ MX.vue=v; if(typeof navSous==='function') navSous('mxVue', v); mxRenderList(); mxCharger(); }
function mxOpen(k){ MX.cur=k; MX.vue='courbe'; if(typeof navSous==='function') navSous('mxOpen', k); mxRenderList(); mxCharger(); }
function mxPeriod(p){ MX.period=p; mxCharger(); }

function mxRenderList(){
    const box=document.getElementById('mx-list'); if(!box) return;
    const scene=(MX.vue==='courbe'&&MX.cur==='site_up')?'sites':MX.vue;
    document.querySelectorAll('.mx-scene').forEach(b=>b.classList.toggle('on', b.dataset.vue===scene));
    const fam={};
    MX.list.forEach(m=>{ if(m.nature==='etat') return; (fam[m.family]=fam[m.family]||[]).push(m); });
    box.innerHTML=Object.keys(fam).map(f=>`<div class="mx-fam">${mxE(f)}</div>`+fam[f].map(m=>{
        let dot='', st='', cls='';
        if(m.etat==='a_jour'){ dot='ok'; if(m.kind==='gauge'&&!m.habitude_connue){ st='habitude dans '+(m.habitude_dans_jours||'?')+' j'; cls='young'; } }
        else if(m.etat==='muette'){ dot='warn'; st='sans nouvelles'; cls='off'; }
        else if(m.etat==='rien_a_signaler'){ dot='ok'; st='rien à signaler'; }
        else if(m.etat==='non_configuree'){ st='non configurée'; cls='off'; }
        else if(m.etat==='jamais_utilisee'){ st='jamais utilisée'; }
        else { st=m.etat_texte||'aucune source'; }
        const on=(MX.vue==='courbe'&&m.key===MX.cur);
        return `<button class="mx-item${on?' on':''}" onclick="mxOpen('${mxE(m.key)}')" title="${mxE(m.desc||'')}"><span class="mx-dot ${dot}"></span><span class="nm">${mxE(m.label)}</span>${st?`<span class="mx-st ${cls}">${mxE(st)}</span>`:''}</button>`;
    }).join('')).join('');
}

async function mxCharger(){
    const p=document.getElementById('mx-page'); if(!p) return;
    const seq=++MX.seq;
    p.innerHTML='<div class="empty-state" style="padding:40px">Chargement…</div>';
    try{
        if(MX.vue==='verdict') await mxVerdict(seq);
        else if(MX.vue==='avap') await mxAvantApres(seq);
        else if(MX.vue==='prevision') await mxPrevision(seq);
        else if(MX.vue==='vides') mxVides();
        else await mxCourbe(seq);
    }catch(e){
        if(seq!==MX.seq) return;
        p.innerHTML='<div class="mx-sec"><b>Échec du chargement.</b><span style="color:var(--txt-soft);word-break:break-word">'+mxE(e&&e.message?e.message:String(e))+'</span></div>';
        console.error('[HISTORIQUE]', MX.vue, MX.cur, MX.period, e);
    }
}

// ── Les gestes : chacun mène à un écran qui existe déjà. Aucun bouton inventé. ─────────
function mxGeste(g){
    const f=g.f, a=g.a;
    if(f==='site'){ switchTab('mysites'); setTimeout(()=>{ if(typeof stOpen==='function') stOpen(a); },80); }
    else if(f==='flotte'){ FL2.demande=a||''; switchTab('fleet'); }
    else if(f==='journal'){ JR.demande={f:'jrTimeline',a:a||undefined}; switchTab('journal'); }
    else if(f==='courbe'){ mxOpen(a); }
    else if(f==='prevision'){ mxVue('prevision'); }
    else if(f==='evolution'){ switchTab('evolution'); setTimeout(()=>{ if(typeof evChoisir==='function') evChoisir(a); },120); }
    else if(f==='aujourdhui'){ switchTab('bureau'); }
    else if(f==='chat'){ sendQuickFix(a||'Qu\'est-ce qui prend de la place sur le disque ?'); }
    else if(f==='tache'){ mxTacheDisque(); }
}
function mxGestes(gs){ return (gs||[]).map((g,i)=>`<button class="mx-btn${i===0?' primary':''}" onclick='mxGeste(${mxE(JSON.stringify(g))})'>${mxE(g.lib)}</button>`).join(''); }
async function mxTacheDisque(){
    try{
        const r=await apiPost('/api/mesures/tache',{});
        const t=document.getElementById('mx-tache-retour');
        const msg=r.ok?(r.created?'Tâche créée (n° '+r.task_id+'), visible dans les tâches d\'Itare.':'Déjà créée : tâche n° '+r.task_id+'.'):('Pas créée : '+(r.reason||'échec'));
        if(t) t.textContent=msg; else buDire(msg);
    }catch(e){ buDire('Pas créée : '+(e.message||e)); }
}
const _MX_PILL={panne:'EN PANNE',regarder:'À REGARDER',pas_encore:'PAS ENCORE',muet:'SANS NOUVELLES',ok:'À JOUR'};

async function mxVerdict(seq){
    const p=document.getElementById('mx-page');
    const v=await apiPost('/api/mesures/verdict',{});
    if(seq!==MX.seq) return;
    const lignes=v.lignes||[];
    const foot=[`${v.sources.a_jour} source${v.sources.a_jour>1?'s':''} à jour`];
    if((v.sources.non_configurees||[]).length) foot.push('non configurée : '+v.sources.non_configurees.map(mxE).join(', '));
    if((v.sources.muettes||[]).length) foot.push('sans nouvelles : '+v.sources.muettes.map(mxE).join(', '));
    p.innerHTML=`<section class="mx-sec" aria-label="Verdict">
        <div class="mx-eyebrow">Maintenant · lu à ${mxE((v.lu_le||'').slice(11,16))}</div>
        <div class="mx-verdict"><div class="mx-vmark ${mxE(v.niveau)}"></div><div style="display:flex;flex-direction:column;gap:3px;min-width:0">
          <p class="mx-vtitle">${mxE(v.titre)}</p><span class="mx-vsub">${mxE(v.sous_titre)}</span></div></div>
        ${lignes.length?`<div class="mx-rows">${lignes.map(l=>`<div class="mx-row"><span class="mx-pill ${mxE(l.niveau)}">${_MX_PILL[l.niveau]||mxE(l.niveau)}</span>
          <div class="mx-rt"><b>${mxE(l.titre)}</b>${l.detail?`<span>${mxE(l.detail)}</span>`:''}</div><div class="mx-gest">${mxGestes(l.gestes)}</div></div>`).join('')}</div>`:''}
        <div id="mx-tache-retour" style="font-size:12.5px;color:var(--ok)"></div>
        <div class="mx-foot">${foot.map(f=>`<span>${f}</span>`).join('')}<span>Mêmes seuils que <a onclick="switchTab('bureau')">Aujourd'hui › Ce qui brûle</a> (certificats ${v.seuils.ssl_jours} j, disque ${v.seuils.disque_jours} j, écart ${v.seuils.ecart_pct} %)</span></div>
      </section><section class="mx-sec" id="mx-courbe-sec"><div class="empty-state">Chargement de la courbe…</div></section>`;
    await mxCourbe(seq, 'mx-courbe-sec');
}

// ── Une courbe : l'axe du temps ENTIER, les trous montrés, les événements posés dessus ───
function mxCle(ts, bucket){
    const s=String(ts||'').replace('T',' ');
    if(bucket==='day') return s.slice(0,10);
    if(bucket==='hour') return s.slice(0,13);
    if(bucket==='5min'){ const m=parseInt(s.slice(14,16)||'0',10); return s.slice(0,14)+String(Math.floor(m/5)*5).padStart(2,'0'); }
    return s.slice(0,16);
}
function mxAxe(from, to, bucket){
    const pas={minute:60e3,'5min':300e3,hour:3600e3,day:86400e3}[bucket]||3600e3;
    const d0=new Date(String(from).replace(' ','T')+'Z'), d1=new Date(String(to).replace(' ','T')+'Z');
    const out=[]; if(isNaN(d0)||isNaN(d1)) return out;
    for(let t=Math.floor(d0.getTime()/pas)*pas; t<=d1.getTime() && out.length<2200; t+=pas){
        out.push(mxCle(new Date(t).toISOString().slice(0,19).replace('T',' '), bucket));
    }
    return out;
}
function mxLibelle(cle, bucket){
    const d=new Date(cle.replace(' ','T').padEnd(16,':00').slice(0,16)+':00Z'); if(isNaN(d)) return cle;
    if(bucket==='day') return _MX_JOURS[d.getUTCDay()]+' '+d.getUTCDate();
    if(bucket==='hour') return (d.getUTCHours()===0?_MX_JOURS[d.getUTCDay()]+' '+d.getUTCDate()+' ':'')+String(d.getUTCHours()).padStart(2,'0')+' h';
    return cle.slice(11,16);
}
const _MX_UNITE_TRANCHE={minute:'par minute','5min':'par 5 min',hour:'par heure',day:'par jour'};

async function mxCourbe(seq, cible){
    const p=document.getElementById(cible||'mx-page');
    const d=await apiPost('/api/mesures/series',{key:MX.cur,period:MX.period});
    if(seq!==MX.seq) return;
    const spec=MX.list.find(m=>m.key===MX.cur)||{};
    if(!d.ok||!(d.series||[]).length||!d.count){
        p.innerHTML=`<section class="${cible?'':'mx-sec'}"><div class="mx-chart-h"><h2>${mxE(d.label||spec.label||MX.cur)}</h2></div>${mxVide(spec, d)}</section>`;
        return;
    }
    let ev={events:[]}, pr={};
    try{ ev=await apiPost('/api/mesures/events',{period:MX.period}); }catch(e2){ console.warn('[HISTORIQUE] marqueurs indisponibles', e2); }
    try{ pr=await apiPost('/api/mesures/profile',{key:MX.cur}); }catch(e3){ console.warn('[HISTORIQUE] profil indisponible', e3); }
    if(seq!==MX.seq) return;
    const bucket=d.bucket||'hour', axe=mxAxe(d.from, d.to, bucket), unite=d.kind==='count'?(_MX_UNITE_TRANCHE[bucket]||''):(d.unit||'');
    const mesurees=new Set(); d.series.forEach(s=>s.points.forEach(x=>{ if(x.v!=null) mesurees.add(mxCle(x.ts,bucket)); }));
    const nMes=axe.filter(k=>mesurees.has(k)).length;
    const per=Object.keys(MX.periods).map(k=>`<button class="mx-per${MX.period===k?' on':''}" onclick="mxPeriod('${k}')">${mxE(MX.periods[k].label)}</button>`).join('');
    let hab='';
    if(pr&&pr.ok){
        if(pr.enough&&pr.deviation_pct!=null) hab=`<span style="color:${mxT(Math.abs(pr.deviation_pct)>=60?'--warn':'--txt-soft')}">${pr.deviation_pct>=0?'+':''}${pr.deviation_pct} % par rapport à l'habitude (${mxE(pr.slot_label||'')} : ${pr.baseline} ${mxE(d.unit||'')})</span>`;
        else hab=`<span>${mxE(pr.reason||'')}</span>`;
    }
    const grp=d.series.length>1;
    const pire=(spec.pire==='bas');
    const liste=grp?`<div class="mx-worst">${d.series.map((s,i)=>{ const vals=s.points.map(x=>x.v).filter(x=>x!=null); const moy=vals.length?(vals.reduce((a,b)=>a+b,0)/vals.length):null;
        const g=(spec.family==='Sites')?{lib:'Fiche',f:'site',a:s.name}:(spec.family==='Flotte'?{lib:'Flotte',f:'flotte',a:s.name}:null);
        return `<div class="mx-wrow"><span class="dn"><i class="mx-dot" style="background:${mxCoul(_MX_COUL[i%_MX_COUL.length])};display:inline-block;margin-right:6px"></i>${mxE(s.name)}</span><span class="val">${moy==null?'—':(Math.round(moy*10)/10)} ${mxE(d.unit||'')}</span><span class="mx-gest">${g?mxGestes([g]):''}</span></div>`; }).join('')}</div>
        <div class="mx-legend"><span>${pire?'Le plus bas d\'abord — c\'est le pire qu\'on regarde en premier':'Le plus haut d\'abord'}</span></div>`:'';
    const evs=(ev.events||[]).filter(e=>e.source!=='actions');
    p.innerHTML=`<section class="${cible?'':'mx-sec'}">
      <div class="mx-chart-h"><h2>${mxE(d.label)}</h2><div class="mx-periods">${per}</div></div>
      <div class="mx-meta">${d.kind==='count'?'Compte '+mxE(unite):'Moyenne '+mxE(_MX_UNITE_TRANCHE[bucket]||'')} · ${nMes} ${bucket==='day'?'jours':bucket==='hour'?'heures':'tranches'} mesurée${nMes>1?'s':''} sur ${axe.length}${d.kind==='count'?'':' · min '+(d.min??'—')+' · moy. '+(d.avg??'—')+' · max '+(d.max??'—')+' '+mxE(d.unit||'')}</div>
      ${hab?`<div style="font-size:12.5px">${hab}</div>`:''}
      <div class="mx-canvas"><canvas id="mx-canvas"></canvas></div>
      <div class="mx-legend"><span><i style="background:${mxCoul('--accent')}"></i>Mesuré</span>${nMes<axe.length?`<span><i style="background:repeating-linear-gradient(45deg,${mxCoul('--txt-ghost')} 0 2px,transparent 2px 5px)"></i>Pas de mesure : l'écran ne relie pas les trous</span>`:''}${evs.length?`<span><i style="background:${mxCoul('--info')}"></i>Événement (clic : ce moment dans le journal)</span>`:''}</div>
      ${liste}
      ${evs.length?`<div class="mx-rows">${evs.slice(-12).reverse().map(e=>`<div class="mx-row"><span class="mx-pill">${mxE(mxLibelle(mxCle(e.ts,'minute'),'minute'))}</span><div class="mx-rt"><b>${mxE(e.title)}</b><span>${mxE(e.label||e.source||'')}</span></div><div class="mx-gest"><button class="mx-btn" onclick='mxGeste({f:"journal",a:${mxE(JSON.stringify(e.ts))}})'>Ce moment</button></div></div>`).join('')}</div>`:''}
    </section>`;
    mxDessiner(d, evs, axe, bucket);
}

// La scène « mesures sans données » de la maquette : chaque mesure qui n'a rien à montrer dit pourquoi.
function mxVides(){
    const p=document.getElementById('mx-page');
    const sans=MX.list.filter(m=>m.nature!=='etat'&&m.etat!=='a_jour');
    p.innerHTML=`<section class="mx-sec"><div class="mx-chart-h"><h2>Quand une mesure n'a rien à montrer, elle dit pourquoi</h2></div>
      ${sans.length?`<div style="display:flex;flex-direction:column;gap:6px">${sans.map(m=>mxVide(m, null)).join('')}</div>`:'<div class="mx-empty"><span class="mx-pill ok">À JOUR</span><div><b>Toutes les mesures ont des données</b><p>Aucune source muette, non configurée ou jamais utilisée.</p></div></div>'}
      <div class="mx-foot"><span>${MX.list.filter(m=>m.etat==='a_jour').length} mesures à jour · ${sans.length} sans données</span></div></section>`;
}

function mxVide(spec, d){
    const e=spec.etat||'aucune_source';
    const pill={rien_a_signaler:['ok','RIEN À SIGNALER'],non_configuree:['regarder','NON CONFIGURÉE'],jamais_utilisee:['','JAMAIS UTILISÉE'],muette:['muet','SANS NOUVELLES'],a_jour:['pas_encore','RIEN SUR CETTE PÉRIODE']}[e]||['','AUCUNE SOURCE'];
    const txt={rien_a_signaler:'La surveillance tourne et rien n\'est arrivé sur la période. C\'est une bonne nouvelle, pas un vide.',
      non_configuree:'Aucune source n\'est déclarée pour cette mesure sur ce serveur : il n\'y a rien à compter. Ce n\'est pas une panne, c\'est une absence.',
      jamais_utilisee:'Rien n\'est encore passé par ce chemin. La mesure commencera au premier événement.',
      muette:'Cette source écrivait et s\'est tue'+(spec.derniere?' (dernière mesure '+mxE(spec.derniere)+')':'')+'. Ce qu\'elle affichait date d\'avant.',
      a_jour:'La source est à jour mais n\'a rien sur cette fenêtre'+(spec.premiere?' (première mesure '+mxE(spec.premiere)+')':'')+'.'}[e]||'Aucune table ne porte cette mesure ici.';
    return `<div class="mx-empty"><span class="mx-pill ${pill[0]}">${pill[1]}</span><div><b>${mxE(spec.label||'')}</b><p>${txt}${d&&d.reason?' ('+mxE(d.reason)+')':''}</p></div></div>`;
}

function mxDessiner(d, evs, axe, bucket){
    const cv=document.getElementById('mx-canvas'); if(!cv||typeof Chart==='undefined') return;
    if(MX.charts.main){ MX.charts.main.destroy(); MX.charts.main=null; }
    const idx=new Map(axe.map((k,i)=>[k,i]));
    const datasets=d.series.map((s,i)=>{ const data=new Array(axe.length).fill(null); s.points.forEach(x=>{ const j=idx.get(mxCle(x.ts,bucket)); if(j!=null) data[j]=x.v; });
        const c=mxCoul(_MX_COUL[i%_MX_COUL.length]);
        return {label:s.name, data, borderColor:c, backgroundColor:c+'22', fill:d.series.length===1, tension:.25, pointRadius:0, borderWidth:1.8, spanGaps:false}; });
    const marques=new Map(); evs.forEach(e=>{ const j=idx.get(mxCle(e.ts,bucket)); if(j!=null) marques.set(j,(marques.get(j)||0)+1); });
    const trous=[]; let run=null; for(let i=0;i<axe.length;i++){ const vide=datasets.every(ds=>ds.data[i]==null); if(vide&&run==null) run=i; if(!vide&&run!=null){ trous.push([run,i-1]); run=null; } } if(run!=null) trous.push([run,axe.length-1]);
    const hachures={id:'mxTrous', beforeDatasetsDraw(ch){ const {ctx,chartArea:a,scales:{x}}=ch; if(!a) return; ctx.save(); ctx.fillStyle=mxCoul('--txt-ghost'); ctx.globalAlpha=.16;
        trous.forEach(([i0,i1])=>{ const x0=x.getPixelForValue(Math.max(0,i0-.5)), x1=x.getPixelForValue(Math.min(axe.length-1,i1+.5)); for(let px=Math.max(x0,a.left); px<Math.min(x1,a.right); px+=6){ ctx.fillRect(px,a.top,2,a.bottom-a.top); } });
        ctx.restore(); ctx.save(); ctx.strokeStyle=mxCoul('--info'); ctx.setLineDash([3,3]);
        marques.forEach((n,i)=>{ const px=x.getPixelForValue(i); ctx.beginPath(); ctx.moveTo(px,a.top); ctx.lineTo(px,a.bottom); ctx.stroke(); }); ctx.restore(); }};
    const grille=mxCoul('--line'), enc=mxCoul('--txt-faint');
    MX.charts.main=new Chart(cv.getContext('2d'),{type:'line', data:{labels:axe.map(k=>mxLibelle(k,bucket)), datasets}, plugins:[hachures],
        options:{responsive:true,maintainAspectRatio:false,animation:false,interaction:{mode:'index',intersect:false},
            onClick:(evt)=>{ const i=Math.round(MX.charts.main.scales.x.getValueForPixel(evt.x)); const k=axe[Math.max(0,Math.min(axe.length-1,i))];
                if(k){ const at=(k.length===10?k+' 00:00':k.length===13?k+':00':k)+':00'; JR.demande={f:'jrTimeline',a:at.slice(0,19),w:bucket==='day'?720:bucket==='hour'?60:15}; switchTab('journal'); } },
            plugins:{legend:{display:d.series.length>1,labels:{color:enc,font:{size:11},boxWidth:10}},
                     tooltip:{callbacks:{title:(it)=>it.length?axe[it[0].dataIndex].replace('T',' '):''}}},
            scales:{x:{ticks:{color:enc,font:{size:10},maxTicksLimit:9,maxRotation:0},grid:{color:grille}},
                    y:{beginAtZero:true,suggestedMax:(d.kind==='gauge'&&d.unit==='%')?100:undefined,ticks:{color:enc,font:{size:10}},grid:{color:grille}}}}});
}

// ── Avant / après : l'évolution se choisit ; les chiffres portent leurs heures mesurées ─
async function mxAvantApres(seq){
    const p=document.getElementById('mx-page');
    if(!MX.evos.length){ const l=await apiPost('/api/mesures/evolutions',{n:30}); MX.evos=l.evolutions||[]; }
    if(seq!==MX.seq) return;
    if(!MX.evos.length){ p.innerHTML='<section class="mx-sec"><div class="mx-chart-h"><h2>Avant / après une évolution</h2></div><div class="mx-empty"><span class="mx-pill">RIEN À JUGER</span><div><b>Aucune évolution appliquée</b><p>Quand le moteur écrira une pièce, on pourra comparer les 24 heures d\'avant et d\'après.</p></div></div></section>'; return; }
    if(!MX.evo) MX.evo=MX.evos[0].id;
    const d=await apiPost('/api/mesures/evolution',{id:MX.evo,hours:24});
    if(seq!==MX.seq) return;
    const sel=`<select id="mx-evo-choix" class="mx-select" onchange="MX.evo=parseInt(this.value,10);mxCharger()">${MX.evos.map(e=>`<option value="${e.id}"${e.id===MX.evo?' selected':''}>#${e.id} · ${mxE(e.ts)} · ${mxE(e.cible||e.description)}</option>`).join('')}</select>`;
    const ms=d.metrics||[];
    const juge=ms.filter(m=>m.judgeable);
    const kpis=juge.map(m=>`<div class="mx-kpi"><span>${mxE(m.label).toUpperCase()}</span><b>${m.before} → ${m.after}</b><em>${Math.abs(m.delta_pct||0)<10?'dans le bruit habituel':(m.delta_pct>0?'+':'')+m.delta_pct+' %, au-delà du bruit'}</em></div>`).join('');
    const table=ms.length?`<div class="mx-tbl"><table class="mx-ab"><thead><tr><th>Mesure</th><th>24 h avant</th><th>24 h après</th><th>Écart</th><th>Heures mesurées</th></tr></thead><tbody>${ms.map(m=>`<tr><td>${mxE(m.label)}</td><td>${m.before}</td><td>${m.after}</td><td style="color:${m.judgeable?(m.delta_pct<0?mxT('--ok'):m.delta_pct>0?mxT('--warn'):'inherit'):mxT('--txt-faint')}">${m.judgeable?((m.delta_pct>0?'+':'')+m.delta_pct+' %'):'—'}</td><td>${m.hours_before} / ${m.hours_after}</td></tr>`).join('')}</tbody></table></div>`:'';
    p.innerHTML=`<section class="mx-sec"><div class="mx-chart-h"><h2>Avant / après une évolution</h2></div>
      <label class="mx-meta" for="mx-evo-choix">Évolution à juger</label>${sel}
      ${d.found&&d.description?`<div style="font-size:12.5px;color:var(--txt-soft)">${mxE(d.description)} · ${mxE(d.ts||'')}</div>`:''}
      ${d.note?`<div class="mx-empty"><span class="mx-pill pas_encore">PAS JUGEABLE</span><div><b>${mxE(d.note)}</b><p>Il faut au moins ${d.hours_required||18} heures mesurées de chaque côté : comparer moins serait inventer un effet.</p></div></div>`:''}
      ${kpis?`<div class="mx-kpis">${kpis}</div>`:''}${table}
      <div class="mx-foot"><span>Une baisse n'est pas forcément due à l'évolution : la charge varie d'elle-même. Un indice, pas une preuve.</span><span><a onclick='mxGeste({f:"evolution",a:${MX.evo}})'>Ouvrir la pièce dans l'onglet Évolution</a></span></div></section>`;
}

// ── La prévision du disque : une date, un rythme, et les deux gestes qui existent ───────
async function mxPrevision(seq){
    const p=document.getElementById('mx-page');
    const f=await apiPost('/api/mesures/forecast',{key:'disk'});
    if(seq!==MX.seq) return;
    const j=f.saturation_days;
    let titre, sous;
    if(!f.enough){ titre='Pas encore de tendance fiable.'; sous=f.reason||''; }
    else if(j==null){ titre='Le disque ne se remplit pas.'; sous=(f.note||'')+' · actuellement '+f.current+' %'; }
    else { titre='À ce rythme, le disque sera plein vers le '+_mxDateFr(f.saturation_date)+', dans '+Math.round(j)+' jours.'; sous='Il gagne '+(f.trend>0?'+':'')+f.trend+' point par jour sur les 14 derniers jours · actuellement '+f.current+' %.'; }
    const niveau=(!f.enough)?'inconnu':(j==null?'stable':(j<=7?'panne':(j<=30?'regarder':'stable')));
    p.innerHTML=`<section class="mx-sec"><div class="mx-chart-h"><h2>Disque — quand sera-t-il plein ?</h2></div>
      <div class="mx-verdict"><div class="mx-vmark ${niveau}"></div><div style="display:flex;flex-direction:column;gap:3px"><p class="mx-vtitle" style="font-size:17px">${mxE(titre)}</p><span class="mx-vsub">${mxE(sous)}</span></div></div>
      ${f.enough&&j!=null?`<div class="mx-gest" style="justify-content:flex-start">${mxGestes([{lib:'Créer la tâche : libérer de l\'espace',f:'tache',a:''},{lib:'Demander à Cassandra ce qui prend de la place',f:'chat',a:'Qu\'est-ce qui prend de la place sur le disque ?'}])}</div><div id="mx-tache-retour" style="font-size:12.5px;color:var(--ok)"></div>`:''}
      <section id="mx-courbe-sec" style="display:flex;flex-direction:column;gap:12px"><div class="empty-state">Chargement de la courbe…</div></section>
      <div class="mx-foot"><span>Régression sur les moyennes horaires des 14 derniers jours, sur les heures réellement mesurées.</span></div></section>`;
    const cur=MX.cur, per=MX.period; MX.cur='disk'; MX.period='30d';
    try{ await mxCourbe(seq,'mx-courbe-sec'); } finally { MX.cur=cur; MX.period=per; }
}
function _mxDateFr(iso){ const M=['janvier','février','mars','avril','mai','juin','juillet','août','septembre','octobre','novembre','décembre']; try{ const s=String(iso||''); return parseInt(s.slice(8,10),10)+' '+M[parseInt(s.slice(5,7),10)-1]; }catch(e){ return String(iso||''); } }

async function apiGet(e){
    const url=e+(e.includes('?')?'&':'?')+'_='+Date.now();
    const r=await fetch(url,{headers:{'X-Session-Token':sessionId,'Cache-Control':'no-cache','Pragma':'no-cache'}});
    if(r.status===401){logout();throw new Error('401');}
    if(!r.ok){
        // Un 4xx/5xx levait « 500 » et rien d'autre, alors que le serveur
        // écrit la cause dans `error` ou `reason` : on lit le corps AVANT de
        // lever, et la cause monte jusqu'à l'écran (fpLoadSection l'affiche).
        // Sans corps JSON exploitable, le message reste le statut nu, comme
        // avant : des appelants le comparent. (2026-09-05)
        let msg=String(r.status);
        try{
            const j=JSON.parse(await r.text());
            if(j&&(j.error||j.reason)) msg=String(j.error||j.reason);
        }catch(_){}
        throw new Error(msg);
    }
    return r.json();
}
async function apiPost(e,body){
    const r=await fetch(e,{method:'POST',headers:{'X-Session-Token':sessionId,'Content-Type':'application/json'},body:JSON.stringify(body||{})});
    if(r.status===401){logout();throw new Error('401');}
    // Une réponse non-JSON (500 brut, page d'erreur, coupure) faisait échouer
    // r.json() avec « Unexpected token », message qui ne désigne jamais la vraie
    // cause. On rend le statut et le début du corps : de quoi diagnostiquer.
    const t=await r.text();
    try{ return JSON.parse(t); }
    catch(err){
        throw new Error('HTTP '+r.status+' sur '+e+' — réponse non-JSON : '+t.slice(0,200));
    }
}
// LOT 5 (B22) : une route qui rend un FICHIER passe par ici — même jeton, même 401, et le statut
// rendu au lieu d'un JSON.parse qui échoue. `json` est lu quand la réponse en est un (refus, 409).
async function apiFichier(e, body){
    const r=await fetch(e,{method:'POST',headers:{'X-Session-Token':sessionId,'Content-Type':'application/json'},body:JSON.stringify(body||{})});
    if(r.status===401){logout();throw new Error('401');}
    const ct=(r.headers.get('content-type')||'');
    if(!r.ok || ct.indexOf('application/json')===0){
        let j=null; try{ j=await r.json(); }catch(err){}
        return {ok:r.ok, status:r.status, json:j, blob:null, reason:(j&&(j.reason||j.error))||''};
    }
    return {ok:true, status:r.status, json:null, blob:await r.blob(), reason:''};
}
function escapeHtml(t){ if(t==null)return ''; return String(t).replace(/[&<>]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[m])); }
// escapeHtml n'échappe PAS les guillemets : suffisant pour du texte entre
// balises, fatal dans une valeur d'attribut. Un srcdoc rempli avec lui se
// refermait au premier style="…" du message, et le cadre restait blanc.
function escapeAttr(t){
    if(t==null) return '';
    return String(t).replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
}
/* UNE COUCHE D'ÉCHAPPEMENT À RETIRER. Le corps des requêtes est échappé à
   l'entrée : « BILAN D'ANALYSE » est rangé « BILAN D&#x27;ANALYSE ». Ré-échappé
   à l'affichage, il se lit « D&#x27;ANALYSE » — une apostrophe devenue six
   caractères, sur un titre qu'on n'a jamais tapé comme ça.
   On retire donc la couche du dessus AVANT de la reposer proprement : la
   chaîne reste échappée exactement une fois. Jamais zéro — l'ordre compte, et
   « &amp; » se défait en dernier, sinon « &amp;lt; » redeviendrait « < ». */
function _txtDeco(s){
    return String(s == null ? '' : s)
        .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
        .replace(/&quot;/g, '"').replace(/&#x27;|&#39;/g, "'")
        .replace(/&amp;/g, '&');
}

function _colorStatVal(id, pct){
    const el=document.getElementById(id); if(!el) return;
    el.className='stat-val '+(pct>=90?'critical':pct>=75?'warning':'ok');
}
function _setStatBar(id, pct){
    const el=document.getElementById(id); if(!el) return;
    el.style.width=pct+'%';
}
function _setMmsVal(id, txt, pct){
    const el=document.getElementById(id); if(!el) return;
    el.textContent=txt;
    el.className='mms-val '+(pct>=90?'critical':pct>=75?'warning':'ok');
}
// ── Vue d'ensemble ───────────────────────────────────────────────────────
// ═══════════════════════════════════════════════════════════════════════════
//  VUE D'ENSEMBLE (21-09, fil 30, maquette v1) — une route, un rendu, un âge par carte
//
//  /api/vue rend verdict, compteurs, cloche, Cassandra, sites, flotte, fil,
//  machine. L'écran n'arbitre rien : il pose ce qu'il reçoit, relit toutes les
//  60 s quand il est devant, et laisse la trame WebSocket nourrir les jauges.
// ═══════════════════════════════════════════════════════════════════════════
const VU = {d:null, t:0, timer:null, wsTs:0, sysCharge:false, sysTimers:[]};
const vuE = v => (typeof escapeHtml === 'function' ? escapeHtml(String(v ?? '')) : String(v ?? ''));
const vuA = v => (typeof escapeAttr === 'function' ? escapeAttr(String(v ?? '')) : String(v ?? '').replace(/"/g, '&quot;'));
function vuHeure(ts){ const t=String(ts||''); return t.length>=16 ? t.slice(11,16) : (t||'—'); }
function vuAge(ts){ if(!ts) return null; const d=(Date.now()-new Date(String(ts).replace(' ','T')+'Z').getTime())/1000; return isFinite(d)?Math.max(0,Math.floor(d)):null; }
function vuAgeTxt(ts){ const a=vuAge(ts); if(a===null) return 'jamais'; if(a<60) return 'il y a '+a+' s'; if(a<3600) return 'il y a '+Math.floor(a/60)+' min'; return vuHeure(ts); }
function vuPuce(t,c){ return `<span class="mx-pill ${c||''}">${vuE(t)}</span>`; }
function vuNiv(n){ return n==='panne'?'panne':(n==='regarder'?'regarder':(n==='inconnu'?'pas_encore':'ok')); }
function vuMark(n){ return n==='stable'?'stable':(n==='panne'?'panne':(n==='inconnu'?'inconnu':'')); }

// ── le composant commun des compteurs : une liste de {nom, valeur, niveau, detail, source, onclick} ──
function mxKpisHtml(kpis){
    return `<div class="mx-kpis">${(kpis||[]).map(k=>{
        const cls = k.niveau==='panne'?'bad':(k.niveau==='regarder'?'avert':(k.niveau==='inconnu'?'inconnu':''));
        const tag = k.onclick ? 'button' : 'div';
        return `<${tag} class="mx-kpi" ${k.onclick?`onclick="${vuA(k.onclick)}"`:''}${k.titre?` title="${vuA(k.titre)}"`:''}><span>${vuE(k.nom)}</span><b${cls?` class="${cls}"`:''}>${vuE(k.valeur===null||k.valeur===undefined?'—':k.valeur)}</b><em>${vuE(k.detail||'')}</em><small>${vuE(k.source||'')}</small></${tag}>`;
    }).join('')}</div>`;
}
function vuAllerVers(a){
    if(!Array.isArray(a) || !a[0]) return;
    // Un renvoi vers la vue elle-même : sa section — et, sans section nommée (une notification machine :
    // RAM, charge…), la machine plutôt que rien.
    if(a[0]==='overview'){ vuAller(a[1]==='vuAller' && a[2] ? a[2] : 'machine'); return; }
    if(typeof ntAller==='function') ntAller(a); else switchTab(a[0]);
}
function vuGeste(g){
    if(!g) return;
    if(g.type==='site' && g.domain){ if(typeof siteAct==='function' && ['status','restart','ssl_renew','logs'].includes(g.action)) siteAct(g.domain, g.action, null); else if(typeof stGeste==='function') { switchTab('mysites'); setTimeout(()=>{ stOpen(g.domain); }, 200); } return; }
    if(g.type==='aller') vuAllerVers(g.aller);
}
function vuAller(sec){
    const el=document.getElementById('vu-'+sec); if(!el) return;
    document.querySelectorAll('#vu-rail .mx-item').forEach(b=>{ const on=b.id==='vunav-'+sec; b.classList.toggle('on',on); if(on) b.setAttribute('aria-current','true'); else b.removeAttribute('aria-current'); });
    // Sans « smooth » : dans le navigateur de l'application le défilement doux ne partait jamais (mesuré :
    // scrollTop restait à 0 après 1,5 s, alors que le défilement immédiat arrive).
    el.scrollIntoView({block:'start'});
}
async function vuCharger(force){
    const main=document.getElementById('vu-main'); if(!main) return;
    let d; try{ d=await apiPost('/api/vue',{}); }catch(e){ d={ok:false, reason:e.message||String(e)}; }
    VU.d=d; VU.t=Date.now();
    if(!d||d.ok===false){ document.getElementById('vu-verdict').innerHTML=`<div class="mx-silence"><b>La vue ne se lit pas.</b> ${vuE((d&&(d.reason||d.error))||'')}</div>`; return; }
    vuRendre(d);
    if(!VU.timer) VU.timer=setInterval(()=>{ const t=document.getElementById('tab-overview'); if(t&&t.classList.contains('active')&&document.visibilityState==='visible'&&Date.now()-VU.t>55000) vuCharger(); }, 15000);
}
document.addEventListener('visibilitychange', ()=>{ if(document.visibilityState==='visible'){ const t=document.getElementById('tab-overview'); if(t&&t.classList.contains('active')&&Date.now()-VU.t>30000) vuCharger(); } });
function vuRendre(d){
    const r=document.getElementById('vu-releve'); if(r) r.textContent=vuHeure(d.releve);
    const p=document.getElementById('vu-portee'); if(p) p.textContent = d.admin ? 'administrateur' : ('compte · '+(d.n_sites||0)+' site'+((d.n_sites||0)>1?'s':''));
    vuVerdict(d); vuKpis(d); vuGestes(d);
    if(d.admin){ vuCass(d); vuParc(d); vuFil(d); vuMachine(d); }
    else { ['vu-cass','vu-parc','vu-fil','vu-machine'].forEach(id=>{ const e=document.getElementById(id); if(e) e.hidden=true; }); }
    const set=(id,txt,dot)=>{ const e=document.getElementById('vust-'+id); if(e) e.textContent=txt; const q=document.getElementById('vudot-'+id); if(q) q.className='mx-dot '+(dot||''); };
    set('verdict', d.niveau==='stable'?vuHeure(d.releve):d.niveau, vuNiv(d.niveau));
    const nc=(d.cloche||{}).total||0; set('gestes', nc?String(nc):'0', nc?((d.cloche.lignes||[]).some(x=>x.niveau==='critique')?'panne':'regarder'):'ok');
    if(d.admin){ const c=d.cassandra||{}; set('cass', c.palier!==undefined&&c.palier!==null?('palier '+c.palier):'—', c.collecteur?'ok':'panne');
      set('sites', String(d.n_sites||0), (d.sites||[]).some(x=>x.up===false)?'panne':'ok');
      const f=d.flotte||{}; set('flotte', (f.machines||[]).length+' att.', (f.hors_ligne||[]).length?'panne':'ok');
      set('fil', String((d.fil||[]).length), '');
      set('machine', d.machine&&d.machine.vivant?'1 s':'muette', d.machine&&d.machine.vivant?'ok':'panne'); }
}
function vuVerdict(d){
    const z=document.getElementById('vu-verdict'); if(!z) return;
    const a=d.ages||{};
    const src = d.admin ? [['machine', d.machine&&d.machine.vivant?'WebSocket · 1 s':'muette', !(d.machine&&d.machine.vivant)], ['sites','sonde · '+(a.sonde?vuHeure(a.sonde):'jamais'), !a.sonde], ['panneau', a.sites?('relevé '+vuHeure(a.sites)):'pas encore relevé', !a.sites], ['flotte','présence · '+(a.flotte?vuHeure(a.flotte):'jamais'), !a.flotte], ['mesures', a.mesures?('lu '+vuHeure(a.mesures)):'—', false]] : [['sites','sonde · 5 min',false]];
    z.innerHTML=`<div class="mx-eyebrow">${d.admin?'Ce matin · verdict composite · un âge par carte':'Tes sites, ce matin · rien de la machine'}</div>
      <div class="mx-verdict"><div class="mx-vmark ${vuMark(d.niveau)}"></div><div class="mx-vbody"><p class="mx-vtitle">${vuE(d.titre)}</p><p class="mx-vsub">${vuE(d.sous_titre||'')}</p>
      <div class="mx-sources">${src.map(x=>`<i>${vuE(x[0])}</i><span class="${x[2]?'mort':''}">${vuE(x[1])}</span>`).join('')}</div>
      <div class="mx-gest">${(d.gestes||[]).slice(0,4).map((g,i)=>`<button class="mx-btn ${i===0&&d.niveau==='panne'?'primary':''}" onclick="vuGeste(VU.d.gestes[${i}])">${vuE(g.label||'Voir')}</button>`).join('')}</div></div></div>`;
}
function vuKpis(d){
    const z=document.getElementById('vu-kpis'); if(!z) return; z.hidden=false;
    const l=(d.compteurs||[]).map((k,i)=>({nom:k.nom, valeur:k.valeur, niveau:k.niveau, detail:k.detail, source:k.source, onclick:`vuKpiClic(${i})`}));
    z.innerHTML=`<div class="mx-chart-h"><h2>Les compteurs</h2><span class="mx-meta">${d.admin?'huit, chacun avec sa source et son âge · un clic ouvre ou filtre':'tes sites · un clic ouvre'}</span></div>`+mxKpisHtml(l);
}
function vuKpiClic(i){ const k=((VU.d||{}).compteurs||[])[i]; if(k&&k.aller) vuAllerVers(k.aller); }
function vuGestes(d){
    const z=document.getElementById('vu-gestes'); if(!z) return; z.hidden=false;
    const c=d.cloche||{}, l=c.lignes||[]; const cpt=c.compteurs||{};
    const pills=[]; const nCrit=l.filter(x=>x.niveau==='critique').length, nAvoir=l.filter(x=>x.niveau==='avoir').length;
    if(nCrit) pills.push(vuPuce(nCrit+' panne'+(nCrit>1?'s':''),'panne')); if(nAvoir) pills.push(vuPuce(nAvoir+' à regarder','regarder')); if(!l.length) pills.push(vuPuce('rien à faire','ok'));
    z.innerHTML=`<div class="mx-chart-h"><h2>Ce qui demande un geste</h2><span class="mx-meta">${pills.join(' ')} · lu dans les notifications · la panne d’abord</span></div>`
      + (l.length ? `<div class="mx-rows">${l.map((x,i)=>{ const niv=x.niveau==='critique'?'panne':(x.niveau==='avoir'?'regarder':'pas_encore'); const act=(x.actions||[])[0];
          return `<div class="mx-row">${vuPuce(niv==='panne'?'panne':(niv==='regarder'?'à regarder':'info'), niv)}<div class="mx-rt"><b><a style="cursor:pointer" onclick="vuAllerVers(VU.d.cloche.lignes[${i}].aller)">${vuE(x.titre)}</a>${x.n>1?' '+vuPuce('×'+x.n,''):''}</b><span>${vuE((x.corps||'').slice(0,160))}${x.maj?' · '+vuE(vuAgeTxt(x.maj)):''}${x.source_nom?' · '+vuE(x.source_nom):''}</span></div><div class="mx-cote">${act?`<button class="mx-btn ${niv==='panne'?'primary':''}" onclick="vuAgir(${i})">${vuE(act.nom)}</button>`:`<button class="mx-btn" onclick="vuAllerVers(VU.d.cloche.lignes[${i}].aller)">Voir</button>`}</div></div>`; }).join('')}</div>`
        : `<div class="mx-silence"><b>Rien ne demande un geste.</b> Aucune notification à faire ni en cours.</div>`)
      + `<div class="mx-foot"><span>Une ligne = une notification, sa clé, son geste — la même dans la cloche.</span>${c.total>l.length?`<span>+${c.total-l.length}</span>`:''}<a onclick="event.stopPropagation(); toggleAlertDropdown()">Toutes les notifications →</a></div>`;
}
function vuAgir(i){
    const x=((VU.d||{}).cloche||{}).lignes[i]; if(!x) return; const a=(x.actions||[])[0]; if(!a) return;
    if(typeof ntFeuille!=='function' || typeof ntAgirGo!=='function'){ if(typeof ntAgir==='function') ntAgir(x.id, a.cle); return; }
    ntFeuille({titre:a.nom+' ?', sous:a.quoi, danger:false, corps:'['+(x.source_nom||'')+'] '+(x.titre||''),
               boutons:[{label:a.nom, cls:'pri', onclick:function(){ ntAgirGo(x.id, a.cle, a.nom); setTimeout(()=>vuCharger(true), 2500); }}]});
}
