function vuMachineAge(){
    const e=document.getElementById('vu-machine-age'); if(!e) return;
    const a=VU.wsTs?Math.floor((Date.now()-VU.wsTs)/1000):null;
    if(a===null){ e.textContent='en attente de la trame WebSocket'; e.className='mx-meta'; return; }
    if(a>15){ e.textContent='WebSocket muette depuis '+a+' s · dernières valeurs gardées'; e.className='mx-meta mort'; ['cpu','ram','disk','load'].forEach(k=>{ const b=document.getElementById('vu-'+k); if(b&&!b.classList.contains('inconnu')){ b.classList.add('inconnu'); b.textContent='inconnu · '+b.textContent; } }); }
    else { e.textContent='WebSocket · il y a '+a+' s'; e.className='mx-meta'; }
}
setInterval(vuMachineAge, 2000);

const CMD_HORS_RAIL = [
    // « Mon compte » est la vision personnelle de Paramètres généraux — l'onglet `account` n'existe plus.
    {tab:'settings', label:'Mon compte',      fam:'Espace perso', aller:['settings','setVision','moi']},
    {tab:'vault',    label:'Mon coffre-fort', fam:'Espace perso'},
    {tab:'settings', label:'Réglages',        fam:'Espace perso'},
];

function cmdDestinations(){
    const out = [];
    document.querySelectorAll('#sidebar .sb-item').forEach(function(el){
        const onglet = el.getAttribute('data-tab');
        if(!onglet || el.style.display === 'none') return;
        const grp = el.closest('.sb-group');
        const fam = grp ? (grp.querySelector('.sb-head') || {}).textContent : '';
        out.push({tab: onglet, label: (el.textContent || '').trim(),
                  fam: (fam || '').trim()});
    });
    // La vue d'ensemble sait les sites et les machines du parc : ils se cherchent ici aussi et ouvrent
    // leur fiche — le champ le promettait sans le tenir.
    const d = (typeof VU !== 'undefined' && VU.d) || {};
    (d.sites || []).forEach(function(s){ if(s && s.domain) out.push({tab:'mysites', label:s.domain, fam:'Site', aller:['mysites','stOpen',s.domain]}); });
    (((d.flotte || {}).machines) || []).forEach(function(m){ if(m && m.nom) out.push({tab:'fleet', label:m.nom, fam:'Machine', aller:['fleet','flOpen',m.nom]}); });
    return out.concat(CMD_HORS_RAIL);
}
let CMD_RES = [];

function cmdChercher(q){
    const zone = document.getElementById('cmd-res');
    if(!zone) return;
    const t = (q || '').trim().toLowerCase();
    CMD_SEL = -1;
    if(!t){ zone.classList.remove('on'); zone.innerHTML = ''; return; }
    const res = cmdDestinations().filter(function(d){
        return d.label.toLowerCase().indexOf(t) >= 0 || d.fam.toLowerCase().indexOf(t) >= 0;
    }).slice(0, 8);
    CMD_RES = res;
    zone.innerHTML = res.length
        ? res.map(function(d, k){
            return '<div class="cmd-item" data-tab="' + escapeAttr(d.tab) + '" data-k="' + k + '"'
                 + ' onclick="cmdAller(' + k + ')">'
                 + '<span class="sb-dot"></span>' + escapeHtml(d.label)
                 + '<span class="k">' + escapeHtml(d.fam) + '</span></div>';
          }).join('')
        : '<div class="cmd-vide">Ni écran, ni site, ni machine de ce nom.</div>';
    zone.classList.add('on');
}

function cmdAller(k){
    const zone = document.getElementById('cmd-res'), champ = document.getElementById('cmd-input');
    if(zone){ zone.classList.remove('on'); zone.innerHTML = ''; }
    if(champ) champ.value = '';
    // Un rang dans la dernière recherche (un site, une machine ouvrent leur fiche) ; un nom d'onglet reste accepté.
    const d = (typeof k === 'number') ? CMD_RES[k] : {tab: k};
    if(!d) return;
    if(d.aller && typeof vuAllerVers === 'function') vuAllerVers(d.aller); else switchTab(d.tab);
}

function cmdTouche(e){
    const zone = document.getElementById('cmd-res');
    if(!zone || !zone.classList.contains('on')) return;
    const items = zone.querySelectorAll('.cmd-item');
    if(!items.length) return;
    if(e.key === 'ArrowDown' || e.key === 'ArrowUp'){
        e.preventDefault();
        CMD_SEL = (CMD_SEL + (e.key === 'ArrowDown' ? 1 : items.length - 1)) % items.length;
        items.forEach(function(x, k){ x.classList.toggle('sel', k === CMD_SEL); });
    } else if(e.key === 'Enter'){
        e.preventDefault();
        const cible = items[CMD_SEL >= 0 ? CMD_SEL : 0];
        if(cible) cmdAller(parseInt(cible.getAttribute('data-k'), 10));
    } else if(e.key === 'Escape'){
        zone.classList.remove('on');
    }
}

document.addEventListener('keydown', function(e){
    if((e.ctrlKey || e.metaKey) && String(e.key).toLowerCase() === 'k'){
        e.preventDefault();
        const c = document.getElementById('cmd-input');
        if(c){ switchTab('overview'); setTimeout(()=>{ c.focus(); c.select(); }, 80); }
    }
});
document.addEventListener('click', function(e){
    const z = document.getElementById('cmd-res');
    if(z && z.classList.contains('on') && !e.target.closest('.cmdbar')) z.classList.remove('on');
});

// ── Bandeau de constantes ────────────────────────────────────────────────
// Chaque mesure garde son historique court : une courbe dit ce qu'un
// pourcentage tait — un disque à 53 % qui monte n'est pas un disque à 53 %
// stable, et c'est la pente qui décide s'il faut s'en occuper.
const VITALS_HIST = {cpu:[], ram:[], disk:[]};
const VITALS_MAX = 40;

function _sparkD(vals, ferme){
    if(!vals.length) return '';
    const n = Math.max(vals.length - 1, 1);
    const pt = vals.map(function(v,k){
        const x = (k / n) * 120;
        const y = 21 - (Math.max(0, Math.min(100, v)) / 100) * 19;
        return x.toFixed(1) + ' ' + y.toFixed(1);
    });
    const d = 'M' + pt.join(' L');
    return ferme ? (d + ' L120 22 L0 22 Z') : d;
}

function majVitals(cpu, ram, disk, load){
    [['cpu',cpu],['ram',ram],['disk',disk]].forEach(function(p){
        const cle = p[0], val = p[1];
        VITALS_HIST[cle].push(val);
        if(VITALS_HIST[cle].length > VITALS_MAX) VITALS_HIST[cle].shift();
        const t = document.getElementById('vu-' + cle);
        if(t){ t.textContent = val + ' %'; t.classList.remove('inconnu'); }
        const l = document.getElementById('vu-' + cle + '-l');
        const f = document.getElementById('vu-' + cle + '-f');
        if(l) l.setAttribute('d', _sparkD(VITALS_HIST[cle], false));
        if(f) f.setAttribute('d', _sparkD(VITALS_HIST[cle], true));
    });
    const lo = document.getElementById('vu-load'); if(lo && load!==undefined && load!==null){ lo.textContent = String(load); lo.classList.remove('inconnu'); }
}
// `majVitalsInfos` (recopie DOM → DOM toutes les 4 s, « relevé il y a moins d'une minute » écrit en dur) est parti :
// la vue porte ses âges, la trame WebSocket porte les jauges.

function ouvrirSysteme(){
    const d=document.getElementById('sys-drawer'), s=document.getElementById('sys-scrim');
    if(d) d.classList.add('on');
    if(s) s.classList.add('on');
    _sysCharger();
}
function fermerSysteme(){
    const d=document.getElementById('sys-drawer'), s=document.getElementById('sys-scrim');
    if(d) d.classList.remove('on');
    if(s) s.classList.remove('on');
    VU.sysTimers.forEach(t=>clearInterval(t)); VU.sysTimers=[];
}
// LES TREIZE CARTES SE CHARGENT ICI, à l'ouverture du tiroir — plus au démarrage de l'application, plus par
// huit minuteurs qui tournaient tiroir fermé (21-09). Tant qu'il est ouvert, trois relectures courtes.
function _sysCharger(){
    const f=[loadDashboard, loadRemotes, loadSSLCerts, loadTailscale, loadFail2ban, loadProcesses, loadSessions, loadPorts, loadOOM, loadFailedUnits, loadDocker, fpLoadSummary, loadMetrics];
    f.forEach(fn=>{ try{ if(typeof fn==='function') fn(); }catch(e){} });
    VU.sysTimers.forEach(t=>clearInterval(t)); VU.sysTimers=[];
    VU.sysTimers.push(setInterval(()=>{ try{ loadMetrics(); loadProcesses(); }catch(e){} }, 5000));
    VU.sysTimers.push(setInterval(()=>{ try{ loadFailedUnits(); loadTailscale(); loadFail2ban(); loadDocker(); }catch(e){} }, 30000));
    VU.sysTimers.push(setInterval(()=>{ try{ loadRemotes(); loadSSLCerts(); loadPorts(); loadOOM(); loadSessions(); }catch(e){} }, 60000));
}
document.addEventListener('keydown', function(e){ if(e.key==='Escape') fermerSysteme(); });

async function loadMetrics(){
    try{
        const d=await apiGet('/api/metrics');
        const cpu=Math.round(d.cpu||0), ram=Math.round(d.ram||0), disk=Math.round(d.disk||0);
        const load=(d.load_1m||0)+' '+(d.load_5m||0)+' '+(d.load_15m||0);
        // Desktop panels
        document.getElementById('cpu-val').textContent=cpu+'%';  _colorStatVal('cpu-val',cpu);
        document.getElementById('ram-val').textContent=ram+'%';  _colorStatVal('ram-val',ram);
        document.getElementById('disk-val').textContent=disk+'%';_colorStatVal('disk-val',disk);
        _setStatBar('cpu-bar',cpu);_setStatBar('ram-bar',ram);_setStatBar('disk-bar',disk);
        document.getElementById('load-val').textContent=load;
        // Mobile strip
        _setMmsVal('mms-cpu',cpu+'%',cpu);
        _setMmsVal('mms-ram',ram+'%',ram);
        _setMmsVal('mms-disk',disk+'%',disk);
        // Drawer
        const mmdCpu=document.getElementById('mmd-cpu');
        if(mmdCpu){mmdCpu.textContent=cpu+'%';_colorStatVal('mmd-cpu',cpu)}
        const mmdRam=document.getElementById('mmd-ram');
        if(mmdRam){mmdRam.textContent=ram+'%';_colorStatVal('mmd-ram',ram)}
        const mmdDisk=document.getElementById('mmd-disk');
        if(mmdDisk){mmdDisk.textContent=disk+'%';_colorStatVal('mmd-disk',disk)}
        _setStatBar('mmd-cpu-bar',cpu);_setStatBar('mmd-ram-bar',ram);_setStatBar('mmd-disk-bar',disk);
        const mmdLoad=document.getElementById('mmd-load');
        if(mmdLoad) mmdLoad.textContent=load;
        // Bandeau de constantes du tableau de bord
        majVitals(cpu, ram, disk);
        // Charts
        cpuHistory.push(cpu); ramHistory.push(ram);
        if(cpuHistory.length>60)cpuHistory.shift();
        if(ramHistory.length>60)ramHistory.shift();
        updateCharts();
    }catch(e){}
}
function initCharts(){
    const ctx=document.getElementById('cpu-chart').getContext('2d');
    cpuChart=new Chart(ctx,{type:'line',data:{labels:[],datasets:[{label:'CPU %',data:[],borderColor:'var(--accent)',backgroundColor:'rgba(0,255,204,.06)',fill:true,tension:0.4,pointRadius:0,borderWidth:2},{label:'RAM %',data:[],borderColor:'var(--violet)',backgroundColor:'rgba(124,92,252,.06)',fill:true,tension:0.4,pointRadius:0,borderWidth:2}]},options:{responsive:true,maintainAspectRatio:false,animation:false,plugins:{legend:{display:false}},scales:{x:{display:false},y:{beginAtZero:true,max:100,grid:{color:'var(--ov-04)'},ticks:{color:'var(--txt-faint)',font:{size:9}}}}}});
}
function updateCharts(){ if(!cpuChart)return; cpuChart.data.labels=cpuHistory.map((_,i)=>i); cpuChart.data.datasets[0].data=cpuHistory; cpuChart.data.datasets[1].data=ramHistory; cpuChart.update('none'); }

