async function gdMontageAjouter(){
    const t=document.getElementById('gd-m-type').value;
    const src=(document.getElementById('gd-m-src').value||'').trim();
    const pt=(document.getElementById('gd-m-pt').value||'').trim();
    const opt=(document.getElementById('gd-m-opt').value||'').trim();
    const per=document.getElementById('gd-m-persist').checked;
    if(!src||!pt){ if(typeof showToast==='function') showToast('Source et point requis','error',2400); return; }
    if(!await buConfirmer('Monter '+src+' sur '+pt+' ?\n\n'+
                (per?'Cette configuration sera écrite dans /etc/fstab et remontée à chaque '+
                     'démarrage. Cassandra valide le fichier après écriture et restaure une '+
                     'sauvegarde en cas de problème.\n\n':'')+
                'C\u2019est un changement d\u2019état du système.')) return;
    if(typeof showToast==='function') showToast('Montage en cours…','info',2500);
    try{
        const d=await apiPost('/api/ged/montage/add',
            {type:t, source:src, point:pt, options:opt, persister:per, confirm:true});
        if(typeof showToast==='function'){
            showToast(d&&d.ok ? ('✓ monté sur '+d.point+(d.persistant?' · permanent':''))
                              : ((d&&d.reason)||'échec'), d&&d.ok?'success':'error', 6000);
        }
        if(d&&d.ok&&d.avertissement&&typeof showToast==='function')
            setTimeout(function(){ showToast(d.avertissement,'info',6000); },800);
        document.getElementById('gd-montage-form').style.display='none';
        gdMontages(); gdSourcesPanneau(); gdSources();
    }catch(e){}
}
async function gdMontages(){
    const z=document.getElementById('gd-montages'); if(!z) return;
    let d; try{ d=await apiPost('/api/ged/montages',{}); }catch(e){ d=null; }
    const l=(d&&d.montages)||[];
    if(!l.length){
        z.innerHTML='<div class="empty-state" style="padding:22px">Aucun partage réseau monté.</div>';
        return;
    }
    z.innerHTML=l.map(function(m){
        return '<div class="gd-rem"><div class="ic">🖧</div><div class="t">'+
          '<b>'+escapeHtml(m.point)+'</b><span>'+escapeHtml(m.type+' · '+m.source)+'</span></div>'+
          (m.persistant?'<span class="gd-tag" style="--c:var(--accent)">permanent</span>':
                        '<span class="gd-tag" style="--c:var(--warn)">jusqu\u2019au redémarrage</span>')+
          '<button class="btn-x mini dgr" data-um="'+escapeAttr(m.point)+'">Démonter</button></div>';
    }).join('');
    z.querySelectorAll('[data-um]').forEach(function(b){
        b.onclick=async function(){
            if(!await buConfirmer('Démonter '+b.dataset.um+' ?\n\nAucun fichier distant n\u2019est touché. '+
                        'La ligne de /etc/fstab est commentée, pas effacée.')) return;
            try{
                const r=await apiPost('/api/ged/montage/remove',{point:b.dataset.um, confirm:true});
                if(typeof showToast==='function')
                    showToast(r&&r.ok?'Démonté':((r&&r.reason)||'échec'), r&&r.ok?'success':'error',4000);
                gdMontages(); gdSources();
            }catch(e){}
        };
    });
}


// LES RATTACHEMENTS du profil (23-09) : le coffre et son compte, le compte du panneau, les domaines.
// Les champs de l'onglet Mon compte retiré étaient des <input> ; ici ce sont des <dd> : on écrit du texte.
async function loadAccount() {
    const T = function(id, v){ const e = document.getElementById(id); if (e) e.textContent = v; };
    try {
        const bw = await apiPost('/api/me/bitwarden', {});
        if (bw && bw.ok) { T('ac-bw-url', bw.server_url || '—'); T('ac-bw-mail', bw.email || '—'); }
        else { T('ac-bw-url', 'non relié'); T('ac-bw-mail', '—'); }
    } catch (e) { T('ac-bw-url', 'injoignable'); }
    try {
        let me = null; try { me = await apiPost('/api/me', {}); } catch(e) {}
        if (!me || !me.ok) me = window._me || {};
        const fp = String(me.fp_account || '');
        const dt = document.getElementById('ac-fp-dt'), dd = document.getElementById('ac-fp');
        if (dt && dd) { dt.hidden = !fp; dd.hidden = !fp; dd.textContent = fp || '—'; }
        const her = new Set(me.sites_herites || []);
        const doms = (me.sites || []).slice().sort();
        const z = document.getElementById('ac-domaines');
        if (z) z.innerHTML = doms.length
            ? '<span class="cf-chips">' + doms.map(function(d){
                const h = her.has(d);
                return '<span class="cf-chip" title="' + (h ? 'par votre compte du panneau' : 'posé sur votre compte') + '">'
                    + escapeHtml(d) + (h ? '<span class="n">panneau</span>' : '') + '</span>';
              }).join('') + '</span>'
            : 'aucun';
    } catch (e) {}
}
// Le nom lisible d'un compte : son nom affiché s'il en a un, sinon la partie
// gauche de son adresse. Une seule règle, partagée par tous les écrans —
// sinon chacun invente son repli et ils finissent par diverger.
function nomLisible(rec){
    if(!rec) return '';
    const n = (typeof rec === 'string') ? '' : String(rec.display_name || '').trim();
    if(n) return n;
    const mail = String((typeof rec === 'string') ? rec : (rec.user || rec.email || '')).trim();
    return mail.split('@')[0] || mail;
}
