async function acMailCharger(){
    const z = document.getElementById('ac-mail-etat');
    try{
        const d = await apiPost('/api/me/mailbox',{});
        const v = function(id,val){ const e=document.getElementById(id); if(e) e.value = val; };
        v('ac-imap-host', d.host||''); v('ac-imap-port', d.port||993); v('ac-imap-user', d.user||'');
        const sm = d.smtp || {};
        v('ac-smtp-host', sm.host||''); v('ac-smtp-port', sm.host ? (sm.port||587) : ''); v('ac-smtp-user', sm.user||'');
        const ssl = document.getElementById('ac-imap-ssl'); if(ssl) ssl.checked = d.ssl !== false;
        if(!z) return;
        if(d.personnelle){
            z.className = 'ac-etat';
            z.innerHTML = '<span class="cf-led"></span><div><b>Boîte personnelle</b>'
                + '<span>Identifiants rangés dans votre coffre-fort.</span></div>';
        } else if(d.configuree){
            // Distinguer les deux est le cœur du changement : tant que la boîte
            // vient de la configuration globale, elle est partagée.
            z.className = 'ac-etat warn';
            z.innerHTML = '<span class="cf-led"></span><div><b>Boîte partagée</b>'
                + '<span>Elle vient de la configuration du serveur : un autre administrateur '
                + 'y a accès. Enregistrez-la ici pour qu’elle devienne la vôtre.</span></div>';
        } else {
            z.className = 'ac-etat off';
            z.innerHTML = '<span class="cf-led"></span><div><b>Aucune boîte</b>'
                + '<span>Renseignez votre serveur IMAP pour que Cassandra lise votre courrier.</span></div>';
        }
    }catch(e){
        if(z) z.innerHTML = '<span class="cf-led"></span><div><b>État inconnu</b>'
            + '<span>Le coffre ne répond pas.</span></div>';
    }
}

