async function acLoadSessions(){
    const el = document.getElementById('ac-sessions'); if(!el) return;
    try{
        const d = await apiPost('/api/me/sessions',{});
        const l = d.sessions || [];
        if(!l.length){
            el.innerHTML = '<div class="empty-state" style="padding:24px">Aucune session active.</div>';
            return;
        }
        el.innerHTML = l.map(function(s){
            // Une session ouverte avant l'ajout des colonnes n'a ni origine ni
            // navigateur : on le dit, plutôt que d'afficher un blanc.
            const nom = s.agent || 'Origine inconnue';
            const bas = [s.ip || '', acQuand(s.last_used || s.created)].filter(Boolean).join(' · ');
            return '<div class="ac-li">'
                + '<span class="cf-led"' + (s.current ? '' : ' style="background:var(--txt-ghost)"') + '></span>'
                + '<span><b>' + escapeHtml(nom) + '</b>'
                + '<span class="d">' + escapeHtml(bas) + '</span></span>'
                + (s.current ? '<span class="now">CELLE-CI</span>'
                             : '<span class="d">#' + escapeHtml(s.id || '') + '</span>') + '</div>';
        }).join('');
    }catch(e){
        el.innerHTML = '<div class="empty-state" style="padding:24px">Indisponible.</div>';
    }
}

async function acLoadHistory() {
    const el = document.getElementById('ac-history'); if (!el) return;
    try {
        // `/api/me/history` rend les MESSAGES de conversation : du texte long,
        // parfois du HTML, qui n'a rien à faire dans une carte « activité ».
        // `/api/me/activity` rend les actes — c'est ce que la carte annonce.
        const d = await apiPost('/api/me/activity', {});
        const ev = (d && d.events) || [];
        if (!ev.length) {
            el.innerHTML = '<div class="empty-state" style="padding:24px">Aucune action enregistrée.</div>';
            return;
        }
        el.innerHTML = ev.slice(0, 12).map(function(e){
            const ts = String(e.ts || '');
            const par = (e.who === 'user') ? '' : 'Cassandra';
            return '<div class="ac-ev"><time>' + escapeHtml(acQuand(ts)) + '</time>'
                + '<p><b>' + escapeHtml(acActe(e.action)) + '</b>'
                + (e.detail ? ' — ' + escapeHtml(String(e.detail).slice(0, 90)) : '')
                + (par ? ' <span style="color:var(--txt-faint)">· par ' + par + '</span>' : '')
                + '</p></div>';
        }).join('');
    } catch (e) {
        el.innerHTML = '<div class="empty-state" style="padding:24px">Indisponible.</div>';
    }
}

// « il y a 4 min » se lit ; « 2026-08-08T05:11:57 » se déchiffre.
function acQuand(ts){
    if(!ts) return '—';
    const t = Date.parse(String(ts).replace(' ', 'T'));
    if(isNaN(t)) return String(ts).slice(0, 16);
    const s = Math.max(0, (Date.now() - t) / 1000);
    if(s < 60) return "à l'instant";
    if(s < 3600) return 'il y a ' + Math.floor(s/60) + ' min';
    if(s < 86400) return 'il y a ' + Math.floor(s/3600) + ' h';
    if(s < 172800) return 'hier';
    return String(ts).slice(0, 10);
}

// Les actions sont des identifiants techniques : on les nomme en français.
const AC_ACTES = {
    reveal: 'Secret révélé', set: 'Secret enregistré', delete: 'Secret supprimé',
    login: 'Connexion', logout: 'Déconnexion',
    fp_scan_start: 'Analyse lancée', site_screenshot: 'Aperçu régénéré',
    user_fp_link: 'Compte adossé à FastPanel', mail_boite: 'Boîte mail enregistrée',
    settings_password: 'Mot de passe modifié', reglage_veille: 'Surveillance modifiée',
};
function acActe(a){
    a = String(a || '').trim();
    if(AC_ACTES[a]) return AC_ACTES[a];
    // Repli lisible plutôt qu'un identifiant brut : « fp_db_create » → « Fp db create ».
    const t = a.replace(/[_.]+/g, ' ').trim();
    return t ? (t.charAt(0).toUpperCase() + t.slice(1)) : 'Action';
}

