// Heures calmes et sourdines (par personne — le serveur les tient déjà)
async function notifCalmesCharger(){
    const el = document.getElementById('ntc-calmes'); if (!el) return;
    try {
        const d = await apiPost('/api/notif/politique', {}); const p = (d && d.prefs) || {};
        const on = !!p.calmes, deb = p.calme_debut || '22:00', fin = p.calme_fin || '08:00';
        el.innerHTML = '<div class="mx-rows">' + _cfgLigneSw('notif_heures_calmes', on, 'Heures calmes', 'de ' + escapeHtml(deb) + ' à ' + escapeHtml(fin) + (p.fuseau ? ' — ' + escapeHtml(p.fuseau) : ' — fuseau inconnu : compté en UTC'), 'notifCalmesEnregistrer(' + (!on) + ')') + '</div>'
          + '<div class="settings-row triple" style="margin-top:8px"><div class="s-field"><label class="s-label">Début</label><input class="s-input" type="time" id="ntc-debut" value="' + escapeHtml(deb) + '"></div><div class="s-field"><label class="s-label">Fin</label><input class="s-input" type="time" id="ntc-fin" value="' + escapeHtml(fin) + '"></div></div>'
          + '<div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:8px"><button class="mx-btn primary" onclick="notifCalmesEnregistrer()">Enregistrer</button><span class="s-hint" id="ntc-msg" style="margin:0"></span></div>';
        // Le fuseau est celui du COMPTE, lu du navigateur à la première ouverture de la cloche — jamais deviné.
        const fz = document.getElementById('ntc-fuseau');
        if (fz) { let tz = ''; try { tz = Intl.DateTimeFormat().resolvedOptions().timeZone || ''; } catch(e) {}
                  fz.textContent = p.fuseau ? 'compté dans votre fuseau : ' + p.fuseau : 'fuseau inconnu — il se pose à la première ouverture de la cloche (votre navigateur dit ' + (tz || '?') + ')'; }
        const sd = document.getElementById('ntc-sourdines');
        if (sd) { const L = (d && d.sourdines) || [];
                  sd.innerHTML = L.length ? '<div class="mx-rows">' + L.map(function(r){ return '<div class="mx-row"><span class="mx-pill">SOURDINE</span><div class="mx-rt"><b>' + escapeHtml(r.portee === 'source' ? (r.cible_nom || r.cible) : 'une notification') + '</b><span>' + escapeHtml(r.portee === 'source' ? 'toute la source' : r.cible) + ' · jusqu\u2019au ' + escapeHtml(String(r.fin).slice(0, 16)) + ' · ' + (r.retenues || 0) + ' retenue(s)</span></div><div class="mx-gest"><button class="mx-btn" onclick="notifSourdineLever(\'' + escapeAttr(r.portee) + '\',\'' + escapeAttr(r.cible) + '\')">Lever</button></div></div>'; }).join('') + '</div>' : 'Aucune sourdine en cours — elles se posent depuis la cloche, sur une notification ou sur toute une source, toujours datées.'; }
        const cm = document.getElementById('ntc-courriel'); const cb = document.getElementById('moi-mail-pref');
        if (cm) cm.textContent = (cb && cb.checked) ? 'Vous êtes prévenu par courriel (alertes, rappels, incidents, récap).' : 'Courriel coupé par l\u2019interrupteur général.';
    } catch(e) { el.innerHTML = '<div class="empty-state">Erreur de chargement</div>'; }
}
