function moiPhotoChoisir(input){
    const f = input && input.files && input.files[0]; if (!f) return;
    if (f.size > 8 * 1024 * 1024) { if (typeof showToast === 'function') showToast('Fichier trop lourd', 'error', 3000); return; }
    const img = new Image(); const rd = new FileReader();
    rd.onload = function(){ img.onload = function(){
        const c = document.createElement('canvas'); c.width = 256; c.height = 256; const x = c.getContext('2d');
        const s = Math.min(img.width, img.height); x.drawImage(img, (img.width - s) / 2, (img.height - s) / 2, s, s, 0, 0, 256, 256);
        let url = ''; try { url = c.toDataURL('image/webp', 0.9); if (url.indexOf('image/webp') < 0) url = c.toDataURL('image/jpeg', 0.9); } catch(e) { url = c.toDataURL('image/png'); }
        moiPhotoEnvoyer(url);
    }; img.src = String(rd.result); };
    rd.readAsDataURL(f); input.value = '';
}
async function moiPhotoEnvoyer(url){
    try { const d = await apiPost('/api/me/photo', {data: url}); if (d && d.ok) { ETAT.moi._monPortrait = url; moiPhotoPeindre(url); if (typeof _umPortrait === 'function') _umPortrait(); if (typeof showToast === 'function') showToast('Photo posée', 'success', 2600); } else if (typeof showToast === 'function') showToast('Refus : ' + ((d && d.error) || '?'), 'error', 4000); }
    catch(e) { if (typeof showToast === 'function') showToast('Erreur réseau', 'error', 3000); }
}
async function moiPhotoRetirer(){
    if (!await fp2Confirm('L\u2019en-tête, le salon et les courriels reviennent à vos initiales.\n\nRetirer votre photo ?', 'Retirer la photo')) return;
    try { const d = await apiPost('/api/me/photo', {retirer: 1}); if (d && d.ok) { ETAT.moi._monPortrait = ''; moiPhotoPeindre(''); moiMenuCharger && moiMenuCharger(); if (typeof showToast === 'function') showToast('Photo retirée', 'success', 2600); } } catch(e) {}
}
async function moiPhotoPanneau(){
    const me = window._me || {}; if (!me.fp_account) return;
    try { const a = await apiPost('/api/fp/user/avatar', {username: me.fp_account}); if (a && a.ok && a.url) { const img = new Image(); img.crossOrigin = 'anonymous'; img.onload = function(){ const c = document.createElement('canvas'); c.width = 256; c.height = 256; const x = c.getContext('2d'); const s = Math.min(img.width, img.height); x.drawImage(img, (img.width - s) / 2, (img.height - s) / 2, s, s, 0, 0, 256, 256); let url = ''; try { url = c.toDataURL('image/webp', 0.9); if (url.indexOf('image/webp') < 0) url = c.toDataURL('image/jpeg', 0.9); } catch(e) { url = c.toDataURL('image/png'); } moiPhotoEnvoyer(url); }; img.onerror = function(){ if (typeof showToast === 'function') showToast('Le panneau ne livre pas cette image', 'error', 3000); }; img.src = a.url; } else if (typeof showToast === 'function') showToast('Le panneau n\u2019a pas de portrait pour ce compte', 'error', 3000); } catch(e) {}
}
function moiMenuCharger(){ try { if (typeof umCharger === 'function') umCharger(); } catch(e) {} }
// Apparence : la taille du texte et l'écran d'ouverture vivent dans le navigateur
function moiTaille(v){ const px = {compacte: '13px', normale: '', grande: '16px'}[v] || ''; document.documentElement.style.fontSize = px; try { localStorage.setItem('cass_taille', v || 'normale'); } catch(e) {} }
function moiOuverture(v){ try { if (v) localStorage.setItem('cass_ouverture', v); else localStorage.removeItem('cass_ouverture'); } catch(e) {} }
(function(){ try { const t = localStorage.getItem('cass_taille'); if (t && t !== 'normale') moiTaille(t); } catch(e) {} })();
// LES GESTES DE LA MACHINE (pièce 2) : une feuille, une route gardée, un retour lisible
async function sysGeste(route, o){
    o = o || {};
    const r = await fp2Demander((o.texte || '') + '\n\n' + (o.question || (o.titre + ' ?')), o.titre || route, {mdp: true, mot: o.mot || '', garde: o.garde || 0, danger: !!o.danger, ok: o.ok || 'Confirmer'});
    if (!r.ok) return null;
    const corps = Object.assign({admin_password: r.mdp}, o.mot ? {mot: r.mot} : {}, o.geste ? {geste: o.geste} : {}, o.extra || {});
    let d = null;
    try { d = await apiPost('/api/system/' + route, corps); } catch(e) { d = {ok: false, error: 'Erreur réseau'}; }
    const msg = d && d.ok ? ('✓ ' + (o.titre || route) + (d.unite ? ' — lancé (' + d.unite + ')' : '') + (d.revoked != null ? ' — ' + d.revoked + ' session(s)' : '') + (d.fichiers && d.octets != null ? ' — ' + (d.fichiers.length || d.fichiers) + ' fichier(s), ' + Math.round(d.octets / 1024) + ' Ko' : ''))
                          : ('✗ ' + ((d && d.error) || 'échec'));
    if (typeof showToast === 'function') showToast(msg, d && d.ok ? 'success' : 'error', d && d.ok ? 3000 : 5000);
    const cible = o.feedback || {backup: 'sys-sauv-msg', restore: 'sys-sauv-msg', rollback: 'sys-sauv-msg', update: 'sys-maj-msg', reinstall: 'sys-maj-msg', vacuum: 'sys-menage-msg', purge: 'sys-menage-msg', caches: 'sys-menage-msg', 'sessions/revoke_all': 'sys-menage-msg', geste: 'cfg-svc-feedback', factory: 'usine-msg'}[route];
    if (cible) _sfb(cible, msg, d && d.ok ? 'ok' : 'err');
    if (route === 'backup' || route === 'restore' || route === 'rollback' || (o.geste === 'parasites')) sysSauvegardesCharger();
    if (route === 'geste') setTimeout(svcCharger, 3000);
    return d;
}
async function sysJournal(service){
    const nom = {cassandra: 'Cassandra', collector: 'Sensorium', ollama: 'Ollama', nginx: 'nginx'}[service] || service;
    const r = await fp2Demander('Les 200 dernières lignes du journal de ' + nom + ' (journalctl).\n\nLire le journal ?', 'Journal · ' + nom, {mdp: true, ok: 'Lire'});
    if (!r.ok) return;
    let d = null; try { d = await apiPost('/api/system/geste', {geste: 'journal', service: service, admin_password: r.mdp}); } catch(e) {}
    if (!d || !d.ok) { if (typeof showToast === 'function') showToast('✗ ' + ((d && d.error) || 'journal illisible'), 'error', 4000); return; }
    if (typeof _fpPanneau === 'function') _fpPanneau('Journal · ' + nom, '<pre style="white-space:pre-wrap;font:11.5px ui-monospace,monospace;max-height:70vh;overflow:auto">' + escapeHtml(d.texte || '(vide)') + '</pre>');
    else buDire(d.texte || '(vide)');
}
async function sysSauvegardesCharger(){
    const dep = document.getElementById('sys-depots'), bas = document.getElementById('sys-bases'); if (!dep) return;
    let d = null; try { d = await apiPost('/api/system/sauvegardes', {}); } catch(e) {}
    if (!d || !d.ok) { dep.innerHTML = '<div class="empty-state">Lecture impossible</div>'; return; }
    const ko = n => (n >= 1048576 ? (n / 1048576).toFixed(1) + ' Mo' : Math.round(n / 1024) + ' Ko');
    dep.innerHTML = (d.depots || []).length ? '<div class="mx-rows">' + d.depots.map(function(x){ return '<div class="mx-row"><span class="mx-pill ' + (x.vivant ? 'stable' : '') + '">DÉPÔT</span><div class="mx-rt"><b>' + escapeHtml(x.nom) + (x.vivant ? ' · le vivant' : '') + '</b><span>' + escapeHtml(x.quand) + ' · cassandra.py ' + ko(x.octets) + '</span></div><div class="mx-gest">' + (x.vivant ? '' : '<button class="mx-btn" onclick="sysGeste(\'rollback\', {titre:\'Revenir au dépôt ' + escapeHtml(x.nom) + '\', texte:\'Le code de ce dépôt reprend la place du vivant ; les données ne bougent pas. Cassandra redémarre.\', mot:\'REVENIR\', ok:\'Revenir\', extra:{nom:\'' + escapeHtml(x.nom) + '\'}})">Revenir à</button>') + '</div></div>'; }).join('') + '</div>'
                                            : '<div class="empty-state">Aucun dépôt gardé par CN_deploy.sh.</div>';
    if (bas) bas.innerHTML = (d.bases || []).length ? '<div class="mx-rows">' + d.bases.map(function(x){ return '<div class="mx-row"><span class="mx-pill">BASE</span><div class="mx-rt"><b>' + escapeHtml(x.nom) + '</b><span>' + escapeHtml((x.fichiers || []).join(', ')) + ' · ' + ko(x.octets) + '</span></div><div class="mx-gest"><button class="mx-btn" onclick="sysGeste(\'restore\', {titre:\'Restaurer ' + escapeHtml(x.nom) + '\', texte:\'Base, mémoire et configuration de cette sauvegarde reprennent la place des vivantes ; le code ne bouge pas. Cassandra redémarre. Ce qui a été écrit depuis est perdu.\', mot:\'RESTAURER\', danger:true, ok:\'Restaurer\', extra:{nom:\'' + escapeHtml(x.nom) + '\'}})">Restaurer</button></div></div>'; }).join('') + '</div>'
                                                  : '<div class="empty-state">Aucune sauvegarde de base : « Sauvegarder maintenant » en fait une.</div>';
    const v = document.getElementById('sys-version'); if (v) v.textContent = 'v' + (d.version || '?').toString().replace(/^v/, '') + ' · ' + (d.md5 || '') + (d.install ? ' · CN_install.sh du ' + (d.install_date || '?') : ' · CN_install.sh ABSENT');
    const pa = document.getElementById('sys-parasites'); const P = d.parasites || {};
    if (pa) { pa.textContent = P.n ? (P.n + ' élément(s), ' + ko(P.octets || 0) + ' : ' + (P.fichiers || []).slice(0, 4).map(function(x){ return x.chemin.split('/').pop(); }).join(', ') + ((P.fichiers || []).length > 4 ? '…' : '')) : 'rien ne traîne'; }
    const r = document.getElementById('sys-retentions'); const R = d.retentions || {};
    if (r) { const lib = {RETENTION_RAW_DAYS: 'brut (une ligne / 30 s)', RETENTION_HOURLY_DAYS: 'horaire', RETENTION_DAILY_DAYS: 'quotidien', RETENTION_HEALTH_DAYS: 'score de santé', RETENTION_LOG_ERRORS_DAYS: 'erreurs des journaux', RETENTION_FP_DAYS: 'statistiques du panneau'};
             r.innerHTML = Object.keys(R).length ? Object.keys(R).map(function(k){ return '<b>' + escapeHtml(lib[k] || k) + '</b> : ' + R[k] + ' j'; }).join(' · ') + ' — constantes du collecteur, lisibles ici, pas réglables (décision à prendre).' : 'collecteur illisible'; }
    if (!(d.install)) { const b = document.querySelector('#sys-maj .mx-btn.primary'); if (b) b.disabled = true; }
}
function sysExporter(){
    apiPost('/api/memory/config', {}).then(function(r){
        const c = (r && r.config) || {}; const propre = {};
        Object.keys(c).forEach(function(k){ if (!/_set$/.test(k) && !/token|key|pass|secret/i.test(k)) propre[k] = c[k]; });
        const b = new Blob([JSON.stringify({cassandra_config_export: true, quand: new Date().toISOString(), config: propre}, null, 2)], {type: 'application/json'});
        const a = document.createElement('a'); a.href = URL.createObjectURL(b); a.download = 'cassandra-configuration.json'; document.body.appendChild(a); a.click(); setTimeout(function(){ URL.revokeObjectURL(a.href); a.remove(); }, 800);
        _sfb('sys-sauv-msg', 'Configuration exportée, sans aucun secret (' + Object.keys(propre).length + ' clés)', 'ok');
    }).catch(function(){ _sfb('sys-sauv-msg', 'Export impossible', 'err'); });
}
function sysImporter(input){
    const f = input && input.files && input.files[0]; if (!f) return;
    const rd = new FileReader();
    rd.onload = async function(){
        let j = null; try { j = JSON.parse(String(rd.result)); } catch(e) { _sfb('sys-sauv-msg', 'Fichier illisible', 'err'); return; }
        const c = (j && j.config) || j || {}; const cles = Object.keys(c).filter(function(k){ return !/token|key|pass|secret/i.test(k); });
        if (!cles.length) { _sfb('sys-sauv-msg', 'Rien à importer', 'err'); return; }
        if (!await fp2Confirm(cles.length + ' clé(s) vont être appliquées : ' + cles.slice(0, 8).join(', ') + (cles.length > 8 ? '…' : '') + '. Les secrets ne voyagent jamais par ce fichier.\n\nAppliquer ?', 'Importer une configuration')) return;
        const upd = {}; cles.forEach(function(k){ upd[k] = c[k]; });
        try { const d = await apiPost('/api/memory/config', {update: upd}); _sfb('sys-sauv-msg', d && d.ok ? 'Importé : ' + Object.keys(d.updated || {}).length + ' clé(s) acceptée(s) sur ' + cles.length : 'Refus', d && d.ok ? 'ok' : 'err'); }
        catch(e) { _sfb('sys-sauv-msg', 'Erreur réseau', 'err'); }
    };
    rd.readAsText(f); input.value = '';
}
function sysUsineChoix(){
    const g = document.getElementById('usine-garder'); if (g) g.hidden = (document.getElementById('usine-ensuite') || {}).value !== '0';
}
async function sysUsine(){
    const coffre = (document.getElementById('usine-coffre') || {}).value !== '0', reinst = (document.getElementById('usine-ensuite') || {}).value !== '0';
    const garder = ['swap', 'depots', 'searxng', 'journaux'].filter(function(k){ const c = document.getElementById('usine-garde-' + k); return c && c.checked; });
    const lib = {swap: 'le swap', depots: 'les dépôts', searxng: 'SearXNG', journaux: 'les journaux'};
    const reste = (coffre ? ['le coffre'] : []).concat(reinst ? [] : garder.map(function(k){ return lib[k]; }));
    await sysGeste('factory', {titre: 'Restauration usine', texte: 'Tout est effacé — code, clés, comptes, mémoire, base, configuration' + (reinst ? ', dépôts et sauvegardes d\u2019install.sh' : '') + ' — puis ' + (reinst ? 'CN_install.sh réinstalle à neuf depuis une copie de travail' : 'rien n\u2019est réinstallé : la machine reste vide') + '. ' + (reste.length ? 'Reste : ' + reste.join(', ') + '.' : 'Rien ne reste.') + ' Rien ne revient.', mot: 'USINE', garde: 30, danger: true, ok: 'Restaurer l\u2019usine', extra: {keep_vault: coffre, reinstaller: reinst, garder: garder}});
}
async function sysMajArchive(input){
    const f = input && input.files && input.files[0]; if (!f) return;
    input.value = '';
    if (f.size > 64 * 1024 * 1024) { _sfb('sys-maj-msg', 'Archive trop grande (' + Math.round(f.size / 1048576) + ' Mo, maximum 64)', 'err'); return; }
    const rd = new FileReader();
    rd.onload = async function(){
        const b64 = String(rd.result || '').split(',')[1] || '';
        if (!b64) { _sfb('sys-maj-msg', 'Archive illisible', 'err'); return; }
        _sfb('sys-maj-msg', '⏳ ' + f.name + ' (' + Math.round(f.size / 1024) + ' Ko) — envoi et vérification…', 'ok');
        const d = await sysGeste('update', {titre: 'Mettre à jour depuis ' + f.name, texte: 'L\u2019archive est vérifiée (cassandra.py et le collecteur compilent, CN_install.sh passe bash -n), puis CN_install.sh part d\u2019une copie de travail : services arrêtés, code et dépendances posés, configuration et mémoire gardées. Quelques minutes, puis Cassandra revient.', ok: 'Mettre à jour', extra: {archive: b64, nom: f.name}});
        if (d && d.ok) _sfb('sys-maj-msg', '✓ ' + (d.version ? 'version ' + d.version + ' · ' : '') + (d.md5 || '') + (d.meme_code ? ' — le même code que celui en place' : '') + (d.note ? ' — ' + d.note : '') + ' — lancé (' + (d.unite || '') + ')', 'ok');
    };
    rd.readAsDataURL(f);
}

// ── LE RELECTEUR DE L'ÉVOLUTION : son côté « en ligne » ──
function relRemplir(rl){
    rl=rl||{};
    const pv=document.getElementById('cfg-rel-provider'), md=document.getElementById('cfg-rel-model'),
          ky=document.getElementById('cfg-rel-key'), ur=document.getElementById('cfg-rel-url');
    if(pv && rl.provider) pv.value=rl.provider;
    if(md && document.activeElement!==md) md.value=rl.model||'';
    if(ur && rl.base_url) ur.value=rl.base_url;
    if(ky) ky.placeholder = rl.cle ? 'clé enregistrée — laisser vide pour la garder' : 'sk-or-v1-••••••••';
    relFournisseur(true);
}
const REL_AIDES = {deepseek:'deepseek-chat : répond sans réfléchir, en une seconde.',
                   openrouter:'Un modèle gratuit finit par « :free » ; « openrouter/free » en tire un au hasard : à éviter.',
                   ollama:'Un petit modèle local refuse tout : préférer un modèle en ligne.',
                   custom:'Le nom que votre point d’accès attend.'};
function relFournisseur(sansModele){
    const pv=(document.getElementById('cfg-rel-provider')||{}).value||'openrouter';
    const f=document.getElementById('cfg-rel-url-field'); if(f) f.style.display = pv==='custom' ? 'block' : 'none';
    const h=document.getElementById('cfg-rel-model-hint'); if(h) h.textContent = REL_AIDES[pv]||'';
}
function relRefermer(){
    ETAT.itare._labRole='';
    const b=document.getElementById('lab-choix'); if(b){ b.hidden=true; b.innerHTML=''; }
    labEnLigneFermer();
    loadLab();
}
async function relEnregistrer(){
    const corps={provider:(document.getElementById('cfg-rel-provider')||{}).value||'',
                 model:((document.getElementById('cfg-rel-model')||{}).value||'').trim().replace(/[.,;:!?»« ]+$/,''),
                 api_key:((document.getElementById('cfg-rel-key')||{}).value||'').trim(),
                 base_url:((document.getElementById('cfg-rel-url')||{}).value||'').trim()};
    if(!corps.model){ _sfb('cfg-rel-msg','Un modèle, tel que le fournisseur l’écrit.','err'); return; }
    try{
        const d=await apiPost('/api/settings/relecteur', corps);
        const k=document.getElementById('cfg-rel-key'); if(k) k.value='';
        if(d && d.ok){
            const sansCle = !(d.cle||corps.provider==='ollama');
            // LA LISTE SE REFERME ET LA CARTE SE DÉSÉLECTIONNE (19-09) : elles restaient ouvertes et vertes.
            relRefermer();
            if(typeof showToast==='function') showToast('Relecteur : '+corps.model+(sansCle?' — sans clé, les pièces attendront':' — « Essayer » sur sa carte le vérifie'), sansCle?'warning':'success', 5000);
        }
        else _sfb('cfg-rel-msg', (d&&d.error)||'refusé', 'err');
    }catch(e){ _sfb('cfg-rel-msg','Erreur réseau','err'); }
}
async function relEssai(){
    const dire=function(m, ok){ _sfb('cfg-rel-msg', m, ok?'ok':'err'); if(typeof showToast==='function') showToast(m, ok?'success':'error', ok?5000:9000); };
    if(typeof showToast==='function') showToast('Question envoyée au relecteur…', 'info', 2500);
    try{
        const d=await apiPost('/api/settings/relecteur/essai',{});
        if(d && d.ok) dire(d.modele+' a répondu en '+d.secondes+' s : '+d.reponse, true);
        else dire('Le relecteur ne répond pas : '+((d&&(d.erreur||d.error))||'aucune réponse'), false);
    }catch(e){ dire('Erreur réseau', false); }
}
async function relRetirer(){
    if(!await fp2Confirm('Le relecteur propre est retiré : l’agent secondaire relira de nouveau les pièces. La clé du relecteur est effacée.\n\nRevenir à l’agent secondaire ?', 'Relecteur de l’évolution')) return;
    try{ const d=await apiPost('/api/settings/relecteur',{retirer:true});
         if(d&&d.ok){ relRefermer(); if(typeof showToast==='function') showToast('L’agent secondaire relit de nouveau.', 'success', 4000); }
         else _sfb('cfg-rel-msg', 'refusé', 'err'); }
    catch(e){ _sfb('cfg-rel-msg','Erreur réseau','err'); }
}

// Le côté « en ligne » d'un rôle : une section cachée sous la carte des rôles
function labEnLigne(role){
    document.querySelectorAll('#tab-settings .set-enligne').forEach(function(s){ s.hidden = s.getAttribute('data-role') !== role; });
    const s = document.querySelector('#tab-settings .set-enligne[data-role="' + role + '"]'); if (s) setTimeout(function(){ s.scrollIntoView({behavior: 'smooth', block: 'start'}); }, 60);
}
function labEnLigneFermer(){ document.querySelectorAll('#tab-settings .set-enligne').forEach(function(s){ s.hidden = true; }); }

// Recherche transversale : quand on cherche, les familles s'effacent — on ne
// veut pas savoir où c'est rangé, on veut le trouver.
function setChercher(q) {
    const t = (q || '').trim().toLowerCase();
    const info = document.getElementById('set-search-info');
    const nav  = document.querySelector('#tab-settings .set-nav');
    const lg   = document.getElementById('set-legende');
    if (nav) nav.style.opacity = t ? '.45' : '';
    if (!t) {
        setFamRestore();
        if (info) info.textContent = '';
        return;
    }
    if (lg) lg.textContent = 'Recherche dans toutes les familles.';
    // Les sections s'effacent ; une liste de résultats prend leur place : chaque ligne dit la carte,
    // la famille, la vision, et « Ouvrir » y mène en la chargeant — jamais une carte brute non chargée.
    const admin = setEstAdmin();
    const hits = [];
    document.querySelectorAll('#tab-settings .settings-section').forEach(function(sec, i){
        sec.style.display = 'none';
        const f = sec.getAttribute('data-fam') || '';
        if (setVisionDe(f) === 'machine' && !admin) return;
        if (sec.getAttribute('data-admin') && !admin) return;
        const txt = (sec.innerText || sec.textContent || '').toLowerCase();
        if (txt.indexOf(t) < 0) return;
        const tt = sec.querySelector('.settings-section-title, .bu-ct');
        hits.push({i: i, fam: f, titre: (tt ? (tt.childNodes[0] && tt.childNodes[0].textContent || tt.textContent) : 'Carte').trim()});
    });
    const vd = document.getElementById('set-verdict'); if (vd) vd.hidden = true;
    const rs = document.getElementById('set-resultats');
    if (rs) {
        rs.hidden = false;
        const nomF = function(f){ const b = document.querySelector('#tab-settings .set-nav-item[data-fam="' + f + '"] b'); return b ? b.textContent : (f || 'sans famille'); };
        rs.innerHTML = '<div class="mx-chart-h"><h2>« ' + escapeHtml(q.trim()) + ' »</h2><span class="mx-meta">' + hits.length + ' carte' + (hits.length > 1 ? 's' : '') + '</span></div>'
          + (hits.length ? '<div class="mx-rows">' + hits.map(function(h){
                const v = setVisionDe(h.fam);
                return '<div class="mx-row"><span class="mx-pill ' + (v === 'moi' ? 'ok' : 'info') + '">' + (v === 'moi' ? 'MON COMPTE' : 'LA MACHINE') + '</span>'
                     + '<div class="mx-rt"><b>' + escapeHtml(h.titre) + '</b><span>' + escapeHtml(nomF(h.fam)) + '</span></div>'
                     + '<div class="mx-gest"><button class="mx-btn primary" onclick="setOuvrir(\'' + escapeHtml(h.fam) + '\',' + h.i + ')">Ouvrir</button></div></div>';
            }).join('') + '</div>'
            : '<div class="mx-empty"><span class="mx-pill">RIEN</span><div><b>Aucune carte ne porte ce mot</b><p>Cherché dans les titres, les libellés et les clés des deux visions.</p></div></div>');
    }
    if (info) info.textContent = hits.length ? (hits.length + ' carte' + (hits.length > 1 ? 's' : '')) : 'aucun résultat';
}
// Un résultat ouvre sa famille, dans sa vision, la charge, et fait défiler jusqu'à la carte.
function setOuvrir(fam, i){
    const inp = document.getElementById('set-search'); if (inp) inp.value = '';
    const info = document.getElementById('set-search-info'); if (info) info.textContent = '';
    const nav = document.querySelector('#tab-settings .set-nav'); if (nav) nav.style.opacity = '';
    const sec = document.querySelectorAll('#tab-settings .settings-section')[i];
    if (sec && sec.id) ETAT.reglages._setOuvrir = sec.id;
    setVision(setVisionDe(fam)); setFam(fam);
    if (sec) setTimeout(function(){ sec.classList.remove('set-plie'); sec.scrollIntoView({behavior: 'smooth', block: 'start'}); }, 60);
}
// Le verdict d'une famille : ce qui manque, avec le geste. Stable = une ligne calme, jamais un vide.
let _setVerdictSeq = 0;
async function setVerdict(fam){
    const box = document.getElementById('set-verdict'); if (!box) return;
    const seq = ++_setVerdictSeq;
    let v = null;
    try { v = await apiGet('/api/reglages/verdict?famille=' + encodeURIComponent(fam || '')); } catch(e) { v = null; }
    if (seq !== _setVerdictSeq || ETAT.reglages._setFam !== fam) return;
    if (!v || !v.ok) { box.hidden = true; return; }
    // « Tout est réglé ici. » ne disait rien : quand rien n'est à régler, la bannière se tait.
    if (v.niveau === 'stable') { box.hidden = true; return; }
    box.hidden = false;
    box.innerHTML = '<div class="mx-verdict"><div class="mx-vmark ' + escapeHtml(v.niveau) + '"></div><div style="display:flex;flex-direction:column;gap:3px;min-width:0"><p class="mx-vtitle">' + escapeHtml(v.titre) + '</p><span class="mx-vsub">' + escapeHtml(v.sous_titre || '') + '</span></div></div>'
      + ((v.lignes || []).length ? '<div class="mx-rows">' + v.lignes.map(function(l){
            return '<div class="mx-row"><span class="mx-pill ' + escapeHtml(l.niveau) + '">' + (l.niveau === 'panne' ? 'À RÉGLER' : 'À REGARDER') + '</span><div class="mx-rt"><b>' + escapeHtml(l.titre) + '</b>' + (l.detail ? '<span>' + escapeHtml(l.detail) + '</span>' : '') + '</div>'
                 + '<div class="mx-gest">' + (l.gestes || []).map(function(g, k){ return '<button class="mx-btn' + (k === 0 ? ' primary' : '') + '" onclick=\'setGeste(' + escapeHtml(JSON.stringify(g)) + ')\'>' + escapeHtml(g.lib) + '</button>'; }).join('') + '</div></div>';
        }).join('') + '</div>' : '');
}
function setGeste(g){
    const f = (g && g.f) || '', a = (g && g.a) || '';
    if (f === 'famille') { setVision(setVisionDe(a)); setFam(a); }
    else if (f === 'carte') { const secs = Array.prototype.slice.call(document.querySelectorAll('#tab-settings .settings-section'));
        const i = secs.findIndex(function(s){ const t = s.querySelector('.settings-section-title'); return t && t.textContent.indexOf(a) >= 0; });
        if (i >= 0) { secs[i].classList.remove('set-plie'); secs[i].scrollIntoView({behavior: 'smooth', block: 'start'}); } }
    else if (f === 'modele') labChoisir(a);
    else if (f === 'modele_oublier') { apiPost('/api/lab/setmodel', {model: ''}).then(function(){ if (typeof showToast === 'function') showToast('Choix oublié : ' + a, 'success', 2600); loadLab(); if (ETAT.reglages._setFam) setVerdict(ETAT.reglages._setFam); }); }
    else if (f === 'pull') labPull(a, '');
    else if (f === 'lab') loadLab();
    else if (f === 'evolution') switchTab('evolution');
}

// Pastilles : ce qui manque, famille par famille. Rien ne s'affiche quand tout
// va bien — une pastille verte partout ne se remarquerait plus.
async function cfgSante() {
    try {
        const d = await apiGet('/api/reglages/sante');
        if (!d.ok) return;
        Object.keys(d.familles || {}).forEach(function(f){
            const el = document.getElementById('past-' + f);
            if (!el) return;
            const x = d.familles[f];
            el.className = 'set-pastille' + (x.alertes.length ? ' ' + x.etat : '');
            el.textContent = x.alertes.length ? String(x.alertes.length) : '';
            el.title = (x.alertes || []).join(' · ');
        });
    } catch(e) {}
}

// CE QUE DIT LA CONFIGURATION — et rien de plus. Ce texte ne parle que du
// FICHIER nginx : des directives présentes ne prouvent pas qu'une connexion
// aboutisse. C'est la confusion qui a coûté deux jours : la carte annonçait
// « opérationnels » pendant que le navigateur bouclait sur des reconnexions.
function wsPhraseConfig(d){
    const n = (d.vhosts || []).length;
    if(d.conforme) return {c: 'var(--txt-soft)',
        t: 'Directives en place sur ' + n + ' vhost(s) — c\u2019est ce que dit ' +
           'le fichier nginx, pas une connexion.'};
    if(n) return {c: 'var(--warn)',
        t: 'Configuration absente ou effacée sur ' + n + ' vhost(s).'};
    return {c: 'var(--txt-muted)',
        t: d.reason || 'Aucun vhost nginx ne mène à Cassandra sur cette machine.'};
}

// CE QUE DIT L'ÉPREUVE. Une vraie connexion, ouverte et tenue — la seule chose
// qui autorise le mot « fonctionne ». Les deux écrans passent par ici : deux
// textes pour un même fait finiraient par diverger.
function wsPhraseEpreuve(vif){
    if(vif.ok) return {c: 'var(--accent)',
        t: 'Connexion établie et tenue : le terminal et les mises à jour en ' +
           'direct fonctionnent. Ouverte en ' + vif.ouverture + ' ms, tenue ' +
           (vif.tenue / 1000).toFixed(1) + ' s, ' + vif.recus +
           ' message(s) reçu(s) — mesuré à ' +
           new Date().toLocaleTimeString('fr-FR') + ', heure de votre navigateur.'};
    return {c: 'var(--warn)',
        t: 'La connexion n\u2019aboutit pas : ' + vif.raison + '.'};
}

// État du relais WebSocket, affiché dans Réglages → Système.
async function cfgWsEtat(force) {
    const el = document.getElementById('cfg-ws-etat');
    const btn = document.getElementById('cfg-ws-install');
    if (!el) return;
    if (force) el.innerHTML = '<div class="empty-state">Vérification…</div>';
    try {
        const d = await apiPost('/api/fp/websocket', {});
        const conforme = !!d.conforme;
        const vhosts = (d.vhosts || []).length;
        const p = wsPhraseConfig(d);
        el.innerHTML = '<div style="font-size:12px;color:' + p.c + '">' +
              escapeHtml(p.t) + '</div>' +
              '<div id="cfg-ws-vif" style="font-size:12px;margin-top:5px;' +
              'color:var(--txt-faint)">Épreuve de la connexion…</div>'
            + ((d.a_reparer || []).length
               ? '<div style="font-size:10.5px;color:var(--txt-faint);margin-top:4px;font-family:ui-monospace,monospace">'
                 + escapeHtml(d.a_reparer.join(', ')) + '</div>' : '')
            + (d.nginx_ok === false
               ? '<div style="font-size:11px;color:var(--danger-soft);margin-top:4px">nginx refuse sa configuration actuelle — corriger avant d\'installer.</div>'
               : '')
            // LE DÉTAIL, ici et nulle part ailleurs. C'est la seule chose que
            // le panneau de FastPanel apportait en propre ; il descend donc
            // avec, plutôt que de justifier une seconde surface.
            + '<div style="margin-top:9px;font-size:11px;color:var(--txt-soft);' +
              'line-height:1.6">' + (d.vhosts || []).map(function(x){
                  return '<div><code>' + escapeHtml(x.file) + '</code> — ' +
                    (x.lisible === false
                       ? '<span style="color:var(--danger-soft)">illisible (' +
                         escapeHtml(x.reason || '') + ')</span>'
                       : (x.complet
                          ? '<span style="color:var(--accent)">configuré</span>'
                          : '<span style="color:var(--warn)">en-têtes absents</span>') +
                         ' (' + x.inclus + '/' + x.blocs + ' bloc·s)') + '</div>';
              }).join('')
            + '<div style="margin-top:6px">Les directives vivent dans <code>' +
              escapeHtml(d.include_path || '') + '</code>' +
              (d.include_present ? ' (présent)' : ' <b>(absent)</b>') +
              ', hors de l\u2019arborescence FastPanel ; le vhost n\u2019en ' +
              'reçoit qu\u2019une ligne <code>include</code> — c\u2019est ce ' +
              'qui rend la correction durable quand FastPanel régénère le ' +
              'vhost. Carte <code>$cassandra_conn_upgrade</code> : ' +
              (d.map_present ? 'posée' : '<b>absente</b>') +
              ' · <code>nginx -t</code> : ' +
              (d.nginx_ok ? 'valide' : '<b>en erreur</b>') + '.</div></div>';
        if (btn) btn.style.display = (!conforme && vhosts) ? '' : 'none';
        // L'ÉPREUVE ENSUITE, jamais avant : elle tient trois secondes, et la
        // carte des réglages ne doit pas attendre pour s'afficher. C'est la
        // même règle que partout ailleurs — rien de lent sur un rendu.
        const vif = await fpWsEpreuve();
        const z = document.getElementById('cfg-ws-vif');
        if (z){
            const q = wsPhraseEpreuve(vif);
            z.style.color = q.c;
            z.textContent = q.t;
        }
    } catch(e) {
        el.innerHTML = '<div style="font-size:12px;color:var(--danger-soft)">Erreur réseau</div>';
    }
}

async function cfgWsAppliquer() {
    _sfb('cfg-ws-feedback', 'Application en cours…', 'ok');
    try {
        const d = await apiPost('/api/fp/websocket/apply', {confirm: true});
        _sfb('cfg-ws-feedback',
             d.ok ? ('✓ ' + ((d.modifies || []).length) + ' fichier(s) modifié(s), nginx rechargé')
                  : ('✗ ' + (d.reason || 'échec')), d.ok ? 'ok' : 'err');
        cfgWsEtat(true);
    } catch(e) {
        _sfb('cfg-ws-feedback', 'Erreur réseau : ' + e.message, 'err');
    }
}

// ── LA VISION « MOI » ────────────────────────────────────────────────────────
// Tout passe par les routes `/api/me/*`, ouvertes à chaque compte par la garde
// centrale. Rien ici ne touche `/api/memory/config`, qui est administrative.
async function moiCharger(){
    try{
        const d = await apiPost('/api/me', {});
        window._me = d || window._me;
        const me = (d && d.me) ? d.me : (d || {});
        const set = function(id, v){ const e = document.getElementById(id); if (e) e.value = v || ''; };
        set('moi-nom', me.display_name);
        set('moi-fonction', me.role_label);
        // `/api/me` rend `user`, à plat. Ni `username`, ni `email`, ni un
        // objet `me` : le champ restait vide sans que rien ne le dise.
        set('moi-id', me.user || d.user || '');
        set('moi-contact', me.contact_email); set('moi-tel', me.phone);
        const lg = document.getElementById('moi-lang'); if (lg) lg.value = me.lang || 'fr';
        moiPhotoPeindre('');
        if (me.photo || d.photo) { try { const ph = await apiPost('/api/me/photo', {}); if (ph && ph.ok && ph.photo) { ETAT.moi._monPortrait = ph.photo; moiPhotoPeindre(ph.photo); if (typeof _umPortrait === 'function') _umPortrait(); } } catch(e) {} }
    }catch(e){}
    try { const ta = document.getElementById('moi-taille'); if (ta) ta.value = localStorage.getItem('cass_taille') || 'normale'; const ou = document.getElementById('moi-ouverture'); if (ou) ou.value = localStorage.getItem('cass_ouverture') || ''; } catch(e) {}
    try{
        const p = await apiPost('/api/me/email_pref', {});
        const c = document.getElementById('moi-mail-pref');
        if (c) c.checked = !!(p && p.enabled);
    }catch(e){}
    // Le thème vit déjà dans le navigateur : la carte le REFLÈTE, elle ne
    // tient pas un second état qui divergerait du premier.
    try{
        const t = document.getElementById('moi-theme');
        if (t && typeof themeActuel === 'function') t.value = themeActuel();
    }catch(e){}
    moiSessions();
    moiNotifs();
    mdpPeindre('moi-mdp-b', 'moi-mdp-regles');
    moiCles();
    // Rattachements et activite viennent de l onglet retire : leurs chargeurs
    // survivent, seul leur point d appel change.
    try{ if (typeof loadAccount === 'function') loadAccount(); }catch(e){}
    try{ if (typeof acLoadHistory === 'function') acLoadHistory(); }catch(e){}
}
async function moiSessions(){
    const w = document.getElementById('moi-sessions'); if (!w) return;
    try{
        const d = await apiPost('/api/me/sessions', {});
        const L = (d && d.sessions) || [];
        if (!L.length){ w.innerHTML = '<div class="empty-state">Aucune session.</div>'; return; }
        const NAT = {local:['réseau local','ok'], internet:['internet',''],
                     serveur:['depuis le serveur','ok']};
        w.innerHTML = L.map(function(s){
            const nat = NAT[s.nature] || ['', ''];
            return '<div class="ses' + (s.current ? ' ses-moi' : '') + '">'
              + '<div class="ses-h"><b>' + escapeHtml(s.agent || 'Appareil inconnu') + '</b>'
              + (s.current ? '<span class="ses-p ok">cette session</span>' : '')
              + (nat[0] ? '<span class="ses-p ' + nat[1] + '">' + nat[0] + '</span>' : '')
              + '<div class="bu-sp"></div>'
              + (s.current ? '' : '<button class="btn-x mini dgr" onclick="moiSesFermer(\''
                  + escapeHtml(s.id) + '\')">Fermer</button>')
              + '</div>'
              + '<dl class="ses-kv">'
              + '<dt>Adresse</dt><dd class="mono">' + escapeHtml(s.ip || '—') + '</dd>'
              + '<dt>Ouverte</dt><dd>' + escapeHtml(s.created || '—') + '</dd>'
              + '<dt>Vue</dt><dd>' + escapeHtml(s.last_used || '—') + '</dd>'
              + '<dt>Repère</dt><dd class="mono">…' + escapeHtml(s.id) + '</dd>'
              + '</dl></div>';
        }).join('');
    }catch(e){ w.innerHTML = '<div class="empty-state">Lecture impossible.</div>'; }
}
// Les règles viennent du SERVEUR : les écrire ici en dur, c'est se donner
// rendez-vous avec une légende qui ment le jour où la politique change.
async function mdpRegles(){
    if (ETAT.moi._mdpR) return ETAT.moi._mdpR;
    try{
        const d = await apiPost('/api/mdp/regles', {});
        ETAT.moi._mdpR = (d && d.regles) || [];
    }catch(e){ ETAT.moi._mdpR = []; }
    return ETAT.moi._mdpR;
}
// La vérification d'écran est un CONFORT : elle dit ce qui manque pendant la
// frappe. Celle qui compte reste au serveur, et elle est la même pour tous les
// clients — y compris ceux qui n'exécutent pas ce script.
const MDP_TESTS = {
    longueur:  function(p){ return p.length >= 9 && p.length <= 20; },
    majuscule: function(p){ return /[A-ZÀ-Þ]/.test(p); },
    chiffre:   function(p){ return /[0-9]/.test(p); },
    special:   function(p){ return /[^A-Za-z0-9À-ÿ\s]/.test(p); }
};
async function mdpPeindre(champId, boiteId){
    const R = await mdpRegles();
    const c = document.getElementById(champId), w = document.getElementById(boiteId);
    if (!c || !w) return;
    const p = c.value || '';
    w.innerHTML = R.map(function(r){
        const f = MDP_TESTS[r.cle];
        const ok = p && f ? f(p) : false;
        return '<span class="mdp-r' + (ok ? ' ok' : '') + '">' + escapeHtml(r.dit) + '</span>';
    }).join('');
    if (!c._mdpLie){
        c._mdpLie = 1;
        c.addEventListener('input', function(){ mdpPeindre(champId, boiteId); });
    }
}
async function moiCles(){
    const w = document.getElementById('moi-cles'); if (!w) return;
    try{
        const d = await apiPost('/api/me/cles', {});
        const L = (d && d.cles) || [];
        // Ce que l'écran annonce dépend de l'état RÉEL du compte : promettre
        // « voici ce qui changera » alors que c'est déjà en place, ce serait
        // parler au futur de quelque chose de fait.
        const eff = document.getElementById('moi-cle-effet');
        if (eff){
            // Trois etats, parce qu'il y en a trois. Confondre « une cle
            // existe » et « la cle est exigee » est ce qui a enferme dehors.
            eff.innerHTML = !L.length
              ? '<b>Aucune clé.</b> Le mot de passe seul suffit à entrer.'
                + '<br>En ajouter une <b>n\'enlève rien</b> : elle ouvre une porte '
                + 'de plus — « Se connecter avec une clé », sans mot de passe. '
                + 'Votre mot de passe continue de fonctionner tout seul.'
              : (d.exigee
                ? '<b>La clé est EXIGÉE.</b> Le mot de passe seul ne suffit plus. '
                  + 'Deux façons d\'entrer :'
                  + '<br>• <b>Avec la clé seule</b> — bouton « Se connecter avec une '
                  + 'clé » sur l\'écran d\'accueil.'
                  + '<br>• <b>Mot de passe puis clé</b> — la connexion habituelle '
                  + 'marque une pause et attend la clé.'
                  + '<br><br><b>Réversible immédiatement</b> : décochez ci-dessous, '
                  + 'ou révoquez la clé. <b>Si vous la perdez</b>, un code de secours '
                  + 'vous fait entrer — il vous en reste <b>' + (d.secours || 0) + '</b>.'
                : '<b>Clé enregistrée, mais pas exigée.</b> C\'est une porte <b>en '
                  + 'plus</b> : le mot de passe seul fonctionne toujours.'
                  + '<br><b>Éprouvez-la maintenant</b> : déconnectez-vous et utilisez '
                  + '« Se connecter avec une clé ». Si ça marche, vous pourrez '
                  + 'l\'exiger ci-dessous en toute sécurité.');
            const bx = document.getElementById('moi-cle-exig');
            if (bx) bx.style.display = L.length ? '' : 'none';
            const cb = document.getElementById('moi-cle-exiger');
            if (cb) cb.checked = !!d.exigee;
        }
        if (d && d.dispo === false){
            w.innerHTML = '<div class="gd-danger">' + escapeHtml(d.empeche || '') + '</div>';
            return;
        }
        if (!L.length){
            // L'état vide DIT où sera le bouton. Sans ça, on le cherche avant
            // d'avoir de quoi le faire apparaître, et on conclut qu'il manque.
            w.innerHTML = '<div class="empty-state">Aucune clé enregistrée — le mot '
                + 'de passe seul suffit à entrer.<br><span class="s-hint">Chaque clé '
                + 'ajoutée apparaîtra ici, avec son bouton <b>Révoquer</b>.</span></div>';
            return;
        }
        w.innerHTML = L.map(function(k){
            return '<div class="ses"><div class="ses-h"><b>' + escapeHtml(k.libelle) + '</b>'
              + '<div class="bu-sp"></div><button class="btn-x mini dgr" onclick="moiCleRetirer(\''
              + escapeHtml(k.id) + '\')">Révoquer</button></div>'
              + '<dl class="ses-kv"><dt>Ajoutée</dt><dd>' + escapeHtml(k.created || '—') + '</dd>'
              + '<dt>Dernier usage</dt><dd>' + escapeHtml(k.last_used || 'jamais') + '</dd>'
              + '<dt>Repère</dt><dd class="mono">…' + escapeHtml(k.id) + '</dd></dl></div>';
        }).join('')
          + '<div class="s-hint" style="margin-top:4px">Codes de secours restants : <b>'
          + (d.secours || 0) + '</b> sur 8. '
          + '<a href="#" onclick="moiCleSecours();return false">En générer de nouveaux</a> '
          + '— les précédents seront effacés.</div>';
    }catch(e){ w.innerHTML = '<div class="empty-state">Lecture impossible.</div>'; }
}
async function moiCleAjouter(){
    const m = document.getElementById('moi-cle-msg');
    const nom = (document.getElementById('moi-cle-nom') || {}).value || '';
    const _ou = (document.getElementById('moi-cle-ou') || {}).value || '';
    if (!window.PublicKeyCredential){
        if (m) m.textContent = 'Ce navigateur ne sait pas enregistrer de clé.'; return;
    }
    try{
        const d = await apiPost('/api/me/cle/defi', {});
        if (m) m.textContent = _ou === 'platform'
            ? 'Confirmez avec Windows Hello ou votre empreinte…'
            : (_ou === 'cross-platform'
               ? 'Touchez votre clé USB, ou suivez votre gestionnaire…'
               : 'Suivez ce que votre navigateur propose…');
        const c = await navigator.credentials.create({publicKey: {
            challenge: _b64uOctets(d.defi),
            rp: {name: 'Cassandra', id: d.rp},
            user: {id: _b64uOctets(_octetsB64u(new TextEncoder().encode(d.compte))),
                   name: d.compte, displayName: d.compte},
            // ES256 puis RS256 : les deux que le serveur sait vérifier. En
            // proposer d'autres reviendrait à accepter ce qu'on ne relit pas.
            pubKeyCredParams: [{type: 'public-key', alg: -7},
                               {type: 'public-key', alg: -257}],
            // `required` des deux côtés : sans clé découvrable, le navigateur
            // ne peut pas proposer le compte sans qu'on le saisisse ; sans
            // vérification d'utilisateur, la clé seule ne vaudrait qu'un facteur.
            // `authenticatorAttachment` n'est POSÉ que si l'utilisateur a choisi :
            // le mettre à vide restreindrait au lieu d'ouvrir, et le navigateur
            // ne proposerait plus rien.
            authenticatorSelection: Object.assign(
                {userVerification: 'required', residentKey: 'required'},
                _ou ? {authenticatorAttachment: _ou} : {}),
            timeout: 120000, attestation: 'none'
        }});
        const r = await apiPost('/api/me/cle/enregistrer', {
            defi: d.defi, libelle: nom,
            client: _octetsB64u(c.response.clientDataJSON),
            attestation: _octetsB64u(c.response.attestationObject)});
        if (!r.ok){ if (m){ m.textContent = '✗ ' + (r.error || 'échec');
                            m.style.color = 'var(--danger-soft)'; } return; }
        if (m){ m.textContent = '✓ Clé enregistrée'; m.style.color = 'var(--ok)'; }
        const n = document.getElementById('moi-cle-nom'); if (n) n.value = '';
        if (r.secours) moiCleMontrerSecours(r.secours);
        moiCles();
    }catch(e){
        if (m){ m.textContent = 'Clé non enregistrée' + (e && e.message ? ' (' + e.message + ')' : '');
                m.style.color = 'var(--danger-soft)'; }
    }
}
async function moiCleRetirer(id){
    if (!await buConfirmer("Révoquer cette clé ?\n\n"
               + "Elle ne pourra plus servir à entrer. Si c'est la dernière, la "
               + "connexion se fera de nouveau par mot de passe seul, "
               + "immédiatement.\n\nRien d'autre n'est touché : vos données, "
               + "votre coffre et vos autres sessions restent en place.")) return;
    try{ await apiPost('/api/me/cle/supprimer', {id: id}); moiCles(); }catch(e){}
}
async function moiCleExiger(el){
    const m = document.getElementById('moi-cle-exig-msg');
    if (el.checked && !await buConfirmer(
        "Exiger la clé à chaque connexion ?\n\n"
        + "Votre mot de passe ne suffira plus. Ne cochez QUE si vous avez déjà "
        + "vérifié que « Se connecter avec une clé » fonctionne.\n\n"
        + "Huit codes de secours vont s'afficher — notez-les : ils ne seront "
        + "plus jamais montrés, et ce sont eux qui vous feront entrer si la clé "
        + "est perdue.")){
        el.checked = false; return;
    }
    try{
        const r = await apiPost('/api/me/cle/exiger', {exiger: !!el.checked});
        if (!r.ok){
            el.checked = !el.checked;
            if (m){ m.textContent = '✗ ' + (r.error || 'échec');
                    m.style.color = 'var(--danger-soft)'; }
            return;
        }
        if (m){ m.textContent = r.exigee ? '✓ La clé est exigée' : '✓ La clé n\'est plus exigée';
                m.style.color = 'var(--ok)'; }
        if (r.secours) moiCleMontrerSecours(r.secours);
        moiCles();
    }catch(e){ el.checked = !el.checked; if (m) m.textContent = 'Erreur'; }
}
async function moiCleSecours(){
    if (!await buConfirmer('Générer de nouveaux codes ? Les précédents cesseront de fonctionner.')) return;
    try{
        const r = await apiPost('/api/me/cle/secours', {});
        if (r && r.codes) moiCleMontrerSecours(r.codes);
        moiCles();
    }catch(e){}
}
// Montrés UNE fois : seule leur empreinte est gardée, on ne peut pas les
// réafficher ensuite. Le dire là plutôt que de le laisser découvrir.
function moiCleMontrerSecours(codes){
    const w = document.getElementById('moi-cle-secours'); if (!w) return;
    // Ils étaient affichés dans un bloc en bas de carte, hors du champ de
    // vision — et ils ont été manqués. On amène l'oeil dessus, et on demande
    // confirmation : un secret irremplaçable ne se montre pas en passant.
    setTimeout(function(){
        try{ w.scrollIntoView({behavior: 'smooth', block: 'center'}); }catch(e){}
        buDire("Notez ces " + codes.length + " codes de secours MAINTENANT :\n\n"
            + codes.join("\n")
            + "\n\nIls ne seront plus jamais affichés. Chacun sert une fois, et "
            + "remplace la clé si vous la perdez.");
    }, 60);
    w.innerHTML = '<div class="gd-danger" style="margin-top:13px">'
      + '<b>Notez ces codes maintenant.</b> Ils ne seront plus jamais affichés — '
      + 'seule leur empreinte est conservée. Chacun sert une fois, et remplace la '
      + 'clé si vous la perdez.<div class="mdp-regles" style="margin-top:9px">'
      + codes.map(function(c){ return '<span class="mdp-r ok mono">' + escapeHtml(c)
          + '</span>'; }).join('') + '</div></div>';
}
async function moiSesFermer(id){
    if (!await buConfirmer('Fermer cette session ? L\'appareil devra se reconnecter.')) return;
    try{ await apiPost('/api/me/sessions/revoke', {id: id}); moiSessions(); }catch(e){}
}
async function moiProfil(){
    const m = document.getElementById('moi-msg');
    const g = function(id){ const e = document.getElementById(id); return e ? e.value.trim() : ''; };
    try{
        const r = await apiPost('/api/me/profile', {display_name: g('moi-nom'), role_label: g('moi-fonction'), contact_email: ((document.getElementById('moi-contact')||{}).value||'').trim(), phone: ((document.getElementById('moi-tel')||{}).value||'').trim(), lang: ((document.getElementById('moi-lang')||{}).value||'fr')});
        if (m){ m.textContent = (r && r.ok) ? '\u2713 Enregistré' : 'Erreur';
                m.style.color = (r && r.ok) ? 'var(--ok)' : 'var(--danger-soft)'; }
    }catch(e){ if (m) m.textContent = 'Erreur'; }
}
async function moiMdp(){
    const m = document.getElementById('moi-mdp-msg');
    const a = document.getElementById('moi-mdp-a'), b = document.getElementById('moi-mdp-b'),
          c = document.getElementById('moi-mdp-c');
    if (!a || !b || !c) return;
    if (b.value !== c.value){
        if (m){ m.textContent = 'Les deux nouveaux mots de passe diffèrent.';
                m.style.color = 'var(--danger-soft)'; }
        return;
    }
    try{
        // La route lit `new`, pas `password` : le nouveau mot de passe
        // arrivait vide, et le changement échouait sans dire pourquoi.
        const r = await apiPost('/api/me/password', {current: a.value, new: b.value});
        if (m){ m.textContent = (r && r.ok) ? '\u2713 Changé' : ('\u2717 ' + ((r && r.error) || 'échec'));
                m.style.color = (r && r.ok) ? 'var(--ok)' : 'var(--danger-soft)'; }
        if (r && r.ok){ a.value = ''; b.value = ''; c.value = ''; }
    }catch(e){ if (m) m.textContent = 'Erreur'; }
}
async function moiRevoquer(){
    if (!await buConfirmer('Fermer toutes vos autres sessions ?')) return;
    try{ await apiPost('/api/me/sessions/revoke_others', {}); moiSessions(); }catch(e){}
}
function moiTheme(){
    const t = document.getElementById('moi-theme');
    if (t && typeof appliquerTheme === 'function') appliquerTheme(t.value);
}
async function moiNotifs(){
    const w = document.getElementById('moi-notifs'); if (!w) return;
    try{
        const d = await apiPost('/api/me/notifs', {});
        const G = (d && d.genres) || {}, E = (d && d.notifs) || {};
        // À QUI, et SI ça peut partir. Sans la seconde, les interrupteurs
        // ci-dessous ne commandent rien — et rien ne le disait.
        const et = document.getElementById('moi-notifs-etat');
        if (et){
            let h = '';
            if (d && d.destinataire){
                h += '<div class="s-hint" style="margin:0 0 10px">Vos e-mails partent à '
                   + '<b>' + escapeHtml(d.destinataire) + '</b> — l\'adresse avec '
                   + 'laquelle vous vous connectez. Il n\'y en a pas d\'autre à régler : '
                   + 'changer d\'identifiant change aussi la destination.</div>';
            }
            if (d && d.smtp === false){
                h += '<div class="gd-danger" style="margin-bottom:12px">'
                   + '<b>Aucun envoi n\'est possible pour l\'instant.</b> Le serveur '
                   + 'd\'envoi (SMTP) n\'est pas configuré : les réglages ci-dessous '
                   + 'sont enregistrés, mais aucun e-mail ne partira.'
                   + '<br><span class="s-hint">Un administrateur le configure dans '
                   + '<b>La machine › Services tiers › E-mail &amp; notifications</b>.</span>'
                   + '</div>';
            }
            et.innerHTML = h;
        }
        const cles = Object.keys(G);
        if (!cles.length){ w.innerHTML = ''; return; }
        w.innerHTML = cles.map(function(k){
            return '<label style="display:flex;align-items:flex-start;gap:9px;'
                + 'font-size:13px;margin-bottom:11px">'
                + '<input type="checkbox" data-genre="' + escapeHtml(k) + '"'
                + (E[k] ? ' checked' : '') + ' onchange="moiNotifEcrire(this)">'
                + '<span><b>' + escapeHtml(G[k].n) + '</b><br>'
                + '<span class="s-hint" style="margin:0">' + escapeHtml(G[k].d)
                + '</span></span></label>';
        }).join('');
    }catch(e){ w.innerHTML = '<div class="empty-state">Lecture impossible.</div>'; }
}
async function moiNotifEcrire(el){
    const o = {}; o[el.getAttribute('data-genre')] = !!el.checked;
    try{ await apiPost('/api/me/notifs', {notifs: o}); }catch(e){}
}
async function moiPref(){
    const c = document.getElementById('moi-mail-pref'); if (!c) return;
    try{ await apiPost('/api/me/email_pref', {enabled: !!c.checked}); }catch(e){}
}

async function cfgSessionTtl(){
    const i = document.getElementById('cfg-session-ttl');
    const m = document.getElementById('cfg-session-msg');
    if (!i) return;
    const v = parseInt(i.value || '24', 10);
    if (!(v >= 1 && v <= 720)){
        if (m){ m.textContent = 'Entre 1 et 720 heures.'; m.style.color = 'var(--danger-soft)'; }
        return;
    }
    try{
        const r = await apiPost('/api/memory/config', {update: {session_ttl_hours: v}});
        if (m){ m.textContent = (r && r.ok) ? '✓ Enregistré' : 'Erreur';
                m.style.color = (r && r.ok) ? 'var(--ok)' : 'var(--danger-soft)'; }
    }catch(e){ if (m) m.textContent = 'Erreur'; }
}
async function setFamRestore() {
    // L'identité décide de la vision : sans elle, un admin se retrouve enfermé dans « Mon compte »
    // jusqu'au clic suivant. On l'attend une fois.
    if (!window._me) { try { window._me = await apiPost('/api/me', {}); } catch(e) {} }
    let f = 'moi-identite';
    try { f = localStorage.getItem('cass_set_fam') || 'moi-identite'; } catch(e) {}
    if (SET_FAMILLES.indexOf(f) < 0) f = 'moi-identite';
    setVision(setVisionDe(f));
    setFam(f);
    if (typeof moiCharger === 'function') moiCharger();
}

// ── Interrupteurs qui n'avaient aucune interface ─────────────────────────
// Le même rendu sert les trois familles : un registre côté serveur, un écran
// côté client. Ajouter un réglage = ajouter une ligne au registre.
async function cfgLoadVeille(famille, cible) {
    const el = document.getElementById(cible || 'cfg-veille-list');
    if (!el) return;
    try {
        const d = await apiGet('/api/reglages/veille?famille=' + encodeURIComponent(famille || ''));
        if (!d.ok || !(d.reglages || []).length) {
            el.innerHTML = '<div class="empty-state">Aucun réglage dans cette famille.</div>';
            return;
        }
        // Une ligne par interrupteur, au dessin commun : l'état à gauche, le libellé et la clé, le geste.
        el.innerHTML = '<div class="mx-rows">' + d.reglages.map(function(r){
            const on = !!r.value;
            return '<div class="mx-row"><span class="set-sw' + (on ? ' on' : '') + '"><i></i>' + (on ? 'ACTIVÉE' : 'ARRÊTÉE') + '</span>'
                 + '<div class="mx-rt"><b>' + escapeHtml(r.label) + '</b><span>' + escapeHtml(r.help || '')
                 + ' <span style="font:11px ui-monospace,monospace;color:var(--txt-ghost)">' + escapeHtml(r.key) + (r.explicite ? '' : ' · valeur par défaut') + '</span></span></div>'
                 + '<div class="mx-gest"><button class="mx-btn" onclick="cfgSaveVeille(\'' + escapeHtml(r.key) + '\', ' + (on ? 'false' : 'true') + ', \''
                 + escapeHtml(famille || '') + '\', \'' + escapeHtml(cible || '') + '\')">' + (on ? 'Arrêter' : 'Activer') + '</button></div></div>';
        }).join('') + '</div>';
    } catch(e) { el.innerHTML = '<div class="empty-state">Erreur de chargement</div>'; }
}

async function cfgSaveVeille(cle, valeur, famille, cible) {
    const fb = {agents: 'cfg-agents-feedback', systeme: 'cfg-ws-feedback'}[famille]
             || 'cfg-veille-feedback';
    try {
        const d = await apiPost('/api/reglages/veille/set', {key: cle, value: !!valeur});
        _sfb(fb, d.output || d.reason || '', d.ok ? 'ok' : 'err');
        cfgLoadVeille(famille, cible);
        cfgSante();
        if (ETAT.reglages._setFam) setVerdict(ETAT.reglages._setFam);
    } catch(e) {
        _sfb(fb, 'Erreur réseau : ' + e.message, 'err');
    }
}

// Rattachement des comptes au panneau d'hébergement, dans Réglages → Comptes.
// Mêmes routes que l'écran de l'onglet FastPanel : deux portes, une seule
// mécanique — l'une part du compte Cassandra, l'autre du compte FastPanel.
async function cfgLoadLinks() {
    const el = document.getElementById('cfg-links-list');
    if (!el) return;
    try {
        const d = await apiPost('/api/fp/users/links', {});
        if (!d.ok) {
            el.innerHTML = '<div class="empty-state">' + escapeHtml(d.reason || 'indisponible') + '</div>';
            return;
        }
        const comptes = d.comptes || [];
        if (!comptes.length) {
            el.innerHTML = '<div class="empty-state">Aucun compte FastPanel détecté sur ce serveur.</div>';
            return;
        }
        const sugg = {};
        (d.suggestions || []).forEach(function(s){ sugg[s.user] = s; });
        el.innerHTML = (d.users || []).map(function(u){
            const s = sugg[u.user];
            const opts = ['<option value="">— aucun —</option>'].concat(comptes.map(function(c){
                const sel = (u.fp_account === c) || (!u.fp_account && s && s.fp_account === c);
                return '<option value="' + escapeHtml(c) + '"' + (sel ? ' selected' : '') + '>'
                     + escapeHtml(c) + '</option>';
            })).join('');
            const herites = u.herites && u.herites.length
                ? '<div style="font-size:11px;color:var(--accent);margin-top:2px">↳ ' + u.herites.length
                  + ' site(s) hérité(s) : ' + escapeHtml(u.herites.join(', ')) + '</div>' : '';
            const propose = (!u.fp_account && s)
                ? '<div style="font-size:11px;color:var(--info);margin-top:2px">Suggestion : <b>'
                  + escapeHtml(s.fp_account) + '</b> — ' + escapeHtml(s.motif) + '</div>' : '';
            return '<div style="border:1px solid var(--ov-07);border-radius:8px;padding:8px 12px;margin-bottom:6px">'
                 + '<div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap">'
                 + '<span style="font-size:13px;color:var(--txt)">👤 ' + escapeHtml(u.user) + '</span>'
                 + '<span style="display:flex;gap:6px;align-items:center">'
                 + '<select class="s-input" style="padding:3px 8px;font-size:11px;min-width:130px" id="cfglnk-'
                 + escapeHtml(u.user) + '">' + opts + '</select>'
                 + '<button class="s-btn" style="padding:3px 10px;font-size:11px" onclick="cfgSaveLink(\''
                 + escapeHtml(u.user) + '\')">Appliquer</button>'
                 + '</span></div>' + propose + herites + '</div>';
        }).join('') || '<div class="empty-state">Aucun compte.</div>';
    } catch(e) { el.innerHTML = '<div class="empty-state">Erreur de chargement</div>'; }
}

async function cfgSaveLink(email) {
    const sel = document.getElementById('cfglnk-' + email);
    const compte = sel ? sel.value : '';
    try {
        const d = await apiPost('/api/fp/users/link', {user: email, fp_account: compte});
        _sfb('cfg-links-feedback', d.output || d.error || d.reason || '',
             d.ok ? 'ok' : 'err');
        if (d.ok) cfgLoadLinks();
    } catch(e) {
        _sfb('cfg-links-feedback', 'Erreur réseau : ' + e.message, 'err');
    }
}

async function cfgEditAccess(email, role, sites) {
    const nv = await buSaisir('Rôle pour ' + email + ' (admin / user) :', role || 'user');
    if (nv === null) return;
    const r = (nv.trim().toLowerCase() === 'admin') ? 'admin' : 'user';
    let s = sites;
    if (r === 'user') { const ns = await buSaisir('Domaines gérés (séparés par virgule) :', sites || ''); if (ns === null) return; s = ns; }
    const sitesArr = (s || '').split(',').map(x => x.trim()).filter(Boolean);
    fetch('/api/users/access', { method:'POST', headers:{'Content-Type':'application/json','X-Session-Token':sessionId},
        body: JSON.stringify({ username: email, role: r, sites: sitesArr }) })
      .then(x => x.json()).then(d => { if (d.ok) { _sfb('cfg-users-feedback','✓ Accès mis à jour','ok'); cfgLoadUsers(); } else _sfb('cfg-users-feedback','✗ '+(d.error||'Erreur'),'err'); })
      .catch(() => _sfb('cfg-users-feedback','✗ Erreur réseau','err'));
}

async function cfgSaveUser() {
    const name = document.getElementById('cfg-user-name')?.value.trim().toLowerCase();
    const pwd  = document.getElementById('cfg-user-pwd')?.value;
    const role = document.getElementById('cfg-user-role')?.value || 'user';
    const sites = (document.getElementById('cfg-user-sites')?.value || '').split(',').map(x => x.trim()).filter(Boolean);
    if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(name||'')) { _sfb('cfg-users-feedback', '✗ Entre une adresse e-mail valide', 'err'); return; }
    if (!pwd) { _sfb('cfg-users-feedback', '✗ Mot de passe requis', 'err'); return; }
    try {
        const r = await fetch('/api/users/set', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'X-Session-Token': sessionId },
            body: JSON.stringify({ username: name, password: pwd, role: role, sites: sites })
        });
        const d = await r.json();
        if (d.ok) {
            _sfb('cfg-users-feedback', '✓ Compte « ' + name + ' » (' + (d.role||role) + ') enregistré', 'ok');
            document.getElementById('cfg-user-name').value = '';
            document.getElementById('cfg-user-pwd').value = '';
            const sEl = document.getElementById('cfg-user-sites'); if (sEl) sEl.value = '';
            cfgLoadUsers();
        } else { _sfb('cfg-users-feedback', '✗ ' + (d.error || 'Erreur'), 'err'); }
    } catch(e) { _sfb('cfg-users-feedback', '✗ Erreur réseau', 'err'); }
}

async function cfgDeleteUser(name) {
    if (!await buConfirmer('Supprimer le compte « ' + name + ' » ?')) return;
    try {
        const r = await fetch('/api/users/delete', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'X-Session-Token': sessionId },
            body: JSON.stringify({ username: name })
        });
        const d = await r.json();
        if (d.ok) {
            _sfb('cfg-users-feedback', '✓ Compte supprimé', 'ok');
            cfgLoadUsers();
            // Le dossier de notes SURVIT au compte : c'est voulu, retirer un
            // compte ne doit pas détruire son travail dans la foulée. Mais ne
            // rien dire ferait s'accumuler des dossiers sans origine connue.
            cfgDossiers(name);
        }
        else { _sfb('cfg-users-feedback', '✗ ' + (d.error || 'Erreur'), 'err'); }
    } catch(e) { _sfb('cfg-users-feedback', '✗ Erreur réseau', 'err'); }
}

// Les dossiers de comptes. `vise` : le compte qu'on vient de supprimer, dont on
// met le dossier en avant.
async function cfgDossiers(vise) {
    let d = null;
    try { d = await apiGet('/api/comptes/dossiers'); } catch(e) {}
    if (!d || !d.ok) { buDire((d && d.reason) || 'inventaire indisponible'); return; }
    const orph = d.orphelins || [];
    const octets = function(n){ n = n || 0;
        return n < 1024 ? n + ' o' : (n < 1048576 ? (n/1024).toFixed(1) + ' Ko'
                                                  : (n/1048576).toFixed(1) + ' Mo'); };
    _pjModale(vise ? ('Dossier de « ' + vise + ' »') : 'Dossiers de comptes',
      (vise ? '<p class="bu-note" style="margin-bottom:11px">Le compte est '+
        'supprimé, <b>son dossier est resté</b>. Retirer un compte ne détruit '+
        'pas son travail — à toi de décider.</p>' : '') +
      (orph.length
        ? '<div class="bu-ct" style="padding:0 0 7px">Sans compte — ' + orph.length +
          '</div>' + orph.map(function(o){
            return '<div class="ca-lg"><span class="n"><code>' +
              escapeHtml(o.dossier) + '</code><i style="display:block;font-style:normal;'+
              'font-size:11px;color:var(--txt-faint)">' + o.notes + ' note(s) · ' +
              octets(o.octets) + '</i></span>' +
              '<button class="btn-x mini dgr" onclick="cfgDossierSupprimer(' +
              JSON.stringify(o.dossier) + ')">Supprimer</button></div>'; }).join('')
        : '<p class="bu-note">Aucun dossier sans compte.</p>') +
      ((d.sans_dossier || []).length
        ? '<div class="bu-ct" style="padding:13px 0 7px">Comptes sans dossier</div>' +
          '<p class="bu-note">' + escapeHtml((d.sans_dossier || []).join(', ')) +
          ' — leur dossier se créera à leur première visite.</p>' : ''),
      function(){ return true; });
}
// Irréversible : on montre d'abord ce qu'on détruirait, on fait retaper ensuite.
async function cfgDossierSupprimer(dossier) {
    let e = null;
    try { e = await apiPost('/api/comptes/dossier/supprimer', {dossier: dossier}); }
    catch(x) {}
    if (!e || !e.ok) { buDire((e && e.reason) || 'suppression impossible'); return; }
    _pjModale('⚠ Supprimer définitivement',
      '<div class="gd-danger"><p><b>' + e.notes + ' note(s)</b>' +
      (e.doc_fichiers ? ' et <b>' + e.doc_fichiers + ' document(s)</b>' : '') +
      ' seront <b>effacés définitivement</b>.</p>' +
      '<p style="margin-top:7px"><code>' + escapeHtml(e.dossier) + '</code> — ' +
      Math.round((e.octets||0)/1024) + ' Ko' +
      (e.docs ? '<br><code>' + escapeHtml(e.docs) + '</code> — ' +
        Math.round((e.doc_octets||0)/1024) + ' Ko' : '') + '</p></div>' +
      '<p class="bu-note" style="margin-top:11px">Les versions, la corbeille et '+
      'la source de documents du compte partent avec. Rien n\'est récupérable '+
      'ensuite.</p>' +
      '<p class="bu-note" style="margin-top:11px">Retape <b>supprimer</b> pour '+
      'confirmer.</p><input class="bu-inp" id="cfg-conf" autocomplete="off">',
      async function(){
        const q = document.getElementById('cfg-conf');
        if (!q || q.value.trim().toLowerCase() !== 'supprimer') {
            buDire('Confirmation incorrecte. Rien n\'a été supprimé.'); return false; }
        const r = await apiPost('/api/comptes/dossier/supprimer',
                                {dossier: dossier, confirme: true});
        if (!r || !r.ok) { buDire((r && r.reason) || 'échec'); return false; }
        if (typeof showToast === 'function')
            showToast('🗑 dossier supprimé — ' + r.notes + ' note(s)', 'success', 3000);
        return true;
      });
    setTimeout(function(){ const q = document.getElementById('cfg-conf');
        if (q) q.focus(); }, 40);
}

async function cfgWipeProd(){
    const r = await fp2Demander('Base, mémoire, sauvegardes de mémoire et de base, portraits, vignettes, pièces et atelier sont effacés ; le code, la configuration, les clés, les comptes, les dépôts et le journal admin restent. Services arrêtés puis relancés : Cassandra revient vide.\n\nTout effacer ?', 'Reset total', {mdp: true, mot: 'EFFACER', garde: 30, danger: true, ok: 'Effacer'});
    if (!r.ok) return;
    _sfb('cfg-wipe-feedback', '⏳ Effacement…', 'ok');
    try { const d = await apiPost('/api/system/wipe', {confirm: r.mot, admin_password: r.mdp});
          _sfb('cfg-wipe-feedback', d && d.ok ? '✓ ' + (d.message || 'Effacement lancé') + (d.unite ? ' (' + d.unite + ')' : '') : '✗ ' + ((d && d.error) || 'échec'), d && d.ok ? 'ok' : 'err'); }
    catch(e) { _sfb('cfg-wipe-feedback', '✗ Erreur réseau', 'err'); }
}

// ── TELEGRAM : le canal du compte ───────────────────────────────────────────
// L'état est PERMANENT dans l'en-tête : `_sfb` s'efface au bout de 5 secondes,
// ce qui convient à un accusé de réception, jamais à un état.
// LE DESTINATAIRE. Le serveur l'ESSAIE avant de l'enregistrer : un
// identifiant accepté sans vérification donne un écran qui dit « enregistré »
// et des alertes qui tombent dans le vide pendant des semaines. Le refus de
// Telegram est rendu tel quel, parce qu'il dit quoi faire.
async function tgCible(){
    const c = document.getElementById('tg-cible');
    const v = c ? String(c.value || '').trim() : '';
    _sfb('tg-feedback', v ? 'Essai de la destination…'
                          : 'Retrait du destinataire…', 'ok');
    let r = null;
    try { r = await apiPost('/api/me/telegram/cible', {cible: v}); }
    catch(e){ r = {ok: false, error: e.message}; }
    _sfb('tg-feedback',
         (r && r.ok) ? (v ? 'Destinataire enregistré et joignable.'
                          : 'Destinataire retiré — la conversation apprise reprend.')
                     : ((r && r.error) || 'Refusé'),
         (r && r.ok) ? 'ok' : 'err');
    tgCharger();
}

/* ── ITARE COMME CONTACT ─────────────────────────────────────────────────── */
function _itaDire(txt, genre){
    // DEUX zones : la carte personnelle et celle de la machine. Un meme
    // identifiant dans les deux ferait toujours parler la premiere, et le
    // message manquerait la ou l'on vient de cliquer.
    if (typeof _sfb !== 'function') return;
    ['ita-feedback', 'ita-feedback-m'].forEach(function(id){
        if (document.getElementById(id))
            _sfb(id, txt, genre === 'err' ? 'err' : 'ok');
    });
}

async function itaCharger(){
    let d;
    try { d = await apiPost('/api/ita/etat', {}); } catch(e){ d = null; }
    if (!d || !d.ok) return;
    const e = document.getElementById('ita-etat');
    // L'ETAT dit CE QUI MANQUE, dans l'ordre où il faut s'en occuper : sans
    // compte pour Itare rien ne marche, sans pseudo relié personne n'est
    // reconnu, et sans écoute vivante rien n'arrive.
    if (e){
        let h = '';
        if (!d.dispo){
            h = '<b style="color:var(--danger)">Telethon n’est pas installé</b> '
              + 'sur le serveur : ce canal ne peut pas fonctionner.';
        } else if (!d.compte_itare){
            h = '<b style="color:var(--txt-faint)">Le compte d’Itare n’est pas '
              + 'encore relié.</b>' + (d.admin ? '' : ' Demandez-le à un administrateur.');
        } else if (!d.relie){
            h = '<b style="color:var(--txt-faint)">Votre compte Telegram '
              + 'n’est pas relié.</b> Reliez-le dans la carte ci-dessus.';
        } else if (!d.connu){
            // RELIE mais pas RECONNU : le cas de ceux qui ont relie leur
            // Telegram avant que cette table existe. Leur redemander de relier
            // un compte deja relie serait absurde.
            h = '<b style="color:var(--txt-faint)">Il manque votre identifiant '
              + 'Telegram.</b> Un clic sur <b>Me faire reconnaître</b> et '
              + 'Cassandra le demande à Telegram.';
        } else {
            h = 'Elle vous reconnaîtra'
              + (d.pseudo ? ' sous <b>@' + escapeHtml(d.pseudo) + '</b>'
                          : ' par votre identifiant Telegram')
              + '. ' + (d.actif ? '<b style="color:var(--ok)">Porte ouverte.</b>'
                                : '<b style="color:var(--txt-faint)">Porte fermée.</b>');
        }
        const ec = d.ecoute || {};
        if (d.compte_itare){
            h += '<br>Écoute : ' + (ec.vivant
                ? '<b style="color:var(--ok)">en cours</b>' +
                  (ec.depuis ? ' depuis ' + escapeHtml(ec.depuis) : '')
                : '<b style="color:var(--danger)">arrêtée</b>' +
                  (ec.erreur ? ' — ' + escapeHtml(ec.erreur) : ''));
        }
        e.innerHTML = h;
    }
    const p = document.getElementById('ita-porte');
    if (p) p.style.display = (d.dispo && d.compte_itare && d.connu) ? '' : 'none';
    // Le bouton de rattrapage n'apparait QUE quand il sert : compte relie,
    // mais rien pour vous reconnaitre.
    const rc = document.getElementById('ita-reco');
    if (rc) rc.style.display = (d.dispo && d.relie && !d.connu) ? '' : 'none';
    const c = document.getElementById('ita-actif');
    if (c) c.checked = !!d.actif;
    // La carte du compte d'Itare vit desormais dans « La machine », un onglet
    // que seule l'administration ouvre : le masquage par le JS ferait doublon,
    // et la garde qui compte est celle du serveur.
    const ah = document.getElementById('ita-admin-h');
    if (ah) ah.innerHTML = d.compte_itare
        ? '<div class="s-hint"><b style="color:var(--ok)">✓ Compte relié.</b> '
          + 'Écoute : ' + ((d.ecoute || {}).vivant
              ? '<b style="color:var(--ok)">en cours</b>'
              : '<b style="color:var(--danger)">arrêtée</b>') + '</div>'
        : '<div class="s-hint"><b style="color:var(--txt-faint)">Compte non '
          + 'relié.</b></div>';
}

async function itaReconnaitre(){
    _itaDire('Demande à Telegram…', 'ok');
    const r = await apiPost('/api/ita/reconnaitre', {});
    _itaDire(r && r.ok
        ? ('C’est fait' + (r.pseudo ? ' — @' + r.pseudo : '') +
           '. Vous pouvez ouvrir la porte.')
        : ((r && r.error) || 'Refusé'), r && r.ok ? 'ok' : 'err');
    itaCharger();
}

async function itaBasculer(actif){
    const r = await apiPost('/api/ita/basculer', {actif: !!actif});
    if (!r || !r.ok){
        // On REMET la case dans son etat reel : une case cochee qui n'a rien
        // change est un mensonge silencieux, et c'est le pire sur une porte.
        const c = document.getElementById('ita-actif');
        if (c) c.checked = !actif;
        _itaDire((r && r.error) || 'Refusé', 'err');
    } else {
        _itaDire(actif ? 'Itare vous répondra sur Telegram.'
                       : 'Itare ne vous répondra plus sur Telegram.', 'ok');
    }
    itaCharger();
}

async function itaIdent(){
    const i = (document.getElementById('ita-id') || {}).value || '';
    const h = (document.getElementById('ita-hash') || {}).value || '';
    const r = await apiPost('/api/ita/ident', {api_id: i.trim(), api_hash: h.trim()});
    if (document.getElementById('ita-hash')) document.getElementById('ita-hash').value = '';
    _itaDire(r && r.ok ? 'Application enregistrée.' : ((r && r.error) || 'Refusé'),
             r && r.ok ? 'ok' : 'err');
    itaCharger();
}

async function itaCode(){
    const t = ((document.getElementById('ita-tel') || {}).value || '').trim();
    if (!t){ _itaDire('Il manque le téléphone d’Itare.', 'err'); return; }
    _itaDire('Demande envoyée à Telegram…', 'ok');
    const r = await apiPost('/api/ita/commencer', {tel: t});
    _itaDire(r && r.ok ? 'Code envoyé sur le téléphone d’Itare.'
                       : ((r && r.error) || 'Refusé'), r && r.ok ? 'ok' : 'err');
}

async function itaValider(){
    const c = ((document.getElementById('ita-code') || {}).value || '').trim();
    const m = (document.getElementById('ita-mdp') || {}).value || '';
    if (!c){ _itaDire('Il manque le code.', 'err'); return; }
    const r = await apiPost('/api/ita/valider', {code: c, mdp: m});
    if (document.getElementById('ita-code')) document.getElementById('ita-code').value = '';
    if (document.getElementById('ita-mdp')) document.getElementById('ita-mdp').value = '';
    if (r && r.besoin_mdp){
        const b = document.getElementById('ita-mdp-b');
        if (b) b.style.display = '';
        _itaDire(r.error || 'Mot de passe requis.', 'err');
        return;
    }
    _itaDire(r && r.ok ? ('Compte d’Itare relié' + (r.qui ? ' — ' + r.qui : '') + '.')
                       : ((r && r.error) || 'Refusé'), r && r.ok ? 'ok' : 'err');
    itaCharger();
}

async function itaRelancer(){
    const r = await apiPost('/api/ita/relancer', {});
    _itaDire(r && r.ok ? 'Écoute relancée.' : ((r && r.error) || 'Refusé'),
             r && r.ok ? 'ok' : 'err');
    setTimeout(itaCharger, 1500);
}

async function itaDelier(){
    // La question tient sur UNE ligne, sans échappement : un saut de ligne
    // écrit à la main dans une chaîne casse tout le bloc, et je m'y suis
    // repris trois fois.
    if (!await buConfirmer("Couper le compte Telegram d'Itare ? Elle ne répondra plus à "
                 + "personne sur ce canal.")) return;
    const r = await apiPost('/api/ita/delier', {});
    _itaDire(r && r.ok ? ('Compte coupé.' + (r.avis ? ' ' + r.avis : ''))
                       : ((r && r.error) || 'Refusé'), r && r.ok ? 'ok' : 'err');
    itaCharger();
}

/* ── TELEGRAM PAR LE COMPTE ─────────────────────────────────────────────── */
// L'écran suit l'ÉTAT rendu par le serveur, il ne le devine pas : chaque
// bouton n'apparaît que lorsque l'étape précédente est franchie. Un bouton
// qui ne peut rien faire est une promesse en trop.
function _tgcMontrer(id, oui){
    const e = document.getElementById(id);
    if (e) e.style.display = oui ? '' : 'none';
}

function _tgcDire(txt, genre){
    // `_sfb` pose la classe SUR le conteneur `.s-feedback`, qui est en
    // `display:none` par defaut. J'ecrivais un `<div class="s-msg">` a
    // l'interieur : la classe n'existe pas, et le conteneur restait masque —
    // aucun message n'apparaissait, jamais, ni succes ni erreur.
    if (typeof _sfb === 'function') _sfb('tgc-feedback', txt, genre === 'err' ? 'err' : 'ok');
}

// L'ETAT PERSISTANT, a cote du champ. Le message de `_sfb` s'efface au bout de
// cinq secondes : sans cette ligne-ci, plus rien ne disait que l'application
// etait enregistree, et on recommencait sans savoir.
function _tgcEtatIdent(oui, qui, refus){
    const e = document.getElementById('tgc-etat-ident');
    if (!e) return;
    if (oui){
        e.innerHTML = '<b style="color:var(--ok)">✓ Application enregistrée</b> dans votre coffre.'
          + (qui ? ' Compte relié : <b>' + escapeHtml(qui) + '</b>.' : '');
        return;
    }
    // LE REFUS RESTE À L'ÉCRAN. Le retour de `_sfb` s'efface en cinq secondes :
    // on cliquait, rien ne semblait se passer, et l'état disait seulement
    // « non enregistrée » — sans jamais dire POURQUOI. C'est presque toujours
    // le coffre du compte qui n'est pas ouvert.
    e.innerHTML = '<b style="color:var(--txt-faint)">Application non enregistrée.</b>'
        + (refus ? '<br><span style="color:var(--danger)">' + escapeHtml(refus) +
                   '</span>' : '');
}

async function tgcCharger(){
    let d;
    try { d = await apiPost('/api/tgc/etat', {}); } catch(e){ d = null; }
    if (!d || !d.ok) return;
    // Telethon absent : on le DIT, avec la commande — et on masque tout le
    // reste plutôt que d'offrir des boutons qui échoueront.
    const abs = document.getElementById('tgc-absent');
    if (abs){
        abs.style.display = d.dispo ? 'none' : '';
        abs.innerHTML = d.dispo ? '' : '<b>Indisponible.</b> ' + escapeHtml(d.raison || '');
    }
    _tgcMontrer('tgc-etapes', !!d.dispo && !d.relie);
    _tgcMontrer('tgc-b-ident', !!d.dispo && !d.relie);
    _tgcMontrer('tgc-e2', !!d.dispo && !d.relie && !!d.identifiants);
    _tgcMontrer('tgc-b-code', !!d.dispo && !d.relie && !!d.identifiants);
    _tgcMontrer('tgc-e3', !!d.attente && !d.relie);
    _tgcMontrer('tgc-avis-code', !!d.attente && !d.relie);
    _tgcMontrer('tgc-b-valider', !!d.attente && !d.relie);
    _tgcMontrer('tgc-b-delier', !!d.relie);
    _tgcMontrer('tgc-b-import', !!d.relie);
    _tgcMontrer('tgc-b-essai', !!d.relie);
    _tgcEtatIdent(!!d.identifiants, d.relie ? (d.qui || '') : '');
}

async function tgcIdent(){
    const id = (document.getElementById('tgc-id') || {}).value || '';
    const h = (document.getElementById('tgc-hash') || {}).value || '';
    if (!id.trim() || !h.trim()){
        _tgcEtatIdent(false, '', 'Les deux valeurs sont nécessaires.');
        return;
    }
    let r = null;
    try{ r = await apiPost('/api/tgc/ident', {api_id: id.trim(), api_hash: h.trim()}); }
    catch(e){ r = {ok: false, error: String(e && e.message || e)}; }
    if (r && r.ok){
        // Le champ est VIDÉ après coup : laisser un secret à l'écran, c'est
        // l'exposer à la première personne qui passe derrière.
        if (document.getElementById('tgc-hash')) document.getElementById('tgc-hash').value = '';
        _tgcDire('Application enregistrée dans votre coffre.', 'ok');
        tgcCharger();
        return;
    }
    // Le refus est posé DANS l'état, pas seulement dans le retour passager.
    const pourquoi = (r && r.error) || 'Refusé, sans raison donnée.';
    _tgcDire(pourquoi, 'err');
    _tgcEtatIdent(false, '', pourquoi);
}

async function tgcCode(){
    const t = ((document.getElementById('tgc-tel') || {}).value || '').trim();
    if (!t){ _tgcDire('Il manque le téléphone du compte.', 'err'); return; }
    _tgcDire('Demande envoyée à Telegram…', 'ok');
    const r = await apiPost('/api/tgc/commencer', {tel: t});
    _tgcDire(r && r.ok ? 'Code envoyé — regardez Telegram.'
                       : ((r && r.error) || 'Refusé'), r && r.ok ? 'ok' : 'err');
    tgcCharger();
}

async function tgcValider(){
    const c = ((document.getElementById('tgc-code') || {}).value || '').trim();
    const m = (document.getElementById('tgc-mdp') || {}).value || '';
    if (!c){ _tgcDire('Il manque le code.', 'err'); return; }
    const r = await apiPost('/api/tgc/valider', {code: c, mdp: m});
    // Le code et le mot de passe ne restent pas à l'écran non plus.
    if (document.getElementById('tgc-code')) document.getElementById('tgc-code').value = '';
    if (document.getElementById('tgc-mdp')) document.getElementById('tgc-mdp').value = '';
    if (r && r.besoin_mdp){
        _tgcMontrer('tgc-e4', true);
        _tgcDire(r.error || 'Mot de passe requis.', 'err');
        return;
    }
    _tgcDire(r && r.ok ? ('Compte relié' + (r.qui ? ' — ' + r.qui : '') + '.')
                       : ((r && r.error) || 'Refusé'), r && r.ok ? 'ok' : 'err');
    tgcCharger();
    if (r && r.ok && typeof cnEcran === 'function'){ try{ cnEcran(); }catch(e){} }
}

async function tgcEssai(){
    // Un essai qui touche VRAIMENT Telegram. Dire « relié » sur la seule
    // présence d'une clé dans le coffre ne prouve rien : une session révoquée
    // depuis le téléphone y reste écrite, et l'écran mentirait.
    _tgcDire('Appel à Telegram…', 'ok');
    let r = null;
    try{ r = await apiPost('/api/tgc/fils', {}); }catch(e){ r = null; }
    if (!r || !r.ok){ _tgcDire((r && r.error) || 'Échec', 'err'); return; }
    _tgcDire('Connexion vivante : ' + (r.fils || []).length +
             ' conversation(s) lue(s).', 'ok');
}

async function tgcImporter(){
    _tgcDire('Lecture des contacts…', 'ok');
    const r = await apiPost('/api/tgc/importer', {});
    if (!r || !r.ok){ _tgcDire((r && r.error) || 'Refusé', 'err'); return; }
    // Ce qui n'a pas pu être versé est DIT : un import muet laisse croire
    // que tout est passé.
    _tgcDire(r.poses + ' fiche(s) sur ' + r.vus + ' versée(s) au répertoire.' +
             ((r.echecs && r.echecs.length)
                ? ' Non versées : ' + r.echecs.join(' ; ') : ''), 'ok');
}

async function tgcDelier(){
    if (!await buConfirmer("Couper le lien avec votre compte Telegram ?\n\n" +
                 "La session sera révoquée chez Telegram, puis effacée de votre " +
                 "coffre. Vos conversations ne seront plus accessibles ici.")) return;
    const r = await apiPost('/api/tgc/delier', {});
    _tgcDire(r && r.ok ? ('Lien coupé.' + (r.avis ? ' ' + r.avis : ''))
                       : ((r && r.error) || 'Refusé'), r && r.ok ? 'ok' : 'err');
    tgcCharger();
}

async function tgCharger(){
    const el = id => document.getElementById(id);
    if (!el('tg-etat')) return;
    try {
        const d = await apiPost('/api/me/telegram', {});
        if (!d || !d.ok) throw new Error((d && d.error) || 'illisible');

        // L'ÉTAT PORTE SUR LA DESTINATION, pas sur le branchement. Un robot
        // branché sans destinataire n'atteint personne, et « branché ✓ »
        // laissait croire le contraire.
        const e = el('tg-etat');
        if (e){
            e.textContent = !d.robot ? '(aucun robot)'
                          : !d.destinataire ? '(branché — sans destinataire)'
                          : (d.origine === 'declare' ? '(vous prévient ✓)'
                                                     : '(vous prévient ✓ · appris)');
            e.style.color = !d.robot ? 'var(--txt-faint)'
                          : !d.destinataire ? 'var(--warn)' : 'var(--ok)';
        }
        el('tg-det').style.display = d.robot ? '' : 'none';
        el('tg-form').style.display = d.robot ? 'none' : '';
        // Le destinataire ne se règle qu'une fois le robot branché : sans
        // jeton, rien ne peut être essayé, et un champ qui refuse tout ce
        // qu'on y met passe pour une panne.
        const bd = el('tg-dest-b');
        if (bd) bd.style.display = d.robot ? '' : 'none';
        const ce = el('tg-cible');
        if (ce && document.activeElement !== ce) ce.value = d.cible || '';
        const bh = el('tg-dest-h');
        if (bh){
            let t = '';
            if (d.origine === 'declare'){
                t = 'Vos notifications partent vers <b>' + escapeHtml(d.cible) +
                    '</b>. Videz le champ et enregistrez pour revenir à la ' +
                    'conversation apprise.';
            } else if (d.origine === 'appris'){
                t = 'Aucun destinataire déclaré : les notifications suivent la ' +
                    'conversation <b>apprise</b> de votre premier message ' +
                    '(<span class="mono">' + escapeHtml(d.chat_id) + '</span>). ' +
                    'Cela marche, mais rien ne garantit que ce soit bien vous — ' +
                    'déclarez votre identifiant pour en être sûr.';
            } else {
                t = 'Aucun destinataire : <b>rien ne vous parviendra</b>. ' +
                    'Écrivez « /start » au robot depuis votre Telegram, ou ' +
                    'posez votre identifiant ici.';
            }
            // Ce que la machine sait DÉJÀ de vous — relevé quand vous avez
            // relié votre compte Telegram. Proposé, jamais posé d'office : le
            // destinataire des alertes est une décision.
            if (d.propose && d.propose !== d.cible){
                t += ' · Votre compte Telegram relié donne ' +
                     '<b>' + escapeHtml(d.propose) + '</b> — ' +
                     '<a href="#" onclick="const c=document.getElementById(' +
                     '&#39;tg-cible&#39;); if(c) c.value=' +
                     JSON.stringify(String(d.propose)) + '; return false;">' +
                     'l\u2019employer</a>.';
            }
            bh.innerHTML = t;
        }
        if (el('tg-url') && !el('tg-url').value) el('tg-url').value = location.origin;

        let a = '';
        if (d.robot && !d.destinataire){
            a = `<div class="s-hint" style="border:1px solid var(--acc-15);background:var(--acc-10);
                 border-radius:9px;padding:10px 12px;color:var(--txt);margin-bottom:12px">
                 <b>Il manque un geste, et rien ne partira sans lui.</b> Un robot Telegram ne
                 peut pas ouvrir une conversation : ouvrez Telegram, écrivez
                 <code>/start</code> à votre robot, puis revenez ici.</div>`;
        } else if (d.robot){
            a = `<div class="s-hint" style="border:1px solid var(--line);background:var(--ov-03);
                 border-radius:9px;padding:10px 12px;color:var(--txt);margin-bottom:12px">
                 Robot branché depuis ${escapeHtml(String(d.depuis || '').slice(0,16))} —
                 <b>${d.messages}</b> notification(s) et message(s). Détacher retire le webhook
                 et efface le jeton, mais <b>garde l'historique</b>.</div>`;
        }
        el('tg-alerte').innerHTML = a;
    } catch(e){ console.warn('tgCharger:', e); }
}

async function tgBrancher(){
    const g = id => (document.getElementById(id) || {}).value || '';
    const j = g('tg-jeton').trim(), u = (g('tg-url') || location.origin).trim();
    if (!j){ _sfb('tg-feedback', 'Collez le jeton donné par @BotFather.', 'err'); return; }
    _sfb('tg-feedback', 'Vérification du robot…', 'ok');
    try {
        const r = await apiPost('/api/me/telegram/brancher', {jeton: j, url: u});
        const c = document.getElementById('tg-jeton');
        if (c) c.value = '';       // le jeton ne reste pas à l'écran
        if (r && r.ok) _sfb('tg-feedback', 'Robot @' + (r.robot || '?') + ' branché.', 'ok');
        else _sfb('tg-feedback', (r && r.error) || 'Échec', 'err');
    } catch(e){ _sfb('tg-feedback', 'Échec : ' + e.message, 'err'); }
    tgCharger();
}

async function tgEssai(){
    try {
        const r = await apiPost('/api/me/telegram/envoyer',
                                {texte: 'Essai depuis Cassandra — vos notifications '
                                      + 'arriveront ici.'});
        _sfb('tg-feedback', (r && r.ok) ? 'Envoyé.' : ((r && r.error) || 'Échec'),
             (r && r.ok) ? 'ok' : 'err');
    } catch(e){ _sfb('tg-feedback', 'Échec : ' + e.message, 'err'); }
    tgCharger();
}

async function tgDetacher(){
    if (!await buConfirmer("Détacher le robot ? Le webhook est retiré et le jeton effacé de votre "
                 + "coffre. Les messages déjà reçus sont conservés.")) return;
    try {
        await apiPost('/api/me/telegram/detacher', {});
        _sfb('tg-feedback', 'Robot détaché.', 'ok');
    } catch(e){ _sfb('tg-feedback', 'Échec : ' + e.message, 'err'); }
    tgCharger();
}

// ── LA MODALE D'AJOUT, REPRISE (2026-09-05). Ces fonctions et leurs globales avaient disparu
// au passage au thème clair (08-08) ; l'HTML les appelait encore : ReferenceError au clic,
// rien à l'écran, et un registre Serveurs impossible à remplir depuis l'interface.
let _faType='synology';
let _faSynMode='direct';

function openFleetAdd(){
    document.getElementById('fleet-add-modal').classList.remove('hidden');
    document.getElementById('fa-name').focus();
    document.getElementById('fa-error').textContent='';
}
function closeFleetAdd(){ document.getElementById('fleet-add-modal').classList.add('hidden'); }

let _faSshMode='password';

function faSetType(type, btn){
    _faType=type;
    document.querySelectorAll('.fa-type-btn').forEach(b=>b.classList.remove('active'));
    btn.classList.add('active');
    ['synology','ssh','cassandra','proxmox','ping'].forEach(t=>{
        const el=document.getElementById('fa-form-'+t);
        if(el) el.style.display=t===type?'':'none';
    });
    document.getElementById('fa-error').textContent='';
}

function faSshMode(mode){
    _faSshMode=mode;
    document.getElementById('fa-ssh-pass-block').style.display=mode==='password'?'':'none';
    document.getElementById('fa-ssh-key-block').style.display=mode==='key'?'':'none';
    document.getElementById('fa-ssh-mode-pass').classList.toggle('active',mode==='password');
    document.getElementById('fa-ssh-mode-key').classList.toggle('active',mode==='key');
}

function faSynMode(mode){
    _faSynMode=mode;
    document.getElementById('fa-syn-direct').style.display=mode==='direct'?'':'none';
    document.getElementById('fa-syn-qc').style.display=mode==='qc'?'':'none';
    document.getElementById('fa-syn-mode-direct').classList.toggle('active',mode==='direct');
    document.getElementById('fa-syn-mode-qc').classList.toggle('active',mode==='qc');
}

async function faResolveQC(){
    const qcid=document.getElementById('fa-syn-qcid').value.trim();
    const el=document.getElementById('fa-qc-result');
    if(!qcid){el.textContent='Entrez un QuickConnect ID';el.style.color='var(--danger)';return;}
    el.textContent='Résolution en cours…';el.style.color='var(--txt-faint)';
    try{
        const r=await fetch('/api/multiserver/resolve_quickconnect',{method:'POST',
            headers:{'Content-Type':'application/json'},
            body:JSON.stringify({session:sessionId,qc_id:qcid})});
        const d=await r.json();
        if(d.ok){
            el.textContent='✓ Résolu : '+d.host+':'+d.port;
            el.style.color='var(--ok)';
        } else {
            el.textContent='❌ '+d.error;el.style.color='var(--danger)';
        }
    } catch(e){el.textContent='Erreur réseau';el.style.color='var(--danger)';}
}

async function addFleetDevice(){
    const name=document.getElementById('fa-name').value.trim();
    const err=document.getElementById('fa-error');
    const btn=document.getElementById('fa-submit-btn');
    if(!name){err.textContent='Nom requis';return;}
    err.textContent='';btn.textContent='Connexion…';btn.disabled=true;

    let payload={session:sessionId,name,type:_faType};

    if(_faType==='synology'){
        const user=document.getElementById('fa-syn-user').value.trim();
        const pass=document.getElementById('fa-syn-pass').value;
        if(!user||!pass){err.textContent='Identifiants Synology requis';btn.textContent='Ajouter';btn.disabled=false;return;}
        payload.username=user; payload.password=pass;
        if(_faSynMode==='qc'){
            const qcid=document.getElementById('fa-syn-qcid').value.trim();
            if(!qcid){err.textContent='QuickConnect ID requis';btn.textContent='Ajouter';btn.disabled=false;return;}
            payload.qc_id=qcid;
        } else {
            const host=document.getElementById('fa-syn-host').value.trim();
            if(!host){err.textContent='IP/Hostname requis';btn.textContent='Ajouter';btn.disabled=false;return;}
            payload.host=host;
            payload.port=parseInt(document.getElementById('fa-syn-port').value)||5000;
            payload.ssl=document.getElementById('fa-syn-ssl').checked;
        }
    } else if(_faType==='cassandra'){
        payload.url=document.getElementById('fa-url').value.trim();
        payload.token=document.getElementById('fa-token').value.trim();
        if(!payload.url||!payload.token){err.textContent='URL et token requis';btn.textContent='Ajouter';btn.disabled=false;return;}
    } else if(_faType==='proxmox'){
        payload.url=document.getElementById('fa-px-url').value.trim();
        payload.username=document.getElementById('fa-px-user').value.trim();
        payload.password=document.getElementById('fa-px-pass').value;
        if(!payload.url||!payload.password){err.textContent='URL et mot de passe requis';btn.textContent='Ajouter';btn.disabled=false;return;}
    } else if(_faType==='ssh'){
        payload.host=document.getElementById('fa-ssh-host').value.trim();
        payload.port=parseInt(document.getElementById('fa-ssh-port').value)||22;
        payload.username=document.getElementById('fa-ssh-user').value.trim()||'root';
        payload.auth=_faSshMode;
        if(!payload.host){err.textContent='IP/Hostname requis';btn.textContent='Ajouter';btn.disabled=false;return;}
        if(_faSshMode==='password'){
            payload.password=document.getElementById('fa-ssh-pass').value;
            if(!payload.password){err.textContent='Mot de passe requis';btn.textContent='Ajouter';btn.disabled=false;return;}
        } else {
            payload.key=document.getElementById('fa-ssh-key').value.trim();
            if(!payload.key){err.textContent='Clé privée requise';btn.textContent='Ajouter';btn.disabled=false;return;}
        }
    } else if(_faType==='ping'){
        payload.host=document.getElementById('fa-ping-host').value.trim();
        payload.port=parseInt(document.getElementById('fa-ping-port').value)||80;
        if(!payload.host){err.textContent='Hôte requis';btn.textContent='Ajouter';btn.disabled=false;return;}
    }

    try{
        const r=await fetch('/api/multiserver/add_device',{method:'POST',
            headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});
        const d=await r.json();
        btn.textContent='Ajouter';btn.disabled=false;
        if(d.ok){
            closeFleetAdd();
            if (typeof fl2Charger === 'function') fl2Charger(); else refreshFleet();
            addSystemMessage('✓ '+name+' ajouté à la flotte ('+_faType+')');
        } else {
            err.textContent=d.error||'Erreur inconnue';
        }
    } catch(e){
        btn.textContent='Ajouter';btn.disabled=false;
        err.textContent='Erreur réseau: '+e.message;
    }
}
// ── Fiche machine ──────────────────────────────────────────────────────────
// Une carte figée n'apprend rien : elle montre l'instant présent et rien
// d'autre. La fiche réunit ce qu'on irait chercher ailleurs — disponibilité,
// pannes passées, journal, rattachements — et permet d'agir.
// ═══ FLOTTE, la refonte du 2026-09-05 — maquette validée par l'administrateur ═══
// Le parc fusionné (/api/flotte/parc) : chaque machine porte ses quatre sources et leur âge,
// son état déclaré et son niveau de contrôle. Les gestes réutilisent l'existant : flOpen
// (historique), flAct (diagnostic SSH), openFleetAdd (déclaration), removeFleetServer,
// /api/multiserver/toggle ; s'ajoutent l'engagement, le ping Tailscale, la mise en sourdine.
const FL2 = { parc: null, lu: 0, vue: 'maintenant', sel: null, seq: 0, demande: null, hours: 168, verdict: null };
const FL_NIV = {agent: 'Cassandra y tourne', ssh: 'diagnostic et gestes', observation: 'vue par le registre, sans geste', signal: 'vue par Tailscale, rien de plus'};
function flE(t){ if(t==null) return ''; return String(t).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function fl2Machine(nom){ return ((FL2.parc || {}).machines || []).find(x => x.nom === nom); }
function fl2Heure(ts){ const t = ts ? new Date(ts) : new Date(); const p = n => String(n).padStart(2, '0'); return p(t.getHours()) + ':' + p(t.getMinutes()); }
function flDot(m){ return m.etat==='erreur'?'danger':m.etat==='avert'?'warn':m.etat==='retiree'||m.statut==='retiree'?'':'ok'; }
function flQuand(ts){ const s=String(ts||''); if(!s) return '—'; const auj=new Date().toISOString().slice(0,10); return s.startsWith(auj)?s.slice(11,16):s.slice(5,16).replace('T',' '); }

// L'OUVERTURE : le parc (une lecture, trois sources), puis la vue demandée par un autre écran (une
// machine), sinon le verdict. Jeton de séquence : une réponse en retard n'écrase pas la dernière.
async function fl2Charger(){
    const box=document.getElementById('fl-rail'); if(!box) return;
    if(!FL2.parc) box.innerHTML='<div style="padding:10px;font-size:11px;color:var(--txt-faint)">Lecture du parc…</div>';
    let d=null;
    try{ d=await apiPost('/api/flotte/parc',{}); }catch(e){ box.innerHTML='<div style="padding:10px;font-size:11px;color:var(--danger-soft)">Parc injoignable : '+flE(e.message||e)+'</div>'; return; }
    if(!d||d.ok===false){ box.innerHTML='<div style="padding:10px;font-size:11px;color:var(--danger-soft)">Parc refusé : '+flE((d&&d.reason)||'?')+'</div>'; return; }
    FL2.parc=d; FL2.lu=Date.now();
    flRail();
    if(FL2.demande!==null){ const q=FL2.demande; FL2.demande=null; if(q) { fl2Ouvrir(q); return; } }
    flVue(FL2.vue||'maintenant');
}
function flVue(v){ FL2.vue=v; if(typeof navSous==='function') navSous('flVue', v); flRail(); flCharger(); }
// FAÇADE (lot 8) : gardée pour les autres écrans et leurs bancs — un ancien nom qui renvoie.
function fl2Aller(s){ flVue({parc:'maintenant', signaux:'signaux', dispo:'dispo', engagement:'engagement'}[s]||s); }
function fl2Ouvrir(nom){ FL2.sel=nom; FL2.vue='machine'; if(typeof navSous==='function') navSous('fl2Ouvrir', nom); flRail(); flCharger(); }
function flOpen(name){ fl2Ouvrir(name); }
// FAÇADE (lot 8) : gardée pour les autres écrans et leurs bancs — un ancien nom qui renvoie.
function fl2Fiche(nom){ if(nom) fl2Ouvrir(nom); else flVue('machine'); }
function flPeriod(h){ FL2.hours=h; flCharger(); }

// FAÇADE (lot 8) : gardée pour les autres écrans et leurs bancs — un ancien nom qui renvoie.
function flAvailability(){ flVue('dispo'); }
function flRail(){
    const box=document.getElementById('fl-rail'); if(!box) return;
    document.querySelectorAll('#tab-fleet .mx-scene').forEach(b=>b.classList.toggle('on', b.dataset.vue===FL2.vue));
    const M=(FL2.parc||{}).machines||[];
    const groupes=['Serveurs','Postes','Mobiles','Retirées','Disparues'];
    box.innerHTML=groupes.filter(g=>M.some(m=>m.groupe===g)).map(g=>`<div class="mx-fam">${flE(g)}</div>`+M.filter(m=>m.groupe===g).map(m=>{
        const on=(FL2.vue==='machine'&&FL2.sel===m.nom);
        const st=m.etat==='erreur'?'hors ligne':(m.statut==='retiree'?'retirée':(m.niveau==='agent'?'agent':m.niveau==='ssh'?'ssh':''));
        return `<button class="mx-item${on?' on':''}" type="button" onclick="fl2Ouvrir('${flE(m.nom)}')" title="${flE(m.libelle||'')}"><span class="mx-dot ${flDot(m)}"></span><span class="nm">${flE(m.nom)}</span>${st?`<span class="mx-st${m.etat==='erreur'?' off':''}">${flE(st)}</span>`:''}</button>`;
    }).join('')).join('');
    const sous=document.getElementById('fl-rail-sous'); const c=(FL2.parc||{}).compte||{};
    if(sous) sous.textContent=(c.declarees||0)+' machines · relevé '+fl2Heure(FL2.lu)+' · un clic ouvre la fiche';
}

async function flCharger(){
    const p=document.getElementById('fl-page'); if(!p) return;
    const seq=++FL2.seq;
    p.innerHTML='<div class="empty-state" style="padding:40px">Chargement…</div>';
    try{
        if(FL2.vue==='machine') await flVueMachine(seq);
        else if(FL2.vue==='signaux') flVueSignaux();
        else if(FL2.vue==='dispo') await flVueDispo(seq);
        else if(FL2.vue==='engagement') flVueEngagement();
        else await flVueMaintenant(seq);
    }catch(e){
        if(seq!==FL2.seq) return;
        p.innerHTML='<div class="mx-sec"><b>Échec du chargement.</b><span style="color:var(--txt-soft);word-break:break-word">'+flE(e&&e.message?e.message:String(e))+'</span></div>';
        console.error('[FLOTTE]', FL2.vue, FL2.sel, e);
    }
}

// ── Les gestes du verdict : chacun mène à ce qui existe ─────────────────────────────────
function flGeste(g){
    const f=g.f, a=g.a;
    if(f==='machine') fl2Ouvrir(a);
    else if(f==='journal'){ JR.demande={f:'jrTimeline',a:a||undefined}; switchTab('journal'); }
    else if(f==='intermittente') fl2Engager(a,'statut','intermittente');
    else if(f==='declarer_ssh'){ const m=fl2Machine(a); fl2DeclarerSsh(a, (m&&m.ip)||''); }
    else if(f==='oublier') fl2Oublier(a);
    else if(f==='dispo') flVue('dispo');
    else if(f==='signaux') flVue('signaux');
    else if(f==='historique'){ MX.demande='fleet_up'; switchTab('history'); }
}
function flGestes(gs){ return (gs||[]).map((g,i)=>`<button class="mx-btn${i===0?' primary':''}" onclick='flGeste(${flE(JSON.stringify(g))})'>${flE(g.lib)}</button>`).join(''); }
const FL_PILL={panne:'HORS LIGNE',regarder:'À REGARDER',muet:'SANS NOUVELLES'};

function flCarte(m){
    const dispo=(m.dispo===null||m.dispo===undefined)?null:m.dispo;
    const role=m.hote?'Serveur hôte · Cassandra y tourne':(m.registre?(m.registre.type+(m.registre.enabled?'':' · suspendue')+(m.registre.hote?' · '+m.registre.hote:'')):(m.disparue?'disparue du tailnet · renommée ou retirée':(m.tailscale_ssh?'vue par Tailscale, contrôlée par Tailscale SSH sans clé':'vue par Tailscale, non déclarée')));
    return `<button class="fl-carte${FL2.sel===m.nom?' on':''}" type="button" onclick="fl2Ouvrir('${flE(m.nom)}')"><div class="h"><span class="mx-dot ${flDot(m)}"></span><b>${flE(m.nom)}</b><small>${flE(m.os||m.type||'')}</small></div>
      <div class="role">${flE(role)}${m.etat==='erreur'?' · <span style="color:var(--danger)">'+flE(m.libelle||'hors ligne')+'</span>':''}</div>
      <div class="bas"><span>30 j</span><span class="fl-jauge"><i style="width:${dispo==null?0:Math.max(1,Math.round(dispo))}%"></i></span><span style="color:${dispo==null?mxT('--txt-ghost'):dispo>=99?mxT('--ok'):dispo>=90?mxT('--warn'):mxT('--txt-faint')}">${dispo==null?'—':String(dispo).replace('.',',')+' %'}</span></div></button>`;
}

// ── Maintenant : le verdict, les chiffres, le parc en cartes ────────────────────────────
async function flVueMaintenant(seq){
    const p=document.getElementById('fl-page');
    let v=null; try{ v=await apiPost('/api/flotte/verdict',{}); }catch(e){ console.warn('[FLOTTE] verdict indisponible', e); }
    if(seq!==FL2.seq) return;
    FL2.verdict=v&&v.ok?v:null;
    const M=(FL2.parc||{}).machines||[]; const c=(FL2.parc||{}).compte||{}; const pr=(FL2.parc||{}).presence||{};
    const verdict=v&&v.ok?`<section class="mx-sec" aria-label="Verdict">
      <div class="mx-eyebrow">Maintenant · relevé ${fl2Heure(FL2.lu)} · présence ${pr.active?'toutes les '+Math.round((pr.periode_s||300)/60)+' min':'désactivée'}</div>
      <div class="mx-verdict"><div class="mx-vmark ${flE(v.niveau)}"></div><div style="display:flex;flex-direction:column;gap:3px;min-width:0"><p class="mx-vtitle">${flE(v.titre)}</p><span class="mx-vsub">${flE(v.sous_titre)}</span></div></div>
      ${(v.lignes||[]).length?`<div class="mx-rows">${v.lignes.map(l=>`<div class="mx-row"><span class="mx-pill ${flE(l.niveau)}">${FL_PILL[l.niveau]||flE(l.niveau)}</span><div class="mx-rt"><b>${flE(l.titre)}</b>${l.detail?`<span>${flE(l.detail)}</span>`:''}</div><div class="mx-gest">${flGestes(l.gestes)}</div></div>`).join('')}</div>`:''}
      <div class="mx-foot"><span>${c.declarees||0} machines connues · ${c.en_ligne||0} en ligne · ${c.ssh||0} contrôlable${(c.ssh||0)>1?'s':''} par SSH</span><span>Même vérité que <a onclick='flGeste({f:"historique"})'>Historique › Flotte — disponibilité</a></span></div>
    </section>`:'';
    const tuile=(k,vv,s,cls)=>`<button class="mx-kpi${cls?' '+cls:''}" onclick="${k}"><span>${s}</span><b>${vv}</b></button>`;
    const groupes=['Serveurs','Postes','Mobiles','Retirées','Disparues'];
    p.innerHTML=verdict+`<section class="mx-sec" aria-label="Le parc">
      <div class="mx-chart-h"><h2>Le parc</h2><span class="mx-meta">registre Serveurs + Tailscale + Sensorium</span></div>
      <div class="mx-kpis">
        ${tuile("flVue('maintenant')", c.declarees||0, 'MACHINES CONNUES')}
        ${tuile("flVue('signaux')", (c.tailscale||0)+'<small style="font-size:12px;color:var(--txt-faint)">/'+(c.declarees||0)+'</small>', 'VUES PAR TAILSCALE')}
        ${tuile("flVue('maintenant')", c.en_ligne||0, 'EN LIGNE')}
        ${tuile("flVue('maintenant')", c.attendues_hors_ligne||0, 'ATTENDUES HORS LIGNE', (c.attendues_hors_ligne||0)?'alerte':'')}
        ${tuile("flVue('engagement')", c.ssh||0, 'CONTRÔLABLES PAR SSH')}
        ${tuile("flVue('dispo')", c.mesurees?c.mesurees:'—', c.mesurees?'DISPONIBILITÉS MESURÉES':'DISPONIBILITÉ NON MESURÉE')}
      </div>
      ${M.length?groupes.filter(g=>M.some(m=>m.groupe===g)).map(g=>`<div class="mx-fam" style="padding-left:0">${flE(g)}</div><div class="fl-cartes">${M.filter(m=>m.groupe===g).map(flCarte).join('')}</div>`).join('')
        :'<div class="mx-empty"><span class="mx-pill">VIDE</span><div><b>Aucune machine connue</b><p>Ni le registre, ni Tailscale, ni le Sensorium ne connaissent de machine. Déclare-en une, ou vérifie Tailscale.</p></div></div>'}
      <div class="mx-foot"><span>Une carte = une machine : son état, ce qu'elle est, sa disponibilité sur 30 jours. Un clic ouvre la fiche. Une machine vue par Tailscale entre ici d'elle-même ; la déclarer au registre est ton geste.</span></div>
    </section>`;
}

// ── Une machine : la fiche, l'engagement, les gestes, puis l'historique et les pannes ────
async function flVueMachine(seq){
    const p=document.getElementById('fl-page');
    const m=FL2.sel?fl2Machine(FL2.sel):null;
    if(!m){ p.innerHTML=`<section class="mx-sec"><div class="mx-chart-h"><h2>Une machine</h2></div><div class="mx-empty"><span class="mx-pill">À CHOISIR</span><div><b>Choisis une machine dans la colonne de gauche</b><p>Sa fiche s'ouvre ici : ce que chaque source en sait, l'engagement, les gestes, l'historique et les pannes.</p></div></div>
      <div class="mx-eyebrow">Les niveaux de contrôle</div><div class="fl-env"><span>signal</span><b>Cassandra la voit (Tailscale), rien de plus. Le seul niveau possible pour un téléphone.</b><span>observation</span><b>Le registre la connaît, sans clé : on lit, on n'agit pas.</b><span>ssh</span><b>Une clé dans le registre, ou Tailscale SSH constaté par la sonde (Linux, sans clé) : diagnostic et gestes sur les services, confirmés et journalisés.</b><span>agent</span><b>Cassandra y tourne : l'hôte.</b></div>
      <div class="mx-eyebrow">Les statuts</div><div class="fl-env"><span>attendue</span><b>hors ligne = coupure, alerte et malus au score</b><span>intermittente</span><b>vient et va : ni alerte ni malus, mais l'absence est datée</b><span>retirée</span><b>sortie du parc : plus de surveillance ni de disponibilité</b></div></section>`; return; }
    const d=await apiPost('/api/flotte/history',{name:m.nom, hours:FL2.hours});
    if(seq!==FL2.seq) return;
    const S=m.sources||{}; const n=flE(m.nom);
    const srcs=[['tailscale','Tailscale'],['sensorium','Sensorium'],['registre','Registre Serveurs'],['ssh','SSH']].map(([k,l])=>{ const s=S[k]||{etat:'neutre',texte:'—',observe:''}; const dot=s.etat==='ok'?'ok':s.etat==='avert'?'warn':s.etat==='erreur'?'danger':''; return `<div class="fl-src"><b><span class="mx-dot ${dot}"></span>${flE(l)}</b>${flE(s.texte||'—')}${s.observe?`<small>${flE(s.observe)}</small>`:''}</div>`; }).join('');
    const statuts=[['attendue','attendue','alerte si hors ligne'],['intermittente','intermittente','jamais d\'alerte, absence datée'],['retiree','retirée','plus de surveillance']].map(([v,l,s])=>`<button class="${m.statut===v?'on':''}" ${m.hote?'disabled':''} onclick="fl2Engager('${n}','statut','${v}')">${l}<small>${s}</small></button>`).join('');
    const niveaux=[['signal','signal','vue par Tailscale'],['ssh','ssh','une clé au registre, ou Tailscale SSH'],['agent','agent','l\'hôte seulement']].map(([v,l,s])=>{ const dis=(v==='agent'&&!m.hote)||(v==='ssh'&&!((m.registre&&m.registre.type==='ssh')||m.tailscale_ssh))||(m.hote&&v!=='agent'); return `<button class="${m.niveau===v?'on':''}" ${dis?'disabled':''} onclick="fl2Engager('${n}','niveau','${v}')">${l}<small>${s}</small></button>`; }).join('');
    const g=[];
    if(!m.hote&&S.tailscale&&S.tailscale.etat!=='neutre') g.push(`<button class="mx-btn primary" onclick="fl2Ping('${n}')">Ping Tailscale</button>`);
    if(m.niveau==='ssh'){ g.push(`<button class="mx-btn" onclick="flAct('diagnostic')">Diagnostic</button><button class="mx-btn" onclick="flAct('disques')">Disques</button><button class="mx-btn" onclick="flAct('memoire')">Mémoire</button><button class="mx-btn" onclick="flAct('journal')">Journal</button><button class="mx-btn" onclick="flAct('services')">Services</button><button class="mx-btn" onclick="flSvcPrompt()">Agir sur un service…</button>`); }
    else if(!m.hote&&m.groupe!=='Mobiles'&&m.statut!=='retiree') g.push(`<button class="mx-btn" onclick="fl2DeclarerSsh('${n}','${flE(m.ip||'')}')">Déclarer une clé SSH</button>`);
    if(m.dernier_contact) g.push(`<button class="mx-btn" onclick='flGeste({f:"journal",a:${flE(JSON.stringify(m.dernier_contact))}})'>Ce moment dans les journaux</button>`);
    if(m.disparue) g.push(`<button class="mx-btn primary" onclick="fl2Oublier('${n}')">Oublier ses traces</button>`);
    if(m.statut==='attendue'&&!m.hote&&!m.disparue) g.push(`<button class="mx-btn" onclick="fl2Engager('${n}','statut','intermittente')">Éteindre l'alerte hors ligne</button>`);
    if(m.registre) g.push(`<button class="mx-btn" onclick="fl2Toggle('${n}', ${m.registre.enabled?'false':'true'})">${m.registre.enabled?'Suspendre la surveillance':'Reprendre la surveillance'}</button>`);
    if(!m.hote&&m.statut!=='retiree'&&!m.disparue) g.push(`<button class="mx-btn" style="border-color:var(--danger);color:var(--danger)" onclick="fl2Engager('${n}','statut','retiree')">Retirer du parc</button>`);
    if(m.registre) g.push(`<button class="mx-btn" style="border-color:var(--danger);color:var(--danger)" onclick="fl2Retirer('${n}')">Effacer du registre</button>`);
    const niveauV=m.etat==='erreur'?'panne':(m.etat==='avert'?'regarder':(m.statut==='retiree'?'inconnu':'stable'));
    const titreV=m.etat==='erreur'?('Attendue et hors ligne'+(m.depuis?' depuis '+flQuand(m.depuis):'')+'.'):(m.statut==='retiree'?'Retirée du parc.':(m.en_ligne===false?'Hors ligne, absence volontaire.':'Répond.'));
    // l'historique : la barre de présence et les événements datés
    const pts=(d&&d.ok?d.points:[])||[]; const ev=(d&&d.ok?d.events:[])||[]; const liens=(d&&d.ok?d.links:[])||[];
    let bar='';
    if(pts.length){ const n0=pts.length; let segs=''; let run=null;
        pts.forEach((x,i)=>{ if(!x.online&&run===null) run=i; if(x.online&&run!==null){ segs+=`<rect x="${run/n0*400}" y="3" width="${Math.max(2,(i-run)/n0*400)}" height="16" rx="2" fill="${m.statut==='intermittente'?mxT('--txt-ghost'):mxT('--danger')}"/>`; run=null; } });
        if(run!==null) segs+=`<rect x="${run/n0*400}" y="3" width="${Math.max(2,(n0-run)/n0*400)}" height="16" rx="2" fill="${m.statut==='intermittente'?mxT('--txt-ghost'):mxT('--danger')}"/>`;
        bar=`<div class="fl-bar"><svg viewBox="0 0 400 22" preserveAspectRatio="none" aria-hidden="true"><rect x="0" y="7" width="400" height="8" rx="4" fill="var(--acc-15)"/>${segs}</svg></div>`; }
    const per=[[24,'24 h'],[168,'7 jours'],[720,'30 jours']].map(([h,l])=>`<button class="mx-per${FL2.hours===h?' on':''}" onclick="flPeriod(${h})">${l}</button>`).join('');
    const KIND={perte:['danger','PERTE'],retour:['ok','RETOUR'],decouverte:['','DÉCOUVERTE'],action:['pas_encore','ACTION']};
    p.innerHTML=`<section class="mx-sec">
      <div class="mx-chart-h"><h2>${n}</h2><span class="mx-meta">${flE(m.groupe||'')} · ${flE(m.os||m.type||'')} · ${flE(m.hote?'serveur hôte':(m.registre?'déclarée au registre ('+m.registre.type+(m.registre.enabled?')':', suspendue)'):'vue par Tailscale, non déclarée'))}</span></div>
      <div class="mx-verdict"><div class="mx-vmark ${niveauV}"></div><div style="display:flex;flex-direction:column;gap:3px"><p class="mx-vtitle" style="font-size:17px">${flE(titreV)}</p><span class="mx-vsub">${flE(m.libelle||'')}${m.niveau==='signal'&&!m.hote?' · vue par Tailscale sans clé SSH : aucun geste à distance possible.':''}</span></div></div>
      <div class="fl-env"><span>état</span><b>${flE(m.libelle||m.etat||'—')} · ${flE(m.statut||'')}</b><span>adresse</span><b style="font-family:'JetBrains Mono',monospace">${flE(m.ip||'—')}</b><span>dernier contact</span><b>${flE(flQuand(m.dernier_contact))}</b><span>contrôle</span><b>${flE(m.niveau||'signal')} — ${flE(FL_NIV[m.niveau]||'')}</b><span>30 jours</span><b>${m.dispo==null?'pas encore mesurée':String(m.dispo).replace('.',',')+' % · '+(m.pannes||0)+' coupure'+((m.pannes||0)>1?'s':'')+(m.indispo?' · '+flE(m.indispo)+' de panne':'')+' · '+(m.releves||0)+' relevés'}</b></div>
      <div class="mx-eyebrow">Ce que chaque source dit</div><div class="fl-srcs">${srcs}</div>
      <div class="mx-eyebrow">Engagement · statut</div><div class="fl-choix">${statuts}</div>
      <div class="mx-eyebrow">Engagement · niveau de contrôle</div><div class="fl-choix">${niveaux}</div>
      <div class="mx-eyebrow">Gestes · confirmés et journalisés</div><div class="mx-gest" style="justify-content:flex-start">${g.join('')}</div>
      <div id="fl2-sortie" style="font-size:12.5px;color:var(--txt-soft)"></div><div id="fl-out"></div>
    </section>
    <section class="mx-sec">
      <div class="mx-chart-h"><h2>Historique et pannes</h2><div class="mx-periods">${per}</div></div>
      <div class="mx-meta">${d&&d.ok?((d.availability==null?'pas encore de mesure':'disponibilité '+String(d.availability).replace('.',',')+' %')+' · '+(d.samples||0)+' relevé'+((d.samples||0)>1?'s':'')+' · le rouge est une coupure comptée, le gris une absence volontaire'):flE((d&&d.reason)||'historique indisponible')}</div>
      ${bar}
      ${ev.length?`<div class="mx-rows">${ev.slice().reverse().slice(0,40).map(e=>{ const k=KIND[e.kind]||['',String(e.kind||'').toUpperCase()]; return `<div class="mx-row"><span class="mx-pill ${k[0]}">${k[1]}</span><div class="mx-rt"><b>${flE(flQuand(e.ts))}${e.duration_min?' — '+e.duration_min+' min':''}</b><span>${flE(e.detail||'')}</span></div><div class="mx-gest"><button class="mx-btn" onclick='flGeste({f:"journal",a:${flE(JSON.stringify(String(e.ts||'')))}})'>Ce moment</button></div></div>`; }).join('')}</div>`:'<div class="mx-empty"><span class="mx-pill">RIEN</span><div><b>Aucun événement sur la période</b><p>Ni perte, ni retour, ni découverte.</p></div></div>'}
      <div class="mx-eyebrow">Rattachements · qui prévenir</div>
      <div class="mx-gest" style="justify-content:flex-start">${liens.length?liens.map(l=>`<span class="mx-pill">${flE(l.kind)} · ${flE(l.ref)} <a style="cursor:pointer;color:var(--danger)" onclick="flUnlink('${flE(l.kind)}','${flE(l.ref)}')">retirer</a></span>`).join(''):'<span style="font-size:12.5px;color:var(--txt-faint)">Aucun rattachement — personne à prévenir si elle tombe.</span>'}</div>
      <div class="fl-form"><select id="fl-kind"><option value="project">Projet</option><option value="domain">Domaine</option><option value="note">Note</option></select><input id="fl-ref" placeholder="identifiant ou nom" style="width:220px"><button class="mx-btn" onclick="flLink()">Rattacher</button></div>
      <div id="fl-dequi"></div><div id="fl-notes"></div>
      <div class="mx-foot"><span>Un contact rattaché est cité dans la tâche créée quand la machine tombe.</span><a onclick='flGeste({f:"historique"})'>La courbe Flotte — disponibilité dans l'Historique</a></div>
    </section>`;
    try{ if(typeof ctDeQui==='function') ctDeQui('server', m.nom, 'fl-dequi'); if(typeof ntDeQui==='function') ntDeQui('machine', m.nom, 'fl-notes'); }catch(e){}
}

// ── Signaux et sources ────────────────────────────────────────────────────────────────
function flVueSignaux(){
    const p=document.getElementById('fl-page'); const M=(FL2.parc||{}).machines||[]; const sante=(FL2.parc||{}).tailscale_sante||[];
    p.innerHTML=`<section class="mx-sec"><div class="mx-chart-h"><h2>Signaux et sources</h2><span class="mx-meta">ce que chaque source dit de chaque machine</span></div>
      <div class="mx-empty"><span class="mx-pill pas_encore">TROIS SOURCES</span><div><b>Elles ne se lisent pas entre elles</b><p>Le registre Serveurs porte le contrôle, Tailscale la présence, le Sensorium les entités et la vigie. Elles sont montrées côte à côte ; l'arbitrage est à toi, par l'engagement.</p></div></div>
      <div class="mx-tbl"><table class="mx-ab"><thead><tr><th>Machine</th><th style="text-align:left">Tailscale</th><th style="text-align:left">Sensorium</th><th style="text-align:left">Registre Serveurs</th><th style="text-align:left">SSH</th></tr></thead><tbody>
      ${M.map(m=>`<tr style="cursor:pointer" onclick="fl2Ouvrir('${flE(m.nom)}')"><td><b>${flE(m.nom)}</b></td>${['tailscale','sensorium','registre','ssh'].map(k=>{ const s=(m.sources||{})[k]||{etat:'neutre',texte:'—'}; const dot=s.etat==='ok'?'ok':s.etat==='avert'?'warn':s.etat==='erreur'?'danger':''; return `<td style="text-align:left"><span class="mx-dot ${dot}" style="display:inline-block;margin-right:6px"></span>${flE(s.texte||'—')}</td>`; }).join('')}</tr>`).join('')}
      </tbody></table></div>
      <div class="mx-foot"><span>Health check Tailscale sur l'hôte : ${sante.length?flE(sante.join(' · ')):'rien à signaler'}</span></div></section>`;
}

// ── Disponibilité 30 j : le pire d'abord ────────────────────────────────────────────────
async function flVueDispo(seq){
    const p=document.getElementById('fl-page');
    const d=await apiPost('/api/flotte/availability',{days:30});
    if(seq!==FL2.seq) return;
    const M=(FL2.parc||{}).machines||[]; const st=nom=>(M.find(m=>m.nom===nom)||{}).statut||'';
    const L=((d&&d.ok?d.machines:[])||[]).slice().sort((a,b)=>(a.availability??101)-(b.availability??101));
    p.innerHTML=`<section class="mx-sec"><div class="mx-chart-h"><h2>Disponibilité 30 j</h2><span class="mx-meta">présence mesurée · la moins disponible en premier</span></div>
      ${L.length?`<div class="mx-tbl"><table class="mx-ab"><thead><tr><th>Machine</th><th style="text-align:left;min-width:160px">Présence</th><th>Disponibilité</th><th>Coupures</th><th>Panne cumulée</th><th style="text-align:left">Statut</th><th></th></tr></thead><tbody>
      ${L.map(x=>{ const a=x.availability; const s=st(x.name); return `<tr><td><b>${flE(x.name)}</b></td><td style="text-align:left"><span class="fl-jauge" style="display:block;height:8px"><i style="width:${a==null?0:Math.max(1,Math.round(a))}%;background:${s==='intermittente'?mxT('--txt-ghost'):mxT('--ok')}"></i></span></td><td style="font-weight:600;color:${a==null?mxT('--txt-ghost'):a>=99?mxT('--ok'):s==='intermittente'?mxT('--txt-faint'):mxT('--warn')}">${a==null?'—':String(a).replace('.',',')+' %'}</td><td>${x.outages||0}</td><td>${flE(x.downtime||'—')}</td><td style="text-align:left"><span class="mx-pill ${s==='attendue'?'ok':''}">${flE((s||'attendue').toUpperCase())}</span></td><td><button class="mx-btn" onclick="fl2Ouvrir('${flE(x.name)}')">Fiche</button></td></tr>`; }).join('')}
      </tbody></table></div>`:'<div class="mx-empty"><span class="mx-pill">PAS ENCORE</span><div><b>Aucune mesure</b><p>'+flE((d&&d.reason)||'La présence n\'a encore rien écrit : elle passe toutes les cinq minutes depuis Tailscale.')+'</p></div></div>'}
      <div class="mx-foot"><span>Une intermittente n'entre pas dans les alertes : sa présence est grise, pas rouge. Une attendue hors ligne compte comme coupure.</span><a onclick='flGeste({f:"historique"})'>La même courbe, par machine, dans l'Historique</a></div></section>`;
}

// ── Engagement ────────────────────────────────────────────────────────────────────────
function flVueEngagement(){
    const p=document.getElementById('fl-page'); const M=(FL2.parc||{}).machines||[];
    p.innerHTML=`<section class="mx-sec"><div class="mx-chart-h"><h2>Engagement</h2><span class="mx-meta">comment on s'engage sur chaque machine</span></div>
      <div class="mx-empty"><span class="mx-pill pas_encore">À TRANCHER</span><div><b>Machine par machine</b><p>Le statut règle les alertes et la disponibilité ; le niveau de contrôle règle ce que Cassandra peut faire. Les deux se changent dans la fiche.</p></div></div>
      <div class="mx-tbl"><table class="mx-ab"><thead><tr><th>Machine</th><th style="text-align:left">Statut</th><th style="text-align:left">Niveau</th><th style="text-align:left">Ce qu'il faut</th></tr></thead><tbody>
      ${M.map(m=>{ let b='rien';
        if(m.niveau==='signal'&&!m.hote&&m.groupe!=='Mobiles'&&m.statut==='attendue') b='une clé SSH dans le registre (Déclarer une machine, type SSH), ou Tailscale SSH sur la machine si elle est sous Linux';
        else if(m.niveau==='observation') b='passer en SSH pour agir : déclarer une clé';
        else if(m.statut==='retiree') b='sortie du parc ; l\'entité Sensorium vit jusqu\'à sa purge';
        else if(m.statut==='intermittente') b='aucune alerte ; absence datée';
        else if(m.etat==='erreur') b='revenir en ligne, ou passer en intermittente si l\'absence est voulue';
        return `<tr style="cursor:pointer" onclick="fl2Ouvrir('${flE(m.nom)}')"><td><b>${flE(m.nom)}</b></td><td style="text-align:left"><span class="mx-pill ${m.statut==='attendue'?'ok':m.statut==='intermittente'?'regarder':''}">${flE((m.statut==='retiree'?'retirée':m.statut||'').toUpperCase())}</span></td><td style="text-align:left"><span class="mx-pill ${m.niveau==='agent'?'ok':'pas_encore'}">${flE((m.niveau||'signal').toUpperCase())}</span> <span style="font-size:12px;color:var(--txt-soft)">${flE(FL_NIV[m.niveau]||'')}</span></td><td style="text-align:left;color:${b==='rien'?mxT('--txt-faint'):mxT('--txt')}">${flE(b)}</td></tr>`; }).join('')}
      </tbody></table></div>
      <div class="mx-foot"><span>Un niveau ne se monte pas d'ici : il se gagne par une clé dans le registre, par Tailscale SSH constaté sur la machine, ou par Cassandra qui tourne dessus.</span></div></section>`;
}

// ── Les gestes d'engagement et de registre — inchangés dans leur fond ─────────────────
async function fl2Engager(nom, quoi, valeur){
    const libelle = quoi === 'statut' ? `Le statut de ${nom} devient « ${valeur === 'retiree' ? 'retirée' : valeur} » : ${{attendue: 'alerte et malus si elle tombe', intermittente: 'plus d’alerte ni de malus, absence datée', retiree: 'plus de surveillance ni de disponibilité'}[valeur] || ''}.`
                                      : `Le niveau de contrôle de ${nom} devient « ${valeur} » : ${FL_NIV[valeur] || ''}.`;
    if (!await fp2Confirm(libelle + '\n\nEnregistrer l’engagement ?', 'Engagement · ' + nom)) return;
    const r = await apiPost('/api/flotte/engagement', { name: nom, statut: quoi === 'statut' ? valeur : '', niveau: quoi === 'niveau' ? valeur : '' });
    if (!r || r.ok === false) { if (typeof showToast === 'function') showToast('Engagement refusé : ' + ((r && r.reason) || '?'), 'error', 5000); return; }
    if (typeof showToast === 'function') showToast('Engagement enregistré : ' + nom + ' · ' + (r.statut || '') + ' · ' + (r.niveau || ''), 'success', 2600);
    await fl2Charger();
}
async function fl2Ping(nom){
    const out = document.getElementById('fl2-sortie'); if (out) out.textContent = 'ping en cours…';
    const r = await apiPost('/api/flotte/ping', { name: nom });
    if (out) out.textContent = r && r.ok ? `ping ${nom} : ${r.latence_ms} ms${r.via ? ' · ' + r.via : ''}` : `ping ${nom} : ${(r && r.reason) || 'échec'}`;
}
function fl2DeclarerSsh(nom, ip){
    openFleetAdd();
    try { const b = Array.from(document.querySelectorAll('.fa-type-btn')).find(x => (x.getAttribute('onclick') || '').includes("'ssh'")); if (b) faSetType('ssh', b); } catch(e) {}
    const n = document.getElementById('fa-name'); if (n) n.value = nom;
    const h = document.getElementById('fa-ssh-host'); if (h && ip) h.value = ip;
    try { faSshMode('key'); } catch(e) {}
}
async function fl2Toggle(nom, activer){
    if (!await fp2Confirm(`${activer ? 'Reprendre' : 'Suspendre'} la surveillance de ${nom} par le registre. La machine reste déclarée.\n\nContinuer ?`, 'Surveillance · ' + nom)) return;
    const r = await apiPost('/api/multiserver/toggle', { session: sessionId, name: nom, enabled: activer });
    if (typeof showToast === 'function') showToast(r && r.ok !== false ? 'Surveillance ' + (activer ? 'reprise' : 'suspendue') : 'Refus : ' + ((r && r.error) || (r && r.reason) || '?'), r && r.ok !== false ? 'success' : 'error', 3000);
    await fl2Charger();
}
async function fl2Oublier(nom){
    if (!await fp2Confirm(`Oublier ${nom} : Tailscale ne la liste plus (renommée ou retirée). Ses traces de présence, sa sonde, son entité Sensorium et ses réglages sont effacés ; l'historique reste.\n\nOublier ?`, 'Disparue · ' + nom)) return;
    const r = await apiPost('/api/flotte/oublier', { name: nom });
    if (typeof showToast === 'function') showToast(r && r.ok ? nom + ' oubliée' : 'Refus : ' + ((r && (r.error || r.reason)) || '?'), r && r.ok ? 'success' : 'error', 3000);
    FL2.sel = ''; FL2.vue = 'maintenant'; fl2Charger();
}
async function fl2Retirer(nom){
    if (!await fp2Confirm(`Effacer ${nom} du registre Serveurs : ses identifiants sont supprimés, l'historique reste.\n\nConfirmer la suppression ?`, 'Registre · ' + nom)) return;
    const r = await apiPost('/api/multiserver/remove', { session: sessionId, name: nom });
    if (typeof showToast === 'function') showToast(r && r.ok ? nom + ' effacée du registre' : 'Refus : ' + ((r && (r.error || r.reason)) || '?'), r && r.ok ? 'success' : 'error', 3000);
    FL2.sel = null; await fl2Charger();
}

// ── Les actions SSH nommées, les liens — dans la fiche ─────────────────────────────────
async function flAct(action, service){
    const nom=FL2.sel; const out=document.getElementById('fl-out'); if(!nom) return;
    if(out) out.innerHTML='<div style="font-size:12.5px;color:var(--txt-faint)">Exécution sur la machine distante…</div>';
    try{
        let r=await fetch('/api/flotte/act',{method:'POST',headers:{'X-Session-Token':sessionId,'Content-Type':'application/json'},body:JSON.stringify({name:nom, action:action, service:service||''})});
        let d=await r.json();
        if(r.status===409 && d.needs_confirm){ if(!await buConfirmer(d.reason+'\n\n'+(d.command||'')+'\n\nContinuer ?')){ if(out) out.innerHTML=''; return; }
            r=await fetch('/api/flotte/act',{method:'POST',headers:{'X-Session-Token':sessionId,'Content-Type':'application/json'},body:JSON.stringify({name:nom, action:action, service:service||'', confirm:true})}); d=await r.json(); }
        if(!out) return;
        if(d.vital){ out.innerHTML=`<div class="mx-empty"><span class="mx-pill regarder">VITAL</span><div><b>${flE(d.reason)}</b></div></div>`; return; }
        out.innerHTML=`<div class="mx-eyebrow">${flE(action)}${service?' — '+flE(service):''} · code ${flE(d.exit_code)} · ${d.duration_ms||0} ms</div>${d.reason?`<div style="color:var(--danger);font-size:12.5px">${flE(d.reason)}</div>`:''}<pre class="fl-sortie">${flE(d.output||'(aucune sortie)')}</pre>`;
    }catch(e){ if(out) out.innerHTML=`<div style="color:var(--danger)">${flE(e.message||'échec')}</div>`; }
}
async function flSvcPrompt(){
    const svc=await buSaisir('Nom du service (ex : nginx, docker) :'); if(!svc) return;
    const act=await buSaisir('Action — status, restart, start ou stop :', 'status'); if(!act) return;
    const key={status:'svc_status',restart:'svc_restart',start:'svc_start',stop:'svc_stop'}[act.trim().toLowerCase()];
    if(!key){ buDire('Action inconnue : status, restart, start ou stop.'); return; }
    flAct(key, svc.trim());
}
async function flLink(){
    const kind=document.getElementById('fl-kind').value, ref=(document.getElementById('fl-ref').value||'').trim();
    if(!ref){ buDire('Indiquez une référence.'); return; }
    try{ const d=await apiPost('/api/flotte/link/save',{name:FL2.sel, kind:kind, ref:ref}); if(!d.ok){ buDire(d.reason||'échec'); return; } flCharger(); }
    catch(e){ buDire('Erreur : '+e.message); }
}
async function flUnlink(kind, ref){ try{ await apiPost('/api/flotte/link/delete',{name:FL2.sel, kind:kind, ref:ref}); flCharger(); }catch(e){ buDire('Erreur : '+e.message); } }

// FAÇADE (lot 8) : gardée pour les autres écrans et leurs bancs — un ancien nom qui renvoie.
function flVersJournal(){
    const m=document.getElementById('fp-modal'); if(m) m.remove();
    JR.demande={f:'jrOpen',a:'flotte'}; switchTab('journal');
}
async function removeFleetServer(name){
    if(!await buConfirmer('Supprimer le serveur "'+name+'" de la flotte ?'))return;
    try{
        const r=await fetch('/api/multiserver/remove',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({session:sessionId,name})});
        const d=await r.json();
        if(d.ok){ refreshFleet(); addSystemMessage('Serveur '+name+' retiré'); }
        else addSystemMessage('❌ '+d.error);
    } catch(e){ addSystemMessage('❌ '+e.message); }
}

async function refreshFleet(){
    const grid=document.getElementById('fleet-grid');
    grid.innerHTML='<div class="empty-state" style="padding:20px">Interrogation de la flotte…</div>';
    try{
        const r=await fetch('/api/multiserver/aggregate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({session:sessionId})});
        if(r.status===401){ logout(); return; }
        const d=await r.json();
        document.getElementById('fa-total').textContent=d.total_servers||0;
        const onEl=document.getElementById('fa-online');
        onEl.textContent=d.online_servers||0;
        onEl.className='fleet-agg-value '+(d.offline_servers>0?'warning':'');
        // Le dénominateur compte : une sonde ping n'a pas de CPU à déclarer.
        // Une moyenne sans son assise laisse croire que toute la flotte y est.
        const base=d.avg_basis||{};
        const _socle=(el,n)=>{ const p=el.parentElement&&el.parentElement.querySelector('.fleet-agg-label');
            if(p&&!p.dataset.base) p.dataset.base=p.textContent;
            if(p) p.textContent=(p.dataset.base||p.textContent)+(n?' · '+n+' machine'+(n>1?'s':''):' · —'); };
        const cpuEl=document.getElementById('fa-cpu');
        cpuEl.textContent=(d.avg_cpu||0)+'%';
        cpuEl.className='fleet-agg-value '+(d.avg_cpu>85?'critical':d.avg_cpu>70?'warning':'');
        _socle(cpuEl, base.cpu||0);
        const ramEl=document.getElementById('fa-ram');
        ramEl.textContent=(d.avg_ram||0)+'%';
        ramEl.className='fleet-agg-value '+(d.avg_ram>85?'critical':d.avg_ram>70?'warning':'');
        _socle(ramEl, base.ram||0);
        if(!d.nodes||d.nodes.length===0){
            grid.innerHTML='<div class="empty-state" style="padding:20px">Aucun serveur dans la flotte.<br>Ajoutez le premier avec le bouton ci-dessus.</div>';
            return;
        }
        grid.innerHTML=d.nodes.map(n=>{
            const isLocal=n.name==='local';
            const online=n.online;
            const dtype=n.type||'cassandra';
            const cpu=n.cpu||0, ram=n.ram||0, disk=n.disk||0, health=n.health_score||0;
            const cc=v=>v>85?'var(--danger)':v>70?'var(--warn)':'var(--ok)';
            const typeIcon={'cassandra':'🤖','synology':'🖧','proxmox':'🧱','ping':'📡','local':'★'}[isLocal?'local':dtype]||'🖥';
            const typeBadge=isLocal?'':`<span style="font-size:9px;background:rgba(124,92,252,.15);color:#9b8ffc;border-radius:3px;padding:1px 5px;margin-left:4px">${dtype.toUpperCase()}</span>`;

            let extraHtml='';
            if(dtype==='synology'&&online){
                const model=n.model?`<span style="color:var(--accent)">${escapeHtml(n.model)}</span> `:' ';
                const dsm=n.dsm_version?`DSM ${escapeHtml(n.dsm_version)} `:'';
                const vols=n.volumes?`· ${n.volumes} vol.`:'';
                const diskInfo=n.disk_used_gb?`${n.disk_used_gb}/${n.disk_total_gb} GB`:'';
                extraHtml=`<div style="font-size:10px;color:var(--txt-faint);margin-bottom:6px">${model}${dsm}${vols}${diskInfo?'· '+diskInfo:''}</div>`;
            }
            if(dtype==='ssh'&&online){
                const info=[n.hostname,n.kernel,n.uptime].filter(Boolean).join(' · ');
                if(info) extraHtml=`<div style="font-size:10px;color:var(--txt-faint);margin-bottom:6px">${escapeHtml(info)}</div>`;
            }
            if(dtype==='proxmox'&&online&&n.nodes){
                extraHtml=`<div style="font-size:10px;color:var(--txt-faint);margin-bottom:6px">${n.nodes} nœud(s) Proxmox</div>`;
            }
            if(dtype==='ping'){
                extraHtml=online
                    ?`<div style="font-size:10px;color:var(--ok);margin:6px 0">✓ Joignable</div>`
                    :`<div style="font-size:10px;color:var(--danger);margin:6px 0">✗ Hors ligne</div>`;
            }

            const metricsHtml=(online&&dtype!=='ping')?`<div class="fleet-node-metrics">
                <div class="fleet-metric-mini"><div class="label">CPU</div><div class="val" style="color:${cc(cpu)}">${cpu}%</div></div>
                <div class="fleet-metric-mini"><div class="label">RAM</div><div class="val" style="color:${cc(ram)}">${ram}%</div></div>
                <div class="fleet-metric-mini"><div class="label">DISK</div><div class="val" style="color:${cc(disk)}">${disk}%</div></div>
            </div>${health?`<div style="font-size:10px;color:var(--txt-faint)">${health>=90?'💚':health>=75?'💛':health>=50?'🧡':'❤️'} Santé ${health}/100</div>`:''}`
            :(n.error&&!online)?`<div style="font-size:11px;color:var(--danger);margin:8px 0">❌ ${escapeHtml(n.error)}</div>`:'';

            const actionsHtml=isLocal
                ?'<div style="font-size:10px;color:var(--txt-faint);margin-top:6px">Serveur local</div>'
                :`<div class="fleet-node-actions"><button class="fleet-node-btn" onclick="flOpen('${escapeAttr(n.name)}')">Ouvrir</button><button class="fleet-node-btn" onclick="sendQuickFix('Statut du serveur ${escapeHtml(n.name)}')">Analyser</button><button class="fleet-node-btn danger" onclick="removeFleetServer('${escapeAttr(n.name)}')">Retirer</button></div>`;

            return `<div class="fleet-node ${online?'':'offline'}">
                <div class="fleet-node-header">
                    <span class="fleet-node-name">${typeIcon} ${escapeHtml(n.name)}${typeBadge}</span>
                    <span class="fleet-node-badge ${online?'online':'offline'}">${online?'● EN LIGNE':'○ HORS LIGNE'}</span>
                </div>
                ${!isLocal?`<div class="fleet-node-url">${escapeHtml(n.url||'')}</div>`:''}
                ${extraHtml}${metricsHtml}${actionsHtml}
            </div>`;
        }).join('');
    } catch(e){ grid.innerHTML=`<div style="color:var(--danger);padding:20px">❌ Erreur: ${escapeHtml(e.message)}</div>`; }
}

// D11 (lot 7) : Aujourd'hui si le bureau a une boîte ou quelque chose à faire ; sinon Aujourd'hui
// quand même (administrateur) ou le Courrier. Une ouverture choisie dans Moi l'emporte.
async function buOuvertureDefaut(me){
    let pref = '';
    try{ pref = localStorage.getItem('cass_ouverture') || ''; }catch(e){}
    if(pref) return;                              // déjà appliquée au chargement
    let vivant = false;
    try{
        const c = await apiPost('/api/courrier/etat', {});
        vivant = !!(c && c.configuree);
        if(!vivant){
            const j = await apiPost('/api/bureau/jour', {});
            const t = (j && j.tuiles) || {};
            vivant = ((t.a_faire || 0) + (t.en_retard || 0) + (t.a_relire || 0)) > 0;
        }
    }catch(e){}
    try{
        if(vivant){ if(typeof buSeg === 'function') buSeg('today'); }
        else if(me && me.is_admin){ if(typeof buSeg === 'function') buSeg('today'); }      // 19-10 : « Aujourd'hui » ouvre le panneau, plus la Vue d'ensemble
        else { if(typeof buSeg === 'function') buSeg('mail'); }
    }catch(e){}
}
async function startApp(){
    try { sbInit(); } catch(e) {}
    const _me = await applyRoleGating();
    // Le nom lisible est posé AVANT le premier message : sans cela, les
    // premières bulles s'affichent « Vous » puis changent d'auteur en cours de
    // conversation, ce qui donne l'impression que quelqu'un d'autre a parlé.
    try { ETAT.moi._monNom = nomLisible(_me) || ''; } catch(e) {}
    const _isUser = (_me && !_me.is_admin);
    if (_isUser) {
        // Compte « user » : conversationnel. On laisse le reste de startApp câbler le chat ;
        // les chargements d'infra échoueront en 403 (silencieux) et leurs panneaux sont masqués.
        try { initParticles(); } catch(e) {}
        const chatEl = document.getElementById('chat-messages');
        if (chatEl) { chatEl.innerHTML=''; addMessage('<strong>CASSANDRA</strong><br><span style="color:var(--txt-faint);font-size:12px">Bonjour ! Pose-moi tes questions, gère tes domaines dans <b>Mes sites</b>, ou tes secrets dans <b>Mon Coffre Fort</b>.</span>', false); }
        // MON BUREAU EST LEUR ACCUEIL : c'est là que vit tout ce qui leur
        // appartient — conversations, courrier, notes, projets, agenda.
        try { switchTab('bureau'); buOuvertureDefaut(_me); } catch(e) {}
        // Le chat est déjà câblé globalement (listeners + onclick) — rien à initialiser de plus.
        return;
    }
    initCharts(); initParticles();
    // ON ARRIVE DANS MON BUREAU. La classe `active` posée dans le balisage
    // montre l'écran mais n'appelle pas son chargeur : sans cette ligne, la
    // page d'arrivée s'ouvrait vide. « Vue d'ensemble » reste à un clic, et
    // les relevés d'infrastructure sont chargés plus bas dans `startApp` —
    // le bandeau et les alertes ne dépendent donc pas de l'onglet ouvert.
    try { switchTab('bureau'); buOuvertureDefaut(_me); } catch(e) {}
    // Le portrait et le choix d'apparence sont posés au démarrage : le premier
    // n'apparaissait qu'après avoir déplié le menu.
    try { remplirCompte(); umSegments(); } catch(e) {}
    try { if(sessionStorage.getItem('cass_verrou')==='1') umVerrouiller(); } catch(e) {}
    // L'état des bulles est restauré depuis la mémoire du navigateur ; leur
    // action est déclarée en HTML, il n'y a plus rien à brancher ici.
    _cbEtat('cb-expert', expertMode);
    // Message de bienvenue
    const chatEl=document.getElementById('chat-messages');
    chatEl.innerHTML='';
    addMessage('<strong>CASSANDRA</strong> — Agent IA souveraine<br><span style="color:var(--txt-faint);font-size:12px">Je suis fraîche, dispo, et sous-caféinée. Commande-moi une mission.</span>', false);
    // [EVO5] Chargement initial HTTP (données déjà dispo) puis bascule WebSocket
    // AU DÉMARRAGE, UNE SEULE LECTURE : la cloche (21-09, fil 30). Les treize cartes du tiroir système et
    // leurs huit minuteurs se chargent à l'ouverture du tiroir (`_sysCharger`) ; la Vue d'ensemble se lit
    // par /api/vue quand on l'ouvre ; le résumé du panneau se relit dans son onglet.
    await Promise.allSettled([loadAlerts()]);
    setInterval(function(){ if (document.getElementById('tab-fastpanel') && document.getElementById('tab-fastpanel').classList.contains('active')) fpLoadSummary(); }, 120000);
    // `checkServicesStatus`, `restartService` et `loadServerInfo` étaient appelées ici sans
    // exister nulle part : la ReferenceError coupait `startApp` avant le WebSocket. Parties.
    // La cloche est poussée par le serveur (trame `notif`) ; cette relecture est un
    // filet, toutes les cinq minutes, pour un WebSocket qui ne passe pas (B27).
    setInterval(loadAlerts, 300000);
    // Badge proactivité : lu au départ, puis à chaque trame `notif` de la proactivité.
    pfPollBadge();
    // Le décompte des tâches muettes est calculé sans ouvrir l'onglet : sinon
    // seule une visite délibérée révélerait une panne qui, elle, est silencieuse.
    cronPollBadge(); setInterval(cronPollBadge, 300000);
    // Collage d'image (Ctrl+V) dans le chat
    _initImagePaste();
    // [EVO5] WebSocket — remplace le polling metrics (1s), processes (2s), sessions (2s),
    //        dashboard (10s), alerts (30s) par un flux push temps-réel
    _initWebSocket();
}

// ── WebSocket client [EVO5] ───────────────────────────────────────────────────
let _ws = null;
let _wsReconnectDelay = 1000;
let _wsFallbackTimer  = null;

function _initWebSocket(){
    const proto = location.protocol === 'https:' ? 'wss' : 'ws';
    const url   = `${proto}://${location.host}/ws?token=${encodeURIComponent(sessionId)}`;
    try {
        _ws = new WebSocket(url);
        _ws.onopen = () => {
            console.log('[WS] Connecté — polling désactivé');
            _wsReconnectDelay = 1000;
            // Annuler le fallback polling si actif
            if(_wsFallbackTimer){ clearInterval(_wsFallbackTimer); _wsFallbackTimer = null; }
            // Indicateur visuel (titre)
            _titreMaj('Cassandra ⚡ Online');
        };
        _ws.onmessage = (evt) => {
            try {
                const msg = JSON.parse(evt.data);
                if(msg.type === 'autonomous_evolution'){
                    _applyAutoEvolution(msg);
                } else if(msg.type === 'metrics'){
                    // Métriques temps-réel
                    if(msg.metrics)  _applyMetrics(msg.metrics);
                    // Health score
                    if(msg.health)   _applyHealth(msg.health);
                } else if(msg.type === 'notif'){
                    // La notification elle-même, et les compteurs de MON compte : on range, on ne relit pas.
                    ntRecevoir(msg);
                } else if(msg.type === 'courrier'){
                    // LOT 3 : la passe a relu ma boîte ; le badge et l'aperçu se rangent sans appel.
                    if(typeof buCourrierRecevoir === 'function') buCourrierRecevoir(msg);
                } else if(msg.type === 'bureau'){
                    // LOT 4 : la passe a recalculé mon Aujourd'hui ; l'écran ouvert se range.
                    if(typeof bjRecevoir === 'function') bjRecevoir(msg);
                } else if(msg.type === 'salon'){
                    // LOT 2 : un message posté, un résident qui écrit — le salon se range sans sonder.
                    if(typeof slEvenement === 'function') slEvenement(msg);
                } else if(msg.type === 'vie'){
                    // battement des comptes non admin : le socket vit, rien à faire
                }
            } catch(e){}
        };
        _ws.onerror = () => {};
        _ws.onclose = () => {
            _titreMaj('Cassandra (reconnexion...)');
            console.log(`[WS] Déconnecté — retry dans ${_wsReconnectDelay}ms`);
            // Fallback polling pendant la reconnexion
            if(!_wsFallbackTimer){
                _wsFallbackTimer = setInterval(()=>{ loadMetrics(); loadProcesses(); }, 3000);
            }
            setTimeout(_initWebSocket, _wsReconnectDelay);
            _wsReconnectDelay = Math.min(_wsReconnectDelay * 2, 30000);
        };
    } catch(e){
        // Browser ne supporte pas WS → polling classique
        setInterval(loadMetrics,   1000);
        setInterval(loadProcesses, 2000);
        setInterval(loadDashboard, 10000);
        setInterval(loadAlerts,    60000);
    }
}

// Applique un objet métriques reçu par WS (même structure que /api/metrics)
function _applyMetrics(m){
    if(!m) return;
    // LE CHEMIN RÉPARÉ (21-09) : cette fonction écrivait dans `cpu-pct`, `cpu-arc`… qui n'existent pas, et lisait
    // `cpu_pct` alors que la trame porte `cpu` — le bandeau n'était à jour que quand la WebSocket était morte.
    try {
        const cpu  = Math.round(m.cpu ?? m.cpu_pct ?? 0);
        const ram  = Math.round(m.ram ?? m.ram_pct ?? 0);
        const disk = Math.round(m.disk ?? m.disk_pct ?? 0);
        VU.wsTs = Date.now();
        majVitals(cpu, ram, disk, m.load_1m);
        // les cartes du tiroir, si elles sont posées
        const cv=document.getElementById('cpu-val'); if(cv){ cv.textContent=cpu+'%'; _colorStatVal('cpu-val',cpu); }
        const rv=document.getElementById('ram-val'); if(rv){ rv.textContent=ram+'%'; _colorStatVal('ram-val',ram); }
        const dv=document.getElementById('disk-val'); if(dv){ dv.textContent=disk+'%'; _colorStatVal('disk-val',disk); }
        _setStatBar('cpu-bar',cpu); _setStatBar('ram-bar',ram); _setStatBar('disk-bar',disk);
        const lv=document.getElementById('load-val'); if(lv && m.load_1m!==undefined) lv.textContent=(m.load_1m||0)+' '+(m.load_5m||0)+' '+(m.load_15m||0);
        _setMmsVal('mms-cpu',cpu+'%',cpu); _setMmsVal('mms-ram',ram+'%',ram); _setMmsVal('mms-disk',disk+'%',disk);
        if(m.top_processes) _applyProcesses(typeof m.top_processes==='string' ? JSON.parse(m.top_processes) : m.top_processes);
    } catch(e){}
}

function _applyAutoEvolution(msg){
    if(!msg) return;
    // Toast de notification
    const icon = msg.status === 'applied' ? '🧬' : '⚠️';
    const txt  = icon + ' Evolution autonome — ' + escapeHtml(msg.description||'');
    showToast(txt, msg.status === 'applied' ? 'success' : 'warning', 6000);
    // La cloche : le serveur pousse la ligne « évolution » lui-même (trame notif) ; le compteur vient de lui.
    // Ajouter en tête de liste dans l'onglet Evolution (si ouvert)
    const list = document.getElementById('evo-history-list');
    if(list){
        const item = document.createElement('div');
        item.style.cssText='border:1px solid rgba(0,255,204,.25);border-radius:8px;padding:10px 12px;margin-bottom:8px;animation:msgIn .3s ease';
        item.innerHTML = '<div style="display:flex;justify-content:space-between">'
            +'<span style="font-size:10px;color:var(--txt-ghost)">#'+escapeHtml(String(msg.evo_id||'?'))+' '+(msg.ts||'').substring(0,16)+'</span>'
            +'<span class="evo-auto-badge">AUTO</span></div>'
            +'<div style="font-size:12px;color:var(--txt);margin-top:3px">'+escapeHtml(msg.description||'')+'</div>'
            +'<div style="font-size:10px;color:var(--txt-faint);font-style:italic">'+escapeHtml(msg.motivation||'')+'</div>';
        list.insertBefore(item, list.firstChild);
    }
}
function _applyHealth(h){
    if(!h) return;
    const s = h.score ?? 0;
    const cls = s>=90?'excellent':s>=75?'good':s>=50?'warning':'critical';
    const color = s>=90?'var(--ok)':s>=75?'var(--accent)':s>=50?'var(--orange)':'var(--red)';
    // Score text inside ring
    const el = document.getElementById('health-score');
    if(el){ el.textContent = s; el.style.color = color; }
    // la Vue d'ensemble : le compteur « Santé » suit la trame (21-09)
    try{ const vk=[...document.querySelectorAll('#vu-kpis .mx-kpi')].find(k=>(k.querySelector('span')||{}).textContent==='Santé'); if(vk){ const b=vk.querySelector('b'); if(b){ b.textContent=s; b.className = s<50?'bad':(s<75?'avert':''); } } const sa=document.getElementById('vu-sante-age'); if(sa) sa.textContent='santé · WebSocket'; }catch(e){}
    // Animate conic ring
    const ring = document.getElementById('health-ring');
    if(ring){
        const deg = Math.round((Math.min(s,100)/100)*360);
        ring.style.background = `conic-gradient(${color} ${deg}deg, var(--ov-06) ${deg}deg)`;
    }
    // Status pill
    const st = document.getElementById('health-status');
    if(st){
        const label = h.status || (s>=90?'Excellent':s>=75?'Bon':s>=50?'Warning':'Critique');
        st.innerHTML = `<span class="status-pill ${cls}">${label}</span>`;
    }
    // Details
    const dt = document.getElementById('health-details');
    if(dt){
        const parts=[];
        if(h.breakdown?.ssl)          parts.push(`SSL ${h.breakdown.ssl}pts`);
        if(h.breakdown?.oom)          parts.push(`OOM ${h.breakdown.oom}pts`);
        if(h.breakdown?.failed_units) parts.push(`Failed ${h.breakdown.failed_units}pts`);
        // la flotte, toujours dite : un 100 sans détail ne prouvait rien
        const fl = h.breakdown?.flotte;
        if(fl){ const p=[]; if((fl.en_ligne||[]).length) p.push(`${fl.en_ligne.length} en ligne`);
            if((fl.hors_ligne||[]).length) p.push(`${fl.hors_ligne.length} HORS LIGNE (${fl.hors_ligne.join(', ')}) ${fl.malus||0}pts`);
            if((fl.intermittentes_hors_ligne||[]).length) p.push(`${fl.intermittentes_hors_ligne.length} intermittente(s) absente(s)`);
            if((fl.retirees||[]).length) p.push(`${fl.retirees.length} retirée(s)`);
            if(p.length) parts.push('Flotte : '+p.join(', ')); }
        if(h.breakdown && parts.length) dt.textContent = parts.join(' · ');
        else if(h.sites !== undefined) dt.textContent = `${h.sites||0} sites · ${h.ssl_expiring||0} SSL`;
    }
    // Mobile strip
    _setMmsVal('mms-health', s+'', s);
    // Drawer ring clone
    const mmdRing=document.getElementById('mmd-health-ring');
    if(mmdRing){
        const deg=Math.round((Math.min(s,100)/100)*360);
        mmdRing.style.background=`conic-gradient(${color} ${deg}deg,var(--ov-06) ${deg}deg)`;
        const sc=document.getElementById('mmd-health-score');
        if(sc){sc.textContent=s;sc.style.color=color;}
    }
    const mmdSt=document.getElementById('mmd-health-status');
    if(mmdSt){
        const label=h.status||(s>=90?'Excellent':s>=75?'Bon':s>=50?'Warning':'Critique');
        mmdSt.innerHTML=`<span class="status-pill ${cls}">${label}</span>`;
    }
    const mmdDt=document.getElementById('mmd-health-details');
    if(mmdDt&&dt) mmdDt.textContent=dt.textContent;
}

function _applyProcesses(procs){
    if(!Array.isArray(procs)) return;
    const html = procs.slice(0,8).map(p=>{
        const cpu = parseFloat(p.cpu_pct||p.cpu||0);
        const color = cpu>50?'var(--red)':cpu>20?'var(--orange)':'var(--accent)';
        return `<div class="proc-row">
            <span class="proc-name">${escapeHtml(p.name||p.comm||'?')}</span>
            <div class="proc-bar-wrap"><div class="proc-bar-fill" style="width:${Math.min(cpu,100)}%;background:${color}"></div></div>
            <span class="proc-pct" style="color:${color}">${cpu.toFixed(1)}%</span>
        </div>`;
    }).join('');
    const el=document.getElementById('processes-list'); if(el) el.innerHTML=html;
    const mmd=document.getElementById('mmd-procs');    if(mmd) mmd.innerHTML=html;
}

