// Une taille s'affiche dans l'unité qui la rend lisible. Diviser toujours par
// 1024 donnait « 0.0 GB » pour 4 Mo de bases : un chiffre qui passe pour une
// panne de collecte alors que la mesure était juste.
function fpTaille(mo){
    const v = parseFloat(mo);
    if (!isFinite(v) || v <= 0) return '0 Mo';
    if (v < 1)      return (v*1024).toFixed(0) + ' Ko';
    if (v < 1024)   return (v < 10 ? v.toFixed(1) : v.toFixed(0)) + ' Mo';
    if (v < 1048576) return (v/1024).toFixed(v < 10240 ? 1 : 0) + ' Go';
    return (v/1048576).toFixed(2) + ' To';
}

