// Le résumé peut manquer de trois façons : réseau ou HTTP (exception),
// source FastPanel injoignable (`{ok:false, reason}`), ou chiffres rendus avec
// un `source_erreur` (une partie manque). Le catch vide d'avant laissait des
// badges « – » : rien ne distinguait « pas encore lu » de « injoignable ».
// L'état s'écrit aux deux endroits qui montrent le résumé. (2026-09-05)
function _fpEtatSommaire(msg, niveau) {
    const coul = niveau === 'warn' ? 'var(--warn)' : 'var(--danger)';
    ['fp-side-etat', 'fp-summary-etat'].forEach(id => {
        const el = document.getElementById(id);
        if (!el) return;
        if (!msg) { el.style.display = 'none'; el.textContent = ''; return; }
        el.style.display = '';
        el.style.color = coul;
        el.textContent = msg;
    });
    if (msg) document.querySelectorAll('#fp-nav .mx-st').forEach(b => {
        b.title = msg;
        if (b.textContent === '–') b.textContent = '?';
    });
}

// Vrai si l'un des deux écrans qui affichent le résumé est à l'écran :
// l'onglet FastPanel, ou la Vue d'ensemble qui porte sa carte.
function fpSommaireVisible() {
    return ['tab-fastpanel', 'tab-overview'].some(id => {
        const el = document.getElementById(id);
        return !!(el && el.classList.contains('active'));
    });
}

async function fpLoadSummary() {
    let d;
    try {
        d = await apiGet('/api/fp/summary');
    } catch(e) {
        _fpEtatSommaire('Résumé indisponible : ' + ((e && e.message) || 'erreur réseau'), 'crit');
        return;
    }
    if (!d || typeof d !== 'object') {
        _fpEtatSommaire('Résumé indisponible : réponse vide', 'crit');
        return;
    }
    if (d.ok === false) {
        _fpEtatSommaire('Source injoignable : ' + (d.reason || 'raison inconnue'), 'crit');
        return;
    }
    // Pas d'exception à partir d'ici : un identifiant absent est une faute
    // d'écran, pas une panne de source. On laisse remonter à la console.
    _fpEtatSommaire((d.source_erreur && !(_fp2Panneau && _fp2Panneau.nom === 'nu')) ? 'Source partielle : ' + d.source_erreur : '', 'warn');
    _fp2Lu.summary = Date.now(); fp2Bandeau(d);
    { const _pp = document.getElementById('fp2-panneau'); if (_pp) { _pp.className = 'fp2-panneau ' + (d.source_erreur ? 'hs' : 'ok'); _pp.title = d.source_erreur || 'résumé lu, base du panneau joignable'; } }
    // Cartes de synthèse du tiroir « Détails système »
    const card = document.getElementById('fp-summary-card');
    if (card) card.style.display = '';
    const fpTabBtn = document.getElementById('tab-fp-btn');
    if (fpTabBtn) fpTabBtn.style.display = '';
    document.getElementById('fps-domains').textContent  = d.domains_count  || 0;
    document.getElementById('fps-dbs').textContent      = d.databases_count || 0;
    document.getElementById('fps-mail').textContent     = d.mail_count      || 0;
    document.getElementById('fps-users').textContent    = d.users_count     || 0;
    const svcs = d.services_down || 0;
    const svcEl = document.getElementById('fps-services');
    svcEl.textContent = svcs === 0 ? '✓ OK' : svcs + ' ↓';
    svcEl.parentElement.className = 'fp-sc ' + (svcs > 0 ? 'crit' : 'ok');
    document.getElementById('fps-services-sub').textContent = svcs > 0 ? svcs + ' service(s) down' : 'Tous actifs';
    const bkFail  = d.backups_failed || 0;
    const bkTotal = d.backups_count  ?? -1;   // -1 = ancienne version sans ce champ
    const bkEl    = document.getElementById('fps-backups');
    const bkSub   = document.getElementById('fps-backups-sub');
    if (bkTotal === 0) {
        bkEl.textContent = '–';
        bkEl.parentElement.className = 'fp-sc';
        bkSub.textContent = 'Aucun configuré';
    } else if (bkFail === 0) {
        bkEl.textContent = '✓ OK';
        bkEl.parentElement.className = 'fp-sc ok';
        bkSub.textContent = '';
    } else {
        bkEl.textContent = bkFail + ' ✗';
        bkEl.parentElement.className = 'fp-sc crit';
        bkSub.textContent = bkFail + ' backup(s) en erreur';
    }
    // Badges sidebar
    document.getElementById('fpbadge-domains').textContent   = d.domains_count  || 0;
    document.getElementById('fpbadge-users').textContent     = d.users_count    || 0;
    document.getElementById('fpbadge-databases').textContent = d.databases_count || 0;
    document.getElementById('fpbadge-mail').textContent      = d.mail_count     || 0;
    // Les comptes que le résumé porte depuis le 19-09 : un « – » ne disait pas « zéro », il disait « pas lu ».
    for (const [sec, cle] of [['ftp','ftp_count'],['dns','dns_count'],['crons','crons_count'],['scans','scans_count'],['php','php_count']]) {
        const b = document.getElementById('fpbadge-' + sec);
        if (b && d[cle] != null) b.textContent = d[cle];
    }
    // Services et backups : mis à jour DANS TOUS LES CAS. Avant, un badge
    // n'était touché que si > 0 : un service relevé gardait son « 2 ↓ »
    // rouge jusqu'au rechargement de la page. (2026-09-05)
    const bs = document.getElementById('fpbadge-services');
    if (bs) {
        // « 9/9 » plutôt que « 0 » : le compte des installés vient du résumé depuis le 19-09.
        if (svcs > 0) { bs.textContent = svcs + ' ↓'; bs.className = 'mx-st off'; }
        else          { bs.textContent = d.services_count != null ? d.services_count + '/' + d.services_count : '0'; bs.className = 'mx-st'; }
    }
    const bb = document.getElementById('fpbadge-backups');
    if (bb) {
        if (bkFail > 0) { bb.textContent = bkFail + ' ✗'; bb.className = 'mx-st off'; }
        else if (bkTotal === 0) { bb.textContent = 'aucune'; bb.className = 'mx-st off'; }
        else            { bb.textContent = String(bkTotal); bb.className = 'mx-st'; }
    }
}

// Le drapeau `_fpInited` ne chargeait la section qu'à la PREMIÈRE ouverture :
// revenir sur l'onglet une heure plus tard montrait la liste d'alors, sans
// rien qui le dise. On recharge la section courante à chaque ouverture ; le
// drapeau reste posé pour qui le lirait encore. (2026-09-05)
// LE DOS COURANT ET SES CAPACITÉS (V18 générique) : le sous-titre, la pastille et le rail se
// dessinent depuis le registre, jamais depuis un nom de panneau gravé dans l'écran.
let _fp2Panneau = null;
const FP2_CAPACITE = {domains:'sites', users:'comptes', databases:'bases', mail:'mail', ftp:'ftp', dns:'dns',
                      backups:'sauvegardes', crons:'crons', php:'php', services:'services', ssl:'ssl', scans:'scans'};
function fp2SectionOff(section){
    const p = _fp2Panneau; if (!p) return '';
    if (section === 'stats') return p.nom === 'fastpanel' ? '' : 'statistiques propres au panneau';
    const cap = FP2_CAPACITE[section]; if (!cap) return '';
    return (p.capacites || []).includes(cap) ? '' : ('capacité « ' + cap + ' » non prise en charge');
}
function fp2AppliquerCapacites(){
    const p = _fp2Panneau; if (!p) return;
    const sous = document.getElementById('fp2-sous');
    if (sous) sous.textContent = p.nom === 'nu'
        ? "Aucun panneau détecté : ce que l'hôte sait dire par lui-même (nginx, comptes, MySQL, systemd, certbot), et ce qui demande un geste."
        : (p.pris_en_charge ? 'Ce que ' + p.libelle + ' porte — sites, certificats, bases, courrier, services — lu dans sa base, et ce qui demande un geste.'
                            : p.libelle + " · version allégée : ce que l'hôte sait dire par lui-même.");
    const past = document.getElementById('fp2-panneau');
    if (past) { past.innerHTML = '<i></i>' + escapeHtml(p.nom === 'nu' ? 'aucun panneau' : p.nom);
                past.className = 'fp2-panneau' + ((p.nom === 'nu' || !p.pris_en_charge) ? ' hs' : '');
                past.title = p.libelle; }
    Object.keys(FP_SECTIONS).forEach(s => {
        const b = document.getElementById('fpnav-' + s); if (!b) return;
        const off = fp2SectionOff(s);
        b.classList.toggle('fp2-off', !!off);
        b.title = off ? (off + ' par le dos courant (' + p.libelle + ') — Réglages › Modules') : '';
    });
}
async function fp2Panneau(){
    try { const d = await apiGet('/api/modules'); if (d && d.panneau) { _fp2Panneau = d.panneau; fp2AppliquerCapacites(); } }
    catch(e) { /* un compte non administrateur ne lit pas le registre : l'écran garde ses libellés */ }
}
async function fpInit() {
    _fpInited = true;
    fp2RailMarquer();
    await fp2Panneau();
    fp2Vigilances();
    await fpLoadSection(_fpSection);
}
function fp2RailMarquer(){
    document.querySelectorAll('#fp-nav .mx-item').forEach(el => {
        const on = el.id === 'fpnav-' + _fpSection;
        el.classList.toggle('on', on);
        if (on) el.setAttribute('aria-current', 'page'); else el.removeAttribute('aria-current');
    });
}
// LE LIEN PROFOND (20-09) : ouvrir la fiche d'un domaine précis. `fp2Ouvrir` indexe un tableau et
// `fpNav` ferme la fiche : la demande est retenue et servie une fois la section rendue.
let _fpDemande = null;
function fpVersSite(domain, section) {
    _fpDemande = { section: section || 'domains', domain: String(domain || '').toLowerCase().replace(/^www\./, '') };
    switchTab('fastpanel');
    setTimeout(() => fpNav(_fpDemande ? _fpDemande.section : 'domains'), 120);
}
function fpNav(section) {
    _fpSection = section;
    fp2RailMarquer();
    fp2FicheFermer();
    const m = document.getElementById('fp-main-area'); if (m) m.scrollTop = 0;
    const i = document.getElementById('fp-rech'); if (i && i.value) i.value = '';
    fpLoadSection(section);
}

function fpRenderValue(key, val, row) {
    // « Dernier dump » vide n'est pas une donnée manquante : c'est un fait, et
    // un fait qui compte. Le dire plutôt que d'afficher un tiret muet.
    if (key === 'dump_at' && !val)
        return '<span style="color:var(--warn)" title="Aucune sauvegarde de cette base">jamais</span>';
    // Une base rattachée à aucun site est souvent un reste d'installation.
    if (key === 'site' && !val)
        return '<span style="color:var(--warn)" title="Aucun site ne déclare cette base">orpheline</span>';
    if (val === null || val === undefined || val === '') return '<span style="color:var(--txt-ghost)">–</span>';
    const s = String(val);
    // Le site rattaché mène à sa fiche : c'est le pont entre les deux onglets.
    if (key === 'site')
        return `<span onclick="event.stopPropagation();switchTab('mysites');setTimeout(()=>stOpen('${escapeAttr(s)}'),80)"
                 style="color:var(--info);cursor:pointer" title="Ouvrir la fiche du site">${escapeHtml(s)} ↗</span>`;
    if (key === 'size_mb' || key === 'files_mb' || key === 'db_mb')
        return escapeHtml(fpTaille(val));
    if (key === 'disk_quota_gb') return escapeHtml(fpTaille(parseFloat(val)*1024));
    if (key === 'ssh_access')
        return val == 1 ? '<span class="fp-badge warn" title="Ce compte peut ouvrir une session SSH">SSH</span>'
                        : '<span class="fp-badge inactive">non</span>';
    if (key === 'error_count') {
        const n = parseInt(val) || 0;
        return n === 0 ? '<span class="fp-badge ok">0</span>'
                       : `<span class="fp-badge ${n>50?'crit':'warn'}">${n}</span>`;
    }
    if (key === 'dump_at') {
        const j = Math.floor((Date.now() - Date.parse(s.replace(' ','T'))) / 86400000);
        // FastPanel est écrit en Go : une date jamais renseignée vaut
        // 0001-01-01, ce qui donnait « il y a 739834 j ». Ce n'est pas une
        // sauvegarde très ancienne, c'est l'absence de sauvegarde.
        if (!isFinite(j) || j > 3650)
            return '<span class="fp-badge crit" title="Aucune sauvegarde de cette base">jamais</span>';
        const cls = j > 30 ? 'crit' : j > 7 ? 'warn' : 'ok';
        return `<span class="fp-badge ${cls}" title="${escapeAttr(s)}">il y a ${j} j</span>`;
    }
    // SSL status
    if (key === 'ssl_enabled') return val == 1 ? '<span class="fp-badge active">SSL ✓</span>' : '<span class="fp-badge inactive">non-SSL</span>';
    if (key === 'ssl_days_left') {
        // Trois cas distincts, qu'on confondait en un seul « Expiré » :
        // pas de certificat, certificat expiré, certificat valide. Un site sans
        // date exploitable n'est pas un site dont le certificat a expiré.
        const n = parseFloat(val);
        if (val === null || val === undefined || val === '' || !isFinite(n))
            return '<span class="fp-badge" title="Aucune date d\'expiration exploitable">aucun certificat</span>';
        if (n < 0) return `<span class="fp-badge crit">EXPIRÉ depuis ${Math.abs(Math.round(n))} j</span>`;
        const cls = n <= 7 ? 'crit' : n <= 30 ? 'warn' : 'ok';
        return `<span class="fp-badge ${cls}">${Math.round(n)} j</span>`;
    }
    // Status badges
    if (key === 'status' || key === 'last_status') {
        const cls = ['active','running','ok','success','connected'].includes(s.toLowerCase()) ? 'active'
                  : ['error','failed','expired','critical'].includes(s.toLowerCase()) ? 'crit'
                  : ['expiring','warning','inactive'].includes(s.toLowerCase()) ? 'warn' : 'inactive';
        return `<span class="fp-badge ${cls}">${escapeHtml(s)}</span>`;
    }
    // Active (bool)
    if (key === 'active' || key === 'enabled') return val == 1 || val === true ? '<span class="fp-badge active">Oui</span>' : '<span class="fp-badge inactive">Non</span>';
    // PHP version pill
    if (key === 'php_version' && val && val !== 'unknown') return `<span class="fp-pill php">PHP ${escapeHtml(s)}</span>`;
    // Disk usage with bar
    if ((key === 'disk_used_gb' || key === 'used_mb') && row) {
        const used  = parseFloat(val) || 0;
        const quota = parseFloat(row.disk_quota_gb || row.quota_mb || 0);
        // `used_mb` est en Mo : l'afficher suivi de « GB » faisait lire
        // 250 Go pour 250 Mo de boîte mail. fpTaille choisit l'unité ; les
        // Go des comptes passent en Mo pour lui. (2026-09-05)
        const txt = key === 'used_mb' ? fpTaille(used) : fpTaille(used * 1024);
        if (quota > 0) {
            const pct  = Math.min(100, Math.round(used / quota * 100));
            const col  = pct > 85 ? 'var(--danger)' : pct > 70 ? 'var(--warn)' : 'var(--ok)';
            return `<span style="color:${col}">${escapeHtml(txt)}</span>
                    <div class="fp-disk-bar"><div class="fp-disk-bar-fill" style="width:${pct}%;background:${col}"></div></div>`;
        }
        return `<span>${escapeHtml(txt)}</span>`;
    }
    if (key === 'size_mb') return `<span>${parseFloat(val).toFixed(0)} MB</span>`;
    if (key === 'disk_quota_gb') return `<span style="color:var(--txt-faint)">${parseFloat(val).toFixed(1)} GB</span>`;
    if (key === 'disk_used_gb')  return `<span>${parseFloat(val).toFixed(2)} GB</span>`;
    if (key === 'quota_mb') return `<span style="color:var(--txt-faint)">${escapeHtml(fpTaille(val))}</span>`;
    // Truncate long strings
    const maxlen = { command: 40, error: 35, path: 38, value: 38, home_dir: 35 };
    const max = maxlen[key] || 60;
    const display = s.length > max ? s.substring(0, max) + '…' : s;
    return escapeHtml(display);
}

function fpBuildAnalyzeMsg(section, row) {
    const name = row.domain || row.username || row.name || row.email || row.login || row.zone || row.service || '?';
    const msgs = {
        domains:   `Analyse le domaine FastPanel "${name}" : PHP ${row.php_version||'?'}, SSL ${row.ssl_days_left||0} jours`,
        users:     `Analyse l'utilisateur FastPanel "${name}" : ${row.disk_used_gb||0} GB utilisés sur ${row.disk_quota_gb||0} GB`,
        databases: `Analyse la base de données "${name}" (${row.size_mb||0} MB, user: ${row.db_user||'?'})`,
        mail:      `Analyse le compte mail "${name}" : ${row.used_mb||0}/${row.quota_mb||0} MB utilisés`,
        backups:   `Analyse le backup FastPanel : type "${row.type||'?'}", statut "${row.status||'?'}", ${row.size_mb||0} MB`,
        services:  `Analyse le service FastPanel "${name}" (statut: ${row.status||'?'})`,
        dns:       `Analyse l'enregistrement DNS : ${row.type||'?'} ${name} → ${row.value||'?'}`,
        crons:     `Analyse le cron FastPanel de "${row.user||'root'}" : ${row.schedule||'?'} → ${(row.command||'').substring(0,60)}`,
        ftp:       `Analyse le compte FTP "${name}" (répertoire: ${row.home_dir||'?'})`,
        php:       `Analyse la version PHP ${name} installée sur le serveur`,
    };
    return msgs[section] || `Analyse FastPanel : ${JSON.stringify(row)}`;
}

async function fpLoadSection(section) {
    const offRaison = fp2SectionOff(section);
    const main = document.getElementById('fp-main-area'); if (!main) return;
    const titre = (FP2[section] || {}).titre || section;
    if (offRaison) {
        main.innerHTML = `<section class="mx-sec"><div class="mx-chart-h"><h2>${escapeHtml(titre)}</h2></div>` + fp2Etat('repli', 'Non pris en charge par le dos courant',
            offRaison + ' (' + ((_fp2Panneau || {}).libelle || 'aucun panneau') + '). Un panneau d\'hébergement reconnu la porterait ; voir Réglages › Modules.') + '</section>';
        fp2Point(section, 'vide');
        return;
    }
    if (section === 'stats') { fpLoadStats(); return; }
    if (section === 'vue') { fp2Vue(); return; }
    if (section === 'ops') { fp2Ops(); return; }
    if (!FP_SECTIONS[section]) return;
    main.innerHTML = `<section class="mx-sec"><div class="mx-attente">Lecture — ${escapeHtml(titre)}…</div></section>`;
    const r = await fp2Charger(section);
    if (_fpSection !== section || !r) return;
    // Vide et injoignable n'ont pas la même page : le serveur rend `{ok:false, reason}` quand la source
    // ne répond pas, une liste sinon, parfois dans un objet portant `source_erreur` (2026-09-05).
    if (r.hs) {
        main.innerHTML = `<section class="mx-sec"><div class="mx-chart-h"><h2>${escapeHtml(titre)}</h2></div>` + fp2Etat('hs', 'Source injoignable', r.hs) + '</section>';
        const badge = document.getElementById('fpbadge-' + section); if (badge) { badge.textContent = '?'; badge.title = r.hs; }
        fp2Point(section, 'vide');
        return;
    }
    if (r.erreur) { main.innerHTML = `<section class="mx-sec"><div class="mx-chart-h"><h2>${escapeHtml(titre)}</h2></div><div class="mx-silence">Erreur de chargement : ${escapeHtml(r.erreur)}</div></section>`; return; }
    fpRenderSection(section);
    if (_fpDemande && _fpDemande.section === section) {
        const dm = _fpDemande.domain; _fpDemande = null;
        const idx = (_fpData[section] || []).findIndex(r => String(r.domain || '').toLowerCase().replace(/^www\./, '') === dm);
        if (idx >= 0) fp2Ouvrir(section, idx);
    }
}

// Actions par ligne. L'onglet ne proposait que « Analyser » : constater qu'un
// service est tombé sans pouvoir le relever obligeait à ouvrir un terminal.
function fpRowActions(section, row) {
    if (section === 'services') {
        const n = String(row.name || '').replace(/'/g, '');
        const actif = String(row.status || '').toLowerCase().indexOf('activ') === 0;
        return `<span onclick="event.stopPropagation();fpSvc('${n}','${actif ? 'restart' : 'start'}')"
                      class="fp-row-action" title="${actif ? 'Redémarrer' : 'Démarrer'}">${actif ? '⟳' : '▶'}</span>
                <span onclick="event.stopPropagation();fpSvc('${n}','stop')" class="fp-row-action" title="Arrêter">⏸</span>
                <span onclick="event.stopPropagation();fpSvcDiag('${n}')" class="fp-row-action" title="Diagnostiquer">🩺</span>`;
    }
    if (section === 'domains') {
        const d = String(row.domain || '').replace(/'/g, '');
        return `<span onclick="event.stopPropagation();fpSslCheck('${d}')" class="fp-row-action" title="Vérifier le certificat servi">🔒</span>
                <span onclick="event.stopPropagation();fpDomCtx('${d}')" class="fp-row-action" title="Projet, responsable, tâches, sauvegardes">🔗</span>`;
    }
    // Ces sections n'avaient AUCUNE action : elles ne servaient qu'à regarder.
    if (section === 'databases') {
        const n = escapeAttr(String(row.name || ''));
        const s = escapeAttr(String(row.site || ''));
        return (s ? `<span onclick="event.stopPropagation();switchTab('mysites');setTimeout(()=>stOpen('${s}'),80)"
                       class="fp-row-action" title="Ouvrir la fiche du site servi">🌐</span>` : '')
             + `<span onclick="event.stopPropagation();fpPhpMyAdmin('${n}')" class="fp-row-action"
                      title="Ouvrir cette base dans phpMyAdmin">🐬</span>`
             + `<span onclick="event.stopPropagation();fpDbDrop('${n}')" class="fp-row-action"
                      title="Supprimer cette base — irréversible">🗑</span>`;
    }
    if (section === 'backups') {
        return `<span onclick="event.stopPropagation();fpBackupPlans()" class="fp-row-action"
                      title="Plans de sauvegarde : lister, lancer, créer">▶</span>`;
    }
    if (section === 'crons') {
        const i = _fpData['crons'] ? _fpData['crons'].indexOf(row) : -1;
        return `<span onclick="event.stopPropagation();fpCronFiche(${i})" class="fp-row-action"
                      title="Fiche : lancer, activer, historique">⏱</span>`;
    }
    if (section === 'scans') {
        const d = escapeAttr(String(row.domain || ''));
        return (d ? `<span onclick="event.stopPropagation();fpScanRun('${d}')"
                       class="fp-row-action" title="Relancer l'analyse de ce site">🛡</span>` : '')
             + (d ? `<span onclick="event.stopPropagation();fpRapports('${d}')"
                          class="fp-row-action" title="Lire les rapports de ce site">📄</span>` : '')
             + (d ? `<span onclick="event.stopPropagation();switchTab('mysites');setTimeout(()=>stOpen('${d}'),80)"
                          class="fp-row-action" title="Ouvrir la fiche du site">🌐</span>` : '');
    }
    if (section === 'users') {
        const u = escapeAttr(String(row.username || ''));
        return `<span onclick="event.stopPropagation();fpUserFiche('${u}')" class="fp-row-action"
                      title="Fiche du compte">👤</span>
                <span onclick="event.stopPropagation();fpUserSsh('${u}')" class="fp-row-action"
                      title="Clés SSH de ce compte">🔑</span>
                <span onclick="event.stopPropagation();fpVoir('domains','${u}')" class="fp-row-action"
                      title="Ses sites">🌐</span>
                <span onclick="event.stopPropagation();fpVoir('databases','${u}')" class="fp-row-action"
                      title="Ses bases de données">🗄</span>`;
    }
    if (section === 'ftp') {
        const s = escapeAttr(String(row.site || ''));
        return (s ? `<span onclick="event.stopPropagation();switchTab('mysites');setTimeout(()=>stOpen('${s}'),80)"
                       class="fp-row-action" title="Le site servi par ce compte">🌐</span>` : '')
             + `<span onclick="event.stopPropagation();fpRunAction('ftp_supprimer',['id'])"
                      class="fp-row-action" title="Supprimer ce compte FTP — irréversible">🗑</span>`;
    }
    if (section === 'mail' || section === 'dns') {
        const d = escapeAttr(String(row.domain || row.zone || ''));
        if (!d) return '';
        return `<span onclick="event.stopPropagation();switchTab('mysites');setTimeout(()=>stOpen('${d}'),80)"
                      class="fp-row-action" title="Ouvrir la fiche du site">🌐</span>
                <span onclick="event.stopPropagation();fpVoir('domains','${d}')" class="fp-row-action"
                      title="Ce domaine dans l'hébergement">🔎</span>`;
    }
    if (section === 'php') {
        const v = escapeAttr(String(row.version || ''));
        return `<span onclick="event.stopPropagation();fpVoir('domains','${v}')" class="fp-row-action"
                      title="Les sites qui utilisent cette version">🌐</span>`;
    }
    return '';
}

// Certaines sections ont une fiche : y envoyer le clic vaut mieux que de
// basculer sur le chat. Sur les crons, « Analyser » partait en conversation
// quel que soit l'endroit cliqué — la ligne n'offrait rien d'autre.
const FP_ROW_FICHE = {
    crons:  (row) => `fpCronFiche(${(_fpData['crons']||[]).indexOf(row)})`,
    users:  (row) => `fpUserFiche(${JSON.stringify(String(row.username||''))})`,
    scans:  (row) => `fpRapports(${JSON.stringify(String(row.domain||''))})`,
};

function fpRowHtml(section, row, cols) {
    const cells = cols.map(c => `<td>${fpRenderValue(c, row[c], row)}</td>`).join('');
    const msg = fpBuildAnalyzeMsg(section, row);
    const safeMsg = JSON.stringify(msg).replace(/"/g, '&quot;');
    const act = fpRowActions(section, row);
    const fiche = FP_ROW_FICHE[section];
    const clic = fiche ? escapeAttr(fiche(row)) : `sendQuickFix(${safeMsg})`;
    return `<tr onclick="${fiche ? clic : `sendQuickFix(${safeMsg})`}">${cells}
        <td style="white-space:nowrap">${act}
        <span class="fp-row-action" onclick="event.stopPropagation();sendQuickFix(${safeMsg})"
              title="Envoyer à Cassandra pour analyse">Analyser ↗</span></td></tr>`;
}


// ── Actions FastPanel ──────────────────────────────────────────────────────
// ═══ HÉBERGEMENT (le panneau), la refonte du 2026-09-05 — maquette validée par l'administrateur ═══
// Chaque chiffre porte sa provenance et son âge ; trois états distincts (vide prouvé,
// repli ou non prouvé, source injoignable) ; une fiche à droite ; chaque geste passe par
// une feuille de confirmation qui dit ce qui va s'écrire au journal. Les fonctions
// d'action existantes (fpSvc, fpScanRun, fpSslIssue, fpDbDrop, fpRunAction…) sont
// réutilisées telles quelles : c'est l'écran qui change, pas les gestes.
const FP2 = {
    vue:       { titre: "Vue d'ensemble",        src: 'base + API',                          prov: '' },
    domains:   { titre: 'Domaines',              src: 'base · site + site_stats',            prov: '' },
    php:       { titre: 'PHP',                   src: 'panneau · website_backends + collecteur', prov: 'repli' },
    ssl:       { titre: 'Certificats',           src: 'collecteur + sonde 443',              prov: '' },
    databases: { titre: 'Bases',                 src: 'base · database',                     prov: '' },
    backups:   { titre: 'Sauvegardes',           src: 'API · plans et journal',              prov: 'api' },
    mail:      { titre: 'Courrier',              src: 'base · mailbox',                      prov: '' },
    ftp:       { titre: 'FTP',                   src: 'base · ftp_user',                     prov: '' },
    dns:       { titre: 'DNS',                   src: 'base · domain',                       prov: '' },
    users:     { titre: 'Comptes du panneau',    src: 'base · panel_account',                prov: '' },
    services:  { titre: 'Services',              src: 'API · cache 120 s',                   prov: 'api' },
    crons:     { titre: 'Crons du panneau',      src: 'base · cron + crontab',               prov: '' },
    scans:     { titre: 'Analyses antivirus',    src: 'fichiers · ai-bolit',                 prov: '' },
    stats:     { titre: 'Statistiques',          src: 'API · statistiques du jour',          prov: 'api' },
};
let _fp2Lu = {};          // section -> horodatage de la dernière lecture réussie
let _fp2Sel = null;       // index de la ligne ouverte dans la fiche
let _fp2Audit = null;     // dernière réponse de /api/fp/audit
let _fp2Resume = null;    // dernière réponse de /api/fp/summary
let _fp2Journal = [];     // les gestes confirmés dans cette session (le journal complet est dans Journaux)
let _fp2Confirm = null;   // la promesse en cours de la feuille de confirmation

function fp2Heure(ts){ const t = ts ? new Date(ts) : new Date(); const p = n => String(n).padStart(2,'0'); return p(t.getHours())+':'+p(t.getMinutes())+':'+p(t.getSeconds()); }
function fp2Puce(txt, cls){ return `<span class="fp2-puce ${cls||'neutre'}">${escapeHtml(String(txt))}</span>`; }
function fp2Jauge(j){
    const n = parseFloat(j);
    if (j === null || j === undefined || j === '' || !isFinite(n)) return fp2Puce('non prouvé', 'avert');
    if (n < 0) return fp2Puce('expiré depuis ' + Math.abs(Math.round(n)) + ' j', 'erreur');
    const c = n > 30 ? 'ok' : (n > 7 ? 'avert' : 'erreur');
    return `<span class="fp2-jauge ${c}"><i style="width:${Math.min(100, n/90*100)}%"></i></span><span class="fp2-mono">${Math.round(n)} j</span>`;
}
function fp2Etat(kind, titre, texte){
    const cls = { vide: 'fp2-vide', hs: 'fp2-hs', repli: 'fp2-repli' }[kind] || 'fp2-vide';
    return `<div class="${cls}"><div><b>${escapeHtml(titre)}</b>${escapeHtml(texte)}</div></div>`;
}
function fp2Ligne(section, i, cellules){
    return `<tr class="l fp2-l ${_fp2Sel === i ? 'sel' : ''}" onclick="fp2Ouvrir('${section}',${i})">${cellules}</tr>`;
}
function fp2Site(d){ const s = String(d || '').replace(/'/g, ''); return s; }

// ── LE RELEVÉ : l'heure du résumé et l'état du panneau, dans la tête de la page ──
// (refonte du 19-09, maquette v1 : le bandeau de six tuiles a fondu dans le verdict de la vue d'ensemble ;
// le volet « Fiche » vide est devenu un panneau à droite, ouvert par un clic ; les gestes vivent là où ils
// répondent à un constat. Les fonctions d'action — fpSvc, fpScanRun, fpSslIssue, fpDbDrop, fpRunAction… —
// sont reprises telles quelles : c'est l'écran qui change, pas les gestes.)
function fp2Bandeau(d){
    _fp2Resume = d || _fp2Resume; d = _fp2Resume || {};
    const rel = document.getElementById('fp2-releve'); if (rel && _fp2Lu.summary) rel.textContent = fp2Heure(_fp2Lu.summary);
    if (d.source_erreur) { const p = document.getElementById('fp2-panneau'); if (p) { p.className = 'fp2-panneau hs'; p.title = d.source_erreur; } }
    if (_fpSection === 'vue') fp2Vue();
}
function fp2Pill(txt, cls){
    const m = { ok: 'ok', avert: 'regarder', erreur: 'panne', info: 'pas_encore', neutre: '' };
    return `<span class="mx-pill ${m[cls] || ''}">${escapeHtml(String(txt))}</span>`;
}
function fp2Point(section, etat){
    const e = document.getElementById('fpetat-' + section); if (!e) return;
    e.className = 'mx-dot ' + ({ ok: 'ok', avert: 'warn', erreur: 'danger', vide: '' }[etat] || '');
}
function fp2Jours(ts){ const t = Date.parse(String(ts || '').replace(' ', 'T')); return isFinite(t) ? Math.floor((Date.now() - t) / 86400000) : null; }
function fp2PhpTxt(s){
    const v = String(s.php_version || '').trim(), src = String(s.php_source || '');
    if (v) return 'PHP ' + v + (s.php_handler ? ' · ' + s.php_handler : '');
    if (/sans PHP/i.test(src)) return 'sans PHP · ' + (String(src).replace(/^.*\(|\)$/g, '').replace('_', ' ') || 'proxy');
    return 'PHP non lue';
}

// ── LES VIGILANCES : ce qui demande un geste, tiré de l'audit (sauvegardes, PHP, SSL) et du résumé (analyses) ──
let _fp2Vig = null;          // null tant que l'audit n'est pas lu ; sinon la liste — vide = rien à faire
let _fp2VigErreur = '';
async function fp2Vigilances(){
    let a;
    // La route n'existe qu'en POST (19-09) : en GET, « Failed to fetch », et les quatre signaux lisaient un audit vide.
    try { a = await apiPost('/api/fp/audit', {}); }
    catch(e) { _fp2Vig = null; _fp2VigErreur = 'audit indisponible : ' + (e.message || ''); if (_fpSection === 'vue') fp2Vue(); return; }
    if (!a || a.ok === false) { _fp2Vig = null; _fp2VigErreur = (a && a.reason) || 'audit refusé'; if (_fpSection === 'vue') fp2Vue(); return; }
    _fp2Audit = a; _fp2VigErreur = '';
    const L = [];
    const bk = a.backups || {};
    const dR = _fp2Resume || {}, planPret = (dR.backup_plans_count > 0 && dR.backups_count === 0), plan0 = (dR.backup_plans || [])[0] || {};
    if (planPret) L.push({ c: 'avert', t: `Le plan « ${plan0.name || '?'} » n’a encore rien copié (première exécution ${fpBackupQuand(plan0)}).`, s: 'backups', b: 'lancer maintenant', go: `fpBackupLancer('${escapeAttr(String(plan0.id ?? ''))}')` });
    else if ((bk.missing || []).length) L.push({ c: 'erreur', t: (bk.total && bk.missing.length === bk.total) ? `${bk.missing.length} site(s) sans sauvegarde, depuis toujours.` : `${bk.missing.length} site(s) sans sauvegarde depuis plus de ${bk.threshold_days || 7} jours.`, s: 'backups', b: 'créer un plan', go: 'fpBackupPlans()' });
    if ((bk.stale || []).length) L.push({ c: 'avert', t: `${bk.stale.length} sauvegarde(s) anciennes.`, s: 'backups', b: 'voir' });
    const ph = a.php || {};
    if ((ph.eol || []).length) L.push({ c: 'erreur', t: `${ph.eol.length} site(s) sur une version PHP en fin de vie.`, s: 'php', b: 'voir' });
    if ((ph.soon || []).length) L.push({ c: 'avert', t: `${ph.soon.length} site(s) sur une version PHP bientôt en fin de vie.`, s: 'php', b: 'voir' });
    const phInc = (ph.unknown || []).filter(x => !/sans PHP/i.test(String(x.source || '')));
    if (phInc.length) L.push({ c: 'avert', t: `Version PHP non lue pour ${phInc.length} site(s).`, s: 'php', b: 'voir' });
    const ss = a.ssl || {};
    if ((ss.missing || []).length) L.push({ c: 'erreur', t: `${ss.missing.length} domaine(s) sans certificat, constaté par la sonde.`, s: 'ssl', b: 'voir' });
    if ((ss.soon || []).length) L.push({ c: 'avert', t: `${ss.soon.length} certificat(s) proche(s) de l'échéance.`, s: 'ssl', b: 'voir' });
    if ((ss.inconnu || []).length) L.push({ c: 'avert', t: `${ss.inconnu.length} domaine(s) au certificat non prouvé.`, s: 'ssl', b: 'voir' });
    const rn = a.renew || {};
    if (rn.enabled === false || rn.disabled) L.push({ c: 'avert', t: (rn.certbot_timer === 'active') ? 'Renouvellement SSL : certbot.timer s’en charge ; la passe de Cassandra est éteinte.' : 'Rien ne renouvelle les certificats : aucun minuteur certbot, passe de Cassandra éteinte.', s: 'ssl', b: 'régler' });
    // La dernière analyse antivirus vient du résumé (19-09) : sept rapports du 7 août, et depuis, rien.
    const d = _fp2Resume || {}, js = d.scans_last ? fp2Jours(d.scans_last) : null;
    if (d.scans_count === 0 && (d.domains_count || 0)) L.push({ c: 'avert', t: 'Aucune analyse antivirus, jamais.', s: 'scans', b: 'lancer une analyse', go: 'fpScanPanel()' });
    else if (js != null && js > 30) L.push({ c: 'avert', t: `Dernière analyse antivirus il y a ${js} jours.`, s: 'scans', b: 'lancer une analyse', go: 'fpScanPanel()' });
    _fp2Vig = L;
    fp2Point('backups', planPret ? 'avert' : ((bk.missing || []).length ? 'erreur' : 'ok'));
    fp2Point('php', (ph.eol || []).length ? 'erreur' : (phInc.length ? 'avert' : 'ok'));
    fp2Point('ssl', (ss.missing || []).length ? 'erreur' : (((ss.soon || []).length || (ss.inconnu || []).length || rn.disabled) ? 'avert' : 'ok'));
    fp2Point('scans', (js != null && js > 30) || d.scans_count === 0 ? 'avert' : (d.scans_count ? 'ok' : 'vide'));
    // Le compte des certificats vient de l'audit : « 4/4 », le même chiffre partout.
    const bssl = document.getElementById('fpbadge-ssl');
    if (bssl && ss.total != null) bssl.textContent = (ss.ssl_active ?? '?') + '/' + ss.total;
    if (_fpSection === 'vue') fp2Vue();
}

async function fp2Relever(){
    const a = document.getElementById('fp2-age'); if (a) a.textContent = 'relevé…';
    try { await fpLoadSummary(); } catch(e) {}
    await fp2Vigilances();
    if (_fpSection && _fpSection !== 'vue') fpLoadSection(_fpSection); else fp2Vue();
}
// l'âge du relevé, en direct
setInterval(() => { const a = document.getElementById('fp2-age'); if (!a || !_fp2Lu.summary) return; a.textContent = 'il y a ' + Math.max(0, Math.round((Date.now() - _fp2Lu.summary)/1000)) + ' s'; }, 1000);

// ── LA CARTE D'UNE SECTION : le titre, la source et l'âge, les gestes de la section, puis le corps ──
function fp2Carte(section, corps, meta){
    const cfg = FP2[section] || { titre: section, src: '' };
    const lu = _fp2Lu[section];
    const q = JSON.stringify("Analyse l'ensemble des " + cfg.titre.toLowerCase() + " de l'hébergement et donne-moi un diagnostic : ce qui va, ce qui demande un geste.").replace(/"/g, '&quot;');
    const gestes = ({
        databases: `<button class="mx-btn" onclick="fpDbCreate()">Créer une base</button>`,
        scans:     `<button class="mx-btn primary" onclick="fpScanPanel()">Lancer une analyse</button><button class="mx-btn" onclick="fpRapports()">Rapports</button>`,
        backups:   `<button class="mx-btn primary" onclick="fpBackupPlans()">Plans de sauvegarde</button>`,
        users:     `<button class="mx-btn" onclick="fpLiens()">Liens Cassandra</button>`,
        services:  `<button class="mx-btn" onclick="fpWebsocket()">WebSocket</button>`,
    })[section] || '';
    return `<section class="mx-sec"><div class="mx-chart-h"><h2>${escapeHtml(cfg.titre)}</h2><span class="mx-meta">${meta ? escapeHtml(meta) + ' · ' : ''}${escapeHtml(cfg.src || '')}${lu ? ' · lu à ' + fp2Heure(lu) : ''}</span></div>
      <div class="mx-gest" style="justify-content:flex-start">${gestes}<button class="mx-btn" onclick="switchTab('dashboard');sendQuickFix(${q})">Analyser avec Cassandra</button><button class="mx-btn" onclick="fpLoadSection('${section}')">Relire</button></div>
      ${corps}</section>`;
}
function fp2Filtrer(q){
    q = (q || '').toLowerCase();
    document.querySelectorAll('#fp-main-area .fp2-l').forEach(el => { el.style.display = el.textContent.toLowerCase().includes(q) ? '' : 'none'; });
}
function fp2Row(section, i, pill, titre, sous, cote){
    return `<div class="mx-row mx-cliq fp2-l${_fp2Sel === i ? ' sel' : ''}" role="button" tabindex="0" onclick="fp2Ouvrir('${section}',${i})" onkeydown="if(event.key==='Enter')fp2Ouvrir('${section}',${i})">${pill}<div class="mx-rt"><b>${titre}</b>${sous ? `<span>${sous}</span>` : ''}</div><div class="mx-cote">${cote || ''}</div></div>`;
}

// ── LE RENDU D'UNE SECTION ──
const FP2_TABLES = new Set(['_generique', 'php', 'databases', 'users', 'mail', 'ftp', 'dns']);
function fpRenderSection(section){
    const rows = _fpData[section] || [];
    const main = document.getElementById('fp-main-area'); if (!main) return;
    _fp2Lu[section] = Date.now();
    if (!['backups', 'php', 'ssl', 'scans'].includes(section)) fp2Point(section, _fpErreur[section] ? 'avert' : (rows.length ? 'ok' : 'vide'));
    let html = '';
    if (_fpErreur[section]) html += fp2Etat('repli', 'Source partielle', _fpErreur[section] + ' — la liste ci-dessous peut être incomplète.');
    if (!rows.length && !_fpErreur[section]) {
        if (section === 'backups') html += fp2SauvegardesVide();
        else {
            const vides = {
                dns:     ['Aucune zone dans le panneau', 'Le panneau ne porte aucune zone DNS : les enregistrements vivent ailleurs. Ce vide est prouvé, pas supposé.'],
                scans:   ['Aucune analyse, jamais', "Aucun rapport antivirus : aucun site n'a été analysé. « Lancer une analyse » choisit un site."],
                crons:   ['Aucun cron du panneau', 'Le panneau ne porte aucune tâche ; les crons du système vivent dans Automatismes.'],
            }[section] || ['Aucun élément · lecture réussie', "La source a répondu et n'a rien à montrer."];
            html += `<div class="mx-silence"><b>${escapeHtml(vides[0])}.</b> ${escapeHtml(vides[1])}</div>`;
        }
        main.innerHTML = fp2Carte(section, html, rows.length ? String(rows.length) : 'aucun'); return;
    }
    const nom = FP2_RENDU[section] ? section : '_generique';
    const R = FP2_RENDU[nom];
    html += FP2_TABLES.has(nom) ? `<div class="mx-tbl"><table class="fp2-liste">${R(section, rows)}</table></div>` : R(section, rows);
    const notes = {
        php:   'La version par site est lue dans la table des backends du panneau ; un site en reverse proxy n’a pas de PHP, ce n’est pas une absence.',
        crons: 'Ce sont les mêmes lignes que l’onglet Automatismes : le rapprochement complet et « surveiller » se règlent là-bas.',
        users: 'Réservé à l’administrateur : un compte ordinaire ne voit que ses propres sites, bases et boîtes.',
        domains: 'Une ligne = un site : sa manière de servir, son poids (fichiers + base), sa dernière réponse HTTP et son certificat. Un clic ouvre la fiche.',
        services: 'Le collecteur ne relève que les unités installées. Un redémarrage passe par une feuille de confirmation et le journal d’administration.',
    }[section];
    if (notes) html += `<div class="mx-foot"><span>${escapeHtml(notes)}</span></div>`;
    main.innerHTML = fp2Carte(section, html, rows.length + (section === 'ssl' ? ' certificat(s)' : ''));
}
// AUCUNE SAUVEGARDE : un verdict, pas une case « 0 ». Ce qu'il y a à perdre, et le geste qui règle ça.
function fp2SauvegardesVide(){
    const d = _fp2Resume || {}, dom = _fpData.domains || [], dbs = _fpData.databases || [];
    const fmo = dom.reduce((s, x) => s + (parseFloat(x.files_mb) || 0), 0), dmo = dbs.reduce((s, x) => s + (parseFloat(x.size_mb) || 0), 0);
    const ns = d.domains_count || dom.length, nb = d.databases_count || dbs.length;
    const plans = d.backup_plans || [];
    // UN PLAN EXISTE, RIEN N'EST ENCORE COPIÉ (20-09) : à regarder, pas une panne — et le geste est « lancer ».
    if (plans.length) {
        const p = plans[0], id = escapeAttr(String(p.id ?? ''));
        return `<div class="mx-verdict"><span class="mx-vmark"></span><div class="mx-vbody">
        <h2 class="mx-vtitle">Aucune copie encore</h2>
        <p class="mx-vsub" style="margin:0">Le plan « <b>${escapeHtml(p.name || '?')}</b> » existe${plans.length > 1 ? ` (et ${plans.length - 1} autre${plans.length > 2 ? 's' : ''})` : ''} : première exécution ${escapeHtml(fpBackupQuand(p))}. Tant qu’il n’a pas tourné, ${ns ? `les <b>${ns} site${ns > 1 ? 's' : ''}</b>` : 'les sites'} et ${nb ? `les <b>${nb} base${nb > 1 ? 's' : ''}</b>` : 'les bases'} ne sont copiés nulle part.</p>
        <div class="mx-gest" style="justify-content:flex-start"><button class="mx-btn primary" onclick="fpBackupLancer('${id}')">Lancer maintenant</button><button class="mx-btn" onclick="fpBackupPlans()">Les plans</button></div>
      </div></div>
      <div class="mx-kpis">
        <div class="mx-kpi"><span>Le plan</span><em>${escapeHtml(p.name || '?')} · ${escapeHtml(fpBackupQuand(p))}${p.type === 'all_users' ? ' · tous les comptes' : ''}</em></div>
        <div class="mx-kpi"><span>Ce qu’on saura après</span><em>chaque passage, une ligne ici : réussie, ratée, et pourquoi</em></div>
        <div class="mx-kpi"><span>Le geste</span><em>« Lancer maintenant » exécute le plan tout de suite ; la copie apparaît ici quand elle est finie</em></div>
      </div>`;
    }
    return `<div class="mx-verdict"><span class="mx-vmark panne"></span><div class="mx-vbody">
        <h2 class="mx-vtitle">Aucune sauvegarde, jamais</h2>
        <p class="mx-vsub" style="margin:0">Aucun plan n’existe dans le panneau : ${ns ? `les <b>${ns} site${ns > 1 ? 's' : ''}</b>${fmo ? ' (' + escapeHtml(fpTaille(fmo)) + ' de fichiers)' : ''}` : 'les sites'} et ${nb ? `les <b>${nb} base${nb > 1 ? 's' : ''}</b>${dmo ? ' (' + escapeHtml(fpTaille(dmo)) + ')' : ''}` : 'les bases'} ne sont copiés nulle part. C’est la première chose à faire sur cette machine.</p>
        <div class="mx-gest" style="justify-content:flex-start"><button class="mx-btn primary" onclick="fpBackupPlans()">Créer un plan</button><button class="mx-btn" onclick="fpOpenPanel()">Ouvrir le panneau</button></div>
      </div></div>
      <div class="mx-kpis">
        <div class="mx-kpi"><span>Ce que fait un plan</span><em>tous les sites et toutes les bases, chaque nuit, dans le stockage du panneau</em></div>
        <div class="mx-kpi"><span>Le geste</span><em>« Créer un plan » ouvre les plans du panneau : un nom, un jour, une heure</em></div>
        <div class="mx-kpi"><span>Ce qu’on saura après</span><em>chaque passage, une ligne ici : réussie, ratée, et pourquoi</em></div>
      </div>`;
}
// LES CERTIFICATS : d'abord ce qu'il faut savoir — valides ou pas, et qui les renouvelle.
function fp2SslTete(rows){
    const a = _fp2Audit || {}, rn = a.renew || {}, ss = a.ssl || {};
    const j = rows.map(r => parseFloat(r.ssl_days_left)).filter(n => isFinite(n));
    const min = j.length ? Math.min.apply(null, j) : null, valides = j.filter(n => n > 0).length;
    const absents = (ss.missing || []).length, renewOff = (rn.enabled === false || rn.disabled);
    const certbot = rn.certbot_timer === 'active';
    const mark = (absents || (min != null && min <= 7)) ? 'panne' : ((renewOff && !certbot) || (min != null && min <= 45)) ? '' : 'stable';
    const titre = absents ? `${absents} domaine${absents > 1 ? 's' : ''} sans certificat` : ((renewOff && !certbot) ? `${valides} certificat${valides > 1 ? 's' : ''} valide${valides > 1 ? 's' : ''}, aucun ne se renouvellera seul` : `${valides} certificat${valides > 1 ? 's' : ''} valide${valides > 1 ? 's' : ''}`);
    const echeance = (min == null) ? '' : (min <= 0 ? 'Le premier a expiré. ' : `Le premier expire dans <b>${Math.round(min)} jour${min > 1 ? 's' : ''}</b>. `);
    const sous = a.renew ? ((renewOff && !certbot)
        ? `Aucun minuteur certbot n’est actif sur la machine, et la passe de renouvellement de Cassandra est éteinte. ${echeance}Activée, elle renouvelle chaque certificat à moins de ${rn.threshold || 15} jours de son échéance.`
        : (certbot ? `certbot.timer est actif : le renouvellement est pris en charge par la machine. ${echeance}` : `La passe de Cassandra renouvelle chaque certificat à moins de ${rn.threshold || 15} jours de son échéance${(rn.candidates || []).length ? ` — ${rn.candidates.length} en attente de la prochaine passe` : ''}. ${echeance}`))
        : 'L’audit n’a pas encore été lu.';
    return `<div class="mx-verdict" style="margin-bottom:4px"><span class="mx-vmark ${mark}"></span><div class="mx-vbody">
        <h2 class="mx-vtitle">${escapeHtml(titre)}</h2><p class="mx-vsub" style="margin:0">${sous}</p>
        ${(renewOff && !certbot) ? `<div class="mx-gest" style="justify-content:flex-start"><button class="mx-btn primary" onclick="fp2RenouvellementActiver()">Activer le renouvellement automatique</button></div>` : ''}
      </div></div>`;
}
async function fp2RenouvellementActiver(){
    const seuil = ((_fp2Audit || {}).renew || {}).threshold || 15;
    if (!await fp2Confirm(`La passe planifiée de Cassandra renouvellera chaque certificat à moins de ${seuil} jours de son échéance, par certbot. Rien ne part maintenant : la prochaine passe s’en charge, et le journal le dira.\n\nActiver le renouvellement automatique ?`, 'Renouvellement des certificats')) return;
    try {
        const d = await apiPost('/api/memory/config', { update: { ssl_autorenew_enabled: true } });
        if (d && d.ok !== false) { if (typeof showToast === 'function') showToast('Renouvellement automatique activé', 'success', 3000); await fp2Vigilances(); if (_fpSection === 'ssl') fpLoadSection('ssl'); }
        else if (typeof showToast === 'function') showToast('Refus : ' + ((d && d.error) || '?'), 'error', 4000);
    } catch(e) { if (typeof showToast === 'function') showToast('Erreur réseau', 'error', 3000); }
}
const FP2_RENDU = {
    _generique(section, rows){
        const cols = (FP_SECTIONS[section] || {}).cols || Object.keys(rows[0] || {});
        return `<tr>${cols.map(c => `<th>${escapeHtml(FP_COL_LABELS[c] || c)}</th>`).join('')}</tr>` +
            rows.map((r, i) => fp2Ligne(section, i, cols.map(c => `<td>${fpRenderValue(c, r[c], r)}</td>`).join(''))).join('');
    },
    domains(section, rows){
        return '<div class="mx-rows">' + rows.map((s, i) => {
            const actif = String(s.status || '').toLowerCase() === 'active';
            const http = s.status_code ? `HTTP ${escapeHtml(String(s.status_code))} · ${parseInt(s.error_count) || 0} err` : 'HTTP non relevé';
            return fp2Row(section, i, fp2Pill(actif ? 'en ligne' : (s.status || '?'), actif ? 'ok' : 'neutre'),
                `<code>${escapeHtml(s.domain || '')}</code>`,
                `${escapeHtml(fp2PhpTxt(s))} · ${escapeHtml(fpTaille(s.files_mb))} + ${escapeHtml(fpTaille(s.db_mb))} base · ${http}${s.user ? ' · ' + escapeHtml(s.user) : ''}`,
                `${fp2Jauge(s.ssl_days_left)}${s.ssl_expiry ? `<span class="mx-meta">expire le ${escapeHtml(s.ssl_expiry)}</span>` : ''}`);
        }).join('') + '</div>';
    },
    ssl(section, rows){
        return fp2SslTete(rows) + '<div class="mx-rows">' + rows.map((s, i) => {
            const n = parseFloat(s.ssl_days_left);
            const et = !isFinite(n) ? ['avert', 'non prouvé'] : n < 0 ? ['erreur', 'expiré'] : n <= 7 ? ['erreur', 'expire'] : n <= 45 ? ['avert', 'bientôt'] : ['ok', 'valide'];
            return fp2Row(section, i, fp2Pill(et[1], et[0]), `<code>${escapeHtml(s.domain || '')}</code>`,
                `échéance ${escapeHtml(s.ssl_expiry || '—')} · source ${escapeHtml(s.ssl_source || 'non sondé')}${s.ssl_source === 'sonde' ? '' : ' · non sondé cette session'}`,
                fp2Jauge(s.ssl_days_left));
        }).join('') + '</div>'
        + `<div class="mx-foot"><span>« Valide » vient du collecteur, qui lit le fichier ; « servi » ne se dit qu’après la sonde 443 : un fichier renouvelé que nginx n’a pas rechargé sert encore l’ancien.</span></div>`;
    },
    php(section, rows){
        const dom = _fpData.domains || [];
        let h = `<tr><th>Version installée</th><th>Complète</th><th>Chemin</th><th>Active</th><th>Source</th></tr>` + rows.map((r, i) => fp2Ligne(section, i,
            `<td><span class="dom">PHP ${escapeHtml(r.version || '?')}</span></td><td class="num">${escapeHtml(r.full_version || '')}</td><td class="num">${escapeHtml(r.path || '')}</td><td>${fpRenderValue('active', r.active, r)}</td><td>${fp2Pill(r.source || 'collecteur', 'neutre')}</td>`)).join('');
        if (dom.length) h += `<tr><th colspan="5" style="padding-top:14px">Par site</th></tr>` + dom.map(s => `<tr><td class="dom">${escapeHtml(s.domain || '')}</td><td colspan="3">${escapeHtml(fp2PhpTxt(s))}</td><td>${fp2Pill(s.php_source || 'collecteur', /non lue/.test(String(s.php_source || '')) ? 'avert' : 'neutre')}</td></tr>`).join('');
        return h;
    },
    databases(section, rows){
        return `<tr><th>Base</th><th>Site</th><th>Taille</th><th>Utilisateur</th><th>Créée</th><th>Dernier vidage</th></tr>` + rows.map((b, i) => fp2Ligne(section, i,
            `<td><span class="dom">${escapeHtml(b.name || '')}</span><span class="sous">${escapeHtml(b.db_type || '')} · ${escapeHtml(b.owner || '')}</span></td><td class="num">${escapeHtml(b.site || '')}${b.site ? '' : fp2Pill('orpheline', 'avert')}</td>
             <td class="num">${escapeHtml(fpTaille(b.size_mb))}</td><td class="num">${escapeHtml(b.db_user || '')}</td><td class="num">${escapeHtml(String(b.created_at || '').slice(0, 10))}</td><td>${fpRenderValue('dump_at', b.dump_at, b)}</td>`)).join('');
    },
    users(section, rows){
        return `<tr><th>Compte</th><th>Rôle</th><th>Sites</th><th>Bases</th><th>SSH</th><th>Courriel</th><th>Créé</th></tr>` + rows.map((c, i) => fp2Ligne(section, i,
            `<td><span class="dom">${escapeHtml(c.username || '')}</span></td><td>${fp2Pill(/SUPER_ADMIN/.test(String(c.roles || '')) ? 'super admin' : 'utilisateur', /SUPER_ADMIN/.test(String(c.roles || '')) ? 'info' : 'neutre')}</td>
             <td class="num">${c.sites_count ?? '–'}</td><td class="num">${c.databases_count ?? '–'}</td><td>${c.ssh_access == 1 ? fp2Pill('oui', 'avert') : fp2Pill('non', 'neutre')}</td><td class="num">${escapeHtml(c.email || '—')}</td><td class="num">${escapeHtml(String(c.created_at || '').slice(0, 10))}</td>`)).join('');
    },
    mail(section, rows){
        return `<tr><th>Adresse</th><th>Domaine</th><th>Quota</th><th>Utilisé</th><th>État</th></tr>` + rows.map((m, i) => fp2Ligne(section, i,
            `<td><span class="dom">${escapeHtml(m.email || '')}</span></td><td class="num">${escapeHtml(m.domain || '')}</td><td class="num">${parseFloat(m.quota_mb) > 0 ? escapeHtml(fpTaille(m.quota_mb)) : 'illimité'}</td><td class="num">${escapeHtml(fpTaille(m.used_mb))}</td><td>${fpRenderValue('status', m.status, m)}</td>`)).join('');
    },
    ftp(section, rows){
        return `<tr><th>Identifiant</th><th>Dossier</th><th>Site</th><th>Propriétaire</th><th>État</th></tr>` + rows.map((f, i) => fp2Ligne(section, i,
            `<td><span class="dom">${escapeHtml(f.login || '')}</span></td><td class="num">${escapeHtml(String(f.home_dir || '').replace(/^\/var\/www\/[^/]+\/data\/www\//, '…/'))}</td><td class="num">${escapeHtml(f.site || '')}</td><td class="num">${escapeHtml(f.owner || '')}</td><td>${fpRenderValue('status', f.status, f)}</td>`)).join('');
    },
    services(section, rows){
        return '<div class="mx-rows">' + rows.map((s, i) => {
            const n = fp2Site(s.name), actif = String(s.status || '').toLowerCase().indexOf('activ') === 0;
            return fp2Row(section, i, fp2Pill(actif ? 'actif' : (s.status || '?'), actif ? 'ok' : 'erreur'),
                `<code>${escapeHtml(s.name || '')}</code>${s.version ? ` <span class="mx-meta">${escapeHtml(s.version)}</span>` : ''}`,
                (s.aliases ? 'alias ' + escapeHtml([].concat(s.aliases).join(', ')) + ' · ' : '') + 'source ' + escapeHtml(s.source || 'API'),
                `<div class="mx-gest"><button class="mx-btn" onclick="event.stopPropagation();fpSvc('${n}','${actif ? 'restart' : 'start'}')">${actif ? 'Redémarrer' : 'Démarrer'}</button><button class="mx-btn" onclick="event.stopPropagation();fpSvcDiag('${n}')">Diagnostic</button></div>`);
        }).join('') + '</div>';
    },
    crons(section, rows){
        return '<div class="mx-rows">' + rows.map((c, i) => {
            const st = String(c.last_status || '').toLowerCase();
            const et = c.enabled == 0 ? ['neutre', 'désactivé'] : ['ok', 'success', 'ran'].includes(st) ? ['ok', 'a tourné'] : ['error', 'failed'].includes(st) ? ['erreur', 'en erreur'] : ['neutre', c.last_run ? st || '—' : 'jamais passé'];
            return fp2Row(section, i, fp2Pill(et[1], et[0]),
                `<code>${escapeHtml(c.schedule || '')}</code> · ${escapeHtml(String(c.command || '').slice(0, 90))}`,
                `${escapeHtml(c.user || '')}${c.last_run ? ' · dernier passage ' + escapeHtml(c.last_run) : ''}${c.source ? ' · ' + escapeHtml(c.source) : ''}`,
                `<span class="mx-meta">surveillé : ${c.watched === true || c.watched === 'true' ? 'oui' : 'non'}</span><button class="mx-btn" onclick="event.stopPropagation();fpCronFiche(${i})">Fiche</button>`);
        }).join('') + '</div>';
    },
    scans(section, rows){
        return '<div class="mx-rows">' + rows.map((a, i) => {
            const st = String(a.status || '').toLowerCase();
            const et = st === 'inconnu' ? ['avert', 'statut inconnu'] : ['ok', 'clean', 'success'].includes(st) ? ['ok', 'propre'] : ['erreur', st || '?'];
            const d = escapeAttr(String(a.domain || ''));
            return fp2Row(section, i, fp2Pill(et[1], et[0]), `<code>${escapeHtml(a.domain || '')}</code>`,
                `${escapeHtml(a.created_at || '')} · ${escapeHtml(String(a.report || '').split('/').pop())}`,
                `<div class="mx-gest"><button class="mx-btn" onclick="event.stopPropagation();fpRapports('${d}')">Rapport</button><button class="mx-btn" onclick="event.stopPropagation();fpScanRun('${d}')">Relancer</button></div>`);
        }).join('') + '</div>';
    },
    backups(section, rows){
        return '<div class="mx-rows">' + rows.map((b, i) => {
            const st = String(b.status || '').toLowerCase();
            const et = ['error', 'failed'].includes(st) ? ['erreur', 'ratée'] : ['ok', 'success', 'done', 'completed'].includes(st) ? ['ok', 'réussie'] : ['neutre', st || '?'];
            return fp2Row(section, i, fp2Pill(et[1], et[0]), `${escapeHtml(b.type || 'sauvegarde')}${b.destination ? ' → ' + escapeHtml(b.destination) : ''}`,
                `${escapeHtml(String(b.created_at || '').slice(0, 16))}${b.size_mb ? ' · ' + escapeHtml(fpTaille(b.size_mb)) : ''}${b.error ? ' · ' + escapeHtml(b.error) : ''}`,
                `<button class="mx-btn" onclick="event.stopPropagation();fpBackupPlans()">Plans</button>`);
        }).join('') + '</div>';
    },
    dns(section, rows){
        return `<tr><th>Zone</th><th>Type</th><th>Nom</th><th>Valeur</th><th>TTL</th></tr>` + rows.map((r, i) => fp2Ligne(section, i,
            `<td class="num">${escapeHtml(r.zone || '')}</td><td>${fp2Pill(r.type || '', 'neutre')}</td><td class="num">${escapeHtml(r.name || '')}</td><td class="num">${escapeHtml(r.value || '')}</td><td class="num">${escapeHtml(r.ttl ?? '')}</td>`)).join('');
    },
};
function fp2Php(s){
    const v = String(s.php_version || '').trim(), src = String(s.php_source || '');
    if (v) return fp2Pill('PHP ' + v, 'neutre');
    if (/sans PHP/i.test(src)) return fp2Pill('sans PHP · ' + (s.php_handler || 'proxy'), 'neutre');
    return fp2Pill('non lue', 'avert');
}

// ── LA FICHE : ce que le panneau sait de la ligne, et les gestes possibles — en panneau à droite ──
function fp2Ouvrir(section, i){
    _fp2Sel = i;
    document.querySelectorAll('#fp-main-area .fp2-l').forEach((el, k) => el.classList.toggle('sel', k === i));
    fp2Fiche(section, (_fpData[section] || [])[i]);
}
function fp2FicheFermer(){
    const v = document.getElementById('fp2-fiche-voile'); if (v) v.classList.remove('on');
    _fp2Sel = null;
    document.querySelectorAll('#fp-main-area .fp2-l.sel').forEach(el => el.classList.remove('sel'));
}
function fp2Fiche(section, r){
    const f = document.getElementById('fp2-fiche'), v = document.getElementById('fp2-fiche-voile'); if (!f || !v) return;
    if (!r) { fp2FicheFermer(); return; }
    const kv = [], gestes = [], pills = [];
    const titre = { domains: r.domain, ssl: r.domain, databases: r.name, users: r.username, mail: r.email, ftp: r.login, services: r.name, crons: (r.command || '').slice(0, 60), scans: r.domain, php: 'PHP ' + (r.version || ''), dns: r.name, backups: r.type }[section] || '';
    const K = (k, val) => kv.push(`<dt>${escapeHtml(k)}</dt><dd>${val}</dd>`);
    const G = (lib, sous, onclick, cls) => gestes.push(`<button class="${cls || ''}" onclick="${onclick}"><b>${escapeHtml(lib)}</b><small>${escapeHtml(sous)}</small></button>`);
    const q = s => fp2Site(s);
    if (section === 'domains' || section === 'ssl') {
        const actif = String(r.status || '').toLowerCase() === 'active', bk = ((_fp2Audit || {}).backups || {});
        pills.push(fp2Pill(actif ? 'en ligne' + (r.status_code ? ' · HTTP ' + r.status_code : '') : (r.status || '?'), actif ? 'ok' : 'neutre'), fp2Pill(fp2PhpTxt(r), 'neutre'));
        const j = parseFloat(r.ssl_days_left); if (isFinite(j)) pills.push(fp2Pill('certificat ' + Math.round(j) + ' j', j <= 7 ? 'erreur' : (j <= 45 ? 'avert' : 'ok')));
        if ((bk.missing || []).includes(r.domain)) pills.push(fp2Pill('jamais sauvegardé', 'erreur'));
        K('racine', `<span class="fp2-mono">${escapeHtml(r.document_root || '—')}</span>`);
        K('certificat', fp2Jauge(r.ssl_days_left) + (r.ssl_expiry ? ` <span class="mx-meta">échéance ${escapeHtml(r.ssl_expiry)} · ${escapeHtml(r.ssl_source || 'non sondé')}</span>` : ''));
        K('poids', `<span class="fp2-mono">${escapeHtml(fpTaille(r.files_mb))} fichiers · ${escapeHtml(fpTaille(r.db_mb))} base</span>`);
        K('HTTP', r.status_code ? `${escapeHtml(String(r.status_code))} · ${parseInt(r.error_count) || 0} erreur(s)` + (r.stats_at ? ` <span class="mx-meta">relevé ${escapeHtml(r.stats_at)}</span>` : '') : 'non relevé');
        const base = (_fpData.databases || []).filter(b => b.site === r.domain); K('base', base.length ? base.map(b => `<span class="fp2-mono">${escapeHtml(b.name)}</span>` + (b.dump_at ? '' : ' · jamais vidée')).join(', ') : 'aucune');
        const ftp = (_fpData.ftp || []).filter(x => x.site === r.domain); K('FTP', ftp.length ? ftp.map(x => `<span class="fp2-mono">${escapeHtml(x.login)}</span>`).join(', ') : 'aucun compte');
        const sc = (_fpData.scans || []).filter(x => x.domain === r.domain); K('analyse', sc.length ? escapeHtml(sc[0].created_at || '') + ' · ' + escapeHtml(sc[0].status || '') : fp2Pill('jamais analysé', 'avert'));
        K('sauvegarde', (bk.missing || []).includes(r.domain) ? fp2Pill('manquante', 'erreur') : ((bk.stale || []).includes(r.domain) ? fp2Pill('ancienne', 'avert') : fp2Pill('à jour ou non suivie', 'neutre')));
        if (r.user) K('compte', `<span class="fp2-mono">${escapeHtml(r.user)}</span>`);
        G('Vérifier le certificat servi', 'sonde 443, en direct', `fpSslCheck('${q(r.domain)}')`); G('Renouveler le certificat', 'certbot · staging d’abord', `fpSslIssue('${q(r.domain)}')`);
        G("Lancer l'analyse", 'antivirus · ~2 min', `fpScanRun('${q(r.domain)}')`); G('Rapports d’analyse', 'lire les rapports', `fpRapports('${q(r.domain)}')`);
        G('Projet, responsable, tâches', 'contexte Cassandra', `fpDomCtx('${q(r.domain)}')`); G('Fiche du site', 'onglet Mes sites', `switchTab('mysites');setTimeout(()=>stOpen('${q(r.domain)}'),80)`);
        G('Ouvrir le panneau', 'dans un nouvel onglet', `fpOpenPanel()`); G('Analyser avec Cassandra', 'envoyer au chat', `switchTab('dashboard');sendQuickFix(${JSON.stringify(fpBuildAnalyzeMsg('domains', r)).replace(/"/g, '&quot;')})`);
    } else if (section === 'databases') {
        pills.push(fp2Pill(r.db_type || 'base', 'neutre'), r.site ? fp2Pill(r.site, 'neutre') : fp2Pill('orpheline', 'avert'), r.dump_at ? fp2Pill('vidée', 'ok') : fp2Pill('jamais vidée', 'avert'));
        K('propriétaire', escapeHtml(r.owner || '')); K('site', r.site ? escapeHtml(r.site) : fp2Pill('orpheline', 'avert')); K('utilisateur', `<span class="fp2-mono">${escapeHtml(r.db_user || '')}</span>`);
        K('taille', `<span class="fp2-mono">${escapeHtml(fpTaille(r.size_mb))}</span>`); K('encodage', escapeHtml(r.charset || '')); K('créée', escapeHtml(String(r.created_at || '').slice(0, 19))); K('dernier vidage', fpRenderValue('dump_at', r.dump_at, r));
        G('phpMyAdmin', 'ouvrir cette base', `fpPhpMyAdmin('${q(r.name)}')`); if (r.site) G('Fiche du site', 'onglet Mes sites', `switchTab('mysites');setTimeout(()=>stOpen('${q(r.site)}'),80)`);
        G('Supprimer la base', 'irréversible · confirmé', `fpDbDrop('${q(r.name)}', '${q(String(r.id ?? ''))}')`, 'danger');
    } else if (section === 'users') {
        pills.push(fp2Pill(/SUPER_ADMIN/.test(String(r.roles || '')) ? 'super administrateur' : 'utilisateur', 'info'), r.ssh_access == 1 ? fp2Pill('SSH autorisé', 'avert') : fp2Pill('sans SSH', 'neutre'));
        K('dossier', `<span class="fp2-mono">${escapeHtml(r.home_dir || '')}</span>`); K('sites', String(r.sites_count ?? '–')); K('bases', String(r.databases_count ?? '–')); K('courriel', escapeHtml(r.email || '—')); K('créé', escapeHtml(String(r.created_at || '').slice(0, 19)));
        G('Fiche complète', 'tout ce que le panneau porte', `fpUserFiche('${q(r.username)}')`); G('Clés SSH', 'lister, ajouter', `fpUserSsh('${q(r.username)}')`); G('Ses sites', 'filtrer les sites', `fpVoir('domains','${q(r.username)}')`); G('Ses bases', 'filtrer les bases', `fpVoir('databases','${q(r.username)}')`);
    } else if (section === 'services') {
        const n = q(r.name), actif = String(r.status || '').toLowerCase().indexOf('activ') === 0;
        pills.push(fp2Pill(actif ? 'actif' : (r.status || '?'), actif ? 'ok' : 'erreur'));
        K('version', escapeHtml(r.version || '—')); K('source', escapeHtml(r.source || 'API')); if (r.aliases) K('alias', escapeHtml([].concat(r.aliases).join(', '))); if (r.last_check) K('relevé', escapeHtml(String(r.last_check).slice(0, 19)));
        G(actif ? 'Redémarrer' : 'Démarrer', 'confirmé · journalisé', `fpSvc('${n}','${actif ? 'restart' : 'start'}')`); G('Diagnostic', 'état, journal récent', `fpSvcDiag('${n}')`); G('Arrêter', 'refusé sur un service vital', `fpSvc('${n}','stop')`, 'danger');
    } else if (section === 'crons') {
        const i = (_fpData.crons || []).indexOf(r);
        pills.push(fp2Pill(r.enabled == 0 ? 'désactivé' : 'actif', r.enabled == 0 ? 'neutre' : 'ok'));
        K('utilisateur', escapeHtml(r.user || '')); K('quand', `<span class="fp2-mono">${escapeHtml(r.schedule || '')}</span>`); K('commande', `<span class="fp2-mono">${escapeHtml(r.command || '')}</span>`); K('dernier passage', escapeHtml(r.last_run || '—')); K('dernier état', fpRenderValue('last_status', r.last_status, r));
        G('Fiche du cron', 'lancer, activer, historique', `fpCronFiche(${i})`); G('Automatismes', 'le rapprochement complet', `switchTab('crons')`);
    } else if (section === 'scans') {
        const st = String(r.status || '').toLowerCase();
        pills.push(st === 'inconnu' ? fp2Pill('statut inconnu', 'avert') : (['ok', 'clean', 'success'].includes(st) ? fp2Pill('propre', 'ok') : fp2Pill(st || '?', 'erreur')));
        K('date', escapeHtml(r.created_at || '')); K('rapport', `<span class="fp2-mono">${escapeHtml(String(r.report || '').split('/').pop())}</span>`);
        G('Relancer l’analyse', 'antivirus', `fpScanRun('${q(r.domain)}')`); G('Lire les rapports', 'de ce site', `fpRapports('${q(r.domain)}')`); G('Fiche du site', 'onglet Mes sites', `switchTab('mysites');setTimeout(()=>stOpen('${q(r.domain)}'),80)`);
    } else if (section === 'mail' || section === 'ftp' || section === 'dns' || section === 'php' || section === 'backups') {
        Object.keys(r).forEach(k => { if (k !== 'id' && k !== 'last_check') K(FP_COL_LABELS[k] || k, fpRenderValue(k, r[k], r)); });
        if (section === 'ftp') G('Supprimer ce compte FTP', 'irréversible · confirmé', `fpRunAction('ftp_supprimer',['id'])`, 'danger');
        if (section === 'mail' && r.domain) G('Fiche du site', 'onglet Mes sites', `switchTab('mysites');setTimeout(()=>stOpen('${q(r.domain)}'),80)`);
        if (section === 'backups') G('Plans de sauvegarde', 'lister, lancer, créer', `fpBackupPlans()`);
    } else {
        Object.keys(r).forEach(k => K(k, escapeHtml(String(r[k] ?? ''))));
    }
    f.innerHTML = `<div class="mx-eyebrow">${escapeHtml(FP2[section] ? FP2[section].titre : section)} › fiche${_fp2Lu[section] ? ' · lu à ' + fp2Heure(_fp2Lu[section]) : ''}</div>
      <h2>${/^(domains|ssl|services|scans|dns)$/.test(section) ? `<code>${escapeHtml(String(titre || ''))}</code>` : escapeHtml(String(titre || ''))}</h2>
      ${pills.length ? `<div class="mx-pills" style="justify-content:flex-start">${pills.join('')}</div>` : ''}
      <dl class="mx-paires">${kv.join('')}</dl>
      ${gestes.length ? `<div class="mx-eyebrow">Gestes · chacun confirmé et journalisé</div><div class="fp2-gestes">${gestes.join('')}</div>` : ''}
      <div class="mx-gest" style="margin-top:auto;padding-top:6px"><button class="mx-btn" onclick="fp2FicheFermer()">Fermer</button></div>`;
    v.classList.add('on');
}
document.addEventListener('keydown', e => { if (e.key === 'Escape') { const v = document.getElementById('fp2-fiche-voile'); if (v && v.classList.contains('on')) fp2FicheFermer(); } });

// ── LA VUE D'ENSEMBLE : un verdict, ses chiffres, ce qui demande un geste, les sites, d'où viennent les chiffres ──
function fp2VerdictHtml(){
    const d = _fp2Resume || {}, a = _fp2Audit, bk = (a || {}).backups || {}, ss = (a || {}).ssl || {}, ph = (a || {}).php || {}, rn = (a || {}).renew || {};
    // Trois états (20-09) : aucun plan · un plan qui n'a encore rien copié · des copies, que l'audit juge.
    const nSites = d.domains_count || 0, missing = (bk.missing || []).length;
    const noPlan = d.backup_plans_count === 0 || (d.backup_plans_count == null && d.backups_count === 0);
    const jamaisRun = (d.backup_plans_count > 0 && d.backups_count === 0), plan0 = (d.backup_plans || [])[0] || {};
    const svcDown = d.services_down || 0, svcN = d.services_count, renewOff = (rn.enabled === false || rn.disabled) && rn.certbot_timer !== 'active';
    const P = [];   // [gravité, phrase]
    if (a) {
        if (noPlan && nSites) P.push(['panne', 'rien n’est sauvegardé']);
        else if (jamaisRun && nSites) P.push(['', 'le plan de sauvegarde n’a pas encore tourné']);
        else if (missing) P.push(['panne', `${missing} site${missing > 1 ? 's' : ''} sans sauvegarde`]);
        if (svcDown) P.push(['panne', `${svcDown} service${svcDown > 1 ? 's' : ''} tombé${svcDown > 1 ? 's' : ''}`]);
        if ((ss.missing || []).length) P.push(['panne', `${ss.missing.length} domaine${ss.missing.length > 1 ? 's' : ''} sans certificat`]);
        if ((ph.eol || []).length) P.push(['panne', `${ph.eol.length} site${ph.eol.length > 1 ? 's' : ''} sur un PHP en fin de vie`]);
        if (renewOff && nSites) P.push(['', 'rien ne renouvelle les certificats']);
        if ((ss.soon || []).length) P.push(['', `${ss.soon.length} certificat${ss.soon.length > 1 ? 's' : ''} expire${ss.soon.length > 1 ? 'nt' : ''} bientôt`]);
    }
    let mark, titre, sous;
    if (!a) {
        mark = 'inconnu'; titre = _fp2VigErreur ? 'L’audit n’a pas pu être lu' : 'Lecture de l’audit…';
        sous = _fp2VigErreur ? escapeHtml(_fp2VigErreur) + ' — les chiffres du résumé restent valables.' : 'Sauvegardes, certificats, PHP : l’audit arrive.';
    } else if (!P.length) {
        mark = 'stable'; titre = nSites ? 'Tout est sain' : 'Rien à surveiller : aucun site';
        sous = nSites ? `${nSites} site${nSites > 1 ? 's' : ''} en ligne, ${svcN != null ? svcN + ' services actifs, ' : ''}certificats valides et renouvelés, sauvegardes en place.` : 'Le panneau ne porte aucun site.';
    } else {
        mark = P.some(x => x[0] === 'panne') ? 'panne' : '';
        titre = P[0][1].charAt(0).toUpperCase() + P[0][1].slice(1) + (P[1] ? ', et ' + P[1][1] : '') + (P.length > 2 ? ` (+${P.length - 2})` : '');
        const morceaux = [];
        if (noPlan && nSites) morceaux.push(`Aucun plan de sauvegarde n’existe dans le panneau : les <b>${nSites} site${nSites > 1 ? 's' : ''}</b>${d.databases_count ? ` et les <b>${d.databases_count} base${d.databases_count > 1 ? 's' : ''}</b>` : ''} ne sont jamais copiés.`);
        else if (jamaisRun && nSites) morceaux.push(`Le plan « <b>${escapeHtml(plan0.name || '?')}</b> » existe mais n’a encore rien copié : première exécution ${escapeHtml(fpBackupQuand(plan0))} — ou lancez-le maintenant.`);
        else if (missing) morceaux.push(`${missing} site${missing > 1 ? 's' : ''} sans sauvegarde depuis plus de ${bk.threshold_days || 7} jours.`);
        if (renewOff && nSites) morceaux.push(`Aucun minuteur certbot ne tourne et la passe de Cassandra est éteinte${d.ssl_min_days != null ? ` : le premier certificat expire dans <b>${d.ssl_min_days} jour${d.ssl_min_days > 1 ? 's' : ''}</b>, et personne ne le renouvellera seul` : ''}.`);
        if (svcDown) morceaux.push(`${svcDown} service${svcDown > 1 ? 's' : ''} installé${svcDown > 1 ? 's' : ''} ne tourne${svcDown > 1 ? 'nt' : ''} pas.`);
        const sains = [];
        if (nSites && !svcDown) sains.push(`${nSites} site${nSites > 1 ? 's' : ''} en ligne`);
        if (svcN != null && !svcDown) sains.push(`${svcN} services actifs`);
        if (sains.length) morceaux.push('Le reste est sain : ' + sains.join(', ') + '.');
        sous = morceaux.join(' ');
    }
    const btn = (t, js, prim) => `<button class="mx-btn${prim ? ' primary' : ''}" onclick="${js}">${t}</button>`;
    let gestes = '';
    if (a && noPlan && nSites) gestes += btn('Créer un plan de sauvegarde', "fpBackupPlans()", true);
    if (a && jamaisRun && nSites && plan0.id != null) gestes += btn('Lancer la sauvegarde maintenant', `fpBackupLancer('${escapeAttr(String(plan0.id))}')`, true);
    if (a && renewOff && nSites) gestes += btn('Activer le renouvellement', "fp2RenouvellementActiver()", !gestes);
    if (a && svcDown) gestes += btn('Voir les services', "fpNav('services')", !gestes);
    gestes += btn('Ouvrir le panneau', 'fpOpenPanel()') + btn('Opérations', "fpNav('ops')");
    const kpi = (k, b, em, cls, small) => `<div class="mx-kpi"><span>${k}</span><b${cls ? ' class="' + cls + '"' : ''}>${b}</b>${em ? `<em>${em}</em>` : ''}${small ? `<small>${small}</small>` : ''}</div>`;
    const age = _fp2Lu.summary ? 'il y a ' + Math.max(0, Math.round((Date.now() - _fp2Lu.summary) / 1000)) + ' s' : 'pas encore lu';
    const js = d.scans_last ? fp2Jours(d.scans_last) : null;
    return `<section class="mx-sec" id="fp2-verdict">
      <div class="mx-eyebrow">Le panneau, maintenant · relevé ${escapeHtml(age)}</div>
      <div class="mx-verdict"><span class="mx-vmark ${mark}"></span><div class="mx-vbody">
        <h2 class="mx-vtitle">${escapeHtml(titre)}</h2><p class="mx-vsub" style="margin:0">${sous}</p>
        <div class="mx-gest" style="justify-content:flex-start">${gestes}</div>
      </div></div>
      <div class="mx-kpis">
        ${kpi('Sites', d.domains_count != null ? String(d.domains_count) : '—', d.domains_actifs != null ? (d.domains_actifs === d.domains_count ? 'tous en ligne' : d.domains_actifs + ' en ligne') : '', '', 'base · ' + escapeHtml(age))}
        ${kpi('Certificats', a ? ((ss.ssl_active ?? '?') + '/' + (ss.total ?? '?')) : '—', d.ssl_min_days != null ? 'le premier expire dans ' + d.ssl_min_days + ' j' : '', (d.ssl_min_days != null && d.ssl_min_days <= 7) ? 'bad' : '', 'collecteur + sonde')}
        ${kpi('Services', svcN != null ? (svcN - svcDown) + '/' + svcN : '—', svcDown ? svcDown + ' tombé(s)' : (svcN != null ? 'tous actifs' : ''), svcDown ? 'bad' : '', 'collecteur · 5 min')}
        ${kpi('Sauvegardes', noPlan ? 'aucune' : jamaisRun ? 'plan prêt' : (d.backups_count != null ? String(d.backups_count) : '—'), noPlan ? `${nSites} site${nSites > 1 ? 's' : ''}, ${d.databases_count || 0} base${(d.databases_count || 0) > 1 ? 's' : ''} jamais copiés` : jamaisRun ? 'aucune copie encore' : (d.backups_failed ? d.backups_failed + ' en erreur' : (d.backup_plans_count ? d.backup_plans_count + ' plan' + (d.backup_plans_count > 1 ? 's' : '') : 'copies')), (noPlan || d.backups_failed) ? 'bad' : (jamaisRun ? 'doux' : ''), 'base · plans et copies')}
        ${kpi('Dernière analyse', js != null ? (js === 0 ? 'aujourd’hui' : 'il y a ' + js + ' j') : (d.scans_count === 0 ? 'jamais' : '—'), js != null ? (js > 30 ? 'à relancer' : 'antivirus') : (d.scans_count === 0 ? 'aucun rapport' : ''), (js != null && js > 30) || d.scans_count === 0 ? 'doux' : '', 'fichiers · rapports')}
      </div></section>`;
}
function fp2GestesHtml(){
    const L = _fp2Vig;
    let corps;
    if (L === null) corps = `<div class="mx-silence">${_fp2VigErreur ? escapeHtml('Audit indisponible : ' + _fp2VigErreur) : 'Lecture de l’audit…'}</div>`;
    else if (!L.length) corps = `<div class="mx-silence"><b>Rien ne demande un geste.</b> Sauvegardes, PHP, certificats et analyses sont sains.</div>`;
    else corps = L.map(x => `<div class="fp2-alerte"><i class="${x.c}"></i><div><b>${escapeHtml(x.t)}</b></div><button class="mx-btn" onclick="${x.go || `fpNav('${x.s}')`}">${escapeHtml(x.b)}</button></div>`).join('');
    return `<section class="mx-sec"><div class="mx-chart-h"><h2>Ce qui demande un geste</h2><span class="mx-meta">tiré de l’audit${L ? ' · ' + L.length + ' vigilance' + (L.length > 1 ? 's' : '') : ''}</span></div>${corps}</section>`;
}
// Une section se charge sans se dessiner : la vue d'ensemble a besoin des sites, et un chargement en
// cours ne se relance pas — le résumé et l'audit redessinent la vue chacun de leur côté.
const _fp2EnCours = {};
async function fp2Charger(section){
    if (fp2SectionOff(section)) return null;
    if (_fp2EnCours[section]) return _fp2EnCours[section];
    const cfg = FP_SECTIONS[section]; if (!cfg || !cfg.endpoint) return null;
    _fp2EnCours[section] = (async () => {
        try {
            const data = await apiGet(cfg.endpoint);
            if (data && !Array.isArray(data) && data.ok === false) { _fpData[section] = []; _fpErreur[section] = ''; return { hs: String(data.reason || 'raison inconnue') }; }
            _fpData[section] = Array.isArray(data) ? data : (data.data || []);
            _fpErreur[section] = (data && !Array.isArray(data) && data.source_erreur) ? String(data.source_erreur) : '';
            const badge = document.getElementById('fpbadge-' + section);
            if (badge && section !== 'ssl') { badge.textContent = _fpData[section].length; badge.title = _fpErreur[section]; }
            return { rows: _fpData[section] };
        } catch(e) { return { erreur: e.message || 'erreur réseau' }; }
        finally { delete _fp2EnCours[section]; }
    })();
    return _fp2EnCours[section];
}
async function fp2Vue(){
    const main = document.getElementById('fp-main-area'); if (!main || _fpSection !== 'vue') return;
    if (!_fpData.domains && !fp2SectionOff('domains')) { await fp2Charger('domains'); if (_fpSection !== 'vue') return; }
    const dom = _fpData.domains || [];
    const sites = dom.length ? `<section class="mx-sec"><div class="mx-chart-h"><h2>Les domaines</h2><span class="mx-meta">${dom.length} · base du panneau</span></div>
        ${FP2_RENDU.domains('domains', dom.slice(0, 8))}
        <div class="mx-foot"><a class="fp2-lien" onclick="fpNav('domains')">Tous les sites, PHP et certificats →</a></div></section>` : '';
    const jd = d => d ? 'il y a ' + Math.max(0, Math.round((Date.now() - d) / 1000)) + ' s' : '';
    const src = (pill, nom, quoi, age) => `<div class="fp2-src">${pill}<div><span class="nm">${nom}</span> <span class="d">· ${quoi}</span></div><span class="mx-meta">${age}</span></div>`;
    const sources = `<section class="mx-sec"><div class="mx-chart-h"><h2>D’où viennent les chiffres</h2><span class="mx-meta">et leur âge</span></div><div>
        ${src(fp2Pill('base', 'ok'), 'Base du panneau', 'sites, comptes, bases, FTP, courrier, crons, analyses', _fp2Lu.summary ? jd(_fp2Lu.summary) : 'pas encore lue')}
        ${src(fp2Pill('API', 'info'), 'API du panneau', 'plans de sauvegarde, statistiques', 'cache 120 s')}
        ${src(fp2Pill('collecteur', 'info'), 'Collecteur de Cassandra', 'services installés, versions PHP, certificats', 'toutes les 5 min')}
        ${src(fp2Pill('sonde', 'avert'), 'Sonde 443', 'le certificat réellement servi, à la demande', _fp2Lu.sonde ? jd(_fp2Lu.sonde) : 'jamais cette session')}
      </div><div class="mx-foot"><span>Un chiffre sans source n’est pas affiché ; un vide lu avec succès se dit « aucun », jamais « – ».</span></div></section>`;
    const session = `<section class="mx-sec"><div class="mx-chart-h"><h2>Gestes de cette session</h2></div>
        ${_fp2Journal.length ? `<div class="mx-rows">${_fp2Journal.slice(-6).reverse().map(e => `<div class="mx-row"><span class="mx-meta">${escapeHtml(e.t)}</span><div class="mx-rt"><b>${escapeHtml(e.q)}</b></div><span></span></div>`).join('')}</div>` : `<div class="mx-silence">Aucun geste confirmé depuis l’ouverture.</div>`}
        <div class="mx-foot"><a class="fp2-lien" onclick="switchTab('journal')">Le journal complet est dans Journaux →</a></div></section>`;
    main.innerHTML = fp2VerdictHtml() + fp2GestesHtml() + sites + `<div class="mx-grid2">${sources}${session}</div>`;
}

// ── LES OPÉRATIONS : le catalogue mogwai, en page du rail, filtré par nature ──
let _fp2OpsFiltre = '';
async function fp2Ops(){
    const main = document.getElementById('fp-main-area'); if (!main) return;
    main.innerHTML = `<section class="mx-sec"><div class="mx-chart-h"><h2>Opérations</h2></div><div class="mx-attente">Lecture du catalogue…</div></section>`;
    try {
        const d = await apiPost('/api/fp/actions', {});
        if (_fpSection !== 'ops') return;
        if (d && d.ok === false) { main.innerHTML = `<section class="mx-sec"><div class="mx-chart-h"><h2>Opérations</h2></div><div class="mx-silence">${escapeHtml(d.reason || 'catalogue indisponible')}</div></section>`; return; }
        _fpData.ops = d.actions || []; _fpData.opsExclues = d.excluded || [];
        _fp2Lu.ops = Date.now();
        fp2OpsRendre();
    } catch(e) { main.innerHTML = `<section class="mx-sec"><div class="mx-chart-h"><h2>Opérations</h2></div><div class="mx-silence">Catalogue indisponible : ${escapeHtml(e.message || '')}</div></section>`; }
}
function fp2OpsNature(a){ return a.agent_blocked ? 'destructif' : a.heavy ? 'lourd' : a.modifies ? 'modifie' : 'lecture'; }
function fp2OpsFiltrer(n){ _fp2OpsFiltre = n; fp2OpsRendre(); }
function fp2OpsRendre(){
    const main = document.getElementById('fp-main-area'); if (!main) return;
    const A = _fpData.ops || [], ex = _fpData.opsExclues || [];
    const n = { lecture: 0, modifie: 0, lourd: 0, destructif: 0 }; A.forEach(a => n[fp2OpsNature(a)]++);
    const noms = { lecture: ['Lecture seule', 'ok'], modifie: ['Modifie', 'info'], lourd: ['Lourd', 'avert'], destructif: ['Destructif', 'erreur'] };
    const puces = `<button class="mx-per${!_fp2OpsFiltre ? ' on' : ''}" onclick="fp2OpsFiltrer('')">Toutes · ${A.length}</button>` + Object.keys(noms).map(k => `<button class="mx-per${_fp2OpsFiltre === k ? ' on' : ''}" onclick="fp2OpsFiltrer('${k}')">${noms[k][0]} · ${n[k]}</button>`).join('');
    const L = _fp2OpsFiltre ? A.filter(a => fp2OpsNature(a) === _fp2OpsFiltre) : A;
    const lignes = L.map(a => {
        const nat = fp2OpsNature(a), args = [a.needs_arg, a.needs_arg2].filter(Boolean);
        return `<div class="mx-row fp2-l">${fp2Pill(noms[nat][0].toLowerCase(), noms[nat][1])}<div class="mx-rt"><b><code>${escapeHtml(a.key)}</code></b><span>${escapeHtml(a.desc || '')}${args.length ? ' · demande : ' + escapeHtml(args.join(', ')) : ''}${(a.heavy || a.modifies) && !a.agent_blocked ? ' · accord requis' : ''}${a.agent_blocked ? ' · réservé à cette interface' : ''}</span></div>
          <button class="mx-btn" onclick="fpRunAction('${escapeAttr(a.key)}',${JSON.stringify(args).replace(/"/g, '&quot;')})">Lancer</button></div>`;
    }).join('');
    main.innerHTML = `<section class="mx-sec"><div class="mx-chart-h"><h2>Opérations</h2><span class="mx-meta">${A.length} · par mogwai, l’interface officielle du panneau${_fp2Lu.ops ? ' · lu à ' + fp2Heure(_fp2Lu.ops) : ''}</span></div>
      <p class="mx-prose">Aucune commande n’est composée à la volée : chaque opération est nommée, vérifiée, et passe par la feuille de confirmation puis le journal d’administration.</p>
      <div class="mx-periods">${puces}</div>
      <div id="fp-act-out"></div>
      ${lignes ? `<div class="mx-rows">${lignes}</div>` : `<div class="mx-silence">Aucune opération de cette nature.</div>`}
      ${ex.length ? `<div class="mx-foot" style="flex-direction:column;gap:4px"><span>Volontairement exclues du catalogue :</span>${ex.map(e => `<span><code>${escapeHtml(e.cmd)}</code> — ${escapeHtml(e.reason)}</span>`).join('')}</div>` : ''}
    </section>`;
}

// ── LA FEUILLE DE CONFIRMATION : remplace le confirm() natif des gestes ──
function fp2Confirm(message, titre){
    return new Promise(async resolve => {
        const fe = document.getElementById('fp2-feuille'), vo = document.getElementById('fp2-voile');
        if (!fe || !vo) { resolve(await buConfirmer(message)); return; }
        const lignes = String(message || '').split('\n').filter(Boolean);
        const question = lignes.length > 1 ? lignes.pop() : 'Confirmer ?';
        const acteur = (typeof currentUser === 'string' && currentUser) ? currentUser : 'toi';
        fe.innerHTML = `<h4>${escapeHtml(titre || 'Confirmer le geste')}</h4><p>${escapeHtml(lignes.join('\n'))}</p>
          <div class="apercu">journal → <b>${escapeHtml(question.replace(/\s*\?$/, ''))}</b> · acteur ${escapeHtml(acteur)} · ${fp2Heure()}</div>
          <div class="actions"><button class="fp-btn" onclick="fp2Fermer(false)">Annuler</button><button class="fp-btn primaire" onclick="fp2Fermer(true)">Confirmer</button></div>`;
        vo.classList.add('on');
        _fp2Confirm = { resolve, q: question };
    });
}
// LA FEUILLE QUI DEMANDE (maquette du 16-09) : un mot de passe administrateur, un mot à taper, un délai
// pendant lequel « Annuler » revient en arrière. Rend {ok, mdp, mot} — {ok:false} si l'on renonce.
let _fp2Demande = null;
function fp2Demander(message, titre, opts){
    opts = opts || {};
    return new Promise(async resolve => {
        const fe = document.getElementById('fp2-feuille'), vo = document.getElementById('fp2-voile');
        if (!fe || !vo) { resolve({ok: await buConfirmer(message), mdp: '', mot: ''}); return; }
        const lignes = String(message || '').split('\n').filter(Boolean);
        const question = lignes.length > 1 ? lignes.pop() : 'Confirmer ?';
        const acteur = (typeof currentUser === 'string' && currentUser) ? currentUser : 'toi';
        fe.innerHTML = `<h4>${escapeHtml(titre || 'Confirmer le geste')}</h4><p>${escapeHtml(lignes.join('\n'))}</p>`
          + (opts.mdp ? `<div class="s-field" style="margin-top:8px"><label class="s-label">Mot de passe administrateur</label><input class="s-input" type="password" id="fp2-mdp" autocomplete="current-password" placeholder="••••••••"></div>` : '')
          + (opts.mot ? `<div class="s-field" style="margin-top:8px"><label class="s-label">Tapez « ${escapeHtml(opts.mot)} »</label><input class="s-input mono" id="fp2-mot" autocomplete="off" placeholder="${escapeHtml(opts.mot)}"></div>` : '')
          + (opts.motif ? `<div class="s-field" style="margin-top:8px"><label class="s-label">Pourquoi ? (obligatoire, consigné au journal)</label><textarea class="s-input" id="fp2-motif" rows="2" placeholder="ex. connexion inconnue à 03:12, fichiers modifiés dans /var/www"></textarea></div>` : '')
          + `<div class="apercu">journal → <b>${escapeHtml(question.replace(/\s*\?$/, ''))}</b> · acteur ${escapeHtml(acteur)} · ${fp2Heure()}</div>`
          + (opts.garde ? `<div class="s-hint" id="fp2-garde" style="margin:6px 0 0">Garde de ${opts.garde} s après « ${escapeHtml(opts.ok || 'Confirmer')} » : « Annuler » arrête tout.</div>` : '')
          + `<div class="actions"><button class="fp-btn" onclick="fp2Fermer(false)">Annuler</button><button class="fp-btn primaire${opts.danger ? ' danger' : ''}" id="fp2-oui" ${(opts.mot || opts.motif) ? 'disabled' : ''} onclick="fp2Fermer(true)">${escapeHtml(opts.ok || 'Confirmer')}</button></div>`;
        vo.classList.add('on');
        if (opts.mot || opts.motif) {
            const im = document.getElementById('fp2-mot'), mo = document.getElementById('fp2-motif');
            const maj = () => { document.getElementById('fp2-oui').disabled = !!((im && im.value.trim() !== opts.mot) || (mo && mo.value.trim().length < 10)); };
            if (im) im.oninput = maj; if (mo) mo.oninput = maj;
        }
        _fp2Demande = { resolve, q: question, opts };
        _fp2Confirm = null;
    });
}
function fp2Fermer(ok){
    if (_fp2Demande) {
        const d = _fp2Demande;
        const mdp = (document.getElementById('fp2-mdp') || {}).value || '';
        const mot = (document.getElementById('fp2-mot') || {}).value || '';
        const motif = (document.getElementById('fp2-motif') || {}).value || '';
        if (ok && d.opts.mdp && !mdp) { const i = document.getElementById('fp2-mdp'); if (i) { i.focus(); i.style.borderColor = 'var(--danger)'; } return; }
        if (ok && d.opts.garde && !d.lance) {
            // le délai de garde : le geste part à la fin, « Annuler » l'arrête avant
            d.lance = true; const b = document.getElementById('fp2-oui'); if (b) b.disabled = true;
            let reste = d.opts.garde; const g = document.getElementById('fp2-garde');
            d.timer = setInterval(() => { reste--; if (g) g.textContent = 'Lancé dans ' + reste + ' s — « Annuler » revient en arrière.'; if (reste <= 0) { clearInterval(d.timer); fp2Fermer(true); } }, 1000);
            if (g) g.textContent = 'Lancé dans ' + reste + ' s — « Annuler » revient en arrière.';
            return;
        }
        if (d.timer) clearInterval(d.timer);
        const vo = document.getElementById('fp2-voile'); if (vo) vo.classList.remove('on');
        _fp2Demande = null;
        if (ok) _fp2Journal.push({ t: fp2Heure(), q: d.q.replace(/\s*\?$/, '') });
        d.resolve({ ok: !!ok, mdp: mdp, mot: mot, motif: motif.trim() });
        return;
    }
    const vo = document.getElementById('fp2-voile'); if (vo) vo.classList.remove('on');
    if (_fp2Confirm) { if (ok) _fp2Journal.push({ t: fp2Heure(), q: _fp2Confirm.q.replace(/\s*\?$/, '') }); _fp2Confirm.resolve(!!ok); _fp2Confirm = null; }
}
document.addEventListener('keydown', e => { if (e.key === 'Escape' && (_fp2Confirm || _fp2Demande)) fp2Fermer(false); });

function _fpPanneau(titre, contenu){
    // Les titres de modales gardaient leurs emojis (refonte du 19-09 : plus d'emoji en titre).
    titre = String(titre || '').replace(/^[^\p{L}\p{N}«»"'(]+/u, '');
    let o=document.getElementById('fp-modal');
    if(!o){
        o=document.createElement('div'); o.id='fp-modal';
        o.style.cssText='position:fixed;inset:0;background:rgba(16,24,40,.35);z-index:1200;display:flex;align-items:center;justify-content:center';
        o.onclick=(e)=>{ if(e.target===o) o.remove(); };
        // Échap ferme aussi : c'est le réflexe de tout le monde, et ça évite
        // qu'une modale reste posée sur la page sans qu'on sache pourquoi.
        o._esc=(e)=>{ if(e.key==='Escape'){ const m=document.getElementById('fp-modal');
                                            if(m) m.remove();
                                            document.removeEventListener('keydown', o._esc); } };
        document.addEventListener('keydown', o._esc);
        document.body.appendChild(o);
    }
    o.innerHTML=`<div style="background:var(--surface-solid);border:1px solid var(--line-strong);border-radius:14px;box-shadow:0 12px 40px rgba(16,24,40,.18);
        width:min(900px,94vw);max-height:86vh;display:flex;flex-direction:column;overflow:hidden">
      <div style="display:flex;gap:10px;align-items:center;padding:11px 16px;border-bottom:1px solid var(--ov-08)">
        <span style="flex:1;font-size:13px;font-weight:700;color:var(--txt-strong)">${escapeHtml(titre)}</span>
        <button class="fp-btn" onclick="document.getElementById('fp-modal').remove()">✕</button>
      </div>
      <div style="flex:1;min-height:0;overflow:auto;padding:14px 16px">${contenu}</div></div>`;
}

async function fpOpenPanel(){
    try{
        const d=await apiGet('/api/fp/panel');
        if(!d.url){
            buDire("L'adresse du panneau n'est pas renseignée.\n\nRéglages → FastPanel : indiquez par exemple https://mon-serveur:8888");
            return;
        }
        window.open(d.url, '_blank', 'noopener');
    }catch(e){ buDire('Erreur : '+e.message); }
}

// phpMyAdmin est servi par FastPanel lui-même : on repart de l'adresse du
// panneau plutôt que d'en deviner une. Le nom de la base est passé en
// paramètre `db`, que phpMyAdmin comprend pour ouvrir directement dessus.
async function fpPhpMyAdmin(nom){
    try{
        const d=await apiGet('/api/fp/panel');
        if(!d.url){
            buDire("L'adresse du panneau n'est pas renseignée.\n\n"
                 +"Réglages → Panneau d'hébergement : indiquez par exemple "
                 +"https://mon-serveur:8888");
            return;
        }
        const base=String(d.url).replace(/\/+$/,'');
        const u=base+'/phpmyadmin/'+(nom?('index.php?db='+encodeURIComponent(nom)):'');
        window.open(u, '_blank', 'noopener');
    }catch(e){ buDire('Erreur : '+e.message); }
}

// Une action qui modifie l'état du serveur répond 409 tant qu'elle n'est pas
// confirmée : la commande exacte est annoncée avant d'être lancée.
async function fpSvc(name, action){
    try{
        let r=await fetch('/api/fp/service/action',{method:'POST',
            headers:{'X-Session-Token':sessionId,'Content-Type':'application/json'},
            body:JSON.stringify({name:name, action:action})});
        let d=await r.json();
        if(r.status===409 && d.needs_confirm){
            if(!await fp2Confirm(d.reason+'\n\nContinuer ?')) return;
            r=await fetch('/api/fp/service/action',{method:'POST',
                headers:{'X-Session-Token':sessionId,'Content-Type':'application/json'},
                body:JSON.stringify({name:name, action:action, confirm:true})});
            d=await r.json();
        }
        if(d.vital){ buDire(d.reason); return; }
        const st=d.state||{};
        _fpPanneau((d.ok?'✅ ':'❌ ')+action+' — '+name,
            `<div style="font-size:12px;color:var(--txt-soft);margin-bottom:8px">
               État : <b style="color:${st.active==='active'?'var(--accent)':'var(--danger-soft)'}">${escapeHtml(st.active||'?')}</b>
               ${st.sub?'('+escapeHtml(st.sub)+')':''} · démarrage auto : ${escapeHtml(st.enabled||'?')}
               · code ${d.exit_code} · ${d.duration_ms||0} ms</div>
             <pre style="margin:0;white-space:pre-wrap;font-size:11px;color:var(--txt)">${escapeHtml(d.output||'(aucune sortie)')}</pre>`);
        fpLoadSection('services');
    }catch(e){ buDire('Erreur : '+e.message); }
}

// ── Opérations FastPanel ───────────────────────────────────────────────────
// Le registre existait côté serveur, avec ses garde-fous, mais rien ne
// l'exposait : l'onglet n'offrait donc aucun pouvoir d'action nouveau. C'est
// ici que les 23 opérations deviennent réellement utilisables.
// LES OPÉRATIONS sont une page du rail (19-09) ; ce nom reste pour qui l'appelait.
async function fpActions(){ fpNav('ops'); }

// Déclencheurs d'analyse : on choisit un SITE, pas un identifiant de
// configuration. La page se contentait de lister des rapports passés — souvent
// aucun — sans jamais permettre d'en produire un.
async function fpScanPanel(){
    _fpPanneau('🛡 Lancer une analyse antivirus', '<div style="color:var(--txt-muted)">Lecture des sites…</div>');
    try{
        const d=await apiPost('/api/fp/scans/targets',{});
        if(!d.ok || !(d.sites||[]).length){
            _fpPanneau('🛡 Lancer une analyse antivirus',
                `<div style="color:var(--warn);font-size:12px">${escapeHtml(d.reason||'aucun site')}</div>`);
            return;
        }
        const l=d.sites.map(s=>{
            const pret=!!s.config_id;
            const jours = s.last_scan
                ? Math.floor((Date.now()-Date.parse(s.last_scan.replace(' ','T')))/86400000) : null;
            const anc = (jours===null||!isFinite(jours)) ? 'jamais analysé'
                      : (jours>30 ? `il y a ${jours} j` : `il y a ${jours} j`);
            const coul = (jours===null) ? 'var(--warn)' : (jours>30 ? 'var(--danger-soft)' : 'var(--ok)');
            return `<tr>
              <td style="padding:5px 8px;font-size:12px;color:var(--txt)">${escapeHtml(s.domain)}</td>
              <td style="padding:5px 8px;font-size:11.5px;color:${coul}">${anc}</td>
              <td style="padding:5px 8px;font-size:11px;color:var(--txt-muted)">
                ${pret ? (s.enabled ? 'planifiée '+escapeHtml(s.planning||'') : 'configurée, non planifiée')
                       : 'aucune planification'}</td>
              <td style="padding:5px 8px;white-space:nowrap">
                <button class="fp-btn" onclick="fpScanRun('${escapeAttr(s.domain)}')">Analyser</button>
                ${s.reports ? `<button class="fp-btn secondary"
                    onclick="fpRapports('${escapeAttr(s.domain)}')"
                    title="${s.reports} rapport(s)">Rapports</button>` : ''}
                ${pret ? '' : `<button class="fp-btn secondary"
                    onclick="fpScanConfig('${escapeAttr(s.domain)}')"
                    title="Analyse automatique chaque semaine">Planifier</button>`}</td></tr>`;
        }).join('');
        _fpPanneau('🛡 Lancer une analyse antivirus', `
          <div style="font-size:11.5px;color:var(--txt-soft);margin-bottom:10px">
            ${d.sites.length} site(s). L'analyse tourne côté FastPanel et son rapport
            apparaîtra dans cette section une fois terminée.</div>
          <table style="width:100%;border-collapse:collapse">${l}</table>
          ${(d.unconfigured||[]).length?`<div style="font-size:10.5px;color:var(--txt-muted);margin-top:10px">
            « Analyser » lance une analyse immédiate, même sans planification.
            « Planifier » ajoute une analyse automatique hebdomadaire (dimanche 3 h).</div>`:''}
          <div id="fpscan-out" style="margin-top:12px"></div>`);
    }catch(e){
        _fpPanneau('🛡 Lancer une analyse antivirus',
            `<div style="color:var(--danger-soft)">${escapeHtml(e.message||'échec')}</div>`);
    }
}

function fpTailleOctets(n){
    if(!n && n!==0) return '';
    if(n < 1024) return n+' o';
    if(n < 1048576) return (n/1024).toFixed(0)+' Ko';
    return (n/1048576).toFixed(1)+' Mo';
}

async function fpRapports(domaine){
    const titre='📄 Rapports d\'analyse'+(domaine?' · '+domaine:'');
    _fpPanneau(titre, '<div style="color:var(--txt-muted)">Lecture du répertoire…</div>');
    try{
        const d=await apiPost('/api/fp/scans/reports',{});
        let liste=d.rapports||[];
        if(domaine) liste=liste.filter(r=>r.domain===domaine);
        if(!d.ok || !liste.length){
            _fpPanneau(titre, `<div style="color:var(--warn);font-size:12px">${
                escapeHtml(d.reason||'aucun rapport pour le moment')}</div>`);
            return;
        }
        const l=liste.map(r=>`<tr>
            <td style="padding:5px 8px;font-size:12px;color:var(--txt)">${escapeHtml(r.domain||r.nom)}</td>
            <td style="padding:5px 8px;font-size:11.5px;color:var(--txt-soft)">${escapeHtml(r.date||'')}</td>
            <td style="padding:5px 8px;font-size:11px;color:var(--txt-muted)">${fpTailleOctets(r.taille)}</td>
            <td style="padding:5px 8px;white-space:nowrap">
              <button class="fp-btn" onclick="fpRapportVoir('${escapeAttr(r.chemin)}')">
                Ouvrir</button></td></tr>`).join('');
        _fpPanneau(titre, `
          <div style="font-size:11.5px;color:var(--txt-soft);margin-bottom:10px">
            ${liste.length} rapport(s)${domaine?'':' · tous sites'}.
            Ils sont affichés en bac à sable : leur contenu cite du code
            malveillant, il n'est jamais exécuté.</div>
          <table style="width:100%;border-collapse:collapse">${l}</table>
          <div id="fprap-out" style="margin-top:12px"></div>`);
    }catch(e){
        _fpPanneau(titre, `<div style="color:var(--danger-soft)">${escapeHtml(e.message||'échec')}</div>`);
    }
}

async function fpRapportVoir(chemin){
    const z=document.getElementById('fprap-out');
    if(z) z.innerHTML='<div style="color:var(--txt-muted);font-size:12px">Lecture du rapport…</div>';
    try{
        const d=await apiPost('/api/fp/scans/report',{path:chemin});
        if(!d.ok){
            if(z) z.innerHTML=`<div style="color:var(--danger-soft);font-size:12px">${
                escapeHtml(d.reason||'lecture impossible')}</div>`;
            return;
        }
        const r=d.resume||{};
        // Un compteur absent vaut « inconnu », jamais zéro : afficher « 0 fichier
        // malveillant » sur une lecture ratée donnerait une fausse assurance.
        const chiffre=(v,lib,coul)=> (v===null||v===undefined) ? '' :
            `<span style="margin-right:14px;color:${v>0?coul:'var(--ok)'};font-size:12px">
               <b>${v}</b> ${lib}</span>`;
        const fic=(r.fichiers||[]);
        _fpPanneau('📄 '+escapeHtml(d.nom||'rapport'), `
          <div style="margin-bottom:10px">
            ${chiffre(r.malveillants,'malveillant(s)','var(--danger-soft)')}
            ${chiffre(r.suspects,'suspect(s)','var(--warn)')}
            ${chiffre(r.analyses,'fichier(s) analysé(s)','var(--txt-soft)')}
            <span style="color:var(--txt-muted);font-size:11px">${escapeHtml(d.modifie||'')} ·
              ${fpTailleOctets(d.taille)}${d.tronque?' · tronqué':''}</span>
          </div>
          ${fic.length?`<details style="margin-bottom:10px">
            <summary style="cursor:pointer;font-size:11.5px;color:var(--txt-soft)">
              ${r.fichiers_total} chemin(s) cité(s) — voir les ${fic.length} premiers</summary>
            <div style="max-height:150px;overflow:auto;margin-top:6px;font-size:11px;
                        color:var(--txt-muted);font-family:ui-monospace,monospace">
              ${fic.map(f=>escapeHtml(f)).join('<br>')}</div></details>`:''}
          <iframe sandbox="" referrerpolicy="no-referrer"
                  style="width:100%;height:60vh;min-height:320px;border:1px solid var(--line);
                         border-radius:6px;background:var(--on-accent)"
                  srcdoc="${escapeAttr(fpRapportEnvelopper(d.html||''))}"></iframe>
          <div style="font-size:10.5px;color:var(--txt-muted);margin-top:8px">
            ${escapeHtml(d.chemin||'')}</div>
          <div style="margin-top:10px">
            <button class="fp-btn secondary" onclick="fpRapports()">← Tous les rapports</button>
          </div>`);
    }catch(e){
        if(z) z.innerHTML=`<div style="color:var(--danger-soft);font-size:12px">${
            escapeHtml(e.message||'échec')}</div>`;
    }
}

// Même principe que le lecteur de courrier : iframe `sandbox=""`, donc ni
// script, ni formulaire, ni navigation, ni accès à la session de Cassandra. Le
// serveur a déjà retiré les balises exécutables — deux verrous plutôt qu'un,
// parce qu'ici le contenu est hostile par construction.
function fpRapportEnvelopper(h){
    return '<!doctype html><meta charset="utf-8">'+
        // Document isolé : les jetons de la page ne franchissent pas l'iframe.
        // `var(--txt)` n'y vaut rien — la bordure était donc simplement absente.
        '<style>body{font:12px/1.5 system-ui,sans-serif;color:#111;background:#fff;margin:10px}'+
        'img{max-width:100%;height:auto}table{max-width:100%;border-collapse:collapse}'+
        'td,th{padding:3px 6px;border:1px solid #d0d0d0;font-size:11px;word-break:break-all}'+
        'pre{white-space:pre-wrap;word-break:break-all;background:#f6f6f6;padding:6px}</style>'+
        (h||'<p>Rapport vide.</p>');
}

async function fpScanRun(domaine){
    const out=document.getElementById('fpscan-out');
    const dire=(t,err)=>{ if(out) out.innerHTML=
        `<div style="font-size:11.5px;color:${err?'var(--danger-soft)':'var(--ok)'};white-space:pre-wrap">${escapeHtml(t)}</div>`; };
    dire('Lancement sur '+domaine+'…');
    try{
        const corps={domain:domaine};
        let r=await fetch('/api/fp/scans/run',{method:'POST',
            headers:{'X-Session-Token':sessionId,'Content-Type':'application/json'},
            body:JSON.stringify(corps)});
        let d=await r.json();
        if(r.status===409 && d.needs_confirm){
            if(!await fp2Confirm(d.reason+'\n\nLancer l\'analyse de '+domaine+' ?')){ dire(''); return; }
            corps.confirm=true;
            r=await fetch('/api/fp/scans/run',{method:'POST',
                headers:{'X-Session-Token':sessionId,'Content-Type':'application/json'},
                body:JSON.stringify(corps)});
            d=await r.json();
        }
        // Le détail (URL essayée, sonde voisine, base authentifiée) est
        // précisément ce qui permet de comprendre un refus : l'omettre obligeait
        // à redemander l'information à l'utilisateur.
        dire(d.ok ? ('✓ Analyse lancée sur '+domaine+'. Le rapport apparaîtra ici une fois terminée.')
                  : ('✗ '+(d.reason||d.output||'échec')
                     +(d.detail ? '\n'+d.detail : '')), !d.ok);
        if(d.ok) setTimeout(()=>fpLoadSection('scans'), 1500);
    }catch(e){ dire('✗ '+e.message, true); }
}

async function fpScanConfig(domaine){
    const out=document.getElementById('fpscan-out');
    const dire=(t,err)=>{ if(out) out.innerHTML=
        `<div style="font-size:11.5px;color:${err?'var(--danger-soft)':'var(--ok)'};white-space:pre-wrap">${escapeHtml(t)}</div>`; };
    try{
        const corps={domain:domaine};
        let r=await fetch('/api/fp/scans/configure',{method:'POST',
            headers:{'X-Session-Token':sessionId,'Content-Type':'application/json'},
            body:JSON.stringify(corps)});
        let d=await r.json();
        if(r.status===409 && d.needs_confirm){
            if(!await fp2Confirm(d.reason+'\n\nCréer cette planification ?')) return;
            corps.confirm=true;
            r=await fetch('/api/fp/scans/configure',{method:'POST',
                headers:{'X-Session-Token':sessionId,'Content-Type':'application/json'},
                body:JSON.stringify(corps)});
            d=await r.json();
        }
        dire(d.ok ? ('✓ '+(d.output||'planifiée'))
                  : ('✗ '+(d.reason||'échec')+(d.detail?'\n'+d.detail:'')), !d.ok);
        if(d.ok) fpScanPanel();
    }catch(e){ dire('✗ '+e.message, true); }
}

// Création d'une base : la seule opération que `mogwai` ne sait pas faire. Elle
// passe par l'API du panneau, pour que FastPanel en ait connaissance — créer la
// base directement dans MySQL la rendrait invisible du panneau, donc absente de
// ses sauvegardes et de ses quotas.
async function fpDbCreate(){
    _fpPanneau('Créer une base de données', '<div class="mx-attente">Lecture des serveurs et des utilisateurs…</div>');
    let d = {};
    try { d = await apiPost('/api/fp/db/users', {}); } catch(e) { d = {}; }
    const users = d.utilisateurs || [], srv = d.serveurs || [], comptes = d.comptes || [];
    _fpPanneau('Créer une base de données', `
      <div class="mx-note" style="margin-bottom:10px">La base est créée <b>via le panneau</b>, qui l’enregistre dans son inventaire : elle entre dans ses sauvegardes et ses quotas. Une base a besoin d’un <b>utilisateur MySQL</b> : un existant, ou un nouveau dont le mot de passe est généré et montré une seule fois.</div>
      <div class="fp2-form">
        <input id="fpdb-nom" class="mx-select" placeholder="nom de la base" autocomplete="off" aria-label="Nom de la base" style="min-width:200px">
        <select id="fpdb-user" class="mx-select" aria-label="Utilisateur MySQL" onchange="const n=document.getElementById('fpdb-newuser'); if(n) n.hidden=!!this.value;"><option value="">nouvel utilisateur…</option>${users.map(u => `<option value="${escapeAttr(String(u.id))}">${escapeHtml(u.login)}${u.owner ? ' · ' + escapeHtml(u.owner) : ''}</option>`).join('')}</select>
        <input id="fpdb-newuser" class="mx-select" placeholder="identifiant du nouvel utilisateur (défaut : le nom de la base)" autocomplete="off" aria-label="Nouvel utilisateur" style="min-width:260px">
        ${comptes.length > 1 ? `<select id="fpdb-owner" class="mx-select" aria-label="Compte propriétaire">${comptes.map(c => `<option value="${escapeAttr(String(c.id))}">pour ${escapeHtml(c.username)}</option>`).join('')}</select>` : ''}
        ${srv.length > 1 ? `<select id="fpdb-srv" class="mx-select" aria-label="Serveur">${srv.map(x => `<option value="${escapeAttr(String(x.id))}"${x.use_as_default ? ' selected' : ''}>${escapeHtml(x.name || ('serveur ' + x.id))}</option>`).join('')}</select>` : ''}
        <button class="mx-btn primary" onclick="fpDbCreateGo()">Créer</button>
      </div>
      <div id="fpdb-out" style="margin-top:12px"></div>`);
    setTimeout(()=>{ const i=document.getElementById('fpdb-nom'); if(i) i.focus(); }, 60);
}

async function fpDbCreateGo(){
    const v = id => (document.getElementById(id) || {}).value || '';
    const nom = v('fpdb-nom').trim(), user = v('fpdb-user'), nouveau = v('fpdb-newuser').trim(), owner = v('fpdb-owner'), srv = v('fpdb-srv');
    const out=document.getElementById('fpdb-out');
    const dire=(t,err)=>{ if(out) out.innerHTML=`<div class="${err?'mx-silence':'mx-note'}"${err?'':' style="color:var(--ok)"'}>${escapeHtml(t)}</div>`; };
    if(!nom){ dire('Indiquez un nom de base.', true); return; }
    dire('Création en cours…');
    const corps = { name: nom, server_id: srv, user_id: user, new_user: user ? '' : nouveau, owner_id: owner };
    try{
        let d = await apiPost('/api/fp/db/create', corps);
        if(d.needs_confirm){
            if(!await fp2Confirm(d.reason+'\n\nCréer cette base ?', 'Nouvelle base')){ dire(''); return; }
            d = await apiPost('/api/fp/db/create', Object.assign({ confirm: true }, corps));
        }
        if(d.ok){
            // LE MOT DE PASSE, UNE SEULE FOIS : il n'est ni journalisé ni renvoyé ailleurs.
            if(out) out.innerHTML = `<div class="mx-note" style="color:var(--ok)">${escapeHtml(d.output || ('Base « ' + nom + ' » créée.'))}</div>`
                + (d.mot_de_passe ? `<div class="mx-silence" style="margin-top:8px"><b>Mot de passe de « ${escapeHtml(d.utilisateur || '')} »</b> — montré une seule fois, rangez-le dans le coffre : <code id="fpdb-mdp" style="user-select:all">${escapeHtml(d.mot_de_passe)}</code> <button class="mx-btn" onclick="navigator.clipboard&&navigator.clipboard.writeText(document.getElementById('fpdb-mdp').textContent).then(()=>{ if(typeof showToast==='function') showToast('Mot de passe copié','success',2500); })">Copier</button></div>` : '');
            fpLoadSection('databases');
        }else{
            dire('✗ '+(d.reason||'échec')+(d.detail?'\n'+d.detail:'')+(d.status?'\n(code '+d.status+')':''), true);
        }
    }catch(e){ dire('✗ '+e.message, true); }
}

// Ouvre une section en la filtrant : c'est ce qui relie les pages entre elles.
// « Les sites de fastuser », « les bases de fastuser », « qui utilise PHP 8.3 »
// étaient des questions sans réponse tant que chaque page restait isolée.
function fpVoir(section, filtre){
    fpNav(section);
    setTimeout(()=>{
        const i=document.getElementById('fp-rech');
        if(i){ i.value=filtre||''; fp2Filtrer(i.value); }
    }, 260);
}

// La suppression d'une base passe par l'API du panneau : mogwai ne sait pas le
// faire. On demande l'identifiant plutôt que de le deviner à partir du nom.
async function fpDbDrop(nom, ident){
    // L'identifiant vient de la ligne (20-09) ; on ne le demande que s'il manque vraiment.
    let id = String(ident || '').trim();
    if(!id){ const r=(_fpData.databases||[]).find(x => String(x.name) === String(nom)); if(r && r.id != null) id = String(r.id); }
    if(!id){
        id=await buSaisir('Supprimer la base « '+nom+' ».\n\nIdentifiant FastPanel de la base '
                    +'(visible dans le panneau) :');
        if(id===null || !id.trim()) return;
    }
    try{
        let r=await fetch('/api/fp/db/delete',{method:'POST',
            headers:{'X-Session-Token':sessionId,'Content-Type':'application/json'},
            body:JSON.stringify({id:id.trim()})});
        let d=await r.json();
        if(r.status===409 && d.needs_confirm){
            if(!await fp2Confirm(d.reason+'\n\nConfirmer la suppression ?')) return;
            r=await fetch('/api/fp/db/delete',{method:'POST',
                headers:{'X-Session-Token':sessionId,'Content-Type':'application/json'},
                body:JSON.stringify({id:id.trim(), confirm:true})});
            d=await r.json();
        }
        buDire(d.ok ? 'Base supprimée.' : ('Échec : '+(d.reason||d.detail||'inconnu')));
        if(d.ok) fpLoadSection('databases');
    }catch(e){ buDire('Erreur : '+e.message); }
}

async function fpRunAction(cle, args){
    const out=document.getElementById('fp-act-out');
    const val={};
    for(const nom of (args||[])){
        const v=await buSaisir('Paramètre « '+nom+' » pour l\'opération '+cle+' :');
        if(v===null) return;
        val[nom==='id'||nom==='domaine'?'arg':'arg2']=v.trim();
    }
    if(out) out.innerHTML='<div style="color:var(--txt-muted);font-size:11.5px">Exécution…</div>';
    try{
        const corps={action:cle, arg:val.arg||'', arg2:val.arg2||''};
        let r=await fetch('/api/fp/act',{method:'POST',
            headers:{'X-Session-Token':sessionId,'Content-Type':'application/json'},
            body:JSON.stringify(corps)});
        let d=await r.json();
        if(r.status===409 && d.needs_confirm){
            if(!await fp2Confirm(d.reason+'\n\n'+(d.command||'')+'\n\nContinuer ?')){
                if(out) out.innerHTML=''; return;
            }
            corps.confirm=true;
            r=await fetch('/api/fp/act',{method:'POST',
                headers:{'X-Session-Token':sessionId,'Content-Type':'application/json'},
                body:JSON.stringify(corps)});
            d=await r.json();
        }
        if(!out) return;
        out.innerHTML=`<div style="font-size:10px;color:${d.ok?'var(--ok)':'var(--danger-soft)'};font-weight:700">
              ${escapeHtml(cle)} · ${d.ok?'réussi':'échec'} ${d.duration_ms!==undefined?'· '+d.duration_ms+' ms':''}</div>
            <div style="font-size:10.5px;color:var(--txt-faint);font-family:monospace">${escapeHtml(d.command||'')}</div>
            ${d.reason?`<div style="color:var(--danger-soft);font-size:11.5px;margin-top:4px;white-space:pre-wrap">${escapeHtml(d.reason)}${d.detail?'\n'+escapeHtml(d.detail):''}</div>`:''}
            <pre style="margin:6px 0 0;white-space:pre-wrap;font-size:11px;color:var(--txt);max-height:280px;overflow:auto">${escapeHtml(d.output||(d.data?JSON.stringify(d.data,null,1).slice(0,3000):'(aucune sortie)'))}</pre>`;
    }catch(e){
        if(out) out.innerHTML=`<div style="color:var(--danger-soft)">${escapeHtml(e.message)}</div>`;
    }
}

// ── WebSocket derrière nginx ───────────────────────────────────────────────
// Le vhost proxifie sans les en-têtes d'upgrade : le terminal et les mises à
// jour en direct ne peuvent pas s'établir. On montre l'état réel, fichier par
// fichier, plutôt qu'un voyant vert ou rouge qui n'apprend rien.
// UN RENVOI, PAS UN SECOND PANNEAU. Le WebSocket se règle dans
// Paramètres → Système : c'est de la configuration nginx. Ce bouton reste
// parce qu'un relais qui tombe se cherche depuis FastPanel — mais il MÈNE à
// la carte, il ne redit plus ce qu'elle dit. Deux surfaces pour un même fait
// finissent par diverger, et celles-ci avaient déjà divergé.
function fpWebsocket(){
    if(typeof switchTab === 'function') switchTab('settings');
    if(typeof setVision === 'function'){ try{ setVision('machine'); }catch(e){} }
    ETAT.reglages._setOuvrir = 'sec-websocket';
    if(typeof setFam === 'function'){ try{ setFam('maintenance'); }catch(e){} }
    // La carte se recharge et se montre : arriver sur la bonne famille sans
    // savoir laquelle des cinq sections regarder ne vaut pas mieux qu'un
    // renvoi vers l'écran entier.
    setTimeout(function(){
        try{ cfgWsEtat(true); }catch(e){}
        const z = document.getElementById('cfg-ws-etat');
        if(z && z.scrollIntoView) z.scrollIntoView({block: 'center'});
    }, 120);
}

function fpWsEpreuve(){
    return new Promise(function(res){
        let ws = null, fini = false, ouvert = 0, recus = 0;
        const debut = Date.now();
        const rendre = function(ok, raison){
            if(fini) return;
            fini = true;
            try{ if(ws) ws.close(); }catch(e){}
            // CE QU'ON A CONSTATÉ, pas ce qu'on en conclut : le temps mis à
            // ouvrir, le temps tenu, et le nombre de messages réellement
            // arrivés. Une affirmation et une mesure se ressemblent tant que
            // la mesure ne montre rien.
            res({ok: ok, raison: raison || '',
                 ouverture: ouvert ? (ouvert - debut) : 0,
                 tenue: ouvert ? (Date.now() - ouvert) : 0,
                 recus: recus});
        };
        try{
            const u = (location.protocol === 'https:' ? 'wss://' : 'ws://') +
                      location.host + '/ws?token=' + encodeURIComponent(sessionId);
            ws = new WebSocket(u);
        }catch(e){ rendre(false, 'ouverture refusée'); return; }
        ws.onerror = function(){ rendre(false, 'connexion refusée'); };
        ws.onclose = function(ev){
            rendre(false, 'fermée aussitôt (code ' + (ev && ev.code) + ')');
        };
        ws.onmessage = function(){ recus++; };
        ws.onopen = function(){
            ouvert = Date.now();
            // TENUE TROIS SECONDES. Une connexion qui tombe dans la seconde
            // n'est pas une connexion : c'est ce qu'on cherche à détecter.
            setTimeout(function(){
                if(ws && ws.readyState === 1) rendre(true, '');
            }, 3000);
        };
        setTimeout(function(){ rendre(false, 'aucune réponse en 8 s'); }, 8000);
    });
}

async function fpSvcDiag(name){
    _fpPanneau('🩺 Diagnostic — '+name, '<div style="color:var(--txt-muted)">Analyse en cours…</div>');
    try{
        const d=await apiPost('/api/fp/service/diagnose',{name:name});
        if(!d.ok){ _fpPanneau('🩺 '+name, '<div style="color:var(--danger-soft)">'+escapeHtml(d.reason||'échec')+'</div>'); return; }
        const st=d.state||{}, cc=d.config_check||{};
        _fpPanneau('🩺 Diagnostic — '+name, `
          <div style="font-size:12px;color:var(--txt-soft);margin-bottom:10px">
            État : <b style="color:${st.active==='active'?'var(--accent)':'var(--danger-soft)'}">${escapeHtml(st.active||'?')}</b>
            ${st.sub?'('+escapeHtml(st.sub)+')':''} · démarrage auto : ${escapeHtml(st.enabled||'?')}
            ${st.since?'<br>Depuis : '+escapeHtml(st.since):''}</div>
          ${cc.cmd?`<div style="margin-bottom:10px"><div style="font-size:10px;color:var(--accent-soft);font-weight:700">CONFIGURATION — ${escapeHtml(cc.cmd)}</div>
            <pre style="margin:4px 0 0;white-space:pre-wrap;font-size:11px;color:${cc.exit_code===0?'var(--accent)':'var(--danger-soft)'}">${escapeHtml(cc.output||cc.error||'')}</pre></div>`:''}
          ${(d.recent_errors||[]).length?`<div style="margin-bottom:10px"><div style="font-size:10px;color:var(--danger-soft);font-weight:700">ERREURS RÉCENTES</div>
            <pre style="margin:4px 0 0;white-space:pre-wrap;font-size:11px;color:#ffb3b3">${escapeHtml(d.recent_errors.join('\n'))}</pre></div>`:''}
          <div style="font-size:10px;color:var(--accent-soft);font-weight:700">JOURNAL</div>
          <pre style="margin:4px 0 0;white-space:pre-wrap;font-size:10.5px;color:#a9bdb6">${escapeHtml(d.logs||'(vide)')}</pre>`);
    }catch(e){ _fpPanneau('🩺 '+name, '<div style="color:var(--danger-soft)">Erreur réseau</div>'); }
}

async function fpSslCheck(domain){
    _fpPanneau('🔒 Certificat — '+domain, '<div style="color:var(--txt-muted)">Interrogation du serveur…</div>');
    try{
        const d=await apiPost('/api/fp/ssl/check',{domain:domain});
        if(!d.ok){
            _fpPanneau('🔒 '+domain, `<div style="color:var(--danger-soft);margin-bottom:10px">Aucun certificat exploitable : ${escapeHtml(d.reason||'')}</div>
              <button class="fp-btn" onclick="fpSslIssue('${escapeAttr(domain)}')">Demander un certificat Let's Encrypt</button>`);
            return;
        }
        const j=d.days_left;
        _fpPanneau('🔒 Certificat — '+domain, `
          <div style="font-size:12px;color:var(--txt-soft);line-height:1.7">
            Expire le <b>${escapeHtml(d.expires||'?')}</b>
            — <b style="color:${j>30?'var(--accent)':(j>0?'var(--warn)':'var(--danger-soft)')}">${j!=null?j+' jour(s)':'?'}</b><br>
            Émetteur : ${escapeHtml(d.issuer||'?')}<br>
            Couvre : ${escapeHtml((d.names||[]).join(', ')||'?')}</div>
          <div style="margin-top:12px"><button class="fp-btn" onclick="fpSslIssue('${escapeAttr(domain)}')">Renouveler maintenant</button></div>
          <div style="margin-top:8px;font-size:10.5px;color:var(--txt-faint)">Lecture directe du certificat servi sur le port 443 — c'est ce que voit un visiteur.</div>`);
    }catch(e){ _fpPanneau('🔒 '+domain, '<div style="color:var(--danger-soft)">Erreur réseau</div>'); }
}

async function fpSslIssue(domain){
    try{
        let r=await fetch('/api/fp/ssl/issue',{method:'POST',
            headers:{'X-Session-Token':sessionId,'Content-Type':'application/json'},
            body:JSON.stringify({domain:domain})});
        let d=await r.json();
        if(r.status===409 && d.needs_confirm){
            if(!await fp2Confirm(d.reason+'\n\nLancer la demande ?')) return;
            _fpPanneau('🔒 '+domain, '<div style="color:var(--txt-muted)">certbot travaille — cela peut prendre une minute…</div>');
            r=await fetch('/api/fp/ssl/issue',{method:'POST',
                headers:{'X-Session-Token':sessionId,'Content-Type':'application/json'},
                body:JSON.stringify({domain:domain, confirm:true})});
            d=await r.json();
        }
        _fpPanneau((d.ok?'✅ ':'❌ ')+'Certificat — '+domain,
            `<pre style="margin:0;white-space:pre-wrap;font-size:11px;color:var(--txt)">${escapeHtml(d.output||d.reason||'')}</pre>`);
        fpLoadSection('domains');
    }catch(e){ buDire('Erreur : '+e.message); }
}

// Le désenclavement, vu de l'utilisateur : un domaine et tout ce que Cassandra
// sait déjà de lui, au lieu de quatre écrans à ouvrir un par un.
async function fpDomCtx(domain){
    _fpPanneau('🔗 '+domain, '<div style="color:var(--txt-muted)">Rassemblement des informations…</div>');
    try{
        const d=await apiPost('/api/fp/domain/context',{domain:domain});
        if(!d.ok){ _fpPanneau('🔗 '+domain, '<div style="color:var(--danger-soft)">'+escapeHtml(d.reason||'échec')+'</div>'); return; }
        const bloc=(t,c)=>`<div style="margin-bottom:12px"><div style="font-size:10px;color:var(--accent-soft);font-weight:700;margin-bottom:4px">${t}</div>${c}</div>`;
        const vide='<div style="font-size:11px;color:var(--txt-faint)">—</div>';
        const p=d.project;
        _fpPanneau('🔗 '+domain,
          bloc('PROJET', (p?`<div style="font-size:12px;color:var(--txt-strong)">${escapeHtml(p.name)}
                <span style="color:var(--txt-faint);font-size:10.5px">${escapeHtml(p.kind||'')}</span></div>`
              :'<div style="font-size:11px;color:var(--txt-faint)">Aucun projet ne porte ce domaine.</div>')
              // Constater un manque sans pouvoir le combler oblige à quitter
              // l'onglet : le rattachement se fait ici, sur la fiche.
              +`<div style="margin-top:6px;display:flex;gap:6px;flex-wrap:wrap">
                  <input id="fpdc-proj" list="fpdc-projets" placeholder="${
                     p?'changer de projet…':'nom du projet…'}"
                     style="flex:1;min-width:150px;background:var(--surface);border:1px solid var(--line);
                            border-radius:5px;color:var(--txt);font-size:11.5px;padding:4px 7px">
                  <datalist id="fpdc-projets">${(d.projects_all||[]).map(x=>
                     `<option value="${escapeAttr(x.name||'')}">`).join('')}</datalist>
                  <button class="fp-btn" onclick="fpDomAttach('${escapeAttr(domain)}')">
                    ${p?'Rattacher':'Créer et rattacher'}</button>
                </div>
                ${p ? `<div style="margin-top:6px;display:flex;gap:6px">
                  <input id="fpdc-note" placeholder="ajouter une note au projet…"
                     style="flex:1;background:var(--surface);border:1px solid var(--line);border-radius:5px;
                            color:var(--txt);font-size:11.5px;padding:4px 7px">
                  <button class="fp-btn secondary"
                     onclick="fpDomAttach('${escapeAttr(domain)}',true)">Noter</button>
                </div>` : ''}
                <div id="fpdc-out" style="margin-top:5px"></div>`)+
          bloc('À PRÉVENIR', (d.contacts||[]).length?(d.contacts||[]).map(c=>
              `<div style="font-size:11.5px;color:var(--txt)">${escapeHtml(c.display_name||'?')}
                 <span style="color:var(--warn);font-size:10px">${escapeHtml(c.role||'')}</span></div>`).join(''):vide)+
          bloc('CERTIFICAT SERVI', d.ssl_live&&d.ssl_live.ok?
              `<div style="font-size:11.5px;color:var(--txt)">${escapeHtml(d.ssl_live.expires||'')}
                 — ${d.ssl_live.days_left} jour(s) · ${escapeHtml(d.ssl_live.issuer||'')}</div>`
              :`<div style="font-size:11px;color:var(--danger-soft)">${escapeHtml((d.ssl_live||{}).reason||'non vérifiable')}</div>`)+
          bloc('TÂCHES OUVERTES', (d.tasks||[]).length?(d.tasks||[]).map(t=>
              `<div style="font-size:11.5px;color:var(--txt)">· ${escapeHtml(t.text||'')}
                 <span style="color:var(--txt-faint);font-size:10px">${escapeHtml(t.due_at||'')}</span></div>`).join(''):vide)+
          bloc('TÂCHES PLANIFIÉES', (d.crons||[]).length?(d.crons||[]).map(c=>
              `<div style="font-size:11px;color:var(--txt)">· ${escapeHtml(c.human||'')} —
                 <span style="color:var(--txt-faint);font-family:monospace">${escapeHtml((c.command||'').slice(0,70))}</span></div>`).join(''):vide)+
          bloc('SAUVEGARDES', (d.backups||[]).length?`<div style="font-size:11px;color:var(--txt)">${d.backups.length} copie(s) couvrant ce domaine — ${(d.backups[0]||{}).compte ? 'celles du compte ' + escapeHtml((d.backups[0]||{}).compte) + ', ' : ''}dernière le ${escapeHtml(String((d.backups[0]||{}).created_at||'').slice(0,16))}</div>`:vide)+
          bloc('FILS DE DISCUSSION', (d.mail_threads||[]).length?(d.mail_threads||[]).map(t=>
              `<div style="font-size:11.5px;color:var(--txt)">· ${escapeHtml(t.subject||'')}</div>`).join(''):vide));
    }catch(e){ _fpPanneau('🔗 '+domain, '<div style="color:var(--danger-soft)">Erreur réseau</div>'); }
}

// Le pont entre les deux mondes : un compte Cassandra adossé à un compte
// FastPanel hérite des sites que celui-ci possède — y compris ceux ajoutés
// plus tard. C'est l'intérêt, et la raison pour laquelle le lien se pose à la
// main : il donne des accès, ce n'est pas à la machine de le décider.
async function fpLiens(prefill){
    _fpPanneau('🔗 Comptes Cassandra ↔ FastPanel',
        '<div style="color:var(--txt-muted)">Lecture des comptes…</div>');
    try{
        const d=await apiPost('/api/fp/users/links',{});
        if(!d.ok){
            _fpPanneau('🔗 Comptes Cassandra ↔ FastPanel',
                `<div style="color:var(--warn);font-size:12px">${escapeHtml(d.reason||'indisponible')}</div>`);
            return;
        }
        const comptes=d.comptes||[];
        const sugg={};
        (d.suggestions||[]).forEach(s=>{ sugg[s.user]={c:s.fp_account,m:s.motif,n:(s.sites||[]).length}; });
        const l=(d.users||[]).map(u=>{
            const s=sugg[u.user];
            const val=u.fp_account||(prefill&&!u.fp_account?prefill:'')||'';
            return `<tr>
              <td style="padding:6px 8px;font-size:11.5px;color:var(--txt);vertical-align:top">
                ${escapeHtml(u.user)}
                <div style="font-size:10px;color:var(--txt-faint)">
                  ${u.explicites.length} saisi(s)${
                  u.herites.length?` · <span style="color:var(--ok)">${u.herites.length} hérité(s)</span>`:''}</div>
                ${u.herites.length?`<div style="font-size:10px;color:var(--txt-faint)">${
                  u.herites.map(x=>escapeHtml(x)).join(', ')}</div>`:''}
                ${(!u.fp_account&&s)?`<div style="font-size:10px;color:var(--info);margin-top:2px">
                  Suggestion : <b>${escapeHtml(s.c)}</b> (${escapeHtml(s.m)}, ${s.n} site(s))</div>`:''}
              </td>
              <td style="padding:6px 8px;vertical-align:top">
                <select id="lnk-${escapeAttr(u.user)}"
                  style="background:var(--surface);border:1px solid var(--line);border-radius:5px;
                         color:var(--txt);font-size:11.5px;padding:4px 7px;min-width:130px">
                  <option value="">— aucun —</option>
                  ${comptes.map(c=>`<option value="${escapeAttr(c)}"${
                    (val===c||(!val&&s&&s.c===c))?' selected':''}>${escapeHtml(c)}</option>`).join('')}
                </select>
              </td>
              <td style="padding:6px 8px;vertical-align:top;white-space:nowrap">
                <button class="fp-btn" onclick="fpLierUser('${escapeAttr(u.user)}')">Appliquer</button>
              </td></tr>`;
        }).join('');
        _fpPanneau('🔗 Comptes Cassandra ↔ FastPanel', `
          <div style="font-size:11.5px;color:var(--txt-soft);margin-bottom:10px">
            Un compte adossé reprend automatiquement les sites de son compte
            FastPanel — <b>y compris ceux créés plus tard</b>. Les domaines saisis
            à la main sont conservés en plus.</div>
          <table style="width:100%;border-collapse:collapse">${l}</table>
          <div id="fplnk-out" style="margin-top:10px"></div>`);
    }catch(e){
        _fpPanneau('🔗 Comptes Cassandra ↔ FastPanel',
            '<div style="color:var(--danger-soft)">Erreur réseau</div>');
    }
}

async function fpLierUser(user){
    const z=document.getElementById('fplnk-out');
    const sel=document.getElementById('lnk-'+user);
    const compte=sel?sel.value:'';
    if(z) z.innerHTML='<div style="font-size:11px;color:var(--txt-muted)">Enregistrement…</div>';
    try{
        const d=await apiPost('/api/fp/users/link',{user:user, fp_account:compte});
        if(z) z.innerHTML=`<div style="font-size:11px;color:${d.ok?'var(--ok)':'var(--danger-soft)'}">${
            escapeHtml(d.output||d.error||d.reason||'')}</div>`;
        if(d.ok) setTimeout(()=>fpLiens(), 800);
    }catch(e){
        if(z) z.innerHTML='<div style="font-size:11px;color:var(--danger-soft)">Erreur réseau</div>';
    }
}

// Clés SSH d'un compte : c'est ce qui donne un accès shell au serveur, et rien
// dans l'interface ne permettait de savoir combien il y en a ni depuis quand.
async function fpUserSsh(nom){
    _fpPanneau('🔑 Clés SSH · '+nom, '<div style="color:var(--txt-muted)">Lecture…</div>');
    try{
        const d=await apiPost('/api/fp/user/ssh',{username:nom});
        if(!d.ok){
            _fpPanneau('🔑 Clés SSH · '+nom,
                `<div style="font-size:11.5px;color:var(--warn)">${escapeHtml(d.reason||'illisible')}</div>`);
            return;
        }
        const k=d.keys||[];
        _fpPanneau('🔑 Clés SSH · '+nom, k.length? `
          <div style="font-size:11.5px;color:var(--txt-soft);margin-bottom:8px">
            ${k.length} clé(s) autorisée(s) — chacune ouvre un accès shell.</div>
          ${k.map(x=>`<div style="padding:6px 0;border-bottom:1px solid var(--ov-06)">
             <div style="font-size:11.5px;color:var(--txt)">${escapeHtml(x.comment||x.title||'sans libellé')}
               <span style="color:var(--txt-faint);font-size:10px">${escapeHtml(x.type||'')}</span></div>
             <div style="font-size:10px;color:var(--txt-faint);font-family:ui-monospace,monospace;
                         word-break:break-all">${escapeHtml(String(x.fingerprint||x.key||'').slice(0,90))}</div>
           </div>`).join('')}`
          : `<div style="font-size:11.5px;color:var(--ok)">Aucune clé SSH déclarée pour ce compte.</div>
             <div style="font-size:10.5px;color:var(--txt-faint);margin-top:4px">
               L'accès se fait donc par mot de passe, ou pas du tout.</div>`);
    }catch(e){
        _fpPanneau('🔑 Clés SSH · '+nom, '<div style="color:var(--danger-soft)">Erreur réseau</div>');
    }
}

// Portrait de substitution : initiales sur une couleur DÉRIVÉE du nom, donc
// stable et propre à chaque compte. Deux utilisateurs ne se ressemblent pas,
// et la forme carrée-arrondie le distingue d'une vraie photo — on ne fait pas
// passer une image fabriquée pour un portrait.
function fpAvatarGenere(nom, taille){
    const t=taille||36;
    let h=0;
    for(let i=0;i<(nom||'').length;i++){ h=((h<<5)-h+nom.charCodeAt(i))|0; }
    const teinte=Math.abs(h)%360;
    const init=(nom||'?').replace(/[^A-Za-z0-9]/g,'').slice(0,2).toUpperCase()||'?';
    return `<div title="Portrait généré — FastPanel n'en stocke pas"
        style="width:${t}px;height:${t}px;border-radius:${Math.round(t*0.28)}px;display:flex;
               align-items:center;justify-content:center;font-weight:700;
               font-size:${Math.round(t*0.34)}px;letter-spacing:.5px;color:var(--bg);
               background:linear-gradient(135deg,hsl(${teinte},70%,62%),hsl(${(teinte+48)%360},70%,48%))"
        >${escapeHtml(init)}</div>`;
}

// Fiche d'un compte du panneau. Le portrait vient de FastPanel quand il en
// stocke un ; sinon un portrait généré — et la fiche dit lequel des deux, pour
// ne pas laisser croire à une photo absente alors que le panneau n'en garde pas.
async function fpUserFiche(nom){
    _fpPanneau('👤 '+nom, '<div style="color:var(--txt-muted)">Lecture du compte…</div>');
    try{
        const av=await apiPost('/api/fp/user/avatar',{username:nom}).catch(()=>({ok:false}));
        // Les comptes sont déjà chargés côté client : les redemander au serveur
        // ne donnerait rien de plus et ajouterait un aller-retour.
        const u=((_fpData['users']||[]).find(x=>String(x.username||'')===nom))||{};
        const portrait = av.ok && av.url
            ? `<img src="${escapeAttr(av.url)}" alt="" style="width:56px;height:56px;
                 border-radius:50%;object-fit:cover;border:1px solid var(--ov-12)">`
            : fpAvatarGenere(nom, 56);
        const ligne=(l,v)=>v?`<div style="font-size:11.5px;color:var(--txt)">
            <span style="color:var(--txt-faint)">${l} :</span> ${escapeHtml(String(v))}</div>`:'';
        _fpPanneau('👤 '+nom, `
          <div style="display:flex;gap:14px;align-items:center;margin-bottom:12px">
            ${portrait}
            <div>
              <div style="font-size:14px;color:var(--txt-strong);font-weight:600">${escapeHtml(nom)}</div>
              <div style="font-size:11px;color:var(--txt-muted)">${escapeHtml(String(u.roles||u.role||''))}</div>
              ${(!av.ok&&av.sans_colonne)?`<div style="font-size:10px;color:var(--txt-faint);margin-top:2px">
                 ${escapeHtml(av.reason)}</div>`:''}
            </div>
          </div>
          ${ligne('Répertoire', u.home_dir)}
          ${ligne('Statut', u.status)}
          ${ligne('Accès SSH', (u.ssh_access===1||u.ssh_access===true)?'oui':'non')}
          ${ligne('Quota', u.quota_gb?u.quota_gb+' Go':'')}
          ${ligne('Sites', u.sites)}
          ${ligne('Bases', u.databases)}
          ${ligne('Courriel de secours', u.restore_email)}
          ${ligne('Créé le', (u.created_at||'').slice(0,10))}
          <div style="margin-top:12px;display:flex;gap:6px;flex-wrap:wrap">
            <button class="fp-btn" onclick="fpVoir('domains','${escapeAttr(nom)}')">Ses sites</button>
            <button class="fp-btn secondary" onclick="fpVoir('databases','${escapeAttr(nom)}')">Ses bases</button>
            <button class="fp-btn secondary" onclick="fpVoir('ftp','${escapeAttr(nom)}')">Ses accès FTP</button>
            <button class="fp-btn secondary" onclick="fpLiens('${escapeAttr(nom)}')"
              title="Adosser un compte Cassandra à ce compte FastPanel">🔗 Comptes Cassandra</button>
          </div>`);
    }catch(e){
        _fpPanneau('👤 '+nom, `<div style="color:var(--danger-soft)">${escapeHtml(e.message||'échec')}</div>`);
    }
}

// Sauvegardes : l'onglet montrait les copies passées sans jamais dire quels
// plans les produisent — donc « aucune sauvegarde » n'indiquait pas quoi faire.
async function fpBackupPlans(){
    _fpPanneau('Plans de sauvegarde', '<div class="mx-attente">Lecture des plans et des stockages…</div>');
    try{
        const d=await apiPost('/api/fp/backup/plans',{});
        const plans=d.plans||[], st=d.stockages||[];
        const lp = plans.length ? `<div class="mx-rows">${plans.map(p=>{
            const id=escapeAttr(String(p.id||'')), actif=(p.enabled===1||p.enabled===true||p.status==='enabled');
            return `<div class="mx-row">${fp2Pill(actif?'actif':'inactif', actif?'ok':'neutre')}<div class="mx-rt"><b>${escapeHtml(p.name||('plan '+id))}</b>
              <span>${escapeHtml(fpBackupQuand(p))}${p.account&&p.account.name?' · vers '+escapeHtml(p.account.name)+' ('+escapeHtml(p.account.type||'')+')':''}${p.full_copy_limit?' · '+p.full_copy_limit+' copies gardées':''}${p.type==='all_users'?' · tous les comptes':(p.user&&p.user.username?' · compte '+escapeHtml(p.user.username):'')}</span></div>
              <div class="mx-gest"><button class="mx-btn" onclick="fpBackupLancer('${id}')">Lancer</button></div></div>`; }).join('')}</div>`
            : `<div class="mx-silence"><b>Aucun plan.</b> ${escapeHtml(d.reason||'Sans plan, rien n\u2019est sauvegardé automatiquement.')}</div>`;
        // SANS STOCKAGE, PAS DE PLAN (20-09) : le panneau répondait 400 sur « account », l'écran montrait le 400.
        const ls = st.length ? `<div class="mx-rows">${st.map(x=>`<div class="mx-row">${fp2Pill(x.type||'?','info')}<div class="mx-rt"><b>${escapeHtml(x.name||'')}</b><span>${escapeHtml(x.path||x.host||x.bucket||'')}</span></div><span></span></div>`).join('')}</div>`
            : `<div class="mx-silence"><b>Aucun stockage déclaré.</b> Un plan a besoin d’un endroit où écrire : un dossier du serveur suffit pour commencer — sur le même disque que les sites, c’est un filet, pas une copie hors machine.</div>
               <div class="fp2-form"><input id="fpbk-st-nom" class="mx-select" value="local" placeholder="nom" aria-label="Nom du stockage"><input id="fpbk-st-chemin" class="mx-select" value="/var/backups/panneau" placeholder="/var/backups/panneau" style="min-width:230px" aria-label="Dossier du serveur"><button class="mx-btn primary" onclick="fpBackupStockageCreer()">Déclarer ce stockage</button></div>`;
        _fpPanneau('Plans de sauvegarde', `
          <div class="mx-eyebrow">Stockages · où les sauvegardes s’écrivent</div>${ls}
          <div class="mx-eyebrow" style="margin-top:14px">Plans</div>${lp}
          <div class="mx-eyebrow" style="margin-top:14px">Nouveau plan · tous les sites et toutes les bases</div>
          <div class="fp2-form">
            <input id="fpbk-nom" class="mx-select" placeholder="nom du plan" value="${plans.length?'':'quotidien'}" aria-label="Nom du plan">
            <select id="fpbk-jour" class="mx-select" aria-label="Quand"><option value="*">chaque jour</option><option value="1">chaque lundi</option><option value="0">chaque dimanche</option></select>
            <select id="fpbk-heure" class="mx-select" aria-label="Heure"><option value="4">à 4 h</option><option value="2">à 2 h</option><option value="23">à 23 h</option></select>
            <select id="fpbk-garder" class="mx-select" aria-label="Copies gardées"><option value="7">7 copies gardées</option><option value="3">3 copies gardées</option><option value="14">14 copies gardées</option><option value="30">30 copies gardées</option></select>
            ${st.length>1?`<select id="fpbk-stockage" class="mx-select" aria-label="Stockage">${st.map(x=>`<option value="${escapeAttr(String(x.id))}">vers ${escapeHtml(x.name||'')}</option>`).join('')}</select>`:''}
            <button class="mx-btn primary" onclick="fpBackupCreer()"${st.length?'':' disabled title="Déclarez d’abord un stockage"'}>Créer</button>
          </div>
          <div id="fpbk-out" style="margin-top:8px"></div>
          <div class="mx-foot" style="margin-top:12px"><span>Ces plans sont ceux du moteur v2 du panneau : dans son interface, <b>Copies de sauvegarde › Differential plans</b> — pas l’onglet « Plans de sauvegarde », qui est l’ancien moteur, site par site.</span></div>`);
    }catch(e){
        _fpPanneau('Plans de sauvegarde', `<div class="mx-silence">${escapeHtml(e.message||'échec')}</div>`);
    }
}
// LANCER UN PLAN (20-09) : l'ancien appel passait `['1']` à fpRunAction, qui prend cette liste pour des NOMS de paramètres
// et demandait « Paramètre « 1 » » ; sa sortie allait dans #fp-act-out, absent hors de la page Opérations.
async function fpBackupLancer(id){
    const z = document.getElementById('fpbk-out');
    const corps = { action: 'sauvegarde', arg: String(id || '') };
    try{
        let d = await apiPost('/api/fp/act', corps);
        if (d.needs_confirm) {
            if (!await fp2Confirm((d.reason || 'Lance le plan de sauvegarde ' + id + '.') + '\n\nLancer la sauvegarde ?', 'Sauvegarde')) return;
            d = await apiPost('/api/fp/act', Object.assign({ confirm: true }, corps));
        }
        const msg = d.ok ? 'Sauvegarde lancée : la copie apparaîtra dans la liste quand elle sera finie.' : ('Refus : ' + (d.reason || '?') + (d.detail ? ' — ' + String(d.detail).slice(0, 160) : ''));
        if (typeof showToast === 'function') showToast(msg, d.ok ? 'success' : 'error', d.ok ? 4000 : 8000);
        if (z) z.innerHTML = `<div class="${d.ok ? 'mx-note' : 'mx-silence'}"${d.ok ? ' style="color:var(--ok)"' : ''}>${escapeHtml(msg)}${d.output ? '<br><span class="mx-meta">' + escapeHtml(String(d.output).slice(0, 300)) + '</span>' : ''}</div>`;
        if (d.ok) setTimeout(() => { fp2Relever(); }, 4000);
    }catch(e){ if (typeof showToast === 'function') showToast('Erreur réseau', 'error', 3000); }
}
function fpBackupQuand(p){
    const j=String(p.day_of_week??'*'), h=String(p.hour??'?');
    const J={'0':'dimanche','1':'lundi','2':'mardi','3':'mercredi','4':'jeudi','5':'vendredi','6':'samedi'};
    return (j==='*' ? 'chaque jour' : (J[j] ? 'chaque '+J[j] : 'les jours '+j))+' à '+h+' h';
}
async function fpBackupStockageCreer(){
    const nom=((document.getElementById('fpbk-st-nom')||{}).value||'').trim(), chemin=((document.getElementById('fpbk-st-chemin')||{}).value||'').trim();
    try{
        let d=await apiPost('/api/fp/backup/storage/create',{name:nom, path:chemin});
        if(d.needs_confirm){
            if(!await fp2Confirm(d.reason+'\n\nDéclarer ce stockage ?', 'Stockage de sauvegarde')) return;
            d=await apiPost('/api/fp/backup/storage/create',{name:nom, path:chemin, confirm:true});
        }
        if(typeof showToast==='function') showToast(d.ok ? (d.output||'Stockage déclaré') : ('Refus : '+(d.reason||'?')+(d.detail?' — '+String(d.detail).slice(0,120):'')), d.ok?'success':'error', d.ok?3500:8000);
        if(d.ok) fpBackupPlans();
    }catch(e){ if(typeof showToast==='function') showToast('Erreur réseau','error',3000); }
}

async function fpBackupCreer(){
    const z=document.getElementById('fpbk-out');
    const nom=(document.getElementById('fpbk-nom')||{}).value||'';
    const jour=(document.getElementById('fpbk-jour')||{}).value||'*';
    const heure=(document.getElementById('fpbk-heure')||{}).value||'4';
    const garder=(document.getElementById('fpbk-garder')||{}).value||'7';
    const stockage=(document.getElementById('fpbk-stockage')||{}).value||'';
    if(!nom.trim()){
        if(z) z.innerHTML='<div class="mx-silence">Donnez un nom au plan.</div>';
        return;
    }
    if(z) z.innerHTML='<div class="mx-attente">Création…</div>';
    const corps={name:nom, day:jour, hour:heure, garder:garder, stockage:stockage};
    try{
        let d=await apiPost('/api/fp/backup/plan/create', corps);
        if(d.needs_storage){ if(z) z.innerHTML=`<div class="mx-silence">${escapeHtml(d.reason||'')}</div>`; return; }
        if(d.needs_confirm){
            if(!await fp2Confirm(d.reason+'\n\nCréer ce plan ?', 'Plan de sauvegarde')){ if(z) z.innerHTML=''; return; }
            d=await apiPost('/api/fp/backup/plan/create', Object.assign({confirm:true}, corps));
        }
        if(z) z.innerHTML=`<div class="${d.ok?'mx-note':'mx-silence'}" style="${d.ok?'color:var(--ok)':''}">${escapeHtml(d.output||d.reason||'')}${d.detail?'<br><span class="mx-meta">'+escapeHtml(String(d.detail).slice(0,300))+'</span>':''}</div>`;
        if(d.ok){ setTimeout(fpBackupPlans, 900); fp2Vigilances().then(()=>{ if(_fpSection==='backups') fpLoadSection('backups'); }); }
    }catch(e){
        if(z) z.innerHTML='<div class="mx-silence">Erreur réseau</div>';
    }
}

// Fiche d'une tâche planifiée vue depuis FastPanel. Les mêmes lignes de
// crontab que l'onglet « Tâches planifiées », donc les mêmes routes : lancer,
// activer, historique. Rien de réimplémenté, tout de rapproché.
async function fpCronFiche(index){
    const c=(_fpData['crons']||[])[index];
    if(!c){ return; }
    const titre='⏱ '+(c.user||'?')+' · '+String(c.command||'').slice(0,40);
    const ref=c.cassandra_id||'';
    const ligne=(l,v)=>v?`<div style="font-size:11.5px;color:var(--txt)">
        <span style="color:var(--txt-faint)">${l} :</span> ${escapeHtml(String(v))}</div>`:'';
    _fpPanneau(titre, `
      ${ligne('Utilisateur', c.user)}
      ${ligne('Planning', c.schedule)}
      <div style="font-size:11px;color:var(--txt-muted);margin:6px 0;font-family:ui-monospace,monospace;
                  word-break:break-all">${escapeHtml(String(c.command||''))}</div>
      ${ligne('Activée', (c.enabled===1||c.enabled===true||c.enabled==='Oui')?'oui':'non')}
      ${ligne('Dernière exécution', c.last_run)}
      ${ligne('Dernier statut', c.last_status)}
      ${ligne('Projet', c.project)}
      <div style="font-size:11px;color:${ref?'var(--ok)':'var(--warn)'};margin-top:8px">
        ${ref ? 'Suivie par Cassandra — historique et alerte sur échec actifs.'
              : 'Pas encore suivie par Cassandra : aucune alerte si elle échoue.'}</div>
      <div style="margin-top:12px;display:flex;gap:6px;flex-wrap:wrap">
        ${ref?`<button class="fp-btn" onclick="fpCronRun('${escapeAttr(String(ref))}')">
                 Lancer maintenant</button>`:''}
        <button class="fp-btn secondary" onclick="switchTab('crons')">
          Ouvrir dans les automatismes</button>
        <button class="fp-btn secondary" onclick="sendQuickFix(${
          JSON.stringify('Analyse cette tâche planifiée FastPanel : '
            +String(c.schedule||'')+' — '+String(c.command||'')).replace(/"/g,'&quot;')})">
          Demander à Cassandra</button>
      </div>
      <div id="fpcron-out" style="margin-top:10px"></div>`);
}

async function fpCronRun(id){
    const z=document.getElementById('fpcron-out');
    if(z) z.innerHTML='<div style="font-size:11px;color:var(--txt-muted)">Lancement…</div>';
    try{
        const d=await apiPost('/api/crons/run',{id:id});
        if(z) z.innerHTML=`<div style="font-size:11px;color:${d.ok?'var(--ok)':'var(--danger-soft)'}">${
            escapeHtml(d.output||d.reason||(d.ok?'Lancée.':'échec'))}</div>`;
    }catch(e){
        if(z) z.innerHTML='<div style="font-size:11px;color:var(--danger-soft)">Erreur réseau</div>';
    }
}

async function fpDomAttach(domain, noteSeule){
    const z=document.getElementById('fpdc-out');
    const nom=(document.getElementById('fpdc-proj')||{}).value||'';
    const note=(document.getElementById('fpdc-note')||{}).value||'';
    if(noteSeule && !note.trim()){
        if(z) z.innerHTML='<div style="font-size:11px;color:var(--warn)">Note vide.</div>';
        return;
    }
    if(!noteSeule && !nom.trim()){
        if(z) z.innerHTML='<div style="font-size:11px;color:var(--warn)">Indiquez un projet.</div>';
        return;
    }
    if(z) z.innerHTML='<div style="font-size:11px;color:var(--txt-muted)">Enregistrement…</div>';
    try{
        const d=await apiPost('/api/fp/domain/attach',
            {domain:domain, project_name:(noteSeule?'':nom), note:note});
        if(z) z.innerHTML=`<div style="font-size:11px;color:${d.ok?'var(--ok)':'var(--danger-soft)'}">${
            escapeHtml(d.output||d.reason||'')}</div>`;
        if(d.ok) setTimeout(()=>fpDomCtx(domain), 700);
    }catch(e){
        if(z) z.innerHTML='<div style="font-size:11px;color:var(--danger-soft)">Erreur réseau</div>';
    }
}

// Audit : les trois défaillances qui ne produisent aucune erreur.
async function fpAudit(){
    _fpPanneau('🩺 Audit de l\'infrastructure', '<div style="color:var(--txt-muted)">Analyse en cours…</div>');
    try{
        const d=await apiPost('/api/fp/audit',{});
        const b=d.backups||{}, php=d.php||{}, ssl=d.ssl||{}, rn=d.renew||{};
        const bloc=(t,c)=>`<div style="margin-bottom:14px"><div style="font-size:10px;color:var(--accent-soft);font-weight:700;margin-bottom:5px">${t}</div>${c}</div>`;
        const rien='<div style="font-size:11px;color:var(--accent)">Rien à signaler.</div>';
        const li=(txt,coul)=>`<div style="font-size:11.5px;color:${coul||'var(--txt)'}">· ${escapeHtml(txt)}</div>`;

        const bSans=(b.missing||[]).map(x=>li(x+' — aucune sauvegarde','var(--danger-soft)')).join('');
        const bVieux=(b.stale||[]).map(x=>li(x.domain+(x.last?(' — dernière le '+x.last):' — aucune date exploitable'),'var(--warn)')).join('');
        const pEol=(php.eol||[]).map(x=>li(x.domain+' — PHP '+x.php+' (support terminé le '+x.eol+')','var(--danger-soft)')).join('');
        const pSoon=(php.soon||[]).map(x=>li(x.domain+' — PHP '+x.php+' (fin le '+x.eol+')','var(--warn)')).join('');
        const sSoon=(ssl.soon||[]).map(x=>li(x.domain+' — '+x.days_left+' jour(s)', x.days_left<=7?'var(--danger-soft)':'var(--warn)')).join('');
        const sSans=(ssl.missing||[]).map(x=>li(x+' — pas de certificat','var(--txt-muted)')).join('');

        _fpPanneau('🩺 Audit de l\'infrastructure',
          bloc('SAUVEGARDES (seuil : '+(b.threshold_days||'?')+' jours)', (bSans+bVieux)||rien)+
          bloc('CERTIFICATS', (sSoon+sSans)||rien)+
          bloc('VERSIONS PHP', (pEol+pSoon)||rien)+
          bloc('RENOUVELLEMENT AUTOMATIQUE',
            `<div style="font-size:11.5px;color:${rn.disabled?'var(--txt-muted)':'var(--accent)'}">
               ${rn.disabled?'Désactivé':'Actif'} — seuil ${rn.threshold||'?'} jours.
               ${rn.certbot_timer?('Minuteur certbot : <b>'+escapeHtml(rn.certbot_timer)+'</b>.'):''}</div>
             ${rn.note?`<div style="font-size:11px;color:var(--txt-faint);margin-top:3px">${escapeHtml(rn.note)}</div>`:''}
             ${(rn.candidates||[]).length?`<div style="font-size:11px;color:var(--warn);margin-top:3px">À renouveler : ${escapeHtml(rn.candidates.join(', '))}</div>`:''}`)+
          `<div style="font-size:10.5px;color:var(--txt-faint);border-top:1px solid var(--ov-08);padding-top:8px">
             Ces constats alimentent aussi le fil de proactivité, une seule fois chacun.</div>`);
    }catch(e){ _fpPanneau('🩺 Audit', '<div style="color:var(--danger-soft)">Erreur réseau</div>'); }
}

function fpFilter(section, q) {
    const rows = _fpData[section] || [];
    const ql = q.toLowerCase();
    const filtered = q ? rows.filter(r => Object.values(r).some(v => String(v||'').toLowerCase().includes(ql))) : rows;
    const tbody = document.querySelector('#fp-main-area .fp-table tbody');
    if (!tbody) return;
    const cfg = FP_SECTIONS[section];
    // Même construction que le rendu initial : dupliquer le gabarit faisait
    // disparaître les boutons d'action dès qu'on tapait dans le filtre.
    tbody.innerHTML = filtered.map(row => fpRowHtml(section, row, cfg.cols)).join('');
}

function fpComputeStats(section, rows) {
    if (!rows.length) return [];
    switch(section) {
        case 'domains': {
            const ssl = rows.filter(r=>r.ssl_enabled==1).length;
            const exp = rows.filter(r=>r.ssl_days_left>0&&r.ssl_days_left<=30).length;
            const active = rows.filter(r=>r.status==='active').length;
            return [
                {val: rows.length, label:'Total'},
                {val: active, label:'Actifs', cls:'ok'},
                {val: ssl, label:'SSL actif', cls:'ok'},
                {val: exp, label:'SSL < 30j', cls: exp>0?'warn':'ok'},
            ];
        }
        case 'users': {
            const totalUsed = rows.reduce((s,r)=>s+(parseFloat(r.disk_used_gb)||0),0);
            const totalQuota = rows.reduce((s,r)=>s+(parseFloat(r.disk_quota_gb)||0),0);
            return [
                {val: rows.length, label:'Utilisateurs'},
                {val: fpTaille(totalUsed*1024), label:'Espace utilisé'},
                {val: totalQuota>0?fpTaille(totalQuota*1024):'—', label:'Quota total'},
            ];
        }
        case 'databases': {
            const total = rows.reduce((s,r)=>s+(parseFloat(r.size_mb)||0),0);
            return [
                {val: rows.length, label:'Bases'},
                {val: fpTaille(total), label:'Taille totale'},
            ];
        }
        case 'mail': {
            const active = rows.filter(r=>r.status==='active').length;
            const totalUsed = rows.reduce((s,r)=>s+(parseFloat(r.used_mb)||0),0);
            return [
                {val: rows.length, label:'Comptes'},
                {val: active, label:'Actifs', cls:'ok'},
                {val: fpTaille(totalUsed), label:'Espace utilisé'},
            ];
        }
        case 'backups': {
            const ok  = rows.filter(r=>['success','ok','completed'].includes((r.status||'').toLowerCase())).length;
            const err = rows.filter(r=>['error','failed'].includes((r.status||'').toLowerCase())).length;
            const vol = rows.reduce((s,r)=>s+(parseFloat(r.size_mb)||0),0);
            return [
                {val: rows.length, label:'Total'},
                {val: ok, label:'Réussis', cls:'ok'},
                {val: err, label:'Échoués', cls: err>0?'crit':'ok'},
                {val: fpTaille(vol), label:'Volume sauvegardé'},
            ];
        }
        case 'scans': {
            // Un site infecté ne doit pas se compter comme les autres.
            const bad = rows.filter(r=>(r.status||'')!=='ok').length;
            const sites = new Set(rows.map(r=>r.domain).filter(Boolean)).size;
            return [
                {val: rows.length, label:'Rapports'},
                {val: sites, label:'Sites analysés'},
                {val: bad, label:'Détections', cls: bad>0?'crit':'ok'},
            ];
        }
        case 'services': {
            const up   = rows.filter(r=>['active','running'].includes((r.status||'').toLowerCase())).length;
            const down = rows.filter(r=>!['active','running','ok'].includes((r.status||'').toLowerCase())).length;
            return [
                {val: rows.length, label:'Services'},
                {val: up, label:'En ligne', cls:'ok'},
                {val: down, label:'Hors ligne', cls: down>0?'crit':'ok'},
            ];
        }
        case 'dns': {
            const zones = new Set(rows.map(r=>r.zone)).size;
            return [{val:rows.length,label:'Enregistrements'},{val:zones,label:'Zones'}];
        }
        case 'crons': {
            const active = rows.filter(r=>r.enabled==1||r.enabled===true).length;
            return [{val:rows.length,label:'Crons'},{val:active,label:'Actifs',cls:'ok'}];
        }
        default: return [{val: rows.length, label:'Entrées'}];
    }
}


// ============================================================
// FASTPANEL2 — STATISTIQUES (CPU breakdown, LA, mémoire, disque)
// ============================================================
let _fpStatsDate   = new Date().toISOString().slice(0,10);
let _fpStatsTab    = 'cpu';
let _fpStatsCharts = {};

const FP_PROCESS_COLORS = [
    'var(--accent)','var(--violet)','var(--warn)','var(--danger)','var(--ok)',
    '#1e90ff','#ff6b9d','#eccc68','#a29bfe','#fd9644',
    '#55efc4','#fdcb6e','#e17055','#74b9ff','#dfe6e9',
];

async function fpLoadStats(date) {
    if (date) _fpStatsDate = date;
    const main = document.getElementById('fp-main-area'); if (!main) return;
    const ONGLETS = [['cpu', 'Processeur'], ['la', 'Charge'], ['memory', 'Mémoire'], ['disk', 'Disque']];
    main.innerHTML = `<section class="mx-sec">
      <div class="mx-chart-h"><h2>Statistiques de la machine</h2><span class="mx-meta">API du panneau · un relevé toutes les 5 min</span></div>
      <div class="fp2-stats-barre">
        <div class="mx-periods">${ONGLETS.map(t => `<button class="mx-per${_fpStatsTab === t[0] ? ' on' : ''}" data-t="${t[0]}" onclick="fpStatsTab('${t[0]}')">${t[1]}</button>`).join('')}</div>
        <div class="fp2-date"><input type="date" class="mx-select" id="fp-stats-date" value="${_fpStatsDate}" max="${new Date().toISOString().slice(0,10)}" onchange="fpLoadStats(this.value)" aria-label="Jour"><button class="mx-btn" onclick="fpLoadStats()">Relire</button></div>
      </div>
      <div class="fp-chart-area" id="fp-chart-area"><div class="mx-attente">Chargement des statistiques…</div></div>
    </section>`;
    // Détruire anciens charts
    Object.values(_fpStatsCharts).forEach(c => { try { c.destroy(); } catch(e){} });
    _fpStatsCharts = {};
    await fpRenderStatsTab(_fpStatsTab);
}

function fpStatsTab(tab) {
    _fpStatsTab = tab;
    document.querySelectorAll('#fp-main-area .mx-per[data-t]').forEach(el => el.classList.toggle('on', el.dataset.t === tab));
    Object.values(_fpStatsCharts).forEach(c => { try { c.destroy(); } catch(e){} });
    _fpStatsCharts = {};
    fpRenderStatsTab(tab);
}

async function fpRenderStatsTab(tab) {
    const area = document.getElementById('fp-chart-area');
    if (!area) return;
    area.innerHTML = '<div class="fp-loading"><div class="loader"></div></div>';
    try {
        // Le sélecteur de date changeait `_fpStatsDate` et rien d'autre : le
        // serveur rendait toujours aujourd'hui. Il lit désormais `?date=`
        // sur les quatre sous-onglets. (2026-09-05)
        const data = await apiGet(`/api/fp/stats/${tab}?date=${encodeURIComponent(_fpStatsDate)}`);
        switch(tab) {
            case 'cpu':    fpRenderCPU(data, area); break;
            case 'la':     fpRenderLA(data, area);  break;
            case 'memory': fpRenderMemory(data, area); break;
            case 'disk':   fpRenderDisk(data, area); break;
        }
    } catch(e) {
        area.innerHTML = `<div class="fp-empty"><div class="fp-empty-icon">⚠️</div>Impossible de charger les stats<br><span style="font-size:10px;color:var(--txt-ghost)">${escapeHtml(e.message)}</span><br><span style="font-size:10px;color:var(--txt-ghost)">Vérifiez que FastPanel2 est actif sur le port 8888</span></div>`;
    }
}

function fpNormalizeData(raw) {
    // Normalise les différentes structures de réponse FastPanel2
    if (!raw) return { source: 'unknown', items: [] };
    // Format API directe FastPanel2
    if (raw.status === 'ok' && raw.data) {
        if (Array.isArray(raw.data)) return { source: 'api', items: raw.data };
        if (raw.data.labels && raw.data.datasets)
            return { source: 'api_chart', labels: raw.data.labels, datasets: raw.data.datasets };
    }
    // Format fallback MySQL
    if (raw.source === 'mysql' && raw.data) return { source: 'mysql', items: raw.data };
    // Format fallback realtime
    if (raw.source === 'realtime' && raw.data) return { source: 'realtime', items: raw.data };
    // Format direct
    if (Array.isArray(raw)) return { source: 'array', items: raw };
    if (raw.data) return { source: 'data', items: Array.isArray(raw.data) ? raw.data : [raw.data] };
    return { source: 'raw', items: [raw] };
}

function fpRenderCPU(raw, area) {
    const d = fpNormalizeData(raw);
    area.innerHTML = '';

    // Si on a le format chart API directe avec breakdown par processus
    if (d.source === 'api_chart' && d.datasets) {
        const ds = d.datasets;
        const labels = d.labels || [];

        // Graphique 1 : CPU total (stacked area)
        const block1 = document.createElement('div');
        block1.className = 'fp-chart-block';
        const isRT = d.source === 'realtime';
        block1.innerHTML = `
            <div class="fp-chart-block-title">
                Charge du processeur
                ${isRT ? '<span class="fp-realtime-badge">⚡ Temps réel</span>' : ''}
            </div>
            <div class="fp-chart-container"><canvas id="fp-cpu-chart"></canvas></div>
            <div class="fp-chart-legend" id="fp-cpu-legend"></div>`;
        area.appendChild(block1);

        const procNames = Object.keys(ds.processes || {});
        const datasets_cfg = procNames.map((name, i) => ({
            label: name,
            data: ds.processes[name],
            backgroundColor: FP_PROCESS_COLORS[i % FP_PROCESS_COLORS.length] + '55',
            borderColor:     FP_PROCESS_COLORS[i % FP_PROCESS_COLORS.length],
            borderWidth: 1.5, fill: true, tension: 0.3, pointRadius: 0,
        }));
        // Ajouter "other" si total > somme processus
        if (ds.total) {
            datasets_cfg.unshift({
                label: 'Total', data: ds.total,
                backgroundColor: 'rgba(0,255,204,0.08)',
                borderColor: 'var(--accent)', borderWidth: 2,
                fill: false, tension: 0.3, pointRadius: 0,
            });
        }

        const ctx = document.getElementById('fp-cpu-chart').getContext('2d');
        _fpStatsCharts['cpu'] = new Chart(ctx, {
            type: 'line',
            data: { labels, datasets: datasets_cfg },
            options: fpChartOptions('CPU %', 100),
        });

        // Légende colorée
        const legend = document.getElementById('fp-cpu-legend');
        datasets_cfg.forEach(ds => {
            const item = document.createElement('div');
            item.className = 'fp-legend-item';
            item.innerHTML = `<div class="fp-legend-dot" style="background:${ds.borderColor}"></div>${escapeHtml(ds.label)}`;
            legend.appendChild(item);
        });
        return;
    }

    // Format realtime (snapshot ps)
    if (d.source === 'realtime' && d.items.length > 0) {
        const snap = d.items[0];
        const procs = snap.processes || {};
        const sorted = Object.entries(procs).sort((a,b) => b[1]-a[1]).slice(0, 12);
        const total = sorted.reduce((s, [,v]) => s+v, 0);

        block_rt = document.createElement('div');
        block_rt.className = 'fp-chart-block';
        block_rt.innerHTML = `
            <div class="fp-chart-block-title">
                Processus actifs <span class="fp-realtime-badge">⚡ Snapshot actuel</span>
            </div>
            <div class="fp-chart-container" style="height:220px"><canvas id="fp-cpu-rt-chart"></canvas></div>`;
        area.appendChild(block_rt);

        const ctx = document.getElementById('fp-cpu-rt-chart').getContext('2d');
        _fpStatsCharts['cpu_rt'] = new Chart(ctx, {
            type: 'bar',
            data: {
                labels: sorted.map(([n]) => n),
                datasets: [{
                    data: sorted.map(([,v]) => v.toFixed(1)),
                    backgroundColor: sorted.map((_, i) => FP_PROCESS_COLORS[i % FP_PROCESS_COLORS.length] + '99'),
                    borderColor:     sorted.map((_, i) => FP_PROCESS_COLORS[i % FP_PROCESS_COLORS.length]),
                    borderWidth: 1.5, borderRadius: 4,
                }]
            },
            options: {
                responsive: true, maintainAspectRatio: false, animation: false,
                plugins: { legend: { display: false },
                    tooltip: { callbacks: { label: ctx => ` ${ctx.parsed.y}% CPU` } } },
                scales: {
                    x: { ticks: { color: 'var(--txt-faint)', font: { size: 10 }, maxRotation: 30 }, grid: { color: 'var(--ov-04)' } },
                    y: { beginAtZero: true, ticks: { color: 'var(--txt-faint)', font: { size: 10 }, callback: v => v+'%' }, grid: { color: 'var(--ov-04)' } }
                }
            }
        });

        // Barre de total
        const info = document.createElement('div');
        info.className = 'fp-chart-block';
        info.innerHTML = `<div class="fp-chart-block-title">Utilisation totale mesurée : <span style="color:var(--accent);font-size:14px">${total.toFixed(1)}%</span></div>
            <div style="font-size:10px;color:var(--txt-faint);margin-top:4px">API FastPanel2 non disponible — snapshot ps en temps réel. Démarrez fastpanel2 pour l'historique.</div>`;
        area.appendChild(info);
        return;
    }

    // Format MySQL rows
    if (d.items && d.items.length > 0 && d.items[0].ts) {
        fpRenderTimeseriesFromRows(area, d.items, 'cpu_total', 'CPU total %', 'var(--accent)');
        return;
    }

    area.innerHTML = '<div class="fp-empty"><div class="fp-empty-icon">📭</div>Aucune donnée CPU disponible pour cette date</div>';
}

function fpRenderLA(raw, area) {
    const d = fpNormalizeData(raw);
    area.innerHTML = '';

    const block = document.createElement('div');
    block.className = 'fp-chart-block';
    block.innerHTML = `
        <div class="fp-chart-block-title">
            Load Average
            ${d.source === 'realtime' ? '<span class="fp-realtime-badge">⚡ Temps réel</span>' : ''}
        </div>
        <div class="fp-chart-container" style="height:220px"><canvas id="fp-la-chart"></canvas></div>
        <div class="fp-chart-legend">
          <div class="fp-legend-item"><div class="fp-legend-dot" style="background:#1e90ff"></div>LA1 (1 min)</div>
          <div class="fp-legend-item"><div class="fp-legend-dot" style="background:var(--info)"></div>LA5 (5 min)</div>
          <div class="fp-legend-item"><div class="fp-legend-dot" style="background:#ff5722"></div>LA15 (15 min)</div>
        </div>`;
    area.appendChild(block);

    let labels = [], la1 = [], la5 = [], la15 = [];

    if (d.source === 'api_chart' && d.datasets) {
        labels = d.labels || [];
        la1    = d.datasets.la1  || [];
        la5    = d.datasets.la5  || [];
        la15   = d.datasets.la15 || [];
    } else if (d.items) {
        d.items.forEach(row => {
            labels.push(row.ts === 'now' ? 'Maintenant' : (row.ts||'').slice(11,16));
            la1.push(parseFloat(row.la1||0));
            la5.push(parseFloat(row.la5||0));
            la15.push(parseFloat(row.la15||0));
        });
    }

    const ctx = document.getElementById('fp-la-chart').getContext('2d');
    _fpStatsCharts['la'] = new Chart(ctx, {
        type: 'line',
        data: {
            labels,
            datasets: [
                { label: 'LA1',  data: la1,  borderColor:'#1e90ff', backgroundColor:'rgba(30,144,255,.08)', fill:true, tension:0.4, pointRadius:0, borderWidth:2 },
                { label: 'LA5',  data: la5,  borderColor:'var(--info)', backgroundColor:'rgba(0,188,212,.06)',  fill:true, tension:0.4, pointRadius:0, borderWidth:1.5 },
                { label: 'LA15', data: la15, borderColor:'#ff5722', backgroundColor:'rgba(255,87,34,.05)',  fill:true, tension:0.4, pointRadius:0, borderWidth:1.5 },
            ]
        },
        options: fpChartOptions('Load Average'),
    });
}

function fpRenderMemory(raw, area) {
    const d = fpNormalizeData(raw);
    area.innerHTML = '';

    // Bloc graphique temporal
    const block = document.createElement('div');
    block.className = 'fp-chart-block';
    block.innerHTML = `
        <div class="fp-chart-block-title">
            Utilisation mémoire
            ${d.source === 'realtime' ? '<span class="fp-realtime-badge">⚡ Temps réel</span>' : ''}
        </div>
        <div class="fp-chart-container" style="height:200px"><canvas id="fp-mem-chart"></canvas></div>`;
    area.appendChild(block);

    let labels = [], used = [], cached = [], free = [], total_mb = 0;

    if (d.source === 'api_chart' && d.datasets) {
        labels = d.labels || [];
        used   = d.datasets.used_mb   || d.datasets.used   || [];
        cached = d.datasets.cached_mb || d.datasets.cached || [];
        free   = d.datasets.free_mb   || d.datasets.free   || [];
    } else if (d.items) {
        d.items.forEach(row => {
            labels.push(row.ts === 'now' ? 'Maintenant' : (row.ts||'').slice(11,16));
            used.push(parseFloat(row.used_mb||row.used||0));
            cached.push(parseFloat(row.cached_mb||row.cached||0));
            free.push(parseFloat(row.free_mb||row.free||0));
            if (row.total_mb) total_mb = parseFloat(row.total_mb);
        });
    }

    const ctx = document.getElementById('fp-mem-chart').getContext('2d');
    _fpStatsCharts['mem'] = new Chart(ctx, {
        type: 'line',
        data: {
            labels,
            datasets: [
                { label: 'Utilisée (MB)', data: used,   borderColor:'var(--danger)', backgroundColor:'rgba(255,71,87,.12)', fill:true, tension:0.3, pointRadius:0, borderWidth:2 },
                { label: 'Cache (MB)',    data: cached, borderColor:'var(--warn)', backgroundColor:'rgba(255,165,0,.08)',  fill:true, tension:0.3, pointRadius:0, borderWidth:1.5 },
                { label: 'Libre (MB)',    data: free,   borderColor:'var(--ok)', backgroundColor:'rgba(46,213,115,.06)', fill:true, tension:0.3, pointRadius:0, borderWidth:1.5 },
            ]
        },
        options: fpChartOptions('MB'),
    });

    // Bloc détail actuel si realtime
    if (d.source === 'realtime' && d.items.length > 0) {
        const r = d.items[0];
        const tot = parseFloat(r.total_mb||0);
        const us  = parseFloat(r.used_mb||0);
        const ca  = parseFloat(r.cached_mb||0);
        const fr  = parseFloat(r.free_mb||0);
        const pct = tot > 0 ? Math.round(us/tot*100) : 0;
        const col = pct > 85 ? 'var(--danger)' : pct > 70 ? 'var(--warn)' : 'var(--ok)';

        const block2 = document.createElement('div');
        block2.className = 'fp-chart-block';
        block2.innerHTML = `
            <div class="fp-chart-block-title">État actuel</div>
            <div class="fp-mem-ring-wrap">
              <div style="text-align:center;flex-shrink:0">
                <div style="font-size:32px;font-weight:700;font-family:'JetBrains Mono',monospace;color:${col}">${pct}%</div>
                <div style="font-size:10px;color:var(--txt-faint);margin-top:4px">${us.toFixed(0)} / ${tot.toFixed(0)} MB</div>
              </div>
              <div class="fp-mem-detail">
                <div class="fp-mem-row"><span class="fp-mem-label">Totale</span><span class="fp-mem-value">${(tot/1024).toFixed(1)} GB</span></div>
                <div class="fp-mem-row"><span class="fp-mem-label">Utilisée</span><span class="fp-mem-value" style="color:${col}">${us.toFixed(0)} MB</span></div>
                <div class="fp-mem-row"><span class="fp-mem-label">Cache</span><span class="fp-mem-value" style="color:var(--warn)">${ca.toFixed(0)} MB</span></div>
                <div class="fp-mem-row"><span class="fp-mem-label">Libre</span><span class="fp-mem-value" style="color:var(--ok)">${fr.toFixed(0)} MB</span></div>
              </div>
            </div>`;

// ===== CASSANDRA UI v2 — AMÉLIORATIONS =====

// Theme toggle

        area.appendChild(block2);
    }
}

// ── CASSANDRA UI v2 : toasts, squelettes, animations — AU NIVEAU GLOBAL.
// Ce bloc vivait à l'intérieur de fpRenderMemory (dans un `if`) : hors mode strict,
// ses fonctions n'étaient hissées qu'à cette fonction, jamais au global — aucun
// toast de l'interface ne s'affichait (relecture de l'onglet FastPanel, 2026-09-05).
// Toast notifications
// `toast` — LE NOM QUE TRENTE ET UN APPELS EMPLOIENT DEJA. Il n a jamais ete
// defini : chacun de ces appels etait garde par « typeof toast === 'function' »,
// une precaution qui a fini par CACHER l absence au lieu d en protéger. Pas un
// de ces messages ne s est affiche — pannes de piece jointe, refus du micro,
// moteur de voix manquant : tout se taisait.
//
// Les niveaux different aussi : `showToast` attend 'error', et 'err' — employe
// partout ailleurs — ne correspondait a aucune classe.
function toast(message, type, duration){
    const t = (type === 'err') ? 'error' : (type || 'info');
    return showToast(message, t, duration || (t === 'error' ? 5000 : 3000));
}

function showToast(message, type = 'info', duration = 3000) {
  let container = document.querySelector('.toast-container');
  if (!container) {
    container = document.createElement('div');
    container.className = 'toast-container';
    document.body.appendChild(container);
  }
  const toast = document.createElement('div');
  toast.className = `toast ${type}`;
  toast.textContent = message;
  container.appendChild(toast);
  setTimeout(() => toast.remove(), duration);
}

// LA PAGE AU REPOS (22-09). Une « animation d'entrée » garait ici TOUTES les cartes à opacité 0 et ne les
// révélait que quand un dixième de leur surface entrait dans la fenêtre (IntersectionObserver, seuil 0,1).
// La carte des secrets du coffre, avec 338 entrées, fait dix-huit mille pixels de haut : son dixième dépasse
// l'écran, elle ne se révélait JAMAIS — page blanche sous un en-tête, sans une erreur. Ce qui doit se voir
// se voit dès le chargement ; un effet d'entrée ne se gare pas hors de vue.

// L'ÉCRAN ALLÉGÉ (22-09) : sur un téléphone, l'essentiel. Réglé par appareil ; sans réglage, allumé sur un écran étroit.
function allegeEtat(){
    try{ const v = localStorage.getItem('cass_allege'); if (v === '1') return true; if (v === '0') return false; }catch(e){}
    return window.matchMedia('(max-width:768px)').matches;
}
function allegeAppliquer(){
    const on = allegeEtat();
    document.body.classList.toggle('allege', on);
    const sw = document.getElementById('um-allege-sw');
    if (sw) { sw.classList.toggle('on', on); sw.setAttribute('aria-checked', on ? 'true' : 'false'); }
}
// LE SALON ALLÉGÉ : la liste des conversations se replie en une ligne ; la ligne l'ouvre en volet, un fil choisi la referme.
document.addEventListener('click', function(e){
    if (!document.body.classList.contains('allege') || !window.matchMedia('(max-width:768px)').matches) return;
    const t = document.getElementById('tab-salon'); if (!t || !t.classList.contains('active')) return;
    if (e.target.closest('#tab-salon .sl-gauche .sl-lbl') && !e.target.closest('.sl-rail-filtre')) { t.classList.toggle('sl-rail-ouvert'); return; }
    if (e.target.closest('#tab-salon #sl-fils .sl-fil') || !e.target.closest('#tab-salon .sl-gauche')) t.classList.remove('sl-rail-ouvert');
});
function allegeBascule(){
    const on = !document.body.classList.contains('allege');
    try{ localStorage.setItem('cass_allege', on ? '1' : '0'); }catch(e){}
    allegeAppliquer();
    if (typeof showToast === 'function') showToast(on ? 'Écran allégé' : 'Écran complet', 'success');
}

// Init on load
document.addEventListener('DOMContentLoaded', () => {
  allegeAppliquer();
  // Welcome toast
  // Le marqueur est remplacé au rendu par la constante : écrite en dur, la
  // version saluait « v14 » alors que v17 tournait.
  setTimeout(() => showToast('🔥 Cassandra 19.0 active', 'success', 2000), 500);
});

function fpRenderDisk(raw, area) {
    const d = fpNormalizeData(raw);
    area.innerHTML = '';

    if (d.source === 'api_chart' && d.labels) {
        // Historique I/O
        const block = document.createElement('div');
        block.className = 'fp-chart-block';
        block.innerHTML = `<div class="fp-chart-block-title">I/O Disque</div>
            <div class="fp-chart-container" style="height:200px"><canvas id="fp-disk-io-chart"></canvas></div>`;
        area.appendChild(block);
        const ds = d.datasets || {};
        const ctx = document.getElementById('fp-disk-io-chart').getContext('2d');
        _fpStatsCharts['disk_io'] = new Chart(ctx, {
            type: 'line',
            data: {
                labels: d.labels,
                datasets: [
                    { label: 'Lecture MB', data: ds.read_mb||[], borderColor:'var(--ok)', backgroundColor:'rgba(46,213,115,.08)', fill:true, tension:0.3, pointRadius:0, borderWidth:2 },
                    { label: 'Écriture MB', data: ds.write_mb||[], borderColor:'var(--danger)', backgroundColor:'rgba(255,71,87,.08)', fill:true, tension:0.3, pointRadius:0, borderWidth:2 },
                ]
            },
            options: fpChartOptions('MB/s'),
        });
        return;
    }

    // Format realtime df
    if (d.items && d.items.length > 0 && d.items[0].pct !== undefined) {
        const block = document.createElement('div');
        block.className = 'fp-chart-block';
        block.innerHTML = `
            <div class="fp-chart-block-title">Utilisation disques <span class="fp-realtime-badge">⚡ Temps réel</span></div>
            <div class="fp-disk-grid" id="fp-disk-grid"></div>`;
        area.appendChild(block);

        const grid = document.getElementById('fp-disk-grid');
        d.items.forEach(disk => {
            const pct = parseInt((disk.pct||'0%').replace('%','')) || 0;
            const col = pct > 85 ? 'var(--danger)' : pct > 70 ? 'var(--warn)' : 'var(--ok)';
            const card = document.createElement('div');
            card.className = 'fp-disk-card';
            card.innerHTML = `
                <div class="fp-disk-card-name" title="${escapeHtml(disk.device)}">${escapeHtml(disk.mount||disk.device)}</div>
                <div style="font-size:9px;color:var(--txt-ghost);margin-bottom:6px;font-family:'JetBrains Mono',monospace">${escapeHtml(disk.device)}</div>
                <div class="fp-disk-card-bar"><div class="fp-disk-card-fill" style="width:${pct}%;background:${col}"></div></div>
                <div class="fp-disk-card-stats">
                    <span>${escapeHtml(disk.used||'–')} utilisés</span>
                    <span style="color:${col};font-weight:700">${pct}%</span>
                    <span style="color:var(--txt-faint)">${escapeHtml(disk.total||'–')}</span>
                </div>`;
            grid.appendChild(card);
        });
        return;
    }

    area.innerHTML = '<div class="fp-empty"><div class="fp-empty-icon">💽</div>Aucune donnée disque disponible</div>';
}

function fpRenderTimeseriesFromRows(area, rows, key, label, color) {
    const block = document.createElement('div');
    block.className = 'fp-chart-block';
    block.innerHTML = `<div class="fp-chart-block-title">${escapeHtml(label)}</div>
        <div class="fp-chart-container"><canvas id="fp-ts-chart"></canvas></div>`;
    area.appendChild(block);
    const labels = rows.map(r => (r.ts||'').slice(11,16));
    const data   = rows.map(r => parseFloat(r[key]||0));
    const ctx = document.getElementById('fp-ts-chart').getContext('2d');
    _fpStatsCharts['ts'] = new Chart(ctx, {
        type: 'line',
        data: { labels, datasets: [{ label, data, borderColor: color,
            backgroundColor: color+'15', fill: true, tension: 0.3,
            pointRadius: 0, borderWidth: 2 }] },
        options: fpChartOptions(label),
    });
    // La courbe seule obligeait à lire les pics à l'œil (19-09) : la moyenne, le pic et son heure.
    const vals = data.filter(v => isFinite(v));
    if (vals.length) {
        let im = 0; vals.forEach((v, i) => { if (v > vals[im]) im = i; });
        const moy = vals.reduce((a, b) => a + b, 0) / vals.length;
        const pct = /%/.test(label), fmt = v => pct ? v.toFixed(1).replace('.', ',') + ' %' : (v >= 100 ? Math.round(v) : v.toFixed(2).replace('.', ','));
        const k = document.createElement('div'); k.className = 'mx-kpis'; k.style.marginTop = '12px';
        k.innerHTML = `<div class="mx-kpi"><span>moyenne</span><b>${fmt(moy)}</b></div><div class="mx-kpi"><span>pic</span><b>${fmt(vals[im])}</b><em>à ${escapeHtml(labels[im] || '')}</em></div><div class="mx-kpi"><span>relevés</span><b>${vals.length}</b><em>un toutes les 5 min</em></div>`;
        area.appendChild(k);
    }
}

function fpChartOptions(yLabel, max) {
    return {
        responsive: true, maintainAspectRatio: false, animation: false,
        interaction: { mode: 'index', intersect: false },
        plugins: {
            legend: { display: false },
            tooltip: {
                backgroundColor: 'rgba(17,17,24,.95)',
                borderColor: 'var(--acc-30)', borderWidth: 1,
                titleColor: 'var(--accent)', bodyColor: 'var(--txt-muted)',
                padding: 10,
            },
        },
        scales: {
            x: {
                ticks: { color:'var(--txt-faint)', font:{ size:9 }, maxTicksLimit: 12, maxRotation: 0 },
                grid: { color:'var(--ov-03)' },
            },
            y: {
                beginAtZero: true,
                ...(max ? { max } : {}),
                ticks: { color:'var(--txt-faint)', font:{ size:9 }, callback: v => v + (yLabel.includes('%') || yLabel==='CPU %' ? '%' : '') },
                grid: { color:'var(--ov-04)' },
            }
        }
    };
}

